insert into kafaa_job_families (id, name_en, name_ar, description_en, description_ar, sort, grp) values
('operations', 'Operations', 'العمليات', 'Running the units safely from the main control room and the plant, around the clock.', 'تشغيل الوحدات بأمان من غرفة التحكم الرئيسية وفي أنحاء المحطة على مدار الساعة.', 1, 'operations'),
('maintenance', 'Maintenance', 'الصيانة', 'Mechanical, electrical and instrumentation and control maintenance, in operation and during outages.', 'الصيانة الميكانيكية والكهربائية والأجهزة والتحكم أثناء التشغيل وفترات الإيقاف.', 2, 'maintenance_engineering'),
('engineering', 'Engineering', 'الهندسة', 'System health, design authority, modifications, reactor engineering and ageing management.', 'سلامة الأنظمة وسلطة التصميم والتعديلات وهندسة المفاعل وإدارة التقادم.', 3, 'maintenance_engineering'),
('radiation-protection', 'Radiation Protection', 'الوقاية من الإشعاع', 'Keeping doses as low as reasonably achievable for workers and the public.', 'إبقاء الجرعات الإشعاعية عند أدنى مستوى ممكن عملياً للعاملين والجمهور.', 4, 'rp_chem_env'),
('chemistry', 'Chemistry', 'الكيمياء', 'Primary and secondary water chemistry, radiochemistry and effluent monitoring.', 'كيمياء المياه في الدائرتين الأولية والثانوية والكيمياء الإشعاعية ورصد المخلفات السائلة.', 5, 'rp_chem_env'),
('nuclear-fuel', 'Nuclear Fuel', 'الوقود النووي', 'Fuel procurement, receipt, refuelling and spent-fuel management.', 'شراء الوقود واستلامه وإعادة التزويد بالوقود وإدارة الوقود المستهلك.', 6, 'maintenance_engineering'),
('outage', 'Outage & Work Management', 'إدارة فترات الإيقاف والأعمال', 'Planning and scheduling refuelling outages and daily plant work.', 'تخطيط وجدولة فترات إيقاف إعادة التزويد بالوقود والأعمال اليومية في المحطة.', 7, 'operations'),
('emergency-preparedness', 'Emergency Preparedness', 'التأهب للطوارئ', 'On-site emergency plans, facilities, drills and exercises.', 'خطط الطوارئ في الموقع ومرافقها والتدريبات والتمارين.', 8, 'ep_security_safeguards'),
('security', 'Security', 'الأمن', 'Physical protection and access authorisation. Kafa''a shows the career path only.', 'الحماية المادية وتصاريح الدخول. تعرض كفاءة المسار المهني فقط.', 9, 'ep_security_safeguards'),
('cyber', 'Cyber & IT/OT', 'الأمن السيبراني وتقنية المعلومات والتشغيل', 'Protecting digital systems and plant networks; enterprise IT.', 'حماية الأنظمة الرقمية وشبكات المحطة وتقنية المعلومات المؤسسية.', 10, 'ep_security_safeguards'),
('safeguards', 'Safeguards', 'الضمانات', 'Nuclear material accountancy and support to IAEA safeguards.', 'محاسبة المواد النووية ودعم ضمانات الوكالة الدولية للطاقة الذرية.', 11, 'ep_security_safeguards'),
('quality', 'Quality', 'الجودة', 'Quality assurance, quality control, inspection and supplier audits.', 'ضمان الجودة ومراقبتها والتفتيش وتدقيق الموردين.', 12, 'safety_quality_oversight'),
('oversight', 'Nuclear Oversight', 'الرقابة النووية', 'Independent oversight, performance improvement, human performance and the Employee Concerns Program.', 'الرقابة المستقلة وتحسين الأداء والأداء البشري وبرنامج مخاوف الموظفين.', 13, 'safety_quality_oversight'),
('licensing', 'Licensing', 'الترخيص', 'Licensing basis, regulatory correspondence and periodic safety review.', 'أساس الترخيص والمراسلات التنظيمية والمراجعة الدورية للسلامة.', 14, 'safety_quality_oversight'),
('training', 'Nuclear Training', 'التدريب النووي', 'Systematic Approach to Training: programmes, simulators and examinations.', 'النهج المنهجي للتدريب: البرامج وأجهزة المحاكاة والاختبارات.', 15, 'training_supply_corporate'),
('health-safety', 'Health & Safety', 'الصحة والسلامة', 'Industrial health and safety management system.', 'نظام إدارة الصحة والسلامة المهنية.', 16, 'safety_quality_oversight'),
('environment', 'Environment', 'البيئة', 'Environmental and radiological environmental monitoring.', 'الرصد البيئي والرصد الإشعاعي البيئي.', 17, 'rp_chem_env'),
('supply-chain', 'Supply Chain', 'سلسلة الإمداد', 'Safety-related procurement, commercial-grade dedication and supplier development.', 'المشتريات المتعلقة بالسلامة واعتماد المواد التجارية وتطوير الموردين.', 18, 'training_supply_corporate'),
('fire-protection', 'Fire Protection', 'الحماية من الحرائق', 'Fire brigade and the fire-protection programme.', 'فرقة الإطفاء وبرنامج الحماية من الحرائق.', 19, 'safety_quality_oversight'),
('corporate', 'Corporate', 'الخدمات المؤسسية', 'HR, finance, legal, communications and stakeholder engagement.', 'الموارد البشرية والمالية والشؤون القانونية والاتصال وإشراك أصحاب المصلحة.', 20, 'training_supply_corporate')
insert into kafaa_job_roles (id, family_id, title_en, title_ar, function_en, function_ar, level, regulated, regulation_ref, regulation_url, basis, basis_note, summary_en, summary_ar, qualifications_en, qualifications_ar, training_path_en, training_path_ar, licensing_body_en, licensing_body_ar, entry_routes, education, entry_level, emiratization_reserved, critical, security_sensitive, sources, status, version, sort, lifecycle) values
('senior-reactor-operator', 'operations', 'Senior Reactor Operator (SRO), incl. unit supervisor', 'مشغّل مفاعل أول (بما في ذلك مشرف الوحدة)', 'Operations', 'العمليات', 'senior', true, 'FANR-REG-17 Art. 4, 8, 10, 11', 'https://www.fanr.gov.ae/en/Documents/FANR-REG17%20V.1%20EN%20-%20BOM%20Version%20Certified.PDF', 'barakah', null, 'Directs Reactor Operators and Local Operators in the main control room and holds command and control of the unit.', 'يوجّه مشغّلي المفاعل والمشغّلين المحليين في غرفة التحكم الرئيسية ويتولى القيادة والسيطرة على الوحدة.', 'REG-17 Art. 4: 24 months as RO at Barakah, or a BSc plus 24 months at Barakah including 12 as LO, plus UAE security clearance. Annual medical; at least 2 SRO-role shifts per quarter.', 'المادة 4 من اللائحة 17: 24 شهراً كمشغّل مفاعل في براكة، أو بكالوريوس مع 24 شهراً في براكة منها 12 شهراً كمشغّل محلي، إضافة إلى تصريح أمني إماراتي. فحص طبي سنوي ونوبتان على الأقل بدور مشغّل أول في كل ربع سنة.', 'COIT, internal comprehensive exam, FANR written and operating exams; COCT every year; biennial requalification.', 'التدريب الأولي للمشغّلين المعتمدين، والاختبار الداخلي الشامل، واختبارات الهيئة الكتابية والتشغيلية؛ التدريب المستمر سنوياً؛ إعادة التأهيل كل سنتين.', 'FANR certificate, valid 5 years, plant-specific', 'شهادة من الهيئة الاتحادية للرقابة النووية صالحة لخمس سنوات وخاصة بالمحطة', '[{"id":"sro_ro24","en":"24 months as Reactor Operator at Barakah","ar":"24 شهراً كمشغّل مفاعل في براكة","rule_ref":"FANR-REG-17 Art. 4","url":"https://www.fanr.gov.ae/en/Documents/FANR-REG17%20V.1%20EN%20-%20BOM%20Version%20Certified.PDF"},{"id":"sro_bsc","en":"BSc in engineering, engineering technology or a related science, plus 24 months of nuclear work at Barakah including 12 as Local Operator","ar":"بكالوريوس في الهندسة أو تكنولوجيا الهندسة أو علم ذي صلة، مع 24 شهراً من العمل النووي في براكة منها 12 شهراً كمشغّل محلي","rule_ref":"FANR-REG-17 Art. 4","url":"https://www.fanr.gov.ae/en/Documents/FANR-REG17%20V.1%20EN%20-%20BOM%20Version%20Certified.PDF"},{"id":"sro_other_plant","en":"24 months as RO, SRO or SRO-Qualified Instructor elsewhere, plus 12 months at Barakah including 6 on crew","ar":"24 شهراً كمشغّل مفاعل أو مشغّل أول أو مدرب مؤهل كمشغّل أول في مكان آخر، مع 12 شهراً في براكة منها 6 أشهر ضمن طاقم","rule_ref":"FANR-REG-17 Art. 4","url":"https://www.fanr.gov.ae/en/Documents/FANR-REG17%20V.1%20EN%20-%20BOM%20Version%20Certified.PDF"},{"id":"clearance","en":"Every route also needs a UAE security clearance (recorded only as confirmed or pending).","ar":"يتطلب كل مسار أيضاً تصريحاً أمنياً إماراتياً (يُسجَّل فقط كمؤكد أو قيد الانتظار).","rule_ref":"FANR-REG-17 Art. 4","url":"https://www.fanr.gov.ae/en/Documents/FANR-REG17%20V.1%20EN%20-%20BOM%20Version%20Certified.PDF"}]'::jsonb, 'high_school', false, false, true, false, '[{"id":"fanr-reg17","label":"FANR-REG-17 Certification of Operating Personnel at Nuclear Facilities (V1, in force 30 May 2024)","url":"https://www.fanr.gov.ae/en/Documents/FANR-REG17%20V.1%20EN%20-%20BOM%20Version%20Certified.PDF"},{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf"},{"id":"sr2024","label":"ENEC Sustainability Report 2024 (GRI data)","url":"https://www.enec.ae/doc/sustainability-program-2024-23102025-low-69009902e1673.pdf"}]'::jsonb, 'published', 1, 1, 'current'),
('shift-supervisor', 'operations', 'Shift Supervisor / Shift Manager', 'مشرف / مدير الوردية', 'Operations', 'العمليات', 'leadership', true, 'FANR-REG-17 (holds SRO certificate)', 'https://www.fanr.gov.ae/en/Documents/FANR-REG17%20V.1%20EN%20-%20BOM%20Version%20Certified.PDF', 'uncertain', 'Barakah title and structure unconfirmed; follows IAEA SSG-75.', 'Holds overall shift authority for the units and acts as emergency director until the emergency organisation activates.', 'يتولى السلطة الكاملة على الوردية في الوحدات ويعمل مديراً للطوارئ إلى أن تُفعَّل منظمة الطوارئ.', 'Normally SRO-certified. IAEA SSG-75: 4-6 years'' experience, 2-3 at an operating plant, at least 1 year on site.', 'يحمل عادةً شهادة مشغّل مفاعل أول. وفق دليل الوكالة SSG-75: خبرة من 4 إلى 6 سنوات، منها سنتان إلى ثلاث في محطة عاملة، وسنة على الأقل في الموقع.', 'Command experience as SRO; leadership programmes such as ESTADAD or ONE; licensee appointment.', 'خبرة قيادية كمشغّل أول؛ برامج قيادية مثل استعداد أو "نحو التميز النووي"؛ تعيين من المرخَّص له.', 'FANR (SRO certificate) and licensee appointment', 'الهيئة الاتحادية للرقابة النووية (شهادة مشغّل أول) وتعيين من المرخَّص له', '[]'::jsonb, 'high_school', false, false, true, false, '[{"id":"ssg75","label":"IAEA SSG-75 (2022) Recruitment, Qualification and Training of Personnel for NPPs","url":"https://www.iaea.org/node/109535"},{"id":"fanr-reg17","label":"FANR-REG-17 Certification of Operating Personnel at Nuclear Facilities (V1, in force 30 May 2024)","url":"https://www.fanr.gov.ae/en/Documents/FANR-REG17%20V.1%20EN%20-%20BOM%20Version%20Certified.PDF"}]'::jsonb, 'published', 1, 2, 'current'),
('reactor-operator', 'operations', 'Reactor Operator (RO)', 'مشغّل المفاعل', 'Operations', 'العمليات', 'professional', true, 'FANR-REG-17 Art. 4, 7, 8, 10, 11', 'https://www.fanr.gov.ae/en/Documents/FANR-REG17%20V.1%20EN%20-%20BOM%20Version%20Certified.PDF', 'barakah', null, 'Manipulates reactivity and plant controls in the main control room and monitors plant parameters.', 'يشغّل أدوات التحكم في التفاعلية وفي المحطة داخل غرفة التحكم الرئيسية ويراقب معايير المحطة.', 'REG-17 Art. 4: high-school diploma plus 36 months as a fully qualified LO (or an equivalent route) plus security clearance.', 'المادة 4 من اللائحة 17: شهادة الثانوية العامة مع 36 شهراً كمشغّل محلي مؤهَّل تأهيلاً كاملاً (أو مسار معادل) وتصريح أمني.', 'COIT 91 weeks / 2,912 h (SR2024); FANR written and operating exams; COCT; quarterly shift minimums.', 'التدريب الأولي للمشغّلين المعتمدين 91 أسبوعاً / 2,912 ساعة؛ اختبارات الهيئة؛ التدريب المستمر؛ الحد الأدنى من النوبات ربع السنوية.', 'FANR certificate, valid 5 years', 'شهادة من الهيئة الاتحادية للرقابة النووية صالحة لخمس سنوات', '[{"id":"ro_lo36","en":"High-school diploma plus 36 months as a fully qualified Local Operator","ar":"شهادة الثانوية العامة مع 36 شهراً كمشغّل محلي مؤهَّل تأهيلاً كاملاً","rule_ref":"FANR-REG-17 Art. 4","url":"https://www.fanr.gov.ae/en/Documents/FANR-REG17%20V.1%20EN%20-%20BOM%20Version%20Certified.PDF"},{"id":"ro_other_plant","en":"24 months as RO or SRO at another plant, plus 12 months at Barakah including 6 on crew","ar":"24 شهراً كمشغّل مفاعل أو مشغّل أول في محطة أخرى، مع 12 شهراً في براكة منها 6 أشهر ضمن طاقم","rule_ref":"FANR-REG-17 Art. 4","url":"https://www.fanr.gov.ae/en/Documents/FANR-REG17%20V.1%20EN%20-%20BOM%20Version%20Certified.PDF"},{"id":"ro_fossil","en":"24 months at a fossil or different-type nuclear plant, plus 12 months at Barakah including 9 on crew","ar":"24 شهراً في محطة وقود أحفوري أو محطة نووية من نوع مختلف، مع 12 شهراً في براكة منها 9 أشهر ضمن طاقم","rule_ref":"FANR-REG-17 Art. 4","url":"https://www.fanr.gov.ae/en/Documents/FANR-REG17%20V.1%20EN%20-%20BOM%20Version%20Certified.PDF"},{"id":"clearance","en":"Every route also needs a UAE security clearance (recorded only as confirmed or pending).","ar":"يتطلب كل مسار أيضاً تصريحاً أمنياً إماراتياً (يُسجَّل فقط كمؤكد أو قيد الانتظار).","rule_ref":"FANR-REG-17 Art. 4","url":"https://www.fanr.gov.ae/en/Documents/FANR-REG17%20V.1%20EN%20-%20BOM%20Version%20Certified.PDF"}]'::jsonb, 'high_school', false, false, true, false, '[{"id":"fanr-reg17","label":"FANR-REG-17 Certification of Operating Personnel at Nuclear Facilities (V1, in force 30 May 2024)","url":"https://www.fanr.gov.ae/en/Documents/FANR-REG17%20V.1%20EN%20-%20BOM%20Version%20Certified.PDF"},{"id":"sr2024","label":"ENEC Sustainability Report 2024 (GRI data)","url":"https://www.enec.ae/doc/sustainability-program-2024-23102025-low-69009902e1673.pdf"},{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf"}]'::jsonb, 'published', 1, 3, 'current'),
('local-operator', 'operations', 'Local Operator (LO)', 'مشغّل محلي', 'Operations', 'العمليات', 'entry', true, 'FANR-REG-17 Art. 12 (licensee qualification)', 'https://www.fanr.gov.ae/en/Documents/FANR-REG17%20V.1%20EN%20-%20BOM%20Version%20Certified.PDF', 'barakah', null, 'Operates equipment outside the main control room under the direction of ROs and SROs.', 'يشغّل المعدات خارج غرفة التحكم الرئيسية بتوجيه من مشغّلي المفاعل والمشغّلين الأوائل.', 'High-school diploma (REG-17). Qualified by the licensee, not certified by FANR.', 'شهادة الثانوية العامة (اللائحة 17). يؤهله المرخَّص له ولا تصدر له شهادة من الهيئة.', 'DNT 24 months, or LOIT 60 weeks / 1,920 h; LOCT 5-6 weeks a year; written exams and JPMs.', 'دبلوم التكنولوجيا النووية 24 شهراً أو التدريب الأولي للمشغّلين المحليين 60 أسبوعاً / 1,920 ساعة؛ تدريب مستمر 5-6 أسابيع سنوياً؛ اختبارات كتابية ومقاييس أداء وظيفي.', 'Licensee qualification (not FANR-certified)', 'تأهيل من المرخَّص له (لا يحمل شهادة من الهيئة)', '[{"id":"dnt","en":"Diploma in Nuclear Technology (24 months) for UAE high-school graduates","ar":"دبلوم التكنولوجيا النووية (24 شهراً) لخريجي الثانوية العامة من المواطنين","rule_ref":"ENEC talent pipeline","url":"https://www.enec.ae/careers-and-scholarships/talent-pipeline-programs/"},{"id":"loit","en":"Local Operator Initial Training (60 weeks / 1,920 h) for direct hires","ar":"التدريب الأولي للمشغّلين المحليين (60 أسبوعاً / 1,920 ساعة) للمعيّنين مباشرة","rule_ref":"SR2024 p.51","url":"https://www.enec.ae/doc/sustainability-program-2024-23102025-low-69009902e1673.pdf"},{"id":"gpo","en":"Graduate Plant Operator for Emirati engineering graduates (start as LO)","ar":"برنامج مشغّل المحطة للخريجين لخريجي الهندسة المواطنين (البدء كمشغّل محلي)","rule_ref":"ENEC GPO release (Aug 2025)","url":"https://www.enec.ae/careers-and-scholarships/talent-pipeline-programs/"}]'::jsonb, 'high_school', true, false, true, false, '[{"id":"fanr-reg17","label":"FANR-REG-17 Certification of Operating Personnel at Nuclear Facilities (V1, in force 30 May 2024)","url":"https://www.fanr.gov.ae/en/Documents/FANR-REG17%20V.1%20EN%20-%20BOM%20Version%20Certified.PDF"},{"id":"sr2024","label":"ENEC Sustainability Report 2024 (GRI data)","url":"https://www.enec.ae/doc/sustainability-program-2024-23102025-low-69009902e1673.pdf"},{"id":"enec-dnt-grad","label":"ENEC · First DNT cohort graduates (17 Jun 2026)","url":"https://www.enec.ae/en/news/latest-news/enec-celebrates-graduation-of-first-national-cohort-from-diploma-in-nuclear-technology-program/"}]'::jsonb, 'published', 1, 4, 'current'),
('shift-technical-advisor', 'operations', 'Shift Technical Advisor (STA)', 'المستشار الفني للوردية', 'Operations / Engineering', 'العمليات / الهندسة', 'senior', false, null, null, 'uncertain', 'A separate STA role at Barakah is unconfirmed; follows IAEA SSG-75.', 'Gives independent engineering advice to the shift on transients and accidents and monitors core and safety functions.', 'يقدّم مشورة هندسية مستقلة للوردية بشأن الحالات العابرة والحوادث ويراقب القلب ووظائف السلامة.', 'SSG-75: university degree plus training in transient and accident analysis.', 'وفق SSG-75: شهادة جامعية مع تدريب على تحليل الحالات العابرة والحوادث.', 'Engineering initial training; simulator transient training; licensee qualification card.', 'التدريب الهندسي الأولي؛ تدريب على المحاكي للحالات العابرة؛ بطاقة تأهيل من المرخَّص له.', 'Licensee; FANR oversight under REG-16', 'المرخَّص له؛ رقابة الهيئة بموجب اللائحة 16', '[]'::jsonb, 'bachelor', false, false, false, false, '[{"id":"ssg75","label":"IAEA SSG-75 (2022) Recruitment, Qualification and Training of Personnel for NPPs","url":"https://www.iaea.org/node/109535"},{"id":"fanr-reg16","label":"FANR-REG-16 Operational Safety","url":"https://www.fanr.gov.ae/en/Documents/REG-16-English.pdf"}]'::jsonb, 'published', 1, 5, 'current'),
('operations-support-work-control', 'operations', 'Operations Support / Work Control / Clearance Writer', 'دعم العمليات / التحكم في الأعمال / محرر العزل', 'Operations', 'العمليات', 'professional', false, null, null, 'barakah', null, 'Runs the work control centre, prepares clearances and tag-outs, and keeps operating procedures current.', 'يدير مركز التحكم في الأعمال ويعدّ عمليات العزل وبطاقات الحظر ويحافظ على تحديث إجراءات التشغيل.', 'Operations background, often a former LO or RO; licensee qualification card.', 'خلفية في العمليات، غالباً مشغّل محلي أو مشغّل مفاعل سابق؛ بطاقة تأهيل من المرخَّص له.', 'Work control qualification card; clearance writer JPMs.', 'بطاقة تأهيل التحكم في الأعمال؛ مقاييس أداء محرر العزل.', 'Licensee', 'المرخَّص له', '[]'::jsonb, 'high_school', false, false, false, false, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf"}]'::jsonb, 'published', 1, 6, 'current'),
('outage-manager-planner', 'outage', 'Outage Manager / Planner / Scheduler', 'مدير / مخطط / مجدول فترات الإيقاف', 'Outage & Work Management', 'إدارة فترات الإيقاف والأعمال', 'senior', false, null, null, 'barakah', null, 'Plans refuelling outages and coordinates contractors; Unit 2''s first refuelling outage involved about 8,000 maintenance tasks.', 'يخطط لفترات إيقاف إعادة التزويد بالوقود وينسق مع المقاولين؛ شملت أول فترة إيقاف للوحدة 2 نحو 8,000 مهمة صيانة.', 'Operations or maintenance background; INPO and WANO work-management practice.', 'خلفية في العمليات أو الصيانة؛ ممارسات إدارة الأعمال لدى معهد عمليات الطاقة النووية والرابطة العالمية لمشغلي المحطات النووية.', 'Work management training; outage planning qualification.', 'تدريب على إدارة الأعمال؛ تأهيل في تخطيط فترات الإيقاف.', 'Licensee', 'المرخَّص له', '[]'::jsonb, 'bachelor', false, false, false, false, '[{"id":"sr2024","label":"ENEC Sustainability Report 2024 (GRI data)","url":"https://www.enec.ae/doc/sustainability-program-2024-23102025-low-69009902e1673.pdf"},{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf"}]'::jsonb, 'published', 1, 7, 'current'),
('maintenance-technician-engineer', 'maintenance', 'Mechanical, Electrical and I&C Maintenance Technician and Engineer', 'فني ومهندس صيانة ميكانيكية وكهربائية وأجهزة وتحكم', 'Maintenance', 'الصيانة', 'professional', false, null, null, 'barakah', null, 'Carries out preventive, corrective and predictive maintenance, calibration and outage work.', 'يتولى الصيانة الوقائية والتصحيحية والتنبؤية والمعايرة وأعمال فترات الإيقاف.', 'Maintenance initial training 53 weeks / 1,969 h; DNT route for technicians; SSG-75: senior technicians 2-3 years.', 'تدريب الصيانة الأولي 53 أسبوعاً / 1,969 ساعة؛ مسار دبلوم التكنولوجيا النووية للفنيين؛ وفق SSG-75 خبرة الفنيين الأوائل 2-3 سنوات.', 'Task qualification cards; JPMs for safety-related work; continuing training (907 trainees in 2024).', 'بطاقات تأهيل المهام؛ مقاييس أداء للأعمال المتعلقة بالسلامة؛ تدريب مستمر (907 متدربين في 2024).', 'Licensee qualification; contractors through equivalency', 'تأهيل من المرخَّص له؛ المقاولون عبر المعادلة', '[]'::jsonb, 'diploma', true, false, true, false, '[{"id":"sr2024","label":"ENEC Sustainability Report 2024 (GRI data)","url":"https://www.enec.ae/doc/sustainability-program-2024-23102025-low-69009902e1673.pdf"},{"id":"ssg75","label":"IAEA SSG-75 (2022) Recruitment, Qualification and Training of Personnel for NPPs","url":"https://www.iaea.org/node/109535"}]'::jsonb, 'published', 1, 8, 'current'),
('systems-design-plant-engineer', 'engineering', 'Systems, Design and Plant Engineer', 'مهندس أنظمة وتصميم ومحطة', 'Engineering', 'الهندسة', 'professional', false, null, null, 'barakah', null, 'Looks after system health and design authority, modifications, ageing management and equipment qualification.', 'يتابع سلامة الأنظمة وسلطة التصميم والتعديلات وإدارة التقادم وتأهيل المعدات.', 'Engineering degree.', 'شهادة في الهندسة.', 'Engineering initial training 20 weeks / 640 h; continuing training (447 engineers in 2024).', 'التدريب الهندسي الأولي 20 أسبوعاً / 640 ساعة؛ تدريب مستمر (447 مهندساً في 2024).', 'Licensee; FANR approval of licensing-basis changes', 'المرخَّص له؛ موافقة الهيئة على تغييرات أساس الترخيص', '[]'::jsonb, 'bachelor', true, false, false, false, '[{"id":"sr2024","label":"ENEC Sustainability Report 2024 (GRI data)","url":"https://www.enec.ae/doc/sustainability-program-2024-23102025-low-69009902e1673.pdf"},{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf"}]'::jsonb, 'published', 1, 9, 'current'),
('reactor-engineer-core-physicist', 'engineering', 'Reactor Engineer / Core Physicist', 'مهندس مفاعل / فيزيائي القلب', 'Reactor Engineering', 'هندسة المفاعل', 'professional', false, null, null, 'generic', 'Nuclear Fuel Design track detail from search digests only.', 'Supports Operations with core design checks, start-up physics tests, fuel performance and reactivity management.', 'يدعم العمليات بفحوص تصميم القلب واختبارات فيزياء بدء التشغيل وأداء الوقود وإدارة التفاعلية.', 'Degree, often an MSc.', 'شهادة جامعية، غالباً ماجستير.', 'Engineering initial training; reactor engineering qualification standard.', 'التدريب الهندسي الأولي؛ معيار تأهيل هندسة المفاعل.', 'Licensee', 'المرخَّص له', '[]'::jsonb, 'master', false, false, true, false, '[{"id":"ssg75","label":"IAEA SSG-75 (2022) Recruitment, Qualification and Training of Personnel for NPPs","url":"https://www.iaea.org/node/109535"},{"id":"sr2024","label":"ENEC Sustainability Report 2024 (GRI data)","url":"https://www.enec.ae/doc/sustainability-program-2024-23102025-low-69009902e1673.pdf"}]'::jsonb, 'published', 1, 10, 'current'),
('nuclear-fuel-specialist', 'nuclear-fuel', 'Nuclear Fuel / Fuel Handling Specialist', 'أخصائي الوقود النووي / مناولة الوقود', 'Nuclear Fuel', 'الوقود النووي', 'professional', true, 'FANR-REG-10 (nuclear material accounting)', null, 'generic', null, 'Covers fuel procurement and receipt, refuelling (about one third of the core per outage), the spent-fuel pool and dry-storage planning.', 'يغطي شراء الوقود واستلامه وإعادة التزويد بالوقود (نحو ثلث القلب في كل فترة إيقاف) وحوض الوقود المستهلك وتخطيط التخزين الجاف.', 'Degree; fuel handling is also part of COIT for operators.', 'شهادة جامعية؛ مناولة الوقود جزء من تدريب المشغّلين المعتمدين أيضاً.', 'Engineering initial training; fuel handling qualification.', 'التدريب الهندسي الأولي؛ تأهيل مناولة الوقود.', 'Licensee; FANR-REG-10 nuclear material accounting', 'المرخَّص له؛ اللائحة 10 لمحاسبة المواد النووية', '[]'::jsonb, 'bachelor', false, false, false, false, '[{"id":"ssg75","label":"IAEA SSG-75 (2022) Recruitment, Qualification and Training of Personnel for NPPs","url":"https://www.iaea.org/node/109535"},{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf"}]'::jsonb, 'published', 1, 11, 'current'),
('cyber-security-engineer', 'cyber', 'Cyber Security / IT-OT Engineer', 'مهندس الأمن السيبراني / تقنية المعلومات والتشغيل', 'IT/OT & Cyber', 'تقنية المعلومات والتشغيل والأمن السيبراني', 'professional', true, 'FANR-REG-08 V2 (adds cyber security)', null, 'generic', null, 'Maintains the cyber security programme and protects digital systems and plant networks under an ISO/IEC 27001 management system.', 'يدير برنامج الأمن السيبراني ويحمي الأنظمة الرقمية وشبكات المحطة ضمن نظام إدارة وفق ISO/IEC 27001.', 'Degree and cyber certifications; ENEC holds ISO/IEC 27001.', 'شهادة جامعية وشهادات في الأمن السيبراني؛ تحمل ENEC شهادة ISO/IEC 27001.', 'Cyber security qualification (general content only in Kafa''a).', 'تأهيل في الأمن السيبراني (محتوى عام فقط في كفاءة).', 'FANR-REG-08 V2', 'اللائحة 08 الإصدار 2 للهيئة', '[]'::jsonb, 'bachelor', false, false, false, true, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf"}]'::jsonb, 'published', 1, 12, 'current'),
('radiation-protection-technician', 'radiation-protection', 'Radiation Protection Technician / Health Physicist / ALARA', 'فني وقاية من الإشعاع / فيزيائي صحي / أخصائي ALARA', 'Radiation Protection', 'الوقاية من الإشعاع', 'professional', true, 'FANR radiation protection regulations', null, 'barakah', null, 'Performs surveys, issues radiation work permits, manages dosimetry and contamination control, and plans ALARA work.', 'يجري المسوحات ويصدر تصاريح العمل الإشعاعي ويدير قياس الجرعات ومكافحة التلوث ويخطط للعمل وفق مبدأ ALARA.', 'RP officers are usually graduates (SSG-75).', 'مسؤولو الوقاية من الإشعاع عادةً من حملة الشهادات الجامعية (SSG-75).', 'RP initial training 36 weeks / 1,056 h; continuing training (111 staff in 2024).', 'تدريب الوقاية من الإشعاع الأولي 36 أسبوعاً / 1,056 ساعة؛ تدريب مستمر (111 موظفاً في 2024).', 'Licensee; FANR radiation protection regulations', 'المرخَّص له؛ لوائح الهيئة للوقاية من الإشعاع', '[]'::jsonb, 'diploma', true, false, true, false, '[{"id":"sr2024","label":"ENEC Sustainability Report 2024 (GRI data)","url":"https://www.enec.ae/doc/sustainability-program-2024-23102025-low-69009902e1673.pdf"},{"id":"ssg75","label":"IAEA SSG-75 (2022) Recruitment, Qualification and Training of Personnel for NPPs","url":"https://www.iaea.org/node/109535"}]'::jsonb, 'published', 1, 13, 'current'),
('chemistry-technician', 'chemistry', 'Chemistry Technician / Chemist', 'فني كيمياء / كيميائي', 'Chemistry', 'الكيمياء', 'professional', true, 'FANR-REG-16 Art. 9 (chemistry training)', 'https://www.fanr.gov.ae/en/Documents/REG-16-English.pdf', 'barakah', null, 'Controls primary and secondary water chemistry, performs radiochemistry and monitors effluents.', 'يضبط كيمياء المياه في الدائرتين الأولية والثانوية ويجري التحاليل الكيميائية الإشعاعية ويرصد المخلفات.', 'Chemistry graduates; GDP route.', 'خريجو الكيمياء؛ مسار برنامج تطوير الخريجين.', 'Chemistry initial training 28 weeks / 896 h (REG-16 Art. 9); continuing training (65 staff in 2024).', 'تدريب الكيمياء الأولي 28 أسبوعاً / 896 ساعة (المادة 9 من اللائحة 16)؛ تدريب مستمر (65 موظفاً في 2024).', 'Licensee; FANR-REG-16 chemistry programme', 'المرخَّص له؛ برنامج الكيمياء وفق اللائحة 16', '[]'::jsonb, 'bachelor', true, false, false, false, '[{"id":"sr2024","label":"ENEC Sustainability Report 2024 (GRI data)","url":"https://www.enec.ae/doc/sustainability-program-2024-23102025-low-69009902e1673.pdf"},{"id":"fanr-reg16","label":"FANR-REG-16 Operational Safety","url":"https://www.fanr.gov.ae/en/Documents/REG-16-English.pdf"}]'::jsonb, 'published', 1, 14, 'current'),
