insert into kafaa_competencies (id, code, domain, domain_en, domain_ar, name_en, name_ar, description_en, description_ar, levels) values
('pf-01', 'PF-01', 'plant', 'Plant fundamentals and APR-1400 systems', 'أساسيات المحطة وأنظمة APR-1400', 'Reactor theory and nuclear physics fundamentals', 'نظرية المفاعل وأساسيات الفيزياء النووية', 'Reactor theory and nuclear physics fundamentals: what a person in a nuclear role needs to know and do, from awareness to expert.', 'نظرية المفاعل وأساسيات الفيزياء النووية: ما يحتاج الشخص في دور نووي إلى معرفته وأدائه، من الإلمام إلى الخبرة.', '[{"level":1,"en":"Explains the purpose and basic principles of reactor theory and nuclear physics fundamentals.","ar":"يشرح الغرض والمبادئ الأساسية لـنظرية المفاعل وأساسيات الفيزياء النووية."},{"level":2,"en":"Applies reactor theory and nuclear physics fundamentals under supervision using approved procedures.","ar":"يطبّق نظرية المفاعل وأساسيات الفيزياء النووية تحت الإشراف باستخدام الإجراءات المعتمدة."},{"level":3,"en":"Applies reactor theory and nuclear physics fundamentals independently and recognises when to stop and ask.","ar":"يطبّق نظرية المفاعل وأساسيات الفيزياء النووية باستقلالية ويعرف متى يتوقف ويسأل."},{"level":4,"en":"Coaches, trains and evaluates others in reactor theory and nuclear physics fundamentals.","ar":"يوجّه الآخرين ويدربهم ويقيّمهم في نظرية المفاعل وأساسيات الفيزياء النووية."}]'::jsonb),
('pf-02', 'PF-02', 'plant', 'Plant fundamentals and APR-1400 systems', 'أساسيات المحطة وأنظمة APR-1400', 'Thermodynamics, heat transfer and fluid flow', 'الديناميكا الحرارية وانتقال الحرارة وجريان الموائع', 'Thermodynamics, heat transfer and fluid flow: what a person in a nuclear role needs to know and do, from awareness to expert.', 'الديناميكا الحرارية وانتقال الحرارة وجريان الموائع: ما يحتاج الشخص في دور نووي إلى معرفته وأدائه، من الإلمام إلى الخبرة.', '[{"level":1,"en":"Explains the purpose and basic principles of thermodynamics, heat transfer and fluid flow.","ar":"يشرح الغرض والمبادئ الأساسية لـالديناميكا الحرارية وانتقال الحرارة وجريان الموائع."},{"level":2,"en":"Applies thermodynamics, heat transfer and fluid flow under supervision using approved procedures.","ar":"يطبّق الديناميكا الحرارية وانتقال الحرارة وجريان الموائع تحت الإشراف باستخدام الإجراءات المعتمدة."},{"level":3,"en":"Applies thermodynamics, heat transfer and fluid flow independently and recognises when to stop and ask.","ar":"يطبّق الديناميكا الحرارية وانتقال الحرارة وجريان الموائع باستقلالية ويعرف متى يتوقف ويسأل."},{"level":4,"en":"Coaches, trains and evaluates others in thermodynamics, heat transfer and fluid flow.","ar":"يوجّه الآخرين ويدربهم ويقيّمهم في الديناميكا الحرارية وانتقال الحرارة وجريان الموائع."}]'::jsonb),
