insert into kafaa_task_items (id, standard_id, code, statement_en, statement_ar, conditions_en, standards_en, method, evaluator_role, critical, sort) values
('qs-lo-turbine-t1', 'qs-lo-turbine', 'LO-WS-TB-T1', 'Perform a routine operator round and record parameters', 'إجراء جولة المشغّل الروتينية وتسجيل المعايير', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'ojt', 'Qualified LO evaluator', false, 1),
('qs-lo-turbine-t2', 'qs-lo-turbine', 'LO-WS-TB-T2', 'Start and stop a secondary-side pump using the approved procedure', 'تشغيل مضخة في الجانب الثانوي وإيقافها باستخدام الإجراء المعتمد', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'jpm', 'Instructor / evaluator', true, 2),
('qs-lo-turbine-t3', 'qs-lo-turbine', 'LO-WS-TB-T3', 'Hang and remove a clearance under supervision', 'وضع العزل وإزالته تحت الإشراف', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'jpm', 'Instructor / evaluator', true, 3),
('qs-lo-turbine-t4', 'qs-lo-turbine', 'LO-WS-TB-T4', 'Respond to a local alarm and report to the control room', 'الاستجابة لإنذار محلي وإبلاغ غرفة التحكم', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'simulator', 'Instructor / evaluator', false, 4),
('qs-lo-turbine-t5', 'qs-lo-turbine', 'LO-WS-TB-T5', 'Apply three-way communication and peer checking', 'تطبيق الاتصال الثلاثي والتحقق من الزميل', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'ojt', 'Qualified LO evaluator', false, 5),
('qs-lo-aux-t1', 'qs-lo-aux', 'LO-WS-AUX-T1', 'Perform a routine operator round and record parameters', 'إجراء جولة المشغّل الروتينية وتسجيل المعايير', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'ojt', 'Qualified LO evaluator', false, 1),
('qs-lo-aux-t2', 'qs-lo-aux', 'LO-WS-AUX-T2', 'Align a system valve line-up per procedure with independent verification', 'ضبط اصطفاف صمامات نظام وفق الإجراء مع تحقق مستقل', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'jpm', 'Instructor / evaluator', true, 2),
('qs-lo-aux-t3', 'qs-lo-aux', 'LO-WS-AUX-T3', 'Observe radiological controls when entering a controlled area', 'مراعاة الضوابط الإشعاعية عند دخول منطقة خاضعة للرقابة', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'ojt', 'RP technician', false, 3),
('qs-lo-aux-t4', 'qs-lo-aux', 'LO-WS-AUX-T4', 'Report an equipment deficiency through the corrective action programme', 'الإبلاغ عن عيب في المعدات عبر برنامج الإجراءات التصحيحية', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'classroom', 'Instructor / evaluator', false, 4),
('qs-ro-t1', 'qs-ro', 'RO-QC-T1', 'Perform a reactor start-up on the full-scope simulator', 'تنفيذ بدء تشغيل المفاعل على المحاكي كامل النطاق', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'simulator', 'SRO-qualified instructor', true, 1),
('qs-ro-t2', 'qs-ro', 'RO-QC-T2', 'Respond to a reactor trip using emergency operating procedures (simulator)', 'الاستجابة لتوقف المفاعل باستخدام إجراءات التشغيل في الطوارئ (المحاكي)', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'simulator', 'SRO-qualified instructor', true, 2),
('qs-ro-t3', 'qs-ro', 'RO-QC-T3', 'Perform a reactivity manipulation with peer verification', 'تنفيذ تعديل في التفاعلية مع تحقق الزميل', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'jpm', 'SRO-qualified instructor', true, 3),
('qs-ro-t4', 'qs-ro', 'RO-QC-T4', 'Conduct a shift turnover', 'إجراء تسليم النوبة', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'ojt', 'Shift supervisor', false, 4),
('qs-ro-t5', 'qs-ro', 'RO-QC-T5', 'Pass the internal comprehensive written exam', 'اجتياز الاختبار الكتابي الداخلي الشامل', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'written', 'Instructor / evaluator', false, 5),
('qs-sro-t1', 'qs-sro', 'SRO-QC-T1', 'Direct the crew through an emergency scenario (simulator)', 'توجيه الطاقم خلال سيناريو طوارئ (المحاكي)', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'simulator', 'SRO-qualified instructor', true, 1),
('qs-sro-t2', 'qs-sro', 'SRO-QC-T2', 'Apply technical specifications to a plant condition', 'تطبيق المواصفات الفنية على حالة في المحطة', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'jpm', 'SRO-qualified instructor', true, 2),
('qs-sro-t3', 'qs-sro', 'SRO-QC-T3', 'Lead a pre-job brief graded to risk', 'قيادة إحاطة ما قبل العمل المتدرجة حسب المخاطر', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'ojt', 'Shift supervisor', false, 3),
('qs-sro-t4', 'qs-sro', 'SRO-QC-T4', 'Make and document a conservative operating decision', 'اتخاذ قرار تشغيلي متحفظ وتوثيقه', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'simulator', 'SRO-qualified instructor', false, 4),
('qs-mech-t1', 'qs-mech', 'MNT-MECH-T1', 'Disassemble and reassemble a centrifugal pump per work package', 'فك مضخة طاردة مركزية وإعادة تجميعها وفق حزمة العمل', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'jpm', 'Instructor / evaluator', true, 1),
('qs-mech-t2', 'qs-mech', 'MNT-MECH-T2', 'Perform a valve packing adjustment', 'ضبط حشوة صمام', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'ojt', 'Qualified maintenance evaluator', false, 2),
('qs-mech-t3', 'qs-mech', 'MNT-MECH-T3', 'Apply foreign material exclusion controls', 'تطبيق ضوابط منع دخول المواد الغريبة', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'ojt', 'Qualified maintenance evaluator', true, 3),
('qs-mech-t4', 'qs-mech', 'MNT-MECH-T4', 'Complete work package documentation', 'إكمال وثائق حزمة العمل', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'classroom', 'Instructor / evaluator', false, 4),
('qs-elec-t1', 'qs-elec', 'MNT-ELEC-T1', 'Perform a motor insulation resistance test', 'إجراء اختبار مقاومة العزل لمحرك', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'jpm', 'Instructor / evaluator', true, 1),
('qs-elec-t2', 'qs-elec', 'MNT-ELEC-T2', 'Apply electrical safe work practices and verify zero energy', 'تطبيق ممارسات العمل الكهربائي الآمن والتحقق من انعدام الطاقة', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'jpm', 'Instructor / evaluator', true, 2),
('qs-elec-t3', 'qs-elec', 'MNT-ELEC-T3', 'Perform breaker preventive maintenance', 'إجراء الصيانة الوقائية للقواطع', 'Given the approved procedure and required tools.', 'Performed without error on critical steps.', 'ojt', 'Qualified maintenance evaluator', false, 3),
