insert into kafaa_advisor_turns (id, session_id, person_id, speaker, text, citations, refused, refusal_category, ts, intent, confidence, redacted, mode, submode) values
('at-1-1', 'as-1', 'p-k-ro', 'user', 'What are the SRO entry requirements?', '[]'::jsonb, false, null, '2026-10-07T08:00:00Z', null, null, false, 'staff', null),
('at-1-2', 'as-1', 'p-k-ro', 'dalil', 'FANR-REG-17 Art. 4 gives three SRO routes: 24 months as RO at Barakah; a BSc plus 24 months at Barakah including 12 as LO; or 24 months as RO/SRO/SRO-QI elsewhere plus 12 at Barakah including 6 on crew. Every route needs UAE security clearance. ENEC and FANR determine eligibility.', '[{"label":"FANR-REG-17","url":"https://www.fanr.gov.ae/en/Documents/FANR-REG17%20V.1%20EN%20-%20BOM%20Version%20Certified.PDF"}]'::jsonb, false, null, '2026-10-07T08:00:00Z', 'role', null, false, 'staff', null),
('at-2-1', 'as-2', null, 'user', 'What are the security arrangements at the plant?', '[]'::jsonb, false, null, '2026-10-07T11:00:00Z', 'refusal', null, false, 'public', null),
('at-2-2', 'as-2', null, 'dalil', 'I can''t discuss plant security. If you are interested in a security career, the Career Map shows the path and the public requirements.', '[{"label":"Security Officer / Physical Protection","url":"/kafaa/careers/roles/security-officer"}]'::jsonb, true, 'security', '2026-10-07T11:00:00Z', 'refusal', null, false, 'public', null),
('at-3-1', 'as-3', 'p-k-graduate', 'user', 'When does the next GPO intake open?', '[]'::jsonb, false, null, '2026-10-07T14:00:00Z', 'programme', 0.4, false, 'applicant', null),
('at-3-2', 'as-3', 'p-k-graduate', 'dalil', 'The GPO programme page gives eligibility and duration, but no approved source states the next intake date. I can pass this to the careers team if you agree.', '[{"label":"Graduate Plant Operator (GPO)","url":"/kafaa/pathways/gpo"}]'::jsonb, false, null, '2026-10-07T14:00:00Z', 'programme', 0.4, false, 'applicant', null),
('as-career-1-1', 'as-career-1', 'w-ro-02', 'user', 'What do I need for SRO?', '[]'::jsonb, false, null, '2026-10-06T07:30:00Z', 'career.gap_to_role', null, false, 'staff', 'career'),
('as-career-1-2', 'as-career-1', 'w-ro-02', 'dalil', 'Senior Reactor Operator: your route is "24 months as RO at Barakah + SRO exams". Gates: 24 months as RO (met), SRO-level COIT content (to do), FANR SRO exams (to do), UAE security clearance (licensee check). Top gaps: Leadership and teamwork (2 to 3), Plant systems knowledge (3 to 4). Indicative only: ENEC and FANR decide.', '[{"label":"FANR-REG-17 Art. 4","url":"https://www.fanr.gov.ae/en/Documents/FANR-REG17%20V.1%20EN%20-%20BOM%20Version%20Certified.PDF"},{"label":"Senior Reactor Operator","url":"/careers/roles/senior-reactor-operator"},{"label":"My Skills Passport","url":"/my/skills"}]'::jsonb, false, null, '2026-10-06T07:30:00Z', 'career.gap_to_role', 1, false, 'staff', 'career'),
('as-career-1-3', 'as-career-1', 'w-ro-02', 'user', 'When could I be SRO?', '[]'::jsonb, false, null, '2026-10-06T07:30:00Z', 'career.roadmap_date', null, false, 'staff', 'career'),
('as-career-1-4', 'as-career-1', 'w-ro-02', 'dalil', 'On the default roadmap your SRO certification falls in 2028-Q1 (indicative): the SRO programme starts at the next intake, then the FANR exams 90 days after it.', '[{"label":"My career roadmap","url":"/my/career/roadmap"},{"label":"FANR-REG-17 Art. 4","url":"https://www.fanr.gov.ae/en/Documents/FANR-REG17%20V.1%20EN%20-%20BOM%20Version%20Certified.PDF"}]'::jsonb, false, null, '2026-10-06T07:30:00Z', 'career.roadmap_date', 1, false, 'staff', 'career'),
('as-career-2-1', 'as-career-2', 'w-lo-03', 'user', 'Which opportunities fit me?', '[]'::jsonb, false, null, '2026-10-07T11:10:00Z', 'career.opportunities', null, false, 'staff', 'career'),
('as-career-2-2', 'as-career-2', 'w-lo-03', 'dalil', 'Three open opportunities match your skills: the outage support role in Unit 2 (82% match), the OE review project (76%) and the turbine shadowing week (71%).', '[{"label":"Opportunity marketplace","url":"/opportunities"}]'::jsonb, false, null, '2026-10-07T11:10:00Z', 'career.opportunities', 1, false, 'staff', 'career'),
('as-career-3-1', 'as-career-3', 'w-mnt-02', 'user', 'Where can I go next?', '[]'::jsonb, false, null, '2026-10-08T05:45:00Z', 'career.next_roles', null, false, 'staff', 'career'),
('as-career-3-2', 'as-career-3', 'w-mnt-02', 'dalil', 'From Maintenance Technician the closest moves are Maintenance Supervisor (ready in about 12 months) and Planning and Scheduling Engineer (stretch).', '[{"label":"My Career Navigator","url":"/my/career"}]'::jsonb, false, null, '2026-10-08T05:45:00Z', 'career.next_roles', 1, false, 'staff', 'career')
