insert into kafaa_feature_flags (id, key, label_en, label_ar, description_en, description_ar, enabled, locked, area, updated_at, updated_by) values
('ff-dalil_public', 'dalil_public', 'Dalil for anonymous visitors', 'دليل للزوار غير المسجلين', 'When off, Dalil asks visitors to sign in before answering. The global kill switch is separate (Dalil settings).', 'عند الإيقاف يطلب دليل من الزوار تسجيل الدخول قبل الإجابة. مفتاح الإيقاف العام منفصل (إعدادات دليل).', true, false, 'dalil', '2026-10-01T08:00:00Z', null),
('ff-dalil_handoff', 'dalil_handoff', 'Dalil human hand-off', 'إحالة دليل إلى شخص', 'Lets users ask for the careers team, a training coordinator or the partner desk, with consent to pass on the conversation.', 'يتيح للمستخدمين طلب فريق المهن أو منسق التدريب أو مكتب الشركاء مع الموافقة على تمرير المحادثة.', true, false, 'dalil', '2026-10-01T08:00:00Z', null),
('ff-contact_form', 'contact_form', 'Public contact form', 'نموذج الاتصال العام', 'When off, the contact page shows official channels only.', 'عند الإيقاف تعرض صفحة الاتصال القنوات الرسمية فقط.', true, false, 'public', '2026-10-01T08:00:00Z', null),
('ff-news', 'news', 'News section on public pages', 'قسم الأخبار في الصفحات العامة', 'Sourced news items on the home page and /news.', 'أخبار موثقة في الصفحة الرئيسية وصفحة الأخبار.', true, false, 'public', '2026-10-01T08:00:00Z', null),
('ff-nexus_links', 'nexus_links', 'Links into ENEC NEXUS', 'روابط إلى ENEC NEXUS', 'Shows deep links into NEXUS Academy, partner readiness and the directory.', 'يعرض روابط مباشرة إلى أكاديمية NEXUS وجاهزية الشركاء والدليل.', true, false, 'nexus', '2026-10-01T08:00:00Z', null),
('ff-self_export', 'self_export', 'Self-service data export', 'تصدير البيانات ذاتياً', 'Lets signed-in users download their own data from My settings.', 'يتيح للمستخدمين تنزيل بياناتهم من "إعداداتي".', true, false, 'privacy', '2026-10-01T08:00:00Z', null),
('ff-speak_up_no_telemetry', 'speak_up_no_telemetry', 'Speak-up: no telemetry (locked)', 'رفع المخاوف: بلا قياس (مقفل)', 'The speak-up route never sends analytics or audit events. Locked on by design.', 'لا يرسل مسار رفع المخاوف أي قياسات أو أحداث تدقيق. مفعّل دائماً بحكم التصميم.', true, true, 'safety', '2026-10-01T08:00:00Z', null),
('ff-gamification_qualification', 'gamification_qualification', 'Points and badges on qualification work (locked off)', 'النقاط والشارات على أعمال التأهيل (مقفل)', 'Qualification is not a game. Locked off by design.', 'التأهيل ليس لعبة. مقفل بحكم التصميم.', false, true, 'safety', '2026-10-01T08:00:00Z', null)
insert into kafaa_skills (id, code, competency_id, name_en, name_ar, area, core, key_level, evidence_keys, adjacent_ids, adv_skill_ids, description_en, description_ar, sources, sort, reusability, skill_type, lifecycle, decay_class, owner_role, version, review_due, level_essence_en, level_essence_ar, alt_labels_en, alt_labels_ar, future_group, fs_area, benchmark_ids, obsolete_on, replaced_by) values
('sk-pf-01', 'PF-01', 'pf-01', 'Reactor theory and nuclear physics fundamentals', 'نظرية المفاعل وأساسيات الفيزياء النووية', 'plant_systems', true, 2, '{}'::text[], array['sk-pf-01-core','sk-pf-01-advfuel','sk-pf-02','sk-pf-02-advcool','sk-pf-03','sk-pf-03-rcs']::text[], '{}'::text[], 'Reactor theory and nuclear physics fundamentals: what a person in a nuclear role needs to know and do, from awareness to expert.', 'نظرية المفاعل وأساسيات الفيزياء النووية: ما يحتاج الشخص في دور نووي إلى معرفته وأدائه، من الإلمام إلى الخبرة.', '[{"id":"ssg75","label":"IAEA SSG-75 (2022) Recruitment, Qualification and Training of Personnel for NPPs","url":"https://www.iaea.org/node/109535"},{"id":"enec-technology","label":"ENEC · Barakah technology","url":"https://www.enec.ae/barakah-plant/technology/"}]'::jsonb, 0, 'sector_specific', 'specialised', 'stable', 'slow', 'nuclear_training', 1, '2029-01-15', 'Practitioner: applies reactor theory and nuclear physics fundamentals on routine work with some supervision, using procedures and checking own work.', 'ممارس: يطبّق نظرية المفاعل وأساسيات الفيزياء النووية في الأعمال الروتينية بإشراف محدود، ملتزماً بالإجراءات ومراجعاً عمله.', '{}'::text[], '{}'::text[], 'nuclear_excellence', null, array['IAEA-WFP']::text[], null, null),
