insert into kafaa_benchmarks (id, name_en, name_ar, owner_en, owner_ar, country_en, country_ar, category, year_from, year_to, year_kind, urls, fact_en, fact_ar, borrow_en, borrow_ar, figures, feature_ids, as_of, status, listed, sort, updated_at, updated_by) values
('WEF-FOJ', 'WEF Future of Jobs Report 2025', 'تقرير مستقبل الوظائف 2025 الصادر عن المنتدى الاقتصادي العالمي', 'World Economic Forum', 'المنتدى الاقتصادي العالمي', 'International', 'دولي', 'global', 2025, null, 'single', array['https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/']::text[], '39% of workers'' core skills expected to change by 2030; AI and big data, networks and cybersecurity, technological literacy grow fastest; environmental stewardship enters the top 10.', 'يُتوقع أن تتغير 39% من المهارات الأساسية للعاملين بحلول 2030؛ وتنمو أسرع مهارات الذكاء الاصطناعي والبيانات الضخمة، والشبكات والأمن السيبراني، والإلمام التقني؛ وتدخل الإشراف البيئي قائمة العشر الأوائل.', 'Core-skill change per role, a rising/stable/declining trend field on every skill, and a transversal core-skills family.', 'قياس تغيّر المهارات الأساسية لكل دور، وحقل اتجاه (صاعد/مستقر/متراجع) على كل مهارة، وعائلة مهارات أساسية مستعرضة.', '[{"key":"core_skills_change_2030","value":39,"unit":"pct","label_en":"Workers'' core skills expected to change by 2030","label_ar":"المهارات الأساسية للعاملين المتوقع تغيّرها بحلول 2030","quote_en":"39","scale_max":100}]'::jsonb, array['FS02','FS03','FS25','FS35','FS41','FS46','FS53','FS70']::text[], '2026-10-10', 'published', true, 10, '2026-10-10T00:00:00Z', null),
('OECD-PIAAC', 'OECD Survey of Adult Skills (PIAAC), Cycle 2', 'مسح منظمة التعاون الاقتصادي والتنمية لمهارات البالغين (PIAAC)، الدورة الثانية', 'OECD', 'منظمة التعاون الاقتصادي والتنمية', '31 countries', '31 دولة', 'global', 2024, null, 'single', array['https://www.oecd.org/en/data/datasets/PIAAC-2nd-Cycle-Database.html','https://www.cso.ie/en/releasesandpublications/ep/p-piaac/programmefortheinternationalassessmentofadultcompetenciespiaac2023/keyfindings']::text[], 'Adds adaptive problem solving as a measured domain (OECD average 251); 29% of adults at Level 1 or below.', 'يضيف حلّ المشكلات التكيّفي مجالاً مقيساً (متوسط دول المنظمة 251)؛ و29% من البالغين في المستوى الأول أو أدنى.', 'Adaptive problem solving as its own assessed scale, and a benchmark line on every score shown to a person.', 'حلّ المشكلات التكيّفي مقياساً مستقلاً يُقيَّم، وخط مرجعي بجانب كل درجة تُعرض على الشخص.', '[{"key":"aps_oecd_average","value":251,"unit":"score","label_en":"Adaptive problem solving, OECD average score","label_ar":"حلّ المشكلات التكيّفي، متوسط دول المنظمة","quote_en":"251","scale_max":500},{"key":"adults_level1_or_below","value":29,"unit":"pct","label_en":"Adults at Level 1 or below","label_ar":"البالغون في المستوى الأول أو أدنى","quote_en":"29","scale_max":100}]'::jsonb, array['FS01','FS10','FS21','FS58']::text[], '2026-10-10', 'published', true, 20, '2026-10-10T00:00:00Z', null),
('OECD-AICI', 'OECD AI Capability Indicators', 'مؤشرات قدرات الذكاء الاصطناعي لمنظمة التعاون الاقتصادي والتنمية', 'OECD', 'منظمة التعاون الاقتصادي والتنمية', 'International', 'دولي', 'global', 2025, null, 'single', array['https://digital-skills-jobs.europa.eu/en/latest/research/oecd-ai-capability-indicators-technical-report']::text[], 'Ten capability dimensions, each on a five-level scale, built so human-skill and AI-capability frameworks can be compared on the same axes.', 'عشرة أبعاد للقدرات، لكلٍّ منها مقياس من خمسة مستويات، صُممت لتُقارَن أطر المهارات البشرية وقدرات الذكاء الاصطناعي على المحاور نفسها.', 'A five-level AI capability rating per task, compared with the human requirement to flag augmentable tasks.', 'تقييم قدرة الذكاء الاصطناعي على خمسة مستويات لكل مهمة، ومقارنته بالمتطلب البشري لتحديد المهام القابلة للتعزيز.', '[{"key":"capability_dimensions","value":10,"unit":"count","label_en":"AI capability dimensions","label_ar":"أبعاد قدرات الذكاء الاصطناعي","quote_en":"Ten"},{"key":"scale_levels","value":5,"unit":"count","label_en":"Levels on each scale","label_ar":"مستويات كل مقياس","quote_en":"five"}]'::jsonb, array['FS06','FS12','FS52']::text[], '2026-10-10', 'published', true, 30, '2026-10-10T00:00:00Z', null),
('ILO-RPL', 'ILO Skills and Lifelong Learning Strategy 2030; recognition of prior learning', 'استراتيجية منظمة العمل الدولية للمهارات والتعلم مدى الحياة 2030؛ الاعتراف بالتعلم السابق', 'International Labour Organization', 'منظمة العمل الدولية', 'International', 'دولي', 'global', 2023, null, 'single', array['https://www.ilo.org/global-skills-programme','https://www.ilo.org/publications/experience-opportunity-unlocking-skills-through-recognition-prior-learning']::text[], 'Names quality-assured assessment, certification and recognition of prior learning (RPL) as one of five pillars; programme covers 61 countries.', 'تجعل التقييم المضمون الجودة والإشهاد والاعتراف بالتعلم السابق إحدى خمس ركائز؛ ويغطي البرنامج 61 دولة.', 'A structured RPL flow (request, evidence, assessor, credit) and re-assessment on each skill''s own validity clock.', 'مسار منظم للاعتراف بالتعلم السابق (طلب، أدلة، مقيّم، رصيد) وإعادة التقييم وفق مدة صلاحية كل مهارة.', '[{"key":"countries","value":61,"unit":"count","label_en":"Countries covered by the programme","label_ar":"الدول التي يغطيها البرنامج","quote_en":"61"},{"key":"pillars","value":5,"unit":"count","label_en":"Pillars of the strategy","label_ar":"ركائز الاستراتيجية","quote_en":"five"}]'::jsonb, array['FS29']::text[], '2026-10-10', 'published', true, 40, '2026-10-10T00:00:00Z', null),
('EU-PACT', 'EU Pact for Skills', 'ميثاق المهارات الأوروبي', 'European Commission', 'المفوضية الأوروبية', 'EU', 'الاتحاد الأوروبي', 'global', 2025, null, 'single', array['https://pact-for-skills.ec.europa.eu/about/news-and-factsheets/more-61-million-workers-trained-under-pact-skills-2025-05-19_en']::text[], 'Over 10 million people trained cumulatively by 2025; 4,000+ member organisations; large-scale partnerships train about a quarter to a third of their workforce a year.', 'أكثر من 10 ملايين شخص تلقّوا التدريب تراكمياً حتى 2025؛ وأكثر من 4,000 مؤسسة عضو؛ وتدرّب الشراكات الكبرى نحو ربع إلى ثلث قواها العاملة سنوياً.', '"% of workforce trained this year" as the headline KPI, and numeric commitments from suppliers and partners.', '"نسبة القوى العاملة المدرَّبة هذا العام" مؤشراً رئيسياً، والتزامات رقمية من الموردين والشركاء.', '[{"key":"people_trained","value":10000000,"unit":"count","label_en":"People trained (cumulative, 2025)","label_ar":"الأشخاص المدرَّبون (تراكمياً، 2025)","quote_en":"10 million"},{"key":"member_organisations","value":4000,"unit":"count","label_en":"Member organisations","label_ar":"المؤسسات الأعضاء","quote_en":"4,000"}]'::jsonb, array['FS53','FS60','FS64','FS65','FS68']::text[], '2026-10-10', 'published', true, 50, '2026-10-10T00:00:00Z', null),
('ESCO', 'ESCO v1.2.1 (European Skills, Competences, Qualifications and Occupations)', 'التصنيف الأوروبي للمهارات والكفاءات والمؤهلات والمهن (ESCO) الإصدار 1.2.1', 'European Commission', 'المفوضية الأوروبية', 'EU, 28 languages incl. Arabic', 'الاتحاد الأوروبي، 28 لغة منها العربية', 'global', 2025, null, 'single', array['https://esco.ec.europa.eu/en/about-esco/what-esco','https://esco.ec.europa.eu/en/classification/skill_main']::text[], '3,039 occupations and 13,939 skills; each skill has a reusability level (transversal to occupation-specific); concepts are marked obsolete, never deleted.', '3,039 مهنة و13,939 مهارة؛ لكل مهارة مستوى قابلية لإعادة الاستخدام (من المستعرضة إلى الخاصة بمهنة)؛ وتُوسَم المفاهيم بأنها متقادمة ولا تُحذف أبداً.', 'Reusability level on every skill, Arabic preferred and alternative labels, obsolete-not-deleted, and a published crosswalk.', 'مستوى قابلية إعادة الاستخدام على كل مهارة، وتسميات عربية مفضلة وبديلة، والتقادم دون الحذف، وجدول مواءمة منشور.', '[{"key":"occupations","value":3039,"unit":"count","label_en":"Occupations","label_ar":"المهن","quote_en":"3,039"},{"key":"skills","value":13939,"unit":"count","label_en":"Skills","label_ar":"المهارات","quote_en":"13,939"}]'::jsonb, array['FS01','FS02','FS04','FS07','FS08','FS34','FS63']::text[], '2026-10-10', 'published', true, 60, '2026-10-10T00:00:00Z', null),
('DIGCOMP', 'DigComp 2.2 / 3.0 digital competence framework', 'إطار الكفاءة الرقمية DigComp 2.2 / 3.0', 'European Commission JRC', 'مركز البحوث المشترك التابع للمفوضية الأوروبية', 'EU', 'الاتحاد الأوروبي', 'global', 2022, 2025, 'editions', array['https://joint-research-centre.ec.europa.eu/scientific-activities-z/education-and-training/digital-transformation-education/digital-competence-framework-citizens-digcomp_en']::text[], '21 competences in 5 areas at 8 proficiency levels, with AI examples in 2.2; only 56% of EU adults had above-basic digital skills in 2023.', '21 كفاءة في 5 مجالات على 8 مستويات إتقان، مع أمثلة عن الذكاء الاصطناعي في الإصدار 2.2؛ ولم يكن لدى سوى 56% من البالغين في الاتحاد الأوروبي مهارات رقمية فوق الأساسية في 2023.', 'A digital and AI ladder with plant-specific examples, extra weight on safety and problem solving, and a "% above basic" indicator.', 'سلّم للمهارات الرقمية والذكاء الاصطناعي بأمثلة من المحطة، ووزن إضافي للسلامة وحلّ المشكلات، ومؤشر "النسبة فوق المستوى الأساسي".', '[{"key":"above_basic_eu_2023","value":56,"unit":"pct","label_en":"EU adults with above-basic digital skills (2023)","label_ar":"البالغون في الاتحاد الأوروبي بمهارات رقمية فوق الأساسية (2023)","quote_en":"56","scale_max":100},{"key":"competences","value":21,"unit":"count","label_en":"Competences","label_ar":"الكفاءات","quote_en":"21"}]'::jsonb, array['FS08','FS09','FS10','FS24']::text[], '2026-10-10', 'published', true, 70, '2026-10-10T00:00:00Z', null),
('GREENCOMP', 'GreenComp, with EntreComp and LifeComp', 'إطار GreenComp مع EntreComp وLifeComp', 'European Commission JRC', 'مركز البحوث المشترك التابع للمفوضية الأوروبية', 'EU', 'الاتحاد الأوروبي', 'global', 2022, null, 'single', array['https://joint-research-centre.ec.europa.eu/greencomp']::text[], 'GreenComp has 12 sustainability competences in 4 areas, authored with the same validated JRC method as DigComp.', 'يضم GreenComp 12 كفاءة للاستدامة في 4 مجالات، أُعدّت بالمنهج المعتمد نفسه لدى مركز البحوث المشترك في DigComp.', 'The 4 x 3 authoring method for an ENEC CleanEnergyComp, LifeComp as the home for human skills, and EntreComp for intrapreneurship.', 'منهج التأليف 4 × 3 لإطار CleanEnergyComp خاص بالمؤسسة، وLifeComp مرجعاً للمهارات الإنسانية، وEntreComp لريادة الأعمال الداخلية.', '[{"key":"competences","value":12,"unit":"count","label_en":"Sustainability competences","label_ar":"كفاءات الاستدامة","quote_en":"12"},{"key":"areas","value":4,"unit":"count","label_en":"Areas","label_ar":"المجالات","quote_en":"4"}]'::jsonb, array['FS25','FS41','FS43','FS46']::text[], '2026-10-10', 'published', true, 80, '2026-10-10T00:00:00Z', null),
('FORECAST', 'Skills England priority skills to 2030 and LSIPs; Cedefop Skills Forecast to 2035', 'المهارات ذات الأولوية حتى 2030 لدى Skills England وخطط المهارات المحلية؛ توقعات المهارات لدى Cedefop حتى 2035', 'Skills England (UK); Cedefop (EU)', 'Skills England (المملكة المتحدة)؛ Cedefop (الاتحاد الأوروبي)', 'UK / EU', 'المملكة المتحدة / الاتحاد الأوروبي', 'national', 2025, null, 'single', array['https://www.gov.uk/government/publications/assessment-of-priority-skills-to-2030/assessment-of-priority-skills-to-2030','https://www.cedefop.europa.eu/en/datasets/dataset-skills-forecast']::text[], 'Priority-occupation demand +15% to 2030 with uncertainty stated up front; a methodology change voids year-on-year comparison and is disclosed; LSIPs make local provision answer employer demand.', 'يرتفع الطلب على المهن ذات الأولوية 15% حتى 2030 مع الإفصاح المسبق عن عدم اليقين؛ وتغيير المنهجية يُبطل المقارنة السنوية ويُعلَن؛ وتجعل خطط المهارات المحلية العرضَ المحلي يستجيب لطلب أصحاب العمل.', 'One declared baseline with bands, "pressure now" kept apart from "demand later", a methodology-change banner, a "not yet modelled" list, and a regional demand-to-provider loop.', 'خط أساس معلن مع نطاقات، وفصل "الضغط الآن" عن "الطلب لاحقاً"، وشريط تنبيه عند تغيير المنهجية، وقائمة "لم يُنمذج بعد"، وحلقة إقليمية من الطلب إلى مقدّمي التدريب.', '[{"key":"priority_demand_growth_2030","value":15,"unit":"pct","label_en":"Priority-occupation demand growth to 2030","label_ar":"نمو الطلب على المهن ذات الأولوية حتى 2030","quote_en":"15","scale_max":100}]'::jsonb, array['FS03','FS16','FS50','FS51','FS54','FS64']::text[], '2026-10-10', 'published', true, 90, '2026-10-10T00:00:00Z', null),
('ONET', 'O*NET Hot Technologies and Bright Outlook', 'التقنيات الرائجة ومؤشر النظرة المشرقة في O*NET', 'US Department of Labor', 'وزارة العمل الأمريكية', 'United States', 'الولايات المتحدة', 'national', 2026, null, 'single', array['https://onetcenter.org/bright.html','https://onetcenter.org/reports/Hot_Technologies_Demand.html']::text[], 'Bright Outlook criteria are published (growth of 5% or more, 75,000+ openings, or new and emerging); hot-across-all-jobs is kept apart from in-demand-for-this-occupation.', 'معايير النظرة المشرقة منشورة (نمو 5% أو أكثر، أو 75,000 فرصة أو أكثر، أو مهنة جديدة وناشئة)؛ ويُفصل "الرائج في كل الوظائف" عن "المطلوب لهذه المهنة".', 'Role and technology badges with published thresholds, past lists kept, and a three-tier consumer label.', 'شارات للأدوار والتقنيات بعتبات منشورة، والاحتفاظ بالقوائم السابقة، وتصنيف من ثلاث درجات للمستخدم.', '[{"key":"bright_growth_threshold","value":5,"unit":"pct","label_en":"Growth threshold for Bright Outlook","label_ar":"عتبة النمو لمؤشر النظرة المشرقة","quote_en":"5","scale_max":100},{"key":"bright_openings_threshold","value":75000,"unit":"count","label_en":"Openings threshold for Bright Outlook","label_ar":"عتبة الفرص لمؤشر النظرة المشرقة","quote_en":"75,000"}]'::jsonb, array['FS06','FS08','FS16','FS71']::text[], '2026-10-10', 'published', true, 100, '2026-10-10T00:00:00Z', null),
('LIGHTCAST', 'Lightcast Open Skills and Skillabi', 'تصنيف المهارات المفتوح من Lightcast وأداة Skillabi', 'Lightcast', 'Lightcast', 'International', 'دولي', 'corporate', 2025, null, 'single', array['https://lightcast.io/blog/open-skills-taxonomy','https://lightcast.io/resources/blog/skillabi-press-release-june-3-2025']::text[], 'About 32,000 to 34,000 skills typed as common, specialised or certification, with stable IDs; Skillabi scores curriculum coverage of real roles from 0 to 100.', 'نحو 32,000 إلى 34,000 مهارة مصنّفة إلى عامة أو متخصصة أو شهادات، بمعرّفات ثابتة؛ وتقيس Skillabi تغطية المناهج للأدوار الفعلية من 0 إلى 100.', 'Skill types, stable IDs and a dated changelog; a curriculum coverage score with the list of skills nothing teaches.', 'أنواع المهارات والمعرّفات الثابتة وسجل تغييرات مؤرّخ؛ ودرجة تغطية المناهج مع قائمة المهارات التي لا يدرّسها شيء.', '[{"key":"skills_low","value":32000,"unit":"count","label_en":"Skills in the taxonomy (low end)","label_ar":"المهارات في التصنيف (الحد الأدنى)","quote_en":"32,000"},{"key":"coverage_scale","value":100,"unit":"score","label_en":"Top of the curriculum coverage score","label_ar":"أعلى درجة لتغطية المناهج","quote_en":"100","scale_max":100}]'::jsonb, array['FS02','FS17','FS57','FS66']::text[], '2026-10-10', 'published', true, 110, '2026-10-10T00:00:00Z', null),
('LINKEDIN', 'LinkedIn Economic Graph: Skills on the Rise and Work Change', 'الرسم البياني الاقتصادي من LinkedIn: المهارات الصاعدة وتغيّر العمل', 'LinkedIn', 'LinkedIn', 'International', 'دولي', 'corporate', 2025, null, 'single', array['https://economicgraph.linkedin.com/research']::text[], 'Skills on the Rise combines three signals (profile additions, skills of recent hires, employer demand); AI literacy ranked first in 2025 and is kept apart from AI engineering.', 'تجمع قائمة المهارات الصاعدة ثلاث إشارات (إضافات الملفات الشخصية، ومهارات المعيَّنين حديثاً، وطلب أصحاب العمل)؛ وجاء الإلمام بالذكاء الاصطناعي أولاً في 2025 ويُفصل عن هندسة الذكاء الاصطناعي.', 'A three-signal rising-skill detector on ENEC''s own data, and AI literacy separated from AI engineering.', 'كاشف للمهارات الصاعدة بثلاث إشارات على بيانات المؤسسة نفسها، وفصل الإلمام بالذكاء الاصطناعي عن هندسته.', '[{"key":"signals","value":3,"unit":"count","label_en":"Signals behind Skills on the Rise","label_ar":"الإشارات وراء المهارات الصاعدة","quote_en":"three"}]'::jsonb, array['FS09','FS70','FS72']::text[], '2026-10-10', 'published', true, 120, '2026-10-10T00:00:00Z', null),
('MCK-DELTA', 'McKinsey DELTAs (Distinct Elements of Talent)', 'العناصر المميزة للمواهب (DELTAs) من ماكنزي', 'McKinsey Global Institute', 'معهد ماكنزي العالمي', 'International (18,000 people, 15 countries)', 'دولي (18,000 شخص في 15 دولة)', 'global', 2021, null, 'single', array['https://www.mckinsey.com/industries/public-and-social-sector/our-insights/defining-the-skills-citizens-will-need-in-the-future-world-of-work']::text[], '56 DELTAs in 13 groups and 4 categories; an item qualifies only if it needs a distinct development and assessment approach.', '56 عنصراً في 13 مجموعة و4 فئات؛ ولا يُدرج عنصر إلا إذا احتاج نهجاً مميزاً في التطوير والتقييم.', 'The inclusion rule as taxonomy governance, and "proficiency against needed" as the main chart.', 'قاعدة الإدراج أداةً لحوكمة التصنيف، و"الإتقان مقابل المطلوب" رسماً رئيسياً.', '[{"key":"deltas","value":56,"unit":"count","label_en":"DELTAs","label_ar":"العناصر المميزة","quote_en":"56"},{"key":"groups","value":13,"unit":"count","label_en":"Groups","label_ar":"المجموعات","quote_en":"13"}]'::jsonb, array['FS02','FS25','FS26','FS54']::text[], '2026-10-10', 'published', true, 130, '2026-10-10T00:00:00Z', null),
('ISO30414', 'ISO 30414:2025 human capital reporting', 'المعيار ISO 30414:2025 لتقارير رأس المال البشري', 'ISO TC 260', 'اللجنة الفنية ISO TC 260', 'International', 'دولي', 'global', 2025, null, 'single', array['https://committee.iso.org/sites/tc260/home/news/content-left-area/news-and-updates/iso-30414-2025-strengthening-hum.html']::text[], 'Second edition (Aug 2025) adds auditable requirements, 14 baseline metrics, and a quantitative plus qualitative disclosure with variance explanations.', 'يضيف الإصدار الثاني (أغسطس 2025) متطلبات قابلة للتدقيق و14 مقياساً أساسياً، وإفصاحاً كمياً ونوعياً مع تفسير الفروق.', 'A Skills, Capabilities and Development disclosure pack where every metric has a definition, owner narrative, variance note and audit trail.', 'حزمة إفصاح عن المهارات والقدرات والتطوير يكون لكل مقياس فيها تعريف وسرد من المالك وملاحظة عن الفروق وسجل تدقيق.', '[{"key":"baseline_metrics","value":14,"unit":"count","label_en":"Baseline metrics","label_ar":"المقاييس الأساسية","quote_en":"14"}]'::jsonb, array['FS43','FS50','FS56','FS60','FS84']::text[], '2026-10-10', 'published', true, 140, '2026-10-10T00:00:00Z', null),
('1EDTECH', 'Open Badges 3.0, CLR 2.0 and CASE', 'الشارات المفتوحة 3.0 وسجل المتعلم الشامل 2.0 وCASE', '1EdTech', '1EdTech', 'International', 'دولي', 'global', 2024, null, 'single', array['https://www.1edtech.org/standards/open-badges','https://www.1edtech.org/standards/clr']::text[], 'Badges and the Comprehensive Learner Record are W3C Verifiable Credentials; CASE carries machine-readable competency definitions.', 'الشارات وسجل المتعلم الشامل بيانات اعتماد قابلة للتحقق وفق W3C؛ ويحمل CASE تعريفات الكفاءات بصيغة قابلة للقراءة آلياً.', 'A CLR-shaped learner record, credentials that point at a competency ID, and a CASE-shaped framework export.', 'سجل متعلم بصيغة CLR، وبيانات اعتماد تشير إلى معرّف كفاءة، وتصدير للإطار بصيغة CASE.', '[]'::jsonb, array['FS08','FS31','FS32','FS69','FS79']::text[], '2026-10-10', 'published', true, 150, '2026-10-10T00:00:00Z', null),
('SFIA9', 'SFIA 9 (Skills Framework for the Information Age)', 'إطار المهارات لعصر المعلومات SFIA 9', 'SFIA Foundation', 'مؤسسة SFIA', 'International', 'دولي', 'global', 2024, null, 'single', array['https://sfia-online.org/en/sfia-9/sfia-9-release-notes']::text[], '7 levels of responsibility defined by generic attributes; skills defined only at levels where they exist; level essence lines, an AI skills view and a change tracker.', '7 مستويات للمسؤولية تُعرّفها سمات عامة؛ وتُعرَّف المهارات فقط في المستويات التي توجد فيها؛ مع أسطر جوهر المستوى وعرض لمهارات الذكاء الاصطناعي وسجل للتغييرات.', 'Generic level attributes across all skills, level essence lines, skills defined only at real levels, and a public change tracker.', 'سمات مستويات عامة لكل المهارات، وأسطر جوهر المستوى، وتعريف المهارات في مستوياتها الفعلية فقط، وسجل تغييرات عام.', '[{"key":"levels","value":7,"unit":"count","label_en":"Levels of responsibility","label_ar":"مستويات المسؤولية","quote_en":"7"}]'::jsonb, array['FS01','FS07','FS08','FS23','FS24','FS54']::text[], '2026-10-10', 'published', true, 160, '2026-10-10T00:00:00Z', null),
('SSG-SF', 'SkillsFuture Skills Frameworks, Critical Core Skills and AI Potential on Tasks', 'أطر المهارات في SkillsFuture والمهارات الأساسية الحرجة وإمكانات الذكاء الاصطناعي في المهام', 'SkillsFuture Singapore', 'SkillsFuture Singapore', 'Singapore', 'سنغافورة', 'national', 2025, null, 'single', array['https://isomer-user-content.by.gov.sg/41/4955bc61-161d-4584-945c-7eeeb276867a/Factsheet%20on%20Top%20skills%20trends%20in%202025.pdf']::text[], 'About 37,000 key work tasks across 2,000 roles; about 24% of tasks can be significantly aided by AI; entry roles typed as Mastery Builders, Analytical Specialists or Human Connectors; 16 Critical Core Skills.', 'نحو 37,000 مهمة عمل رئيسية في 2,000 دور؛ ويمكن للذكاء الاصطناعي أن يساعد بدرجة كبيرة في نحو 24% من المهام؛ وتُصنَّف أدوار الدخول إلى بُناة الإتقان أو المتخصصين التحليليين أو صانعي التواصل الإنساني؛ و16 مهارة أساسية حرجة.', 'A task layer between role and skill, AI exposure per task, role archetypes with ladder-rung protection, and a core-skills set.', 'طبقة مهام بين الدور والمهارة، ودرجة تعرّض لكل مهمة للذكاء الاصطناعي، ونماذج أدوار مع حماية درجات السلّم، ومجموعة مهارات أساسية.', '[{"key":"tasks","value":37000,"unit":"count","label_en":"Key work tasks","label_ar":"مهام العمل الرئيسية","quote_en":"37,000"},{"key":"ai_aided_tasks","value":24,"unit":"pct","label_en":"Tasks that AI can significantly aid","label_ar":"المهام التي يمكن للذكاء الاصطناعي أن يساعد فيها بدرجة كبيرة","quote_en":"24","scale_max":100},{"key":"critical_core_skills","value":16,"unit":"count","label_en":"Critical Core Skills","label_ar":"المهارات الأساسية الحرجة","quote_en":"16"}]'::jsonb, array['FS05','FS06','FS07','FS11','FS12','FS23','FS25','FS52','FS70','FS81']::text[], '2026-10-10', 'published', true, 170, '2026-10-10T00:00:00Z', null),
('SG-CAREER', 'Careers and Skills Passport, CareersFinder and Career Health SG', 'جواز المهن والمهارات وCareersFinder وصحة المسار المهني في سنغافورة', 'SSG, MOM, WSG', 'SSG وMOM وWSG', 'Singapore', 'سنغافورة', 'national', 2024, 2025, 'range', array['https://www.myskillsfuture.gov.sg/csp','https://www.mom.gov.sg/newsroom/speeches/2025/0710-speech-by-min-at-career-health-summit-2025']::text[], '315,000 people opened their passport and 4,900 shared it (Apr 2025); three consent gates and curated sharing; CareersFinder used by 55,000+; ACE = Assess, Chart, Execute.', 'فتح 315,000 شخص جوازهم وشاركه 4,900 (أبريل 2025)؛ ثلاث بوابات للموافقة ومشاركة منتقاة؛ واستخدم CareersFinder أكثر من 55,000 شخص؛ وACE تعني التقييم والتخطيط والتنفيذ.', 'A provenance badge on every record, curated sharing with expiry, adjacency moves backed by real transitions, and a visible career-health check.', 'شارة مصدر على كل سجل، ومشاركة منتقاة بتاريخ انتهاء، وتنقلات متجاورة تدعمها انتقالات فعلية، وفحص ظاهر لصحة المسار المهني.', '[{"key":"passports_opened","value":315000,"unit":"count","label_en":"People who opened their passport","label_ar":"الأشخاص الذين فتحوا جوازهم","quote_en":"315,000"},{"key":"passports_shared","value":4900,"unit":"count","label_en":"People who shared it","label_ar":"الأشخاص الذين شاركوه","quote_en":"4,900"}]'::jsonb, array['FS15','FS32','FS33','FS35','FS69','FS75','FS76']::text[], '2026-10-10', 'published', true, 180, '2026-10-10T00:00:00Z', null),
('SG-JTM', 'Jobs Transformation Maps', 'خرائط تحوّل الوظائف', 'Workforce Singapore', 'Workforce Singapore', 'Singapore', 'سنغافورة', 'national', 2025, null, 'single', array['https://wsg.gov.sg/for-employers/jobs-transformation-maps.html','https://www.mom.gov.sg/newsroom/parliament-questions-and-replies/2025/1104-written-answer-to-pq-on-update-on-jobs-transformation-maps']::text[], '19 maps covering about 1.7 million workers; each ends in redesigned roles and a reskilling pathway, not a trend report.', '19 خريطة تغطي نحو 1.7 مليون عامل؛ تنتهي كل منها بأدوار معاد تصميمها ومسار لإعادة التأهيل، لا بتقرير عن الاتجاهات.', 'A per-role transformation page: technology drivers, tasks added or removed, the redesigned profile and a dated reskilling path.', 'صفحة تحوّل لكل دور: محرّكات التقنية، والمهام المضافة أو المحذوفة، والملف المعاد تصميمه، ومسار مؤرّخ لإعادة التأهيل.', '[{"key":"maps","value":19,"unit":"count","label_en":"Transformation maps","label_ar":"خرائط التحوّل","quote_en":"19"},{"key":"workers","value":1700000,"unit":"count","label_en":"Workers covered","label_ar":"العاملون المشمولون","quote_en":"1.7 million"}]'::jsonb, array['FS05','FS11','FS81']::text[], '2026-10-10', 'published', true, 190, '2026-10-10T00:00:00Z', null),
('ENTITLE', 'SkillsFuture Level-Up (SG) and Lifelong Learning Entitlement (UK)', 'برنامج SkillsFuture Level-Up (سنغافورة) واستحقاق التعلم مدى الحياة (المملكة المتحدة)', 'MOE/SSG Singapore; DfE England', 'وزارة التعليم وSSG في سنغافورة؛ وزارة التعليم في إنجلترا', 'Singapore / UK', 'سنغافورة / المملكة المتحدة', 'national', 2024, 2025, 'range', array['https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling','https://www.gov.uk/government/publications/lifelong-learning-entitlement-lle-overview/lifelong-learning-entitlement-overview']::text[], 'A non-expiring mid-career credit usable only on about 7,000 outcome-filtered courses, plus a training allowance; the LLE expresses learning in credits with 30-credit modules.', 'رصيد لا ينتهي لمنتصف المسار المهني يُستخدم فقط في نحو 7,000 دورة منتقاة وفق نتائجها، إضافة إلى بدل تدريب؛ ويعبّر استحقاق التعلم مدى الحياة عن التعلم بأرصدة في وحدات من 30 رصيداً.', 'A visible learning balance, an outcome-gated catalogue, protected study time, and a credit unit for every learning asset.', 'رصيد تعلم ظاهر، وكتالوج مشروط بالنتائج، ووقت دراسة محمي، ووحدة رصيد لكل أصل تعلّمي.', '[{"key":"outcome_filtered_courses","value":7000,"unit":"count","label_en":"Outcome-filtered courses","label_ar":"الدورات المنتقاة وفق النتائج","quote_en":"7,000"},{"key":"module_credits","value":30,"unit":"count","label_en":"Credits per module","label_ar":"الأرصدة لكل وحدة","quote_en":"30"}]'::jsonb, array['FS17','FS18','FS19','FS30','FS78']::text[], '2026-10-10', 'published', true, 200, '2026-10-10T00:00:00Z', null),
('FSC', 'Future Skills Centre Impact Report 2025', 'تقرير الأثر 2025 لمركز مهارات المستقبل', 'Future Skills Centre (ESDC-funded)', 'مركز مهارات المستقبل (بتمويل من ESDC)', 'Canada', 'كندا', 'national', 2025, null, 'single', array['https://fsc-ccf.ca/wp-content/uploads/2025/08/FSC-Impact-Report-EN-FINAL.pdf']::text[], '400 pilot and research projects, each with an independent evaluator; 78% of completed projects report adoption, expansion or further investment.', '400 مشروع تجريبي وبحثي لكلٍّ منها مقيّم مستقل؛ و78% من المشاريع المكتملة أفادت بالتبنّي أو التوسّع أو استثمار إضافي.', 'A pilots registry (hypothesis, comparison group, evaluator, published result including failures) and an adoption-rate KPI.', 'سجل للمشاريع التجريبية (فرضية، ومجموعة مقارنة، ومقيّم، ونتيجة منشورة بما فيها الإخفاقات) ومؤشر لمعدل التبنّي.', '[{"key":"projects","value":400,"unit":"count","label_en":"Pilot and research projects","label_ar":"المشاريع التجريبية والبحثية","quote_en":"400"},{"key":"adoption_rate","value":78,"unit":"pct","label_en":"Completed projects reporting adoption, expansion or more investment","label_ar":"المشاريع المكتملة التي أفادت بالتبنّي أو التوسّع أو استثمار إضافي","quote_en":"78","scale_max":100}]'::jsonb, array['FS56','FS61']::text[], '2026-10-10', 'published', true, 210, '2026-10-10T00:00:00Z', null),
('UPKEEP', 'Australia National Skills Taxonomy (ASC retired) and Korea NCS', 'التصنيف الوطني للمهارات في أستراليا (إلغاء ASC) ومعايير الكفاءة الوطنية في كوريا', 'Jobs and Skills Australia; MOEL Korea', 'هيئة الوظائف والمهارات الأسترالية؛ وزارة العمل الكورية', 'Australia / Korea', 'أستراليا / كوريا', 'national', 2024, 2025, 'range', array['https://www.jobsandskills.gov.au/australian-skills-classification','https://moel.go.kr/english/news/moelNewsDetail.do?idx=3137']::text[], 'Australia removed its skills classification in Jan 2025 over timeliness and validation; Korea''s NCS ties each unit to a module and a qualification but is criticised where delivery never followed.', 'ألغت أستراليا تصنيفها للمهارات في يناير 2025 بسبب ضعف التحديث والتحقق؛ وتربط معايير الكفاءة الكورية كل وحدة بوحدة تدريبية ومؤهل، لكنها تُنتقد حيث لم يتبعها تنفيذ.', 'Review dates and staleness flags, skills derived from artefacts already maintained, and an annual orphan-rate audit.', 'تواريخ مراجعة وإشارات تقادم، ومهارات مشتقة من أصول تُصان أصلاً، وتدقيق سنوي لنسبة المهارات اليتيمة.', '[]'::jsonb, array['FS30','FS54','FS57']::text[], '2026-10-10', 'published', true, 220, '2026-10-10T00:00:00Z', null),
('JAHIZ', 'Jahiz federal future-skills platform', 'منصة جاهز الاتحادية لمهارات المستقبل', 'UAE Government Development and the Future Office + FAHR', 'مكتب التطوير الحكومي والمستقبل والهيئة الاتحادية للموارد البشرية الحكومية', 'UAE', 'الإمارات العربية المتحدة', 'uae', 2022, null, 'single', array['https://wam.ae/en/details/1395303102696','https://u.ae/en/information-and-services/jobs/training-and-development/Strategies-for-improving-digital-skills-and-eGovernment-literacy']::text[], '20 future skills in four groups (Digital, 10X, Data and AI, New Economy); badges build a Future Skills Wallet linked to performance management.', '20 مهارة مستقبلية في أربع مجموعات (الرقمية، و10X، والبيانات والذكاء الاصطناعي، والاقتصاد الجديد)؛ والشارات تبني محفظة مهارات المستقبل المرتبطة بإدارة الأداء.', 'The four-group structure plus a nuclear fifth group, a wallet tied to the development plan, and a dated whole-workforce target.', 'هيكل المجموعات الأربع مع مجموعة نووية خامسة، ومحفظة مرتبطة بخطة التطوير، وهدف مؤرّخ لكامل القوى العاملة.', '[{"key":"future_skills","value":20,"unit":"count","label_en":"Future skills","label_ar":"مهارات المستقبل","quote_en":"20"},{"key":"groups","value":4,"unit":"count","label_en":"Groups","label_ar":"المجموعات","quote_en":"four"}]'::jsonb, array['FS02','FS31','FS41','FS62','FS74']::text[], '2026-10-10', 'published', true, 230, '2026-10-10T00:00:00Z', null),
('UAE-NQF', 'UAE National Qualifications Framework and NQC work-experience recognition', 'الإطار الوطني للمؤهلات في الإمارات والاعتراف بالخبرة العملية لدى المركز الوطني للمؤهلات', 'National Qualifications Centre (MoHESR)', 'المركز الوطني للمؤهلات (وزارة التعليم العالي والبحث العلمي)', 'UAE', 'الإمارات العربية المتحدة', 'uae', 2024, 2026, 'editions', array['https://www.wam.ae/en/article/c12hbfm-national-qualifications-centre-discusses','https://uaelegislation.gov.ae/en/legislations/2615/download']::text[], 'The 2024 Cabinet Resolution defines RPL; in July 2026 the NQC sought private-sector pilots for a framework that converts work experience into academic hours or vocational qualifications.', 'يعرّف قرار مجلس الوزراء لعام 2024 الاعتراف بالتعلم السابق؛ وفي يوليو 2026 دعا المركز الوطني للمؤهلات القطاع الخاص إلى تجارب لإطار يحوّل الخبرة العملية إلى ساعات أكاديمية أو مؤهلات مهنية.', 'An NQF level on every credential and learning asset, an RPL package NQC-recognised assessors can review, and ENEC as a pilot employer.', 'مستوى في الإطار الوطني على كل اعتماد وأصل تعلّمي، وحزمة اعتراف بالتعلم السابق يراجعها مقيّمون معترف بهم، والمؤسسة جهة عمل تجريبية.', '[]'::jsonb, array['FS24','FS29','FS30','FS66']::text[], '2026-10-10', 'published', true, 240, '2026-10-10T00:00:00Z', null),
('MOHRE', 'MoHRE occupational classification and skill levels', 'التصنيف المهني ومستويات المهارة لدى وزارة الموارد البشرية والتوطين', 'Ministry of Human Resources and Emiratisation', 'وزارة الموارد البشرية والتوطين', 'UAE', 'الإمارات العربية المتحدة', 'uae', 2026, null, 'current', array['https://www.khaleejtimes.com/uae/government/uae-ministry-launches-new-job-classification-scheme','https://gulfnews.com/uae/government/uae-workforce-jumps-124-in-2025-as-new-firms-surge-mohre-says-1.500416665']::text[], '725 occupational categories in nine occupational levels and five skill levels, ISCO-aligned.', '725 فئة مهنية في تسعة مستويات مهنية وخمسة مستويات مهارة، متوافقة مع التصنيف الدولي ISCO.', 'An occupation code and national skill level on every role, and a skill-level uplift metric.', 'رمز مهنة ومستوى مهارة وطني على كل دور، ومقياس لرفع مستوى المهارة.', '[{"key":"occupational_categories","value":725,"unit":"count","label_en":"Occupational categories","label_ar":"الفئات المهنية","quote_en":"725"},{"key":"skill_levels","value":5,"unit":"count","label_en":"Skill levels","label_ar":"مستويات المهارة","quote_en":"five"}]'::jsonb, array['FS63']::text[], '2026-10-10', 'published', true, 250, '2026-10-10T00:00:00Z', null),
('NAFIS', 'Nafis and the Emirati Talent Competitiveness Council', 'برنامج نافس ومجلس تنافسية الكوادر الإماراتية', 'ETCC + MoHRE', 'مجلس تنافسية الكوادر الإماراتية ووزارة الموارد البشرية والتوطين', 'UAE', 'الإمارات العربية المتحدة', 'uae', 2026, null, 'single', array['https://www.wam.ae/en/article/c1betlp-emiratisation-agenda-advances-with-leadership','https://www.zawya.com/en/press-release/events-and-conferences/uaes-emiratisation-drive-enters-a-new-outcomes-era-eiojkgck']::text[], 'Emiratisation has moved to an "outcomes era": retention and progression rather than placement counts.', 'انتقل التوطين إلى "مرحلة النتائج": الاستبقاء والتقدّم بدلاً من أعداد التعيين.', 'Emirati readiness by competency for critical and future roles, plus retention at 12/24/36 months.', 'جاهزية الكوادر الإماراتية حسب الكفاءة للأدوار الحرجة والمستقبلية، مع الاستبقاء عند 12 و24 و36 شهراً.', '[]'::jsonb, array['FS62','FS73']::text[], '2026-10-10', 'published', true, 260, '2026-10-10T00:00:00Z', null),
('UAE-AI', 'UAE National AI Strategy 2031 and Abu Dhabi DGE AiNative', 'الاستراتيجية الوطنية للذكاء الاصطناعي 2031 وبرنامج AiNative لدائرة التمكين الحكومي في أبوظبي', 'UAE Government; DGE Abu Dhabi', 'حكومة الإمارات؛ دائرة التمكين الحكومي في أبوظبي', 'UAE', 'الإمارات العربية المتحدة', 'uae', 2025, null, 'single', array['https://www.khaleejtimes.com/abu-dhabi-train-23000-government-employees-ai-by-2027','https://dge.gov.ae/en/what-we-do']::text[], 'AiNative targets 23,000 Abu Dhabi government employees trained in AI by 2027; a K-12 AI curriculum runs from the 2025-26 school year.', 'يستهدف برنامج AiNative تدريب 23,000 موظف حكومي في أبوظبي على الذكاء الاصطناعي بحلول 2027؛ ويبدأ منهج للذكاء الاصطناعي من الروضة حتى الثاني عشر من العام الدراسي 2025-2026.', 'A dated AI-capability target, approved-use classes for AI tools, and intake-year baselines for new joiners.', 'هدف مؤرّخ لقدرات الذكاء الاصطناعي، وفئات استخدام معتمدة لأدواته، وخطوط أساس حسب سنة الالتحاق للموظفين الجدد.', '[{"key":"employees_trained_target_2027","value":23000,"unit":"count","label_en":"Government employees to be trained in AI by 2027","label_ar":"الموظفون الحكوميون المستهدف تدريبهم على الذكاء الاصطناعي بحلول 2027","quote_en":"23,000"}]'::jsonb, array['FS09','FS36','FS62','FS74','FS77']::text[], '2026-10-10', 'published', true, 270, '2026-10-10T00:00:00Z', null),
('IAEA-WFP', 'IAEA NG-T-3.10 Workforce Planning and the Nuclear Infrastructure Competency Framework', 'وثيقة الوكالة الدولية للطاقة الذرية NG-T-3.10 لتخطيط القوى العاملة وإطار كفاءات البنية التحتية النووية', 'IAEA', 'الوكالة الدولية للطاقة الذرية', 'International', 'دولي', 'nuclear_energy', 2011, null, 'reference', array['https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf','https://www.iaea.org/sites/default/files/20/11/nicf.pdf']::text[], 'Demand, supply, gap and fill-plan by phase, with three-scenario demand curves; NICF links each competency to the activity and phase that needs it.', 'الطلب والعرض والفجوة وخطة السدّ حسب المرحلة، مع منحنيات طلب بثلاثة سيناريوهات؛ ويربط إطار كفاءات البنية التحتية كل كفاءة بالنشاط والمرحلة اللذين يحتاجانها.', 'Scenario bands rather than point estimates, a fill plan per gap, and a "why this competency exists" link to its activity.', 'نطاقات سيناريوهات بدلاً من تقديرات نقطية، وخطة سدّ لكل فجوة، ورابط "لماذا توجد هذه الكفاءة" إلى نشاطها.', '[{"key":"scenarios","value":3,"unit":"count","label_en":"Demand scenarios","label_ar":"سيناريوهات الطلب","quote_en":"three"}]'::jsonb, array['FS04','FS05','FS13','FS38','FS45','FS50','FS51','FS73','FS84']::text[], '2026-10-10', 'published', true, 280, '2026-10-10T00:00:00Z', null),
('IAEA-1917', 'IAEA-TECDOC-1917 Assessing Behavioural Competencies in Nuclear Facilities', 'الوثيقة التقنية IAEA-TECDOC-1917 لتقييم الكفاءات السلوكية في المنشآت النووية', 'IAEA', 'الوكالة الدولية للطاقة الذرية', 'International', 'دولي', 'nuclear_energy', 2020, null, 'single', array['https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1917_web.pdf']::text[], 'Structured interviews, simulation observation, 360 and situational judgement as assessable evidence for behavioural competence.', 'المقابلات المنظمة، وملاحظة المحاكاة، وتقييم 360 درجة، والحكم الظرفي أدلةٌ قابلة للتقييم على الكفاءة السلوكية.', 'A behavioural track with the same evidence model as technical skills, and situational judgement items for safety behaviours.', 'مسار سلوكي بنموذج الأدلة نفسه للمهارات الفنية، وأسئلة حكم ظرفي لسلوكيات السلامة.', '[]'::jsonb, array['FS23','FS26','FS49','FS58','FS59']::text[], '2026-10-10', 'published', true, 290, '2026-10-10T00:00:00Z', null),
('IAEA-AI', 'IAEA AI for nuclear energy ("Atoms for Algorithms")', 'الذكاء الاصطناعي للطاقة النووية لدى الوكالة الدولية للطاقة الذرية ("الذرّات من أجل الخوارزميات")', 'IAEA', 'الوكالة الدولية للطاقة الذرية', 'International', 'دولي', 'nuclear_energy', 2025, null, 'single', array['https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence','https://www.neimagazine.com/news/iaea-hosts-first-ai-nuclear-symposium/']::text[], 'First IAEA AI and nuclear energy symposium (250+ organisations); digital twins and predictive maintenance named as operational uses.', 'أول ندوة للوكالة عن الذكاء الاصطناعي والطاقة النووية (أكثر من 250 مؤسسة)؛ وذُكرت التوائم الرقمية والصيانة التنبؤية استخداماتٍ تشغيلية.', 'An operational Nuclear + AI skill family: AI output verification and the duty to challenge it, twin validation, anomaly triage.', 'عائلة مهارات تشغيلية تجمع النووي والذكاء الاصطناعي: التحقق من مخرجات الذكاء الاصطناعي وواجب الاعتراض عليها، والتحقق من التوائم، وفرز الحالات الشاذة.', '[{"key":"organisations","value":250,"unit":"count","label_en":"Organisations at the first symposium","label_ar":"المؤسسات المشاركة في الندوة الأولى","quote_en":"250"}]'::jsonb, array['FS14','FS22','FS37','FS40','FS49']::text[], '2026-10-10', 'published', true, 300, '2026-10-10T00:00:00Z', null),
('OT-CYBER', 'IAEA NSS 42-G computer security and NICE Framework v2.0 OT role', 'دليل الأمن النووي NSS 42-G لأمن الحاسوب والدور المتعلق بالتقنيات التشغيلية في إطار NICE 2.0', 'IAEA; NIST/CISA', 'الوكالة الدولية للطاقة الذرية؛ NIST وCISA', 'International / US', 'دولي / الولايات المتحدة', 'nuclear_energy', 2021, 2025, 'editions', array['https://www.iaea.org/node/97473','https://niccs.cisa.gov/tools/nice-framework/work-role/operational-technology-ot-cybersecurity-engineering']::text[], 'NICE v2.0 adds its first OT work role inside engineering; NICE uses task, knowledge and skill statements with stable IDs.', 'يضيف الإصدار 2.0 من إطار NICE أول دور عمل للتقنيات التشغيلية ضمن الهندسة؛ ويستخدم الإطار عبارات مهام ومعارف ومهارات بمعرّفات ثابتة.', 'Stable statement IDs, and cyber hygiene for all staff while security roles stay at career-path level only.', 'معرّفات ثابتة للعبارات، والنظافة السيبرانية لكل الموظفين مع بقاء أدوار الأمن على مستوى المسار المهني فقط.', '[]'::jsonb, array['FS08']::text[], '2026-10-10', 'published', true, 310, '2026-10-10T00:00:00Z', null),
('NEA', 'OECD-NEA NEST Framework and Plan 2035', 'إطار NEST وخطة 2035 لوكالة الطاقة النووية', 'OECD Nuclear Energy Agency', 'وكالة الطاقة النووية التابعة لمنظمة التعاون الاقتصادي والتنمية', 'International (15 countries in NEST)', 'دولي (15 دولة في NEST)', 'nuclear_energy', 2024, 2025, 'range', array['https://www.oecd-nea.org/upload/docs/application/pdf/2025-10/plan_2035_-_vision_paper_-_final_version.pdf','https://oecd-nea.org/jcms/pl_98798/nest-framework-five-years-of-international-co-operation-on-nuclear-education-and-skills-development']::text[], '215+ NEST Fellows learn inside real multinational projects; Plan 2035 runs Inspire, Mentor and Network lanes with an expert video-lecture library.', 'أكثر من 215 زميلاً في NEST يتعلمون داخل مشاريع متعددة الجنسيات حقيقية؛ وتدير خطة 2035 مسارات الإلهام والإرشاد والتواصل مع مكتبة محاضرات مرئية للخبراء.', 'Fellowships inside real projects, an expert lecture library that doubles as knowledge capture, and a Future Leaders track.', 'زمالات داخل مشاريع حقيقية، ومكتبة محاضرات للخبراء تعمل أيضاً على حفظ المعرفة، ومسار لقادة المستقبل.', '[{"key":"fellows","value":215,"unit":"count","label_en":"NEST Fellows","label_ar":"زملاء NEST","quote_en":"215"}]'::jsonb, array['FS13','FS14','FS18','FS27','FS28','FS39','FS42','FS44','FS46','FS47','FS67','FS77']::text[], '2026-10-10', 'published', true, 320, '2026-10-10T00:00:00Z', null),
('UK-NUC', 'UK Nuclear Skills Strategic Plan, Destination Nuclear and nuclear skills passports', 'الخطة الاستراتيجية للمهارات النووية في المملكة المتحدة وبرنامج Destination Nuclear وجوازات المهارات النووية', 'UK Government and industry; Sellafield with Digital Catapult', 'حكومة المملكة المتحدة والقطاع؛ Sellafield مع Digital Catapult', 'United Kingdom', 'المملكة المتحدة', 'nuclear_energy', 2022, 2024, 'editions', array['https://world-nuclear-news.org/articles/uk-sets-out-plan-for-boosting-nuclear-workforce','https://www.digicatapult.org.uk/wp-content/uploads/2022/07/Digital_Catapult_Sellafield_DLT_Field_Labs_Report_Final-July-22-ver-2.pdf']::text[], '40,000 new jobs by 2030; Destination Nuclear targets career-changers; the Sellafield passport trial used wallets with selective disclosure.', '40,000 وظيفة جديدة بحلول 2030؛ ويستهدف Destination Nuclear المنتقلين من مسارات مهنية أخرى؛ واستخدمت تجربة جواز Sellafield محافظ رقمية بإفصاح انتقائي.', 'A transferable-skills translator for career-changers, sector target tracking, and selectively disclosable passports.', 'مترجم للمهارات القابلة للنقل للمنتقلين مهنياً، ومتابعة أهداف القطاع، وجوازات قابلة للإفصاح الانتقائي.', '[{"key":"new_jobs_2030","value":40000,"unit":"count","label_en":"New nuclear jobs by 2030","label_ar":"وظائف نووية جديدة بحلول 2030","quote_en":"40,000"}]'::jsonb, array['FS29','FS32','FS34','FS68','FS69','FS77']::text[], '2026-10-10', 'published', true, 330, '2026-10-10T00:00:00Z', null),
('SMR-WF', 'New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)', 'نماذج القوى العاملة للمحطات الجديدة والمفاعلات الصغيرة (BWRX-300 في كندا وNuScale E2 وبرنامج MATCH في فرنسا)', 'OPG, GE Vernova Hitachi, Sask Polytech, NuScale, GIFEN', 'OPG وGE Vernova Hitachi وSask Polytech وNuScale وGIFEN', 'Canada / US / France', 'كندا / الولايات المتحدة / فرنسا', 'nuclear_energy', 2023, 2025, 'range', array['https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/','https://engineering.oregonstate.edu/facilities/energy-exploration-e2-center','https://www.nucleareurope.eu/blog/highlight-of-the-month/match-program-a-tool-for-nuclear-capacity-building-in-france/']::text[], 'Short cross-over nuclear courses for adjacent industries (Sask Polytech with NSAN); simulated SMR control rooms on campuses; MATCH refreshes job-by-job demand every year (about 100,000 hires 2023-2033).', 'دورات نووية قصيرة للعبور من الصناعات المجاورة (Sask Polytech مع NSAN)؛ وغرف تحكم محاكاة لمفاعلات صغيرة في الحرم الجامعية؛ ويحدّث MATCH الطلب وظيفةً بوظيفة كل عام (نحو 100,000 تعيين بين 2023 و2033).', 'An SMR delta per existing role, cross-over courses, plant-literacy simulation for non-operators, and an annual job-by-job refresh.', 'فرق المفاعلات الصغيرة لكل دور قائم، ودورات عبور، ومحاكاة للإلمام بالمحطة لغير المشغّلين، وتحديث سنوي وظيفةً بوظيفة.', '[{"key":"hires_2023_2033","value":100000,"unit":"count","label_en":"Hires in France 2023-2033 (MATCH)","label_ar":"التعيينات في فرنسا 2023-2033 (MATCH)","quote_en":"100,000"}]'::jsonb, array['FS13','FS14','FS19','FS28','FS34','FS38','FS39','FS40','FS51','FS68']::text[], '2026-10-10', 'published', true, 340, '2026-10-10T00:00:00Z', null),
('NUC-NET', 'Nuclear education networks: ENEN2plus, Nordic NNTP, IAEA MSCFP and INMA, KINGS', 'شبكات التعليم النووي: ENEN2plus وبرنامج NNTP الشمالي وزمالة MSCFP وINMA لدى الوكالة وKINGS', 'ENEN; Fortum/TVO/Uniper/Vattenfall; IAEA; KEPCO', 'ENEN؛ Fortum وTVO وUniper وVattenfall؛ الوكالة الدولية للطاقة الذرية؛ KEPCO', 'EU / Nordics / International / Korea', 'الاتحاد الأوروبي / دول الشمال / دولي / كوريا', 'nuclear_energy', 2019, 2026, 'range', array['https://cordis.europa.eu/project/id/101061677','https://www.fortum.com/careers/NNTP','https://www.iaea.org/node/136445','https://www.iaea.org/node/17745']::text[], 'Bi-monthly mobility grants paid to learners; a trainee cohort run by four competing operators; study funding paired with placements; endorsed nuclear-management master''s programmes.', 'منح تنقّل كل شهرين تُدفع للمتعلمين؛ ودفعة متدربين يديرها أربعة مشغّلين متنافسين؛ وتمويل للدراسة مقترن بالتدريب الميداني؛ وبرامج ماجستير معتمدة في الإدارة النووية.', 'Rolling micro-grants, multi-employer cohorts (modules + project + mentor), sponsored study with placement, and a nuclear-management competency model.', 'منح صغيرة متجددة، ودفعات متعددة الجهات (وحدات + مشروع + مرشد)، ودراسة مموّلة مع تدريب ميداني، ونموذج كفاءات للإدارة النووية.', '[{"key":"operators_in_cohort","value":4,"unit":"count","label_en":"Operators running one trainee cohort","label_ar":"المشغّلون الذين يديرون دفعة متدربين واحدة","quote_en":"four"}]'::jsonb, array['FS18','FS20','FS28','FS45','FS47','FS48','FS66','FS67','FS82','FS83']::text[], '2026-10-10', 'published', true, 350, '2026-10-10T00:00:00Z', null),
('ENERGY-JOBS', 'IEA World Energy Employment 2025 and IRENA/ILO Renewable Energy and Jobs 2025', 'تقرير التوظيف العالمي في قطاع الطاقة 2025 لوكالة الطاقة الدولية وتقرير الطاقة المتجددة والوظائف 2025 لآيرينا ومنظمة العمل الدولية', 'IEA; IRENA with ILO', 'وكالة الطاقة الدولية؛ آيرينا مع منظمة العمل الدولية', 'International', 'دولي', 'nuclear_energy', 2025, null, 'single', array['https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025','https://build-up.ec.europa.eu/en/resources-and-tools/publications/annual-review-2025-renewable-energy-and-jobs']::text[], '76 million energy jobs in 2024; 60% of surveyed firms report shortages, worst for plant operators and nuclear specialists; renewable job growth slowed partly due to automation.', '76 مليون وظيفة في الطاقة في 2024؛ و60% من الشركات المشمولة أفادت بنقص، وأشدّه في مشغّلي المحطات والمتخصصين النوويين؛ وتباطأ نمو وظائف الطاقة المتجددة جزئياً بسبب الأتمتة.', 'External shortage lines beside internal numbers, an automation factor in demand, and a public skills-pledge mechanic.', 'خطوط نقص خارجية بجانب الأرقام الداخلية، وعامل أتمتة في الطلب، وآلية تعهدات علنية بالمهارات.', '[{"key":"energy_jobs_2024","value":76000000,"unit":"count","label_en":"Energy jobs worldwide (2024)","label_ar":"وظائف الطاقة في العالم (2024)","quote_en":"76 million"},{"key":"firms_reporting_shortages","value":60,"unit":"pct","label_en":"Surveyed firms reporting shortages","label_ar":"الشركات المشمولة التي أفادت بنقص","quote_en":"60","scale_max":100}]'::jsonb, array['FS12','FS14','FS42','FS43','FS48','FS52','FS53','FS65']::text[], '2026-10-10', 'published', true, 360, '2026-10-10T00:00:00Z', null),
('AI-LIT', 'EU AI Act Article 4 AI-literacy repository and UNESCO AI Competency Frameworks', 'مستودع ممارسات الإلمام بالذكاء الاصطناعي وفق المادة 4 من قانون الذكاء الاصطناعي الأوروبي وأطر كفاءات الذكاء الاصطناعي لليونسكو', 'European Commission AI Office; UNESCO', 'مكتب الذكاء الاصطناعي في المفوضية الأوروبية؛ اليونسكو', 'EU / International', 'الاتحاد الأوروبي / دولي', 'ai', 2024, 2026, 'range', array['https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices','https://gcedclearinghouse.org/en/node/146447']::text[], 'Article 4 applies from 2 Feb 2025; the repository labels practices planned, partially rolled out or fully implemented and separates providers from deployers; UNESCO uses 4 dimensions at Understand, Apply, Create.', 'تسري المادة 4 من 2 فبراير 2025؛ ويصنّف المستودع الممارسات إلى مخططة أو مطبقة جزئياً أو مطبقة كلياً ويفصل المزوّدين عن المستخدِمين؛ وتستخدم اليونسكو 4 أبعاد بمستويات الفهم والتطبيق والإبداع.', 'An AI-literacy register per AI system, provider vs deployer literacy, maturity labels, and a 4-dimension AI competency grid.', 'سجل للإلمام بالذكاء الاصطناعي لكل نظام، والتمييز بين إلمام المزوّد والمستخدِم، ووسوم النضج، وشبكة كفاءات للذكاء الاصطناعي بأربعة أبعاد.', '[{"key":"unesco_dimensions","value":4,"unit":"count","label_en":"UNESCO AI competency dimensions","label_ar":"أبعاد كفاءات الذكاء الاصطناعي لدى اليونسكو","quote_en":"4"}]'::jsonb, array['FS09','FS36','FS37','FS49','FS55','FS76','FS80']::text[], '2026-10-10', 'published', true, 370, '2026-10-10T00:00:00Z', null),
('UAE-PEERS', 'ADNOC AI upskilling and EGA Academy', 'تأهيل أدنوك في الذكاء الاصطناعي وأكاديمية الإمارات العالمية للألمنيوم', 'ADNOC; Emirates Global Aluminium', 'أدنوك؛ الإمارات العالمية للألمنيوم', 'UAE', 'الإمارات العربية المتحدة', 'corporate', 2025, null, 'single', array['https://reports.adnoc.ae/e/sustainability-report-2025/eJFjvFKd42','https://www.wam.ae/en/article/blmzwis-ega-launches-ega-academy']::text[], '40,000+ ADNOC staff trained on AI fundamentals; an agentic-AI course with 18,000+ participants produced 10,000+ agents; EGA runs 12-month national trainee cohorts with a role on completion.', 'أكثر من 40,000 موظف في أدنوك تدرّبوا على أساسيات الذكاء الاصطناعي؛ وأنتجت دورة في الذكاء الاصطناعي الوكيلي بأكثر من 18,000 مشارك أكثر من 10,000 وكيل؛ وتدير الإمارات العالمية للألمنيوم دفعات متدربين وطنية لمدة 12 شهراً مع وظيفة عند الإكمال.', 'AI learning whose output is a built artefact, AI-fundamentals coverage as a board KPI, and national trainee cohorts.', 'تعلّم للذكاء الاصطناعي يكون ناتجه أداة مبنية، وتغطية أساسيات الذكاء الاصطناعي مؤشراً لمجلس الإدارة، ودفعات متدربين وطنية.', '[{"key":"staff_trained_ai","value":40000,"unit":"count","label_en":"ADNOC staff trained on AI fundamentals","label_ar":"موظفو أدنوك المدرَّبون على أساسيات الذكاء الاصطناعي","quote_en":"40,000"},{"key":"agents_built","value":10000,"unit":"count","label_en":"Agents built in the agentic-AI course","label_ar":"الوكلاء المبنيون في دورة الذكاء الاصطناعي الوكيلي","quote_en":"10,000"}]'::jsonb, array['FS19','FS20','FS37','FS60','FS74','FS80','FS83']::text[], '2026-10-10', 'published', true, 380, '2026-10-10T00:00:00Z', null),
('CORP', 'Corporate reskilling programmes: AT&T, IBM, Schneider/Unilever, Google AI Essentials', 'برامج إعادة التأهيل في الشركات: AT&T وIBM وSchneider/Unilever وGoogle AI Essentials', 'AT&T; IBM; Schneider Electric; Unilever; Google', 'AT&T؛ IBM؛ Schneider Electric؛ Unilever؛ Google', 'International', 'دولي', 'corporate', 2014, 2025, 'range', array['https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/','https://workofthefuture-taskforce.mit.edu/document/2020-working-paper-qi-kochan','https://gloat.com/wp-content/uploads/Schneider-Electric-Gloat-Case-Study.pdf','https://services.google.com/fh/files/misc/new_google_career_certificates_impact_report.pdf']::text[], 'AT&T told staff which roles were shrinking and how to reach growing ones; IBM linked strategic-skill badges to performance and promotion; marketplaces made projects, roles and mentoring one feed; Google keeps market statistics apart from measured outcomes.', 'أخبرت AT&T موظفيها بالأدوار المتقلصة وكيف يصلون إلى الأدوار النامية؛ وربطت IBM شارات المهارات الاستراتيجية بالأداء والترقية؛ وجعلت الأسواق الداخلية المشاريع والأدوار والإرشاد في موجز واحد؛ وتفصل Google إحصاءات السوق عن النتائج المقيسة.', 'Honest role decline signals, a strategic badge tier with consequences, a time envelope for gigs, and market data separated from outcomes.', 'إشارات صادقة عن تراجع الأدوار، وفئة شارات استراتيجية لها عواقب، وإطار زمني للمهام القصيرة، وفصل بيانات السوق عن النتائج.', '[]'::jsonb, array['FS11','FS15','FS16','FS17','FS27','FS31','FS53','FS75','FS79','FS81']::text[], '2026-10-10', 'published', true, 390, '2026-10-10T00:00:00Z', null),
('SKILLS-TECH', 'Skills-platform mechanics: Workday/TechWolf, Degreed, Workera, Pluralsight, Credly, AI role-play', 'آليات منصات المهارات: Workday/TechWolf وDegreed وWorkera وPluralsight وCredly ولعب الأدوار بالذكاء الاصطناعي', 'Vendors', 'مزوّدو المنصات', 'International', 'دولي', 'corporate', 2024, 2026, 'range', array['https://www.techwolf.ai/customer-stories/workday','https://degreed.com/experience/blog/degreed-peer-ratings-your-360-degree-view-of-skills/','https://workera.ai/skills-intelligence-platform','https://training.talent.linkedin.com/introducing-role-play-with-ai-coach']::text[], 'Explicit vs inferred skills with confirm or remove; multi-source ratings; adaptive tests reach an estimate in about 20 items; role-play practice in 5-10 minutes (LinkedIn does not save the feedback).', 'مهارات صريحة مقابل مستنتجة مع التأكيد أو الإزالة؛ وتقييمات متعددة المصادر؛ واختبارات تكيّفية تصل إلى تقدير في نحو 20 سؤالاً؛ وتدريب على لعب الأدوار في 5 إلى 10 دقائق (لا تحفظ LinkedIn الملاحظات).', 'Inferred-skill suggestions the person confirms, multi-source proficiency, adaptive assessment, and role-play practice with saved feedback.', 'اقتراحات مهارات مستنتجة يؤكدها الشخص، وإتقان متعدد المصادر، وتقييم تكيّفي، وتدريب على لعب الأدوار مع حفظ الملاحظات.', '[{"key":"adaptive_items","value":20,"unit":"count","label_en":"Items an adaptive test needs for an estimate","label_ar":"الأسئلة التي يحتاجها الاختبار التكيّفي للوصول إلى تقدير","quote_en":"20"}]'::jsonb, array['FS03','FS10','FS21','FS22','FS33','FS44','FS55','FS56','FS59','FS72','FS79']::text[], '2026-10-10', 'published', true, 400, '2026-10-10T00:00:00Z', null)
insert into kafaa_role_profile_versions (id, role_id, horizon, version, status, is_public, path_only, requirements, drivers, rationale_en, rationale_ar, sources, as_of, supersedes_id, superseded_by_id, created_by, created_at, updated_at, published_by, published_at) values
