insert into kafaa_level_attributes (id, level, attribute, name_en, name_ar, text_en, text_ar, sfia_levels, sort) values
('la:1:essence', 1, 'essence', 'Level essence', 'جوهر المستوى', 'Knows what the skill is for and why it matters for safety; uses it only with guidance.', 'يعرف الغرض من المهارة وأهميتها للسلامة، ولا يمارسها إلا بتوجيه.', '1-2', 10),
('la:1:autonomy', 1, 'autonomy', 'Autonomy', 'الاستقلالية', 'Works under close direction; every task is checked.', 'يعمل تحت توجيه مباشر، وتُراجَع كل مهمة.', '1-2', 11),
('la:1:influence', 1, 'influence', 'Influence', 'التأثير', 'Interacts mainly with own team and passes on information accurately.', 'يتفاعل أساساً مع فريقه، وينقل المعلومات بدقة.', '1-2', 12),
('la:1:complexity', 1, 'complexity', 'Complexity', 'التعقيد', 'Routine, well-defined tasks with a procedure for every step.', 'مهام روتينية محددة بوضوح، لكل خطوة فيها إجراء.', '1-2', 13),
('la:1:knowledge', 1, 'knowledge', 'Knowledge', 'المعرفة', 'Basic facts and terms, and the reasons behind the main rules.', 'حقائق ومصطلحات أساسية، والأسباب الكامنة وراء القواعد الرئيسية.', '1-2', 14),
('la:1:behaviours', 1, 'behaviours', 'Behaviours', 'السلوكيات', 'Asks questions, reports concerns and accepts correction.', 'يطرح الأسئلة، ويبلّغ عن المخاوف، ويتقبّل التصحيح.', '1-2', 15),
('la:2:essence', 2, 'essence', 'Level essence', 'جوهر المستوى', 'Does routine work with the skill reliably while a qualified person checks the result.', 'يؤدي الأعمال الروتينية بالمهارة بموثوقية، بينما يراجع شخص مؤهل النتيجة.', '3', 20),
('la:2:autonomy', 2, 'autonomy', 'Autonomy', 'الاستقلالية', 'Works under general direction on routine tasks and asks when conditions change.', 'يعمل بتوجيه عام في المهام الروتينية، ويستوضح عند تغيّر الظروف.', '3', 21),
('la:2:influence', 2, 'influence', 'Influence', 'التأثير', 'Works with other teams on shared tasks and reports status clearly.', 'يعمل مع فرق أخرى في المهام المشتركة، ويبلّغ عن الحالة بوضوح.', '3', 22),
('la:2:complexity', 2, 'complexity', 'Complexity', 'التعقيد', 'A range of routine tasks with some variation and known problems.', 'مجموعة من المهام الروتينية مع بعض التنوع والمشكلات المعروفة.', '3', 23),
('la:2:knowledge', 2, 'knowledge', 'Knowledge', 'المعرفة', 'Working knowledge of the procedures, the equipment and their limits.', 'معرفة عملية بالإجراءات والمعدات وحدودها.', '3', 24),
('la:2:behaviours', 2, 'behaviours', 'Behaviours', 'السلوكيات', 'Uses the human performance tools without prompting and records work fully.', 'يستخدم أدوات الأداء البشري دون تذكير، ويوثّق العمل كاملاً.', '3', 25),
('la:3:essence', 3, 'essence', 'Level essence', 'جوهر المستوى', 'Works alone to the qualification standard, in normal and abnormal conditions.', 'يعمل منفرداً وفق معيار التأهيل، في الظروف العادية وغير العادية.', '4', 30),
('la:3:autonomy', 3, 'autonomy', 'Autonomy', 'الاستقلالية', 'Plans and performs own work without supervision and is accountable for the result.', 'يخطط عمله وينفّذه دون إشراف، ويتحمّل مسؤولية النتيجة.', '4', 31),
('la:3:influence', 3, 'influence', 'Influence', 'التأثير', 'Checks others'' work, briefs the team and influences decisions in own area.', 'يراجع عمل الآخرين ويقدّم الإحاطات للفريق، ويؤثر في القرارات ضمن نطاقه.', '4', 32),
('la:3:complexity', 3, 'complexity', 'Complexity', 'التعقيد', 'Varied and non-routine work, including off-normal conditions.', 'أعمال متنوعة وغير روتينية، بما في ذلك الظروف غير الاعتيادية.', '4', 33),
('la:3:knowledge', 3, 'knowledge', 'Knowledge', 'المعرفة', 'Deep knowledge of the systems and of the reasoning behind the procedures.', 'معرفة معمّقة بالأنظمة وبالمنطق الكامن وراء الإجراءات.', '4', 34),
('la:3:behaviours', 3, 'behaviours', 'Behaviours', 'السلوكيات', 'Makes conservative decisions under pressure and stops work when unsure.', 'يتخذ قرارات متحفظة تحت الضغط ويوقف العمل عند الشك.', '4', 35),
('la:4:essence', 4, 'essence', 'Level essence', 'جوهر المستوى', 'Sets the standard for the skill across ENEC and grows the people who hold it.', 'يضع المعيار للمهارة على مستوى المؤسسة ويطوّر من يمتلكونها.', '5', 40),
('la:4:autonomy', 4, 'autonomy', 'Autonomy', 'الاستقلالية', 'Sets the direction for the skill and decides within broad policy.', 'يحدد توجّه المهارة، ويتخذ القرارات ضمن السياسة العامة.', '5', 41),
('la:4:influence', 4, 'influence', 'Influence', 'التأثير', 'Influences across units and with external peers; the advice given shapes decisions.', 'يؤثر عبر الوحدات ومع النظراء الخارجيين، وتُسهم المشورة المقدمة في صنع القرار.', '5', 42),
('la:4:complexity', 4, 'complexity', 'Complexity', 'التعقيد', 'Complex, novel problems with incomplete information and high consequences.', 'مشكلات معقدة وجديدة بمعلومات ناقصة وعواقب كبيرة.', '5', 43),
('la:4:knowledge', 4, 'knowledge', 'Knowledge', 'المعرفة', 'Authoritative knowledge, including industry experience and the regulatory basis.', 'معرفة مرجعية تشمل خبرة القطاع والأساس التنظيمي.', '5', 44),
('la:4:behaviours', 4, 'behaviours', 'Behaviours', 'السلوكيات', 'Models the safety culture, develops others and challenges the organisation constructively.', 'يجسّد ثقافة السلامة، ويطوّر الآخرين، ويتحدى المؤسسة بشكل بنّاء.', '5', 45)
insert into kafaa_skill_level_ranges (id, skill_id, min_level, max_level, basis, track, rationale_en, rationale_ar, version, updated_by, updated_at) values
('slr:sk-pf-01', 'sk-pf-01', 1, 4, 'full', 'technical', 'Defined at all four levels: the skill is held from first awareness to setting the standard for others.', 'معرَّفة في المستويات الأربعة: تُمتلك المهارة من الإلمام الأول حتى وضع المعيار للآخرين.', 1, 'p-training-mgr', '2026-10-09T08:00:00Z'),
('slr:sk-pf-01-core', 'sk-pf-01-core', 2, 4, 'licence_like', 'technical', 'Starts at Practitioner: a qualified plant task is either done under supervision or not at all. Awareness of it sits with the parent skill, Reactor theory and nuclear physics fundamentals.', 'تبدأ من مستوى الممارس: مهمة المحطة المؤهَّلة تُؤدّى تحت الإشراف أو لا تُؤدّى إطلاقاً. أما الإلمام بها فيندرج تحت المهارة الأم: نظرية المفاعل وأساسيات الفيزياء النووية.', 1, 'p-training-mgr', '2026-10-09T08:00:00Z'),
('slr:sk-pf-01-advfuel', 'sk-pf-01-advfuel', 1, 3, 'not_operated', 'technical', 'Stops at Qualified: Expert means setting the standard on an operating plant, and no such technology is operated, so level 4 cannot be evidenced. No deployment decision implied.', 'تتوقف عند مستوى المؤهَّل: الخبير يضع المعيار في محطة عاملة، ولا تُشغَّل هذه التقنية، فلا يمكن إثبات المستوى الرابع. لا يعني ذلك أي قرار بالنشر.', 1, 'p-training-mgr', '2026-10-09T08:00:00Z'),
