('so-e5', 'SO-E5', 'Station blackout: restore AC power and protect the core', 'انقطاع التيار الكامل عن المحطة: استعادة التيار المتردد وحماية القلب', 'emergency', 'ns-01', array['coct','loct']::text[], true, 16, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"}]'::jsonb),
('so-e6', 'SO-E6', 'Anticipated transient without reactor trip', 'عابر متوقَّع دون إيقاف المفاعل', 'emergency', 'co-03', array['coct']::text[], true, 17, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"}]'::jsonb),
('so-e7', 'SO-E7', 'Emergency classification and notifications from the control room', 'تصنيف الطوارئ والإبلاغ من غرفة التحكم', 'emergency', 'ep-02', array['coct']::text[], true, 18, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"}]'::jsonb),
('so-e8', 'SO-E8', 'Excess steam demand event', 'حدث زيادة الطلب على البخار', 'emergency', 'ns-01', array['coct']::text[], true, 19, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"}]'::jsonb),
('so-s1', 'SO-S1', 'Transition from emergency operating procedures to severe accident guidelines', 'الانتقال من إجراءات التشغيل الطارئة إلى إرشادات الحوادث الجسيمة', 'severe_accident', 'ns-01', array['coct']::text[], true, 20, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"}]'::jsonb),
('so-s2', 'SO-S2', 'Evaluate severe accident strategies with the technical support centre', 'تقييم استراتيجيات الحوادث الجسيمة مع مركز الدعم الفني', 'severe_accident', 'ep-01', array['coct']::text[], true, 21, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"}]'::jsonb),
('so-s3', 'SO-S3', 'Protect containment integrity in a beyond-design-basis event', 'حماية سلامة الاحتواء في حدث يتجاوز أساس التصميم', 'severe_accident', 'ns-01', array['coct']::text[], true, 22, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"}]'::jsonb),
('so-t1', 'SO-T1', 'Three-way communication and clear crew briefings under stress', 'التواصل الثلاثي وإحاطات واضحة للطاقم تحت الضغط', 'team', 'co-02', array['coct','loct']::text[], true, 23, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"}]'::jsonb),
('so-t2', 'SO-T2', 'Conservative decision-making when plant conditions are uncertain', 'اتخاذ قرارات متحفظة عندما تكون ظروف المحطة غير مؤكدة', 'team', 'ld-02', array['coct']::text[], true, 24, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"}]'::jsonb),
('so-t3', 'SO-T3', 'Peer checking and procedure place-keeping', 'التحقق المتبادل وتتبّع الموضع في الإجراءات', 'team', 'hu-01', array['coct','loct']::text[], true, 25, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"}]'::jsonb),
('so-t4', 'SO-T4', 'Crew leadership: clear roles, command and control', 'قيادة الطاقم: أدوار واضحة وقيادة وتحكم', 'team', 'ld-01', array['coct']::text[], true, 26, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"}]'::jsonb),
('so-l1', 'SO-L1', 'Local operator field actions directed from the control room', 'إجراءات المشغّل المحلي الميدانية بتوجيه من غرفة التحكم', 'abnormal', 'co-01', array['loct']::text[], true, 27, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"}]'::jsonb),
('so-l2', 'SO-L2', 'Local operator response to a plant fire alarm with the fire brigade', 'استجابة المشغّل المحلي لإنذار حريق في المحطة مع فرقة الإطفاء', 'emergency', 'ep-02', array['loct']::text[], true, 28, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"}]'::jsonb)
insert into kafaa_sim_scenarios (id, code, title_en, title_ar, summary_en, summary_ar, events_en, events_ar, category, purpose, objective_ids, competency_ids, positions, duration_min, fidelity, programmes, status, revision, author_person_id, last_edited_by, submitted_at, approved_by, approved_at, review_note, last_run_on, run_count, history, sources, created_at, updated_at) values
('scn-001', 'SCN-001', 'Power ascension with a feedwater heater out of service', 'رفع القدرة مع خروج أحد مسخّنات مياه التغذية من الخدمة', 'The crew takes the unit from minimum load towards full power with one feedwater heater isolated, coordinating reactivity changes and secondary-side limits.', 'يرفع الطاقم الوحدة من الحمل الأدنى نحو القدرة الكاملة مع عزل أحد مسخّنات مياه التغذية، وينسّق تغييرات التفاعلية وحدود الدائرة الثانوية.', 'A heater is isolated before the run starts; a slow controller drift appears later in the run.', 'يُعزل أحد المسخّنات قبل بدء الجلسة، ويظهر انحراف بطيء في أحد أجهزة التحكم لاحقاً.', 'normal', 'training', array['so-n1','so-n2','so-n3','so-t1','so-t3']::text[], array['co-02','co-03','hu-01']::text[], array['ss','sro','ro']::text[], 240, 'full_scope', array['coct']::text[], 'approved', 2, 'p-k-instructor', 'p-k-instructor', null, 'p-training-mgr', '2024-02-04T11:00:00Z', null, '2025-02-20', 5, '[{"at":"2024-02-04T06:00:00Z","by":"p-k-instructor","action":"created","revision":1,"status":"draft"},{"at":"2024-02-04T08:00:00Z","by":"p-k-instructor","action":"revised","revision":2,"status":"in_review"},{"at":"2024-02-04T11:00:00Z","by":"p-training-mgr","action":"approve","revision":2,"status":"approved","note":null}]'::jsonb, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"},{"id":"enec-training-facilities","label":"ENEC · Training facilities","url":"https://www.enec.ae/discover/how-nuclear-energy-works/who-operates-the-plant-/training-facilities/"}]'::jsonb, '2024-02-04T06:00:00Z', '2024-02-04T11:00:00Z'),
('scn-002', 'SCN-002', 'Planned load reduction for condenser work', 'خفض مخطط للحمل لأعمال المكثف', 'A planned power reduction to allow work on the condenser, with a surveillance that requires a technical specification entry along the way.', 'خفض مخطط للقدرة للسماح بأعمال على المكثف، مع اختبار مراقبة يتطلب الدخول في إحدى المواصفات الفنية خلال العملية.', 'One surveillance result is out of tolerance and needs an operability call.', 'تأتي نتيجة أحد اختبارات المراقبة خارج حدود التفاوت وتحتاج إلى قرار بشأن قابلية التشغيل.', 'normal', 'training', array['so-n2','so-n4','so-t1']::text[], array['co-02','co-03','ns-02']::text[], array['ss','sro','ro','lo']::text[], 180, 'full_scope', array['coct','loct']::text[], 'approved', 1, 'w-instr-01', 'w-instr-01', null, 'p-training-mgr', '2024-03-05T11:00:00Z', null, '2025-08-20', 5, '[{"at":"2024-03-05T06:00:00Z","by":"w-instr-01","action":"created","revision":1,"status":"draft"},{"at":"2024-03-05T11:00:00Z","by":"p-training-mgr","action":"approve","revision":1,"status":"approved","note":null}]'::jsonb, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"},{"id":"enec-training-facilities","label":"ENEC · Training facilities","url":"https://www.enec.ae/discover/how-nuclear-energy-works/who-operates-the-plant-/training-facilities/"}]'::jsonb, '2024-03-05T06:00:00Z', '2024-03-05T11:00:00Z'),
('scn-003', 'SCN-003', 'Shift turnover into a surveillance with an inoperable channel', 'تسليم وردية يليه اختبار مراقبة مع قناة غير قابلة للتشغيل', 'The oncoming crew takes over mid-surveillance and finds one protection channel already declared inoperable.', 'يتسلّم الطاقم القادم الوردية في منتصف اختبار مراقبة ويجد إحدى قنوات الحماية مُعلنة غير قابلة للتشغيل.', 'A second indication becomes erratic during the test.', 'تصبح قراءة ثانية غير مستقرة أثناء الاختبار.', 'normal', 'training', array['so-a1','so-n3','so-n4','so-t3']::text[], array['co-02','hu-01','ns-02','pf-03']::text[], array['ss','sro','ro']::text[], 120, 'full_scope', array['coct']::text[], 'approved', 1, 'p-k-instructor', 'p-k-instructor', null, 'p-training-mgr', '2024-04-06T11:00:00Z', null, '2026-05-21', 5, '[{"at":"2024-04-06T06:00:00Z","by":"p-k-instructor","action":"created","revision":1,"status":"draft"},{"at":"2024-04-06T11:00:00Z","by":"p-training-mgr","action":"approve","revision":1,"status":"approved","note":null}]'::jsonb, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"},{"id":"enec-training-facilities","label":"ENEC · Training facilities","url":"https://www.enec.ae/discover/how-nuclear-energy-works/who-operates-the-plant-/training-facilities/"}]'::jsonb, '2024-04-06T06:00:00Z', '2024-04-06T11:00:00Z'),
('scn-004', 'SCN-004', 'Loss of one main feedwater pump at full power', 'فقدان إحدى مضخات مياه التغذية الرئيسية عند القدرة الكاملة', 'One main feedwater pump trips at full power; the crew stabilises the plant with the automatic runback and field support.', 'تتوقف إحدى مضخات مياه التغذية الرئيسية عند القدرة الكاملة، ويثبّت الطاقم المحطة باستخدام الخفض الآلي والدعم الميداني.', 'The runback is incomplete and needs operator action.', 'يكون الخفض الآلي غير مكتمل ويحتاج إلى تدخل المشغّل.', 'abnormal', 'training', array['so-a2','so-t1','so-t2']::text[], array['co-02','ld-02','pf-03']::text[], array['ss','sro','ro','lo']::text[], 120, 'full_scope', array['coct','loct']::text[], 'approved', 2, 'w-instr-01', 'w-instr-01', null, 'p-training-mgr', '2024-05-07T11:00:00Z', null, '2025-02-20', 5, '[{"at":"2024-05-07T06:00:00Z","by":"w-instr-01","action":"created","revision":1,"status":"draft"},{"at":"2024-05-07T08:00:00Z","by":"w-instr-01","action":"revised","revision":2,"status":"in_review"},{"at":"2024-05-07T11:00:00Z","by":"p-training-mgr","action":"approve","revision":2,"status":"approved","note":null}]'::jsonb, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"},{"id":"enec-training-facilities","label":"ENEC · Training facilities","url":"https://www.enec.ae/discover/how-nuclear-energy-works/who-operates-the-plant-/training-facilities/"}]'::jsonb, '2024-05-07T06:00:00Z', '2024-05-07T11:00:00Z'),
('scn-005', 'SCN-005', 'Instrument channel failure during a power change', 'عطل في قناة قياس أثناء تغيير القدرة', 'During a planned power change a level channel fails, affecting an automatic controller; the crew diagnoses and takes manual control.', 'أثناء تغيير مخطط للقدرة تتعطل قناة قياس منسوب فتؤثر على جهاز تحكم آلي، فيشخّص الطاقم العطل ويتحول إلى التحكم اليدوي.', 'The failure is gradual, not a step change.', 'يكون العطل تدريجياً وليس مفاجئاً.', 'abnormal', 'training', array['so-a1','so-n2','so-t3']::text[], array['co-03','hu-01','pf-03']::text[], array['ss','sro','ro']::text[], 90, 'full_scope', array['coct']::text[], 'approved', 1, 'w-instr-02', 'w-instr-02', null, 'p-training-mgr', '2024-06-08T11:00:00Z', null, '2025-11-20', 5, '[{"at":"2024-06-08T06:00:00Z","by":"w-instr-02","action":"created","revision":1,"status":"draft"},{"at":"2024-06-08T11:00:00Z","by":"p-training-mgr","action":"approve","revision":1,"status":"approved","note":null}]'::jsonb, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"},{"id":"enec-training-facilities","label":"ENEC · Training facilities","url":"https://www.enec.ae/discover/how-nuclear-energy-works/who-operates-the-plant-/training-facilities/"}]'::jsonb, '2024-06-08T06:00:00Z', '2024-06-08T11:00:00Z'),
('scn-006', 'SCN-006', 'Reactor coolant pump seal degradation', 'تدهور موانع تسرّب مضخة مبرّد المفاعل', 'Seal parameters on one reactor coolant pump degrade over time; the crew decides when to remove the pump from service.', 'تتدهور مؤشرات موانع التسرّب في إحدى مضخات مبرّد المفاعل مع الوقت، ويقرر الطاقم متى يُخرج المضخة من الخدمة.', 'Degradation accelerates after the first crew decision.', 'يتسارع التدهور بعد أول قرار للطاقم.', 'abnormal', 'training', array['so-a3','so-t2','so-t4']::text[], array['ld-01','ld-02','pf-03']::text[], array['ss','sro','ro','sta']::text[], 120, 'full_scope', array['coct']::text[], 'approved', 1, 'p-k-instructor', 'p-k-instructor', null, 'p-training-mgr', '2024-07-09T11:00:00Z', null, '2025-08-20', 5, '[{"at":"2024-07-09T06:00:00Z","by":"p-k-instructor","action":"created","revision":1,"status":"draft"},{"at":"2024-07-09T11:00:00Z","by":"p-training-mgr","action":"approve","revision":1,"status":"approved","note":null}]'::jsonb, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"},{"id":"enec-training-facilities","label":"ENEC · Training facilities","url":"https://www.enec.ae/discover/how-nuclear-energy-works/who-operates-the-plant-/training-facilities/"}]'::jsonb, '2024-07-09T06:00:00Z', '2024-07-09T11:00:00Z'),
('scn-007', 'SCN-007', 'Small primary-to-secondary leak with a rising activity trend', 'تسرّب صغير من الأولية إلى الثانوية مع اتجاه متزايد للنشاط', 'Radiation monitors show a slowly rising trend; the crew confirms the leak, applies the technical specifications and plans a controlled shutdown.', 'تُظهر أجهزة رصد الإشعاع اتجاهاً متزايداً ببطء، فيؤكد الطاقم التسرّب ويطبّق المواصفات الفنية ويخطط لإيقاف مُتحكَّم به.', 'The leak rate increases slowly over the session.', 'يزداد معدل التسرّب ببطء خلال الجلسة.', 'abnormal', 'training', array['so-a4','so-n4','so-t2']::text[], array['ld-02','ns-02']::text[], array['ss','sro','ro','sta']::text[], 150, 'full_scope', array['coct']::text[], 'approved', 1, 'w-instr-01', 'w-instr-01', null, 'p-training-mgr', '2024-08-10T11:00:00Z', null, '2026-02-20', 5, '[{"at":"2024-08-10T06:00:00Z","by":"w-instr-01","action":"created","revision":1,"status":"draft"},{"at":"2024-08-10T11:00:00Z","by":"p-training-mgr","action":"approve","revision":1,"status":"approved","note":null}]'::jsonb, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"},{"id":"enec-training-facilities","label":"ENEC · Training facilities","url":"https://www.enec.ae/discover/how-nuclear-energy-works/who-operates-the-plant-/training-facilities/"}]'::jsonb, '2024-08-10T06:00:00Z', '2024-08-10T11:00:00Z'),
('scn-008', 'SCN-008', 'Loss of a non-safety electrical bus', 'فقدان قضيب توزيع كهربائي غير مرتبط بالأمان', 'A non-safety bus de-energises; the crew identifies lost loads, restores equipment and coordinates field checks.', 'ينقطع التيار عن قضيب توزيع غير مرتبط بالأمان، فيحدد الطاقم الأحمال المفقودة ويستعيد المعدات وينسّق الفحوص الميدانية.', 'One standby pump does not start automatically.', 'لا تبدأ إحدى المضخات الاحتياطية العمل تلقائياً.', 'abnormal', 'training', array['so-a5','so-t1','so-t3']::text[], array['co-02','hu-01','pf-03']::text[], array['ss','sro','ro','lo']::text[], 120, 'full_scope', array['coct','loct']::text[], 'approved', 1, 'w-instr-02', 'w-instr-02', null, 'p-training-mgr', '2024-09-11T11:00:00Z', null, '2025-05-21', 5, '[{"at":"2024-09-11T06:00:00Z","by":"w-instr-02","action":"created","revision":1,"status":"draft"},{"at":"2024-09-11T11:00:00Z","by":"p-training-mgr","action":"approve","revision":1,"status":"approved","note":null}]'::jsonb, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"},{"id":"enec-training-facilities","label":"ENEC · Training facilities","url":"https://www.enec.ae/discover/how-nuclear-energy-works/who-operates-the-plant-/training-facilities/"}]'::jsonb, '2024-09-11T06:00:00Z', '2024-09-11T11:00:00Z'),
('scn-009', 'SCN-009', 'Dropped control element at power', 'سقوط أحد عناصر التحكم أثناء التشغيل', 'A single control element drops into the core at power; the crew responds, assesses power distribution and plans recovery.', 'يسقط عنصر تحكم واحد داخل القلب أثناء التشغيل، فيستجيب الطاقم ويقيّم توزيع القدرة ويخطط للاستعادة.', 'Recovery is possible only after a power reduction.', 'لا تكون الاستعادة ممكنة إلا بعد خفض القدرة.', 'abnormal', 'training', array['so-a6','so-n2']::text[], array['co-03']::text[], array['ss','sro','ro']::text[], 90, 'full_scope', array['coct']::text[], 'approved', 1, 'p-k-instructor', 'p-k-instructor', null, 'p-training-mgr', '2024-01-12T11:00:00Z', null, '2026-02-20', 5, '[{"at":"2024-01-12T06:00:00Z","by":"p-k-instructor","action":"created","revision":1,"status":"draft"},{"at":"2024-01-12T11:00:00Z","by":"p-training-mgr","action":"approve","revision":1,"status":"approved","note":null}]'::jsonb, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"},{"id":"enec-training-facilities","label":"ENEC · Training facilities","url":"https://www.enec.ae/discover/how-nuclear-energy-works/who-operates-the-plant-/training-facilities/"}]'::jsonb, '2024-01-12T06:00:00Z', '2024-01-12T11:00:00Z'),
('scn-010', 'SCN-010', 'Loss of component cooling water to one train', 'فقدان مياه تبريد المكونات لأحد المسارات', 'Cooling water to one train is lost; the crew protects affected equipment and swaps to the standby train with field support.', 'تُفقد مياه التبريد لأحد المسارات، فيحمي الطاقم المعدات المتأثرة وينتقل إلى المسار الاحتياطي بدعم ميداني.', 'A heat exchanger outlet temperature keeps rising until the swap.', 'تستمر درجة حرارة مخرج أحد المبادلات الحرارية في الارتفاع حتى يتم التبديل.', 'abnormal', 'training', array['so-a7','so-t3']::text[], array['hu-01','pf-03']::text[], array['ss','sro','ro','lo']::text[], 120, 'full_scope', array['coct','loct']::text[], 'approved', 1, 'w-instr-01', 'w-instr-01', null, 'p-training-mgr', '2024-02-13T11:00:00Z', null, '2026-08-20', 5, '[{"at":"2024-02-13T06:00:00Z","by":"w-instr-01","action":"created","revision":1,"status":"draft"},{"at":"2024-02-13T11:00:00Z","by":"p-training-mgr","action":"approve","revision":1,"status":"approved","note":null}]'::jsonb, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"},{"id":"enec-training-facilities","label":"ENEC · Training facilities","url":"https://www.enec.ae/discover/how-nuclear-energy-works/who-operates-the-plant-/training-facilities/"}]'::jsonb, '2024-02-13T06:00:00Z', '2024-02-13T11:00:00Z'),
('scn-011', 'SCN-011', 'Reactor trip with a stuck control element', 'إيقاف المفاعل مع علوق أحد عناصر التحكم', 'The reactor trips and one control element does not fully insert; the crew completes the standard post-trip actions and verifies shutdown margin.', 'يتوقف المفاعل ولا يدخل أحد عناصر التحكم بالكامل، فيُكمل الطاقم الإجراءات القياسية بعد الإيقاف ويتحقق من هامش الإيقاف.', 'An auxiliary feedwater train is slow to start.', 'يتأخر أحد مسارات مياه التغذية المساعدة في البدء.', 'emergency', 'training', array['so-e1','so-t1']::text[], array['co-01','co-02']::text[], array['ss','sro','ro']::text[], 120, 'full_scope', array['coct']::text[], 'approved', 1, 'w-instr-02', 'w-instr-02', null, 'p-training-mgr', '2024-03-14T11:00:00Z', null, '2025-11-20', 5, '[{"at":"2024-03-14T06:00:00Z","by":"w-instr-02","action":"created","revision":1,"status":"draft"},{"at":"2024-03-14T11:00:00Z","by":"p-training-mgr","action":"approve","revision":1,"status":"approved","note":null}]'::jsonb, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"},{"id":"enec-training-facilities","label":"ENEC · Training facilities","url":"https://www.enec.ae/discover/how-nuclear-energy-works/who-operates-the-plant-/training-facilities/"}]'::jsonb, '2024-03-14T06:00:00Z', '2024-03-14T11:00:00Z'),
('scn-012', 'SCN-012', 'Small-break loss-of-coolant accident with one safety injection train unavailable', 'حادث فقدان مبرّد بكسر صغير مع عدم توفر أحد مسارات الحقن الآمن', 'A small break in the primary system with one safety injection train out of service; the crew diagnoses the event and follows the emergency procedures.', 'كسر صغير في الدائرة الأولية مع خروج أحد مسارات الحقن الآمن من الخدمة، ويشخّص الطاقم الحدث ويتّبع إجراءات الطوارئ.', 'The break grows slightly during the first hour.', 'يتّسع الكسر قليلاً خلال الساعة الأولى.', 'emergency', 'training', array['so-e1','so-e2','so-t2','so-t4']::text[], array['co-01','ld-01','ld-02','ns-01']::text[], array['ss','sro','ro','sta']::text[], 180, 'full_scope', array['coct']::text[], 'approved', 2, 'p-k-instructor', 'p-k-instructor', null, 'p-training-mgr', '2024-04-15T11:00:00Z', null, '2026-02-20', 10, '[{"at":"2024-04-15T06:00:00Z","by":"p-k-instructor","action":"created","revision":1,"status":"draft"},{"at":"2024-04-15T08:00:00Z","by":"p-k-instructor","action":"revised","revision":2,"status":"in_review"},{"at":"2024-04-15T11:00:00Z","by":"p-training-mgr","action":"approve","revision":2,"status":"approved","note":null}]'::jsonb, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"},{"id":"enec-training-facilities","label":"ENEC · Training facilities","url":"https://www.enec.ae/discover/how-nuclear-energy-works/who-operates-the-plant-/training-facilities/"}]'::jsonb, '2024-04-15T06:00:00Z', '2024-04-15T11:00:00Z'),
('scn-013', 'SCN-013', 'Steam generator tube rupture with a slow isolation', 'تمزق أنبوب مولّد البخار مع عزل بطيء', 'A tube rupture in one steam generator; the crew identifies the affected generator, isolates it and cools down within the procedure limits.', 'تمزق أنبوب في أحد مولّدات البخار، فيحدد الطاقم المولّد المتأثر ويعزله ويبرّد ضمن حدود الإجراء.', 'One isolation valve closes slowly.', 'يُغلق أحد صمامات العزل ببطء.', 'emergency', 'training', array['so-e1','so-e3','so-t1','so-t4']::text[], array['co-01','co-02','ld-01','ns-01']::text[], array['ss','sro','ro','sta']::text[], 180, 'full_scope', array['coct']::text[], 'approved', 1, 'w-instr-01', 'w-instr-01', null, 'p-training-mgr', '2024-05-16T11:00:00Z', null, '2026-05-21', 10, '[{"at":"2024-05-16T06:00:00Z","by":"w-instr-01","action":"created","revision":1,"status":"draft"},{"at":"2024-05-16T11:00:00Z","by":"p-training-mgr","action":"approve","revision":1,"status":"approved","note":null}]'::jsonb, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"},{"id":"enec-training-facilities","label":"ENEC · Training facilities","url":"https://www.enec.ae/discover/how-nuclear-energy-works/who-operates-the-plant-/training-facilities/"}]'::jsonb, '2024-05-16T06:00:00Z', '2024-05-16T11:00:00Z'),
('scn-014', 'SCN-014', 'Loss of all feedwater after a turbine trip', 'فقدان كامل مياه التغذية بعد توقف التوربين', 'After a turbine trip no feedwater source is available; the crew restores a heat sink and decides when to use the alternative cooling path.', 'بعد توقف التوربين لا يتوفر أي مصدر لمياه التغذية، فيستعيد الطاقم مصرف الحرارة ويقرر متى يستخدم مسار التبريد البديل.', 'The first restoration attempt does not succeed.', 'لا تنجح المحاولة الأولى للاستعادة.', 'emergency', 'training', array['so-e1','so-e4','so-t2']::text[], array['co-01','ld-02','ns-01']::text[], array['ss','sro','ro','sta']::text[], 150, 'full_scope', array['coct']::text[], 'approved', 1, 'w-instr-02', 'w-instr-02', null, 'p-training-mgr', '2024-06-17T11:00:00Z', null, '2025-08-20', 5, '[{"at":"2024-06-17T06:00:00Z","by":"w-instr-02","action":"created","revision":1,"status":"draft"},{"at":"2024-06-17T11:00:00Z","by":"p-training-mgr","action":"approve","revision":1,"status":"approved","note":null}]'::jsonb, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"},{"id":"enec-training-facilities","label":"ENEC · Training facilities","url":"https://www.enec.ae/discover/how-nuclear-energy-works/who-operates-the-plant-/training-facilities/"}]'::jsonb, '2024-06-17T06:00:00Z', '2024-06-17T11:00:00Z'),
('scn-015', 'SCN-015', 'Station blackout with a delayed diesel generator start', 'انقطاع التيار الكامل مع تأخر بدء مولّد الديزل', 'All AC power is lost and the emergency diesel generators are delayed; the crew protects the core, classifies the event and restores power with field teams.', 'يُفقد التيار المتردد بالكامل ويتأخر بدء مولّدات الديزل الطارئة، فيحمي الطاقم القلب ويصنّف الحدث ويستعيد التيار مع الفرق الميدانية.', 'One diesel generator starts only after local action.', 'لا يبدأ أحد مولّدات الديزل إلا بعد تدخل محلي.', 'emergency', 'training', array['so-e5','so-e7','so-t4']::text[], array['ep-02','ld-01','ns-01']::text[], array['ss','sro','ro','sta','lo']::text[], 240, 'full_scope', array['coct','loct']::text[], 'approved', 1, 'p-k-instructor', 'p-k-instructor', null, 'p-training-mgr', '2024-07-18T11:00:00Z', null, '2026-05-21', 5, '[{"at":"2024-07-18T06:00:00Z","by":"p-k-instructor","action":"created","revision":1,"status":"draft"},{"at":"2024-07-18T11:00:00Z","by":"p-training-mgr","action":"approve","revision":1,"status":"approved","note":null}]'::jsonb, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"},{"id":"enec-training-facilities","label":"ENEC · Training facilities","url":"https://www.enec.ae/discover/how-nuclear-energy-works/who-operates-the-plant-/training-facilities/"}]'::jsonb, '2024-07-18T06:00:00Z', '2024-07-18T11:00:00Z'),
('scn-016', 'SCN-016', 'Anticipated transient without reactor trip during a feedwater transient', 'عابر متوقَّع دون إيقاف المفاعل أثناء عابر في مياه التغذية', 'A feedwater transient where the automatic reactor trip does not occur; the crew takes the manual and alternative shutdown actions.', 'عابر في مياه التغذية لا يحدث معه الإيقاف الآلي للمفاعل، فيتخذ الطاقم إجراءات الإيقاف اليدوية والبديلة.', 'The first manual action is only partly effective.', 'يكون الإجراء اليدوي الأول فعالاً جزئياً فقط.', 'emergency', 'training', array['so-a2','so-e6','so-t2']::text[], array['co-03','ld-02','pf-03']::text[], array['ss','sro','ro','sta']::text[], 120, 'full_scope', array['coct']::text[], 'in_review', 1, 'p-k-instructor', 'p-k-instructor', '2026-10-01T09:00:00Z', null, null, null, null, 0, '[{"at":"2024-08-19T06:00:00Z","by":"p-k-instructor","action":"created","revision":1,"status":"draft"},{"at":"2026-10-01T09:00:00Z","by":"p-k-instructor","action":"edited","revision":1,"status":"in_review"}]'::jsonb, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"},{"id":"enec-training-facilities","label":"ENEC · Training facilities","url":"https://www.enec.ae/discover/how-nuclear-energy-works/who-operates-the-plant-/training-facilities/"}]'::jsonb, '2024-08-19T06:00:00Z', '2026-10-01T09:00:00Z'),
('scn-017', 'SCN-017', 'Main steam line break inside containment', 'كسر في خط البخار الرئيسي داخل الاحتواء', 'A steam line break inside containment leads to an excess steam demand event; the crew isolates the break, controls cooldown and makes the emergency classification.', 'يؤدي كسر في خط البخار داخل الاحتواء إلى حدث زيادة في الطلب على البخار، فيعزل الطاقم الكسر ويتحكم في التبريد ويصنّف حالة الطوارئ.', 'Containment pressure rises faster than expected.', 'يرتفع ضغط الاحتواء أسرع من المتوقع.', 'emergency', 'training', array['so-e1','so-e7','so-e8']::text[], array['co-01','ep-02','ns-01']::text[], array['ss','sro','ro','sta']::text[], 150, 'full_scope', array['coct']::text[], 'approved', 1, 'w-instr-01', 'w-instr-01', null, 'p-training-mgr', '2024-09-20T11:00:00Z', null, '2026-08-20', 5, '[{"at":"2024-09-20T06:00:00Z","by":"w-instr-01","action":"created","revision":1,"status":"draft"},{"at":"2024-09-20T11:00:00Z","by":"p-training-mgr","action":"approve","revision":1,"status":"approved","note":null}]'::jsonb, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"},{"id":"enec-training-facilities","label":"ENEC · Training facilities","url":"https://www.enec.ae/discover/how-nuclear-energy-works/who-operates-the-plant-/training-facilities/"}]'::jsonb, '2024-09-20T06:00:00Z', '2024-09-20T11:00:00Z'),
('scn-018', 'SCN-018', 'Core exit temperatures rising: transition to severe accident guidelines', 'ارتفاع درجات حرارة مخرج القلب: الانتقال إلى إرشادات الحوادث الجسيمة', 'Core cooling degrades beyond the emergency procedures; the crew recognises the transition criteria and works with the technical support centre on strategies.', 'يتدهور تبريد القلب بما يتجاوز إجراءات الطوارئ، فيتعرّف الطاقم على معايير الانتقال ويعمل مع مركز الدعم الفني على الاستراتيجيات.', 'Communication with the support centre is delayed at first.', 'يتأخر التواصل مع مركز الدعم في البداية.', 'severe_accident', 'training', array['so-s1','so-s2','so-t4']::text[], array['ep-01','ld-01','ns-01']::text[], array['ss','sro','ro','sta']::text[], 240, 'full_scope', array['coct']::text[], 'approved', 1, 'w-instr-02', 'w-instr-02', null, 'p-training-mgr', '2024-01-21T11:00:00Z', null, '2025-11-20', 5, '[{"at":"2024-01-21T06:00:00Z","by":"w-instr-02","action":"created","revision":1,"status":"draft"},{"at":"2024-01-21T11:00:00Z","by":"p-training-mgr","action":"approve","revision":1,"status":"approved","note":null}]'::jsonb, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"},{"id":"enec-training-facilities","label":"ENEC · Training facilities","url":"https://www.enec.ae/discover/how-nuclear-energy-works/who-operates-the-plant-/training-facilities/"}]'::jsonb, '2024-01-21T06:00:00Z', '2024-01-21T11:00:00Z'),
('scn-019', 'SCN-019', 'Containment protection after a prolonged station blackout', 'حماية الاحتواء بعد انقطاع مطوّل للتيار عن المحطة', 'After a prolonged loss of AC power, the crew and the technical support centre choose and carry out containment protection strategies.', 'بعد فقدان مطوّل للتيار المتردد، يختار الطاقم ومركز الدعم الفني استراتيجيات حماية الاحتواء وينفّذانها.', 'Some portable equipment arrives late.', 'تصل بعض المعدات المتنقلة متأخرة.', 'severe_accident', 'training', array['so-e5','so-s2','so-s3']::text[], array['ep-01','ns-01']::text[], array['ss','sro','ro','sta']::text[], 240, 'full_scope', array['coct']::text[], 'draft', 1, 'p-k-instructor', 'p-k-instructor', null, null, null, null, null, 0, '[{"at":"2024-02-22T06:00:00Z","by":"p-k-instructor","action":"created","revision":1,"status":"draft"}]'::jsonb, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"},{"id":"enec-training-facilities","label":"ENEC · Training facilities","url":"https://www.enec.ae/discover/how-nuclear-energy-works/who-operates-the-plant-/training-facilities/"}]'::jsonb, '2024-02-22T06:00:00Z', '2024-02-22T06:00:00Z'),
('scn-020', 'SCN-020', 'Fire alarm in the turbine building with field response', 'إنذار حريق في مبنى التوربين مع استجابة ميدانية', 'A fire alarm in the turbine building; local operators confirm conditions, support the fire brigade and carry out actions directed by the control room.', 'إنذار حريق في مبنى التوربين، يتحقق المشغّلون المحليون من الظروف ويدعمون فرقة الإطفاء وينفّذون الإجراءات بتوجيه من غرفة التحكم.', 'Smoke spreads to an adjacent area.', 'ينتشر الدخان إلى منطقة مجاورة.', 'abnormal', 'training', array['so-l1','so-l2','so-t1']::text[], array['co-01','co-02','ep-02']::text[], array['ss','lo']::text[], 90, 'limited_scope', array['loct']::text[], 'approved', 1, 'w-instr-02', 'w-instr-02', null, 'p-training-mgr', '2024-03-23T11:00:00Z', null, null, 0, '[{"at":"2024-03-23T06:00:00Z","by":"w-instr-02","action":"created","revision":1,"status":"draft"},{"at":"2024-03-23T11:00:00Z","by":"p-training-mgr","action":"approve","revision":1,"status":"approved","note":null}]'::jsonb, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"},{"id":"enec-training-facilities","label":"ENEC · Training facilities","url":"https://www.enec.ae/discover/how-nuclear-energy-works/who-operates-the-plant-/training-facilities/"}]'::jsonb, '2024-03-23T06:00:00Z', '2024-03-23T11:00:00Z'),
('scn-021', 'SCN-021', 'Field support for the loss of an electrical bus', 'الدعم الميداني عند فقدان قضيب توزيع كهربائي', 'Local operators restore equipment in the field after a bus is lost, using peer checks and place-keeping while the control room directs the recovery.', 'يستعيد المشغّلون المحليون المعدات ميدانياً بعد فقدان قضيب توزيع، مع التحقق المتبادل وتتبّع الموضع بينما توجّه غرفة التحكم الاستعادة.', 'One breaker needs a second attempt.', 'يحتاج أحد القواطع إلى محاولة ثانية.', 'abnormal', 'training', array['so-a5','so-l1','so-t3']::text[], array['co-01','hu-01','pf-03']::text[], array['ro','lo']::text[], 90, 'limited_scope', array['loct']::text[], 'approved', 1, 'w-instr-02', 'w-instr-02', null, 'p-training-mgr', '2024-04-24T11:00:00Z', null, null, 0, '[{"at":"2024-04-24T06:00:00Z","by":"w-instr-02","action":"created","revision":1,"status":"draft"},{"at":"2024-04-24T11:00:00Z","by":"p-training-mgr","action":"approve","revision":1,"status":"approved","note":null}]'::jsonb, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"},{"id":"enec-training-facilities","label":"ENEC · Training facilities","url":"https://www.enec.ae/discover/how-nuclear-energy-works/who-operates-the-plant-/training-facilities/"}]'::jsonb, '2024-04-24T06:00:00Z', '2024-04-24T11:00:00Z'),
('scn-022', 'SCN-022', 'Crew resource management: degraded indications', 'إدارة موارد الطاقم: قراءات متدهورة', 'Several indications degrade at once; the scenario focuses on crew roles, communication and conservative decisions rather than on one malfunction.', 'تتدهور عدة قراءات في وقت واحد، ويركز السيناريو على أدوار الطاقم والتواصل والقرارات المتحفظة بدلاً من عطل واحد.', 'Two indications disagree; one is wrong.', 'تتعارض قراءتان، إحداهما خاطئة.', 'abnormal', 'training', array['so-a1','so-t1','so-t2','so-t3','so-t4']::text[], array['co-02','hu-01','ld-01','ld-02','pf-03']::text[], array['ss','sro','ro','sta']::text[], 120, 'full_scope', array['coct']::text[], 'approved', 3, 'w-instr-01', 'w-instr-01', null, 'p-training-mgr', '2024-05-25T11:00:00Z', null, '2026-08-20', 10, '[{"at":"2024-05-25T06:00:00Z","by":"w-instr-01","action":"created","revision":1,"status":"draft"},{"at":"2024-05-25T08:00:00Z","by":"w-instr-01","action":"revised","revision":2,"status":"in_review"},{"at":"2024-05-25T09:00:00Z","by":"w-instr-01","action":"revised","revision":3,"status":"in_review"},{"at":"2024-05-25T11:00:00Z","by":"p-training-mgr","action":"approve","revision":3,"status":"approved","note":null}]'::jsonb, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"},{"id":"enec-training-facilities","label":"ENEC · Training facilities","url":"https://www.enec.ae/discover/how-nuclear-energy-works/who-operates-the-plant-/training-facilities/"}]'::jsonb, '2024-05-25T06:00:00Z', '2024-05-25T11:00:00Z'),
('scn-023', 'SCN-023', 'Legacy turbine runback (superseded)', 'خفض حمل التوربين القديم (استُبدل)', 'An older turbine runback scenario kept for history; replaced by the loss of one main feedwater pump scenario.', 'سيناريو قديم لخفض حمل التوربين محفوظ للسجل، واستُبدل بسيناريو فقدان إحدى مضخات مياه التغذية الرئيسية.', '', '', 'abnormal', 'training', array['so-a2']::text[], array['pf-03']::text[], array['ss','sro','ro']::text[], 60, 'desktop', array['coct']::text[], 'retired', 2, 'w-instr-02', 'w-instr-02', null, 'p-training-mgr', '2024-06-26T11:00:00Z', 'Superseded by SCN-004 (loss of one main feedwater pump).', null, 0, '[{"at":"2024-06-26T06:00:00Z","by":"w-instr-02","action":"created","revision":1,"status":"draft"},{"at":"2024-06-26T08:00:00Z","by":"w-instr-02","action":"revised","revision":2,"status":"in_review"},{"at":"2024-06-26T11:00:00Z","by":"p-training-mgr","action":"approve","revision":2,"status":"approved","note":null},{"at":"2025-06-30T06:00:00Z","by":"p-training-mgr","action":"retire","revision":2,"status":"retired","note":"Superseded by SCN-004 (loss of one main feedwater pump)."}]'::jsonb, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"},{"id":"enec-training-facilities","label":"ENEC · Training facilities","url":"https://www.enec.ae/discover/how-nuclear-energy-works/who-operates-the-plant-/training-facilities/"}]'::jsonb, '2024-06-26T06:00:00Z', '2025-06-30T06:00:00Z'),
('scn-024', 'SCN-024', 'Emergency classification under time pressure', 'تصنيف الطوارئ تحت ضغط الوقت', 'Plant conditions change quickly; the shift supervisor and the shift technical advisor must classify the event and complete notifications on time.', 'تتغير ظروف المحطة بسرعة، ويجب على مشرف الوردية والمستشار الفني للوردية تصنيف الحدث وإتمام الإبلاغ في الوقت المحدد.', 'A second change in conditions arrives during the notification.', 'يحدث تغير ثانٍ في الظروف أثناء الإبلاغ.', 'emergency', 'training', array['so-e7','so-t1']::text[], array['co-02','ep-02']::text[], array['ss','sro','sta']::text[], 90, 'full_scope', array['coct']::text[], 'in_review', 1, 'w-instr-01', 'w-instr-01', '2026-10-01T09:00:00Z', null, null, null, null, 0, '[{"at":"2024-07-27T06:00:00Z","by":"w-instr-01","action":"created","revision":1,"status":"draft"},{"at":"2026-10-01T09:00:00Z","by":"w-instr-01","action":"edited","revision":1,"status":"in_review"}]'::jsonb, '[{"id":"iaea-tecdoc-1963","label":"IAEA-TECDOC-1963 (2021) Development, Use and Maintenance of NPP Simulators for the Training and Authorization of Personnel","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1963web.pdf"},{"id":"enec-training-facilities","label":"ENEC · Training facilities","url":"https://www.enec.ae/discover/how-nuclear-energy-works/who-operates-the-plant-/training-facilities/"}]'::jsonb, '2024-07-27T06:00:00Z', '2026-10-01T09:00:00Z')
