insert into kafaa_course_skill_links (id, course_id, skill_id, level, objective_n, objective_en, objective_ar, active, updated_by, updated_at) values
('csl-plantdata-da-01-analysis', 'c-fs-plantdata', 'sk-da-01-analysis', 2, 1, 'Analyse plant trend and work-order data and present a defensible finding', 'تحليل بيانات اتجاهات المحطة وأوامر العمل وتقديم نتيجة قابلة للدفاع عنها', true, null, '2026-10-10T00:00:00Z'),
('csl-plantdata-fs-ai-plantdata', 'c-fs-plantdata', 'sk-fs-ai-plantdata', 1, 2, 'Judge whether a data set is fit for the question being asked', 'الحكم على ملاءمة مجموعة البيانات للسؤال المطروح', true, null, '2026-10-10T00:00:00Z'),
('csl-scripting-da-01-scripting', 'c-fs-scripting', 'sk-da-01-scripting', 2, 1, 'Write, test and document a short script that automates a routine analysis', 'كتابة نص برمجي قصير واختباره وتوثيقه لأتمتة تحليل روتيني', true, null, '2026-10-10T00:00:00Z'),
('csl-scripting-fs-ai-automation', 'c-fs-scripting', 'sk-fs-ai-automation', 1, 2, 'Describe where a task can be automated and where a person must stay in the loop', 'وصف المواضع التي يمكن فيها أتمتة المهمة وتلك التي يجب أن يبقى فيها الإنسان طرفاً', true, null, '2026-10-10T00:00:00Z'),
('csl-twin-da-01-twins', 'c-fs-twin', 'sk-da-01-twins', 2, 1, 'Explain how a plant digital twin is built, fed and kept in step with the plant', 'شرح كيفية بناء التوأم الرقمي للمحطة وتغذيته والإبقاء على تطابقه مع المحطة', true, null, '2026-10-10T00:00:00Z'),
('csl-twin-fs-ai-twin', 'c-fs-twin', 'sk-fs-ai-twin', 1, 2, 'Check a twin''s output against recorded behaviour and flag drift', 'مطابقة مخرجات التوأم مع السلوك المسجّل والإشارة إلى الانحراف', true, null, '2026-10-10T00:00:00Z'),
('csl-remote-da-01-remote', 'c-fs-remote', 'sk-da-01-remote', 2, 1, 'Monitor an autonomous or remote task and decide when to intervene', 'مراقبة مهمة ذاتية أو عن بُعد وتقرير وقت التدخل', true, null, '2026-10-10T00:00:00Z'),
('csl-remote-mp-01-remote', 'c-fs-remote', 'sk-mp-01-remote', 1, 2, 'Plan a remote inspection and the installation checks around it', 'تخطيط فحص عن بُعد وفحوص التركيب المحيطة به', true, null, '2026-10-10T00:00:00Z'),
('csl-remote-fs-dp-robotics', 'c-fs-remote', 'sk-fs-dp-robotics', 1, 3, 'Describe the inspection robots and drones in use and their limits', 'وصف روبوتات الفحص والطائرات المسيّرة المستخدمة وحدودها', true, null, '2026-10-10T00:00:00Z'),
('csl-aiverify-fs-ai-verify', 'c-fs-aiverify', 'sk-fs-ai-verify', 2, 1, 'Verify an AI output against independent indications and challenge it when they disagree', 'التحقق من مخرجات الذكاء الاصطناعي مقابل مؤشرات مستقلة والطعن فيها عند التعارض', true, null, '2026-10-10T00:00:00Z'),
('csl-aiverify-da-02-review', 'c-fs-aiverify', 'sk-da-02-review', 2, 2, 'Review AI outputs under the governance procedure and record the result', 'مراجعة مخرجات الذكاء الاصطناعي وفق إجراء الحوكمة وتسجيل النتيجة', true, null, '2026-10-10T00:00:00Z'),
('csl-aiverify-fs-ai-anomaly', 'c-fs-aiverify', 'sk-fs-ai-anomaly', 1, 3, 'Triage an AI alert with at least one independent indication', 'فرز تنبيه من الذكاء الاصطناعي بمؤشر مستقل واحد على الأقل', true, null, '2026-10-10T00:00:00Z'),
('csl-agents-fs-ai-prompt', 'c-fs-agents', 'sk-fs-ai-prompt', 2, 1, 'Write clear, bounded prompts and agent instructions for an approved tool', 'كتابة أوامر وتعليمات وكلاء واضحة ومحددة لأداة معتمدة', true, null, '2026-10-10T00:00:00Z'),
('csl-agents-fs-ai-use', 'c-fs-agents', 'sk-fs-ai-use', 2, 2, 'Use approved AI tools in daily work within their use class', 'استخدام أدوات الذكاء الاصطناعي المعتمدة في العمل اليومي ضمن فئة استخدامها', true, null, '2026-10-10T00:00:00Z'),
('csl-agents-fs-ai-data-care', 'c-fs-agents', 'sk-fs-ai-data-care', 1, 3, 'Decide which data may and may not go into a tool', 'تحديد البيانات التي يجوز إدخالها في الأداة وتلك التي لا يجوز', true, null, '2026-10-10T00:00:00Z'),
('csl-cyber-fs-cy-phishing', 'c-fs-cyber', 'sk-fs-cy-phishing', 1, 1, 'Recognise a phishing attempt and respond safely', 'التعرف على محاولة تصيّد والتصرف بأمان', true, null, '2026-10-10T00:00:00Z'),
('csl-cyber-fs-cy-media', 'c-fs-cyber', 'sk-fs-cy-media', 1, 2, 'Follow the removable media rules every time', 'اتباع قواعد الوسائط القابلة للإزالة في كل مرة', true, null, '2026-10-10T00:00:00Z'),
('csl-cyber-fs-cy-access', 'c-fs-cyber', 'sk-fs-cy-access', 1, 3, 'Look after passwords and access as personal duties', 'العناية بكلمات المرور والصلاحيات كواجبات شخصية', true, null, '2026-10-10T00:00:00Z'),
('csl-cyber-fs-cy-zones', 'c-fs-cyber', 'sk-fs-cy-zones', 1, 4, 'Explain in general terms why plant and office networks are kept apart', 'شرح سبب فصل شبكات المحطة عن شبكات المكاتب بعبارات عامة', true, null, '2026-10-10T00:00:00Z'),
('csl-cyber-fs-cy-report', 'c-fs-cyber', 'sk-fs-cy-report', 1, 5, 'Report a suspected cyber incident through the right channel', 'الإبلاغ عن حادث سيبراني مشتبه به عبر القناة الصحيحة', true, null, '2026-10-10T00:00:00Z'),
('csl-smr-fs-adv-smr', 'c-fs-smr', 'sk-fs-adv-smr', 2, 1, 'Compare SMR design families with the APR-1400 and explain the main differences', 'مقارنة عائلات تصميم المفاعلات المعيارية الصغيرة بمفاعل APR-1400 وشرح الفروق الرئيسية', true, null, '2026-10-10T00:00:00Z'),
('csl-smr-pf-01-advfuel', 'c-fs-smr', 'sk-pf-01-advfuel', 1, 2, 'Describe advanced fuel forms and core materials in general terms', 'وصف أشكال الوقود المتقدمة ومواد القلب بعبارات عامة', true, null, '2026-10-10T00:00:00Z'),
('csl-smr-fs-adv-multimodule', 'c-fs-smr', 'sk-fs-adv-multimodule', 1, 3, 'Explain how one control room can oversee several modules', 'شرح كيفية إشراف غرفة تحكم واحدة على عدة وحدات', true, null, '2026-10-10T00:00:00Z'),
('csl-passive-fs-adv-passive', 'c-fs-passive', 'sk-fs-adv-passive', 2, 1, 'Explain how passive safety features work and change operator actions', 'شرح عمل خصائص السلامة الخاملة وكيف تغيّر إجراءات المشغّل', true, null, '2026-10-10T00:00:00Z'),
('csl-passive-ns-01-psa', 'c-fs-passive', 'sk-ns-01-psa', 1, 2, 'Read a probabilistic safety insight and say what it means for a design choice', 'قراءة رؤية احتمالية للسلامة وبيان دلالتها على خيار تصميمي', true, null, '2026-10-10T00:00:00Z'),
('csl-passive-pf-02-advcool', 'c-fs-passive', 'sk-pf-02-advcool', 1, 3, 'Describe gas, liquid-metal and natural-circulation coolant systems', 'وصف أنظمة التبريد بالغاز والمعادن السائلة والدوران الطبيعي', true, null, '2026-10-10T00:00:00Z'),
('csl-factoryqa-fs-adv-factoryqa', 'c-fs-factoryqa', 'sk-fs-adv-factoryqa', 2, 1, 'Plan quality surveillance for a factory-built module', 'تخطيط مراقبة الجودة لوحدة مصنّعة في المصنع', true, null, '2026-10-10T00:00:00Z'),
('csl-factoryqa-mp-01-remote', 'c-fs-factoryqa', 'sk-mp-01-remote', 1, 2, 'Check modular installation against its records, including remote inspection', 'فحص التركيب المعياري مقابل سجلاته، بما في ذلك الفحص عن بُعد', true, null, '2026-10-10T00:00:00Z'),
('csl-h2heat-fs-gr-h2heat', 'c-fs-h2heat', 'sk-fs-gr-h2heat', 2, 1, 'Explain how nuclear heat and power could serve hydrogen and industrial users', 'شرح كيفية خدمة الحرارة والطاقة النوويتين لمستخدمي الهيدروجين والصناعة', true, null, '2026-10-10T00:00:00Z'),
('csl-h2heat-ch-01-advchem', 'c-fs-h2heat', 'sk-ch-01-advchem', 1, 2, 'Describe the chemistry of high-temperature coolants such as molten salt', 'وصف كيمياء المبرّدات عالية الحرارة مثل الأملاح المنصهرة', true, null, '2026-10-10T00:00:00Z'),
('csl-h2heat-fs-gr-grid', 'c-fs-h2heat', 'sk-fs-gr-grid', 1, 3, 'Describe flexible operation alongside renewables on the grid', 'وصف التشغيل المرن إلى جانب الطاقة المتجددة على الشبكة', true, null, '2026-10-10T00:00:00Z'),
('csl-ghg-fs-gr-ghg', 'c-fs-ghg', 'sk-fs-gr-ghg', 2, 1, 'Classify emissions by scope and explain an emissions-avoided figure', 'تصنيف الانبعاثات حسب النطاق وشرح رقم الانبعاثات التي تم تجنبها', true, null, '2026-10-10T00:00:00Z'),
('csl-ghg-fs-gr-esg', 'c-fs-ghg', 'sk-fs-gr-esg', 1, 2, 'Read an ESG disclosure and identify its main metrics', 'قراءة إفصاح بيئي واجتماعي وحوكمي وتحديد مقاييسه الرئيسية', true, null, '2026-10-10T00:00:00Z'),
('csl-ghg-fs-gr-lifecycle', 'c-fs-ghg', 'sk-fs-gr-lifecycle', 1, 3, 'Outline a lifecycle carbon assessment for a plant activity', 'وضع مخطط لتقييم الكربون على امتداد دورة الحياة لنشاط في المحطة', true, null, '2026-10-10T00:00:00Z'),
('csl-systems-fs-tr-systems', 'c-fs-systems', 'sk-fs-tr-systems', 2, 1, 'Map a plant or organisational problem as a system with loops and delays', 'رسم مشكلة في المحطة أو المؤسسة كمنظومة ذات حلقات وتأخيرات', true, null, '2026-10-10T00:00:00Z'),
('csl-systems-fs-tr-analytical', 'c-fs-systems', 'sk-fs-tr-analytical', 1, 2, 'Break a problem into causes and test them with evidence', 'تفكيك المشكلة إلى أسباب واختبارها بالأدلة', true, null, '2026-10-10T00:00:00Z'),
('csl-resilience-fs-tr-resilience', 'c-fs-resilience', 'sk-fs-tr-resilience', 2, 1, 'Adapt routines through a change while keeping safety standards', 'تكييف الروتين خلال التغيير مع الحفاظ على معايير السلامة', true, null, '2026-10-10T00:00:00Z'),
('csl-resilience-fs-tr-selfaware', 'c-fs-resilience', 'sk-fs-tr-selfaware', 1, 2, 'Notice your own limits and ask for support early', 'إدراك حدودك وطلب الدعم مبكراً', true, null, '2026-10-10T00:00:00Z'),
('csl-creative-fs-tr-creative', 'c-fs-creative', 'sk-fs-tr-creative', 2, 1, 'Generate several options for a problem and choose one with evidence', 'توليد عدة خيارات لمشكلة واختيار أحدها بالأدلة', true, null, '2026-10-10T00:00:00Z'),
('csl-creative-fs-tr-curiosity', 'c-fs-creative', 'sk-fs-tr-curiosity', 1, 2, 'Keep a learning habit and share what you learn', 'الحفاظ على عادة التعلم ومشاركة ما تتعلمه', true, null, '2026-10-10T00:00:00Z'),
('csl-dataquality-fs-ai-plantdata', 'c-fs-dataquality', 'sk-fs-ai-plantdata', 2, 1, 'Assess and improve the quality of plant records used for decisions', 'تقييم جودة سجلات المحطة المستخدمة في القرارات وتحسينها', true, null, '2026-10-10T00:00:00Z'),
('csl-dataquality-fs-dp-ework', 'c-fs-dataquality', 'sk-fs-dp-ework', 1, 2, 'Complete electronic work packages to the data standard', 'إكمال حزم العمل الإلكترونية وفق معيار البيانات', true, null, '2026-10-10T00:00:00Z'),
('csl-xr-fs-ai-xr', 'c-fs-xr', 'sk-fs-ai-xr', 2, 1, 'Rehearse a maintenance task in VR and use AR work instructions', 'التمرّن على مهمة صيانة بالواقع الافتراضي واستخدام تعليمات العمل بالواقع المعزز', true, null, '2026-10-10T00:00:00Z'),
('csl-xr-fs-dp-ework', 'c-fs-xr', 'sk-fs-dp-ework', 1, 2, 'Link an XR step to its electronic work package', 'ربط خطوة الواقع الممتد بحزمة العمل الإلكترونية الخاصة بها', true, null, '2026-10-10T00:00:00Z'),
('csl-procure-fs-dp-procurement', 'c-fs-procure', 'sk-fs-dp-procurement', 2, 1, 'Run a sourcing event end to end in the digital procurement system', 'إدارة عملية توريد من البداية إلى النهاية في نظام المشتريات الرقمي', true, null, '2026-10-10T00:00:00Z'),
('csl-smr-x-fs-adv-smr', 'c-fs-smr-x', 'sk-fs-adv-smr', 1, 1, 'Describe SMR concepts and how they differ from large plants', 'وصف مفاهيم المفاعلات المعيارية الصغيرة واختلافها عن المحطات الكبيرة', true, null, '2026-10-10T00:00:00Z'),
('csl-smr-x-fs-adv-passive', 'c-fs-smr-x', 'sk-fs-adv-passive', 1, 2, 'Describe passive safety in general terms', 'وصف السلامة الخاملة بعبارات عامة', true, null, '2026-10-10T00:00:00Z'),
('csl-plantlit-x-fs-tr-techlit', 'c-fs-plantlit-x', 'sk-fs-tr-techlit', 1, 1, 'Explain how a PWR plant turns heat into electricity', 'شرح كيف تحوّل محطة مفاعل الماء المضغوط الحرارة إلى كهرباء', true, null, '2026-10-10T00:00:00Z'),
('csl-plantlit-x-fs-tr-systems', 'c-fs-plantlit-x', 'sk-fs-tr-systems', 1, 2, 'Describe how the main plant systems depend on each other', 'وصف اعتماد أنظمة المحطة الرئيسية بعضها على بعض', true, null, '2026-10-10T00:00:00Z')
insert into kafaa_academies (id, programme_id, code, name_en, name_ar, tagline_en, tagline_ar, theme, module_course_ids, project_en, project_ar, deliverable_en, deliverable_ar, artefact_kind, mentor_role_en, mentor_role_ar, reviewer_role_en, reviewer_role_ar, criteria_en, criteria_ar, weeks, weekly_hours, capacity, capstone_skills, no_decision, simulated, benchmark_ids, sources, sort) values
('ac-ai', 'pg-acad-ai', 'ACAD-AI', 'AI Academy', 'أكاديمية الذكاء الاصطناعي', 'From approved tools to a governed assistant you built and verified for your own work.', 'من الأدوات المعتمدة إلى مساعد محوكم بنيته وتحققت منه لعملك.', 'data_ai', array['c-fs-agents','c-fs-aiverify','c-fs-plantdata','c-fs-scripting']::text[], 'Build and verify a small governed AI assistant or automation for a real task in your own work, in the approved sandbox.', 'ابنِ مساعداً أو أتمتة صغيرة ومحوكمة بالذكاء الاصطناعي لمهمة حقيقية في عملك وتحقق منها، في البيئة التجريبية المعتمدة.', 'The working artefact, its verification record (independent checks and challenges) and a one-page owner note.', 'الأداة العاملة، وسجل التحقق منها (فحوص مستقلة وطعون)، وملاحظة من صفحة واحدة من المالك.', 'automation', 'AI practitioner mentor (Digital and AI governance)', 'مرشد ممارس للذكاء الاصطناعي (الحوكمة الرقمية والذكاء الاصطناعي)', 'AI governance reviewer', 'مراجع حوكمة الذكاء الاصطناعي', 'Staff in any role with a task an approved AI tool could help with; line manager supports 4 hours a week.', 'موظفون في أي دور لديهم مهمة يمكن أن تساعد فيها أداة ذكاء اصطناعي معتمدة؛ ويدعم المدير المباشر 4 ساعات أسبوعياً.', 24, 4, 16, '[{"skill_id":"sk-fs-ai-verify","level":2},{"skill_id":"sk-fs-ai-prompt","level":2},{"skill_id":"sk-fs-ai-automation","level":1}]'::jsonb, false, true, array['UAE-PEERS','NUC-NET']::text[], '[{"id":"fs19-adnoc","label":"ADNOC · Sustainability Report 2025 (AI upskilling)","url":"https://reports.adnoc.ae/e/sustainability-report-2025/eJFjvFKd42","as_of":"2026-10-10"},{"id":"fs20-nntp","label":"Fortum · Nordic Nuclear Trainee Programme","url":"https://www.fortum.com/careers/NNTP","as_of":"2026-10-10"}]'::jsonb, 1),
('ac-twin', 'pg-acad-twin', 'ACAD-TWIN', 'Digital Twin Bootcamp', 'المعسكر التدريبي للتوائم الرقمية', 'Validate a twin against recorded plant behaviour before anyone relies on it.', 'تحقق من التوأم مقابل سلوك المحطة المسجّل قبل أن يعتمد عليه أحد.', 'digital_plant', array['c-fs-plantdata','c-fs-dataquality','c-fs-twin','c-fs-scripting']::text[], 'Validate a SIMULATED digital twin of one plant system against recorded (SIMULATED) data and report drift and limits.', 'تحقق من توأم رقمي مُحاكى لأحد أنظمة المحطة مقابل بيانات مسجلة (مُحاكاة)، وأبلغ عن الانحراف والحدود.', 'A validation report: data used, checks run, drift found, limits of use and the owner who keeps it in step.', 'تقرير تحقق: البيانات المستخدمة، والفحوص المنفذة، والانحراف المكتشف، وحدود الاستخدام، والمالك المسؤول عن إبقائه متطابقاً.', 'twin_validation', 'Digital plant engineer mentor', 'مرشد مهندس المحطة الرقمية', 'Engineering subject-matter reviewer', 'مراجع متخصص في الهندسة', 'Engineers, technicians and operators who use plant data; scripting basics completed or taken in the first month.', 'المهندسون والفنيون والمشغلون الذين يستخدمون بيانات المحطة؛ مع إكمال أساسيات البرمجة النصية أو أخذها في الشهر الأول.', 24, 4, 12, '[{"skill_id":"sk-fs-ai-twin","level":2},{"skill_id":"sk-fs-ai-plantdata","level":2},{"skill_id":"sk-fs-ai-dataeng","level":1}]'::jsonb, false, true, array['NUC-NET','UAE-PEERS']::text[], '[{"id":"fs19-iaea-ai","label":"IAEA Bulletin · Enhancing nuclear power production with artificial intelligence","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence","as_of":"2026-10-10"},{"id":"fs20-nntp","label":"Fortum · Nordic Nuclear Trainee Programme","url":"https://www.fortum.com/careers/NNTP","as_of":"2026-10-10"}]'::jsonb, 2),
('ac-smr', 'pg-acad-smr', 'ACAD-SMR', 'SMR Fundamentals cohort', 'دفعة أساسيات المفاعلات المعيارية الصغيرة', 'Understand small modular reactors and what would change in your role. No deployment decision implied.', 'افهم المفاعلات المعيارية الصغيرة وما الذي سيتغير في دورك. لا يُفهم من ذلك أي قرار بالنشر.', 'advanced_reactor', array['c-fs-smr','c-fs-passive','c-fs-factoryqa']::text[], 'Write a role-delta note: how your role would change in a multi-module plant, as a planning assumption.', 'اكتب مذكرة فرق الدور: كيف سيتغير دورك في محطة متعددة الوحدات، كافتراض تخطيطي.', 'A two-page role-delta note with the tasks that grow, shrink or are new, and the learning each needs. Planning assumption only.', 'مذكرة فرق الدور من صفحتين تتضمن المهام التي تنمو أو تتقلص أو تستجد، والتعلم الذي تحتاجه كل منها. افتراض تخطيطي فقط.', 'role_delta', 'Senior operations mentor', 'مرشد عمليات أول', 'Quality and nuclear safety reviewer', 'مراجع الجودة والسلامة النووية', 'Operations, engineering, quality and maintenance staff; open to all families. Concept learning only.', 'موظفو العمليات والهندسة والجودة والصيانة؛ ومفتوحة لجميع العائلات الوظيفية. تعلّم مفاهيمي فقط.', 26, 3, 16, '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-adv-factoryqa","level":1}]'::jsonb, true, true, array['NUC-NET']::text[], '[{"id":"fs20-enen","label":"CORDIS · ENEN2plus project","url":"https://cordis.europa.eu/project/id/101061677","as_of":"2026-10-10"},{"id":"fs20-nntp","label":"Fortum · Nordic Nuclear Trainee Programme","url":"https://www.fortum.com/careers/NNTP","as_of":"2026-10-10"}]'::jsonb, 3),
('ac-energy', 'pg-acad-energy', 'ACAD-ENERGY', 'Energy Transition cohort', 'دفعة التحول في قطاع الطاقة', 'Nuclear in a net-zero system: heat, hydrogen, grid flexibility and carbon accounting.', 'الطاقة النووية في منظومة صافي الانبعاثات الصفري: الحرارة والهيدروجين ومرونة الشبكة ومحاسبة الكربون.', 'green', array['c-fs-h2heat','c-fs-ghg','c-fs-systems']::text[], 'A lifecycle carbon and heat-integration study for one plant activity, on SIMULATED data.', 'دراسة للكربون على امتداد دورة الحياة ولتكامل الحرارة لنشاط واحد في المحطة، على بيانات مُحاكاة.', 'A short study with the method, the assumptions, the result and what would change it. SIMULATED data only.', 'دراسة قصيرة تتضمن المنهجية والافتراضات والنتيجة وما الذي قد يغيّرها. بيانات مُحاكاة فقط.', 'study', 'Sustainability mentor', 'مرشد الاستدامة', 'Sustainability lead reviewer', 'مراجع قائد الاستدامة', 'Staff in engineering, chemistry, sustainability, finance and strategy roles.', 'الموظفون في أدوار الهندسة والكيمياء والاستدامة والمالية والاستراتيجية.', 26, 3, 14, '[{"skill_id":"sk-fs-gr-h2heat","level":2},{"skill_id":"sk-fs-gr-ghg","level":2},{"skill_id":"sk-fs-gr-grid","level":1}]'::jsonb, true, true, array['UAE-PEERS','NUC-NET']::text[], '[{"id":"fs19-enec-sr","label":"ENEC · Sustainability Report 2024 (GRI data)","url":"https://www.enec.ae/doc/sustainability-program-2024-23102025-low-69009902e1673.pdf","as_of":"2026-10-10"},{"id":"fs20-ega","label":"WAM · EGA launches EGA Academy","url":"https://www.wam.ae/en/article/blmzwis-ega-launches-ega-academy","as_of":"2026-10-10"}]'::jsonb, 4)
