insert into kafaa_performance_tasks (id, code, title_en, title_ar, brief_en, brief_ar, role_en, role_ar, fs_area, skill_ids, evidence_level, minutes, min_minutes, data, decisions, checks, rubric, rubric_version, pass_pct, gates, simulated, benchmark_ids, sources, status, sort) values
('pt-feedwater-drift', 'PT-DATA-01', 'Plant data: the channel that drifts', 'بيانات المحطة: القناة التي تنحرف', 'You are reviewing twelve hours of feedwater flow from three redundant channels (SIMULATED). The shift wants to know whether the flow really changed. Mark where the anomaly shows, decide what to do and justify it.', 'تراجع اثنتي عشرة ساعة من تدفق مياه التغذية من ثلاث قنوات احتياطية (بيانات محاكاة). تريد المناوبة معرفة ما إذا كان التدفق قد تغيّر فعلاً. علّم موضع ظهور الشذوذ وقرّر ما تفعل وبرّر قرارك.', 'Performance engineer on day shift', 'مهندس أداء في المناوبة النهارية', 'ai_data', array['sk-fs-ai-plantdata','sk-fs-tr-analytical']::text[], 2, 20, 5, '{"t0":"2026-09-14T06:00:00Z","step_min":15,"series":[{"key":"fw_a","label_en":"Feedwater flow, channel A","label_ar":"تدفق مياه التغذية، القناة A","unit":"%","values":[99.1,99.1,99.1,99.1,99.1,99.1,99.11,99.11,99.11,99.11,99.1,99.1,99.1,99.1,99.1,99.1,99.1,99.11,99.11,99.11,99.12,99.11,99.12,99.12,99.12,99.12,99.12,99.12,99.11,99.11,99.11,99.11,99.11,99.11,99.11,99.11,99.1,99.11,99.12,99.12,99.25,99.25,99.25,99.24,99.24,99.24,99.24,99.24]},{"key":"fw_b","label_en":"Feedwater flow, channel B","label_ar":"تدفق مياه التغذية، القناة B","unit":"%","values":[99.16,99.17,99.16,99.16,99.16,99.16,99.16,99.16,99.17,99.17,99.23,99.23,99.23,99.23,99.23,99.23,99.23,99.23,99.24,99.24,99.13,99.13,99.13,99.13,99.12,99.12,99.12,99.12,99.12,99.12,99.29,99.45,99.61,99.77,99.93,100.09,100.25,100.4,100.56,100.72,100.99,101.15,101.31,101.47,101.63,101.79,101.95,102.11]},{"key":"fw_c","label_en":"Feedwater flow, channel C","label_ar":"تدفق مياه التغذية، القناة C","unit":"%","values":[99.14,99.14,99.14,99.14,99.14,99.14,99.14,99.14,99.15,99.15,99.21,99.21,99.21,99.21,99.21,99.21,99.21,99.21,99.22,99.22,99.21,99.21,99.21,99.2,99.21,99.21,99.21,99.21,99.21,99.21,99.2,99.2,99.2,99.2,99.21,99.21,99.21,99.21,99.21,99.21,99.21,99.21,99.21,99.21,99.21,99.21,99.21,99.21]}]}'::jsonb, '[{"key":"average","en":"Use the average of the three channels and carry on","ar":"استخدام متوسط القنوات الثلاث والمتابعة"},{"key":"suspect","en":"Treat channel B as suspect: rely on the two agreeing channels, raise a work request and tell the shift supervisor","ar":"اعتبار القناة B مشكوكاً فيها: الاعتماد على القناتين المتوافقتين وفتح طلب عمل وإبلاغ مشرف المناوبة"},{"key":"recal","en":"Recalibrate channel B yourself now","ar":"معايرة القناة B بنفسك الآن"},{"key":"reduce","en":"Ask for an immediate power reduction","ar":"طلب خفض فوري للقدرة"}]'::jsonb, '[{"key":"redundant","en":"Compared redundant or related channels","ar":"قارنت القنوات الاحتياطية أو ذات الصلة"},{"key":"status","en":"Checked signal quality and instrument status","ar":"تحققت من جودة الإشارة وحالة الأداة"},{"key":"history","en":"Checked recent maintenance and calibration","ar":"تحققت من الصيانة والمعايرة الأخيرة"},{"key":"procedure","en":"Checked the procedure that applies","ar":"تحققت من الإجراء المطبق"}]'::jsonb, '[{"key":"anomaly","label_en":"Finds the anomaly","label_ar":"يحدد الشذوذ","max":3,"mode":"auto_anomaly","critical":false,"levels":[{"score":3,"en":"Marks channel B where its drift away from A and C shows.","ar":"يعلّم القناة B حيث يظهر انحرافها عن A وC."},{"score":2,"en":"Marks the right signal within three readings of where the anomaly shows.","ar":"يعلّم الإشارة الصحيحة على بعد ثلاث قراءات أو أقل من موضع ظهور الشذوذ."},{"score":1,"en":"Marks the right signal at another point.","ar":"يعلّم الإشارة الصحيحة في موضع آخر."},{"score":0,"en":"Marks another signal.","ar":"يعلّم إشارة أخرى."}]},{"key":"quality","label_en":"Checks the data before trusting it","label_ar":"يتحقق من البيانات قبل الوثوق بها","max":3,"mode":"assessor","critical":false,"levels":[{"score":3,"en":"Names the checks made (redundant channels, quality status, recent work) and what each showed.","ar":"يذكر التحققات التي أجراها (القنوات الاحتياطية، حالة الجودة، الأعمال الأخيرة) وما أظهره كل منها."},{"score":2,"en":"Makes relevant checks but does not say what they showed.","ar":"يجري تحققات ذات صلة لكنه لا يذكر ما أظهرته."},{"score":1,"en":"Makes one check only.","ar":"يجري تحققاً واحداً فقط."},{"score":0,"en":"Trusts the data or the tool without any check.","ar":"يثق بالبيانات أو الأداة دون أي تحقق."}]},{"key":"decision","label_en":"Chooses a safe, conservative action","label_ar":"يختار إجراءً آمناً ومتحفظاً","max":3,"mode":"auto_decision","critical":true,"levels":[{"score":3,"en":"The safe, conservative action that keeps people informed and in charge.","ar":"الإجراء الآمن المتحفظ الذي يُبقي الأشخاص على اطلاع وفي موقع القرار."},{"score":1,"en":"An action that is not unsafe but is premature or disproportionate.","ar":"إجراء غير خطر لكنه متسرّع أو غير متناسب."},{"score":0,"en":"An unsafe action: this line is critical, so the task is not passed whatever the total.","ar":"إجراء غير آمن: هذا البند حاسم، فلا تُجتاز المهمة أياً كان المجموع."}]},{"key":"justify","label_en":"Justifies the decision","label_ar":"يبرر القرار","max":3,"mode":"assessor","critical":false,"levels":[{"score":3,"en":"Cites the evidence, states what is uncertain and challenges the tool or data where needed.","ar":"يستشهد بالأدلة ويذكر مواضع عدم اليقين ويعترض على الأداة أو البيانات عند الحاجة."},{"score":2,"en":"Cites evidence but does not state uncertainty.","ar":"يستشهد بالأدلة لكنه لا يذكر عدم اليقين."},{"score":1,"en":"Gives a reason without evidence.","ar":"يعطي سبباً دون دليل."},{"score":0,"en":"No real justification.","ar":"لا يوجد تبرير فعلي."}]}]'::jsonb, 1, 65, array['MC-DIGITAL-PLANT']::text[], true, array['SKILLS-TECH','IAEA-AI']::text[], '[{"label":"TechWolf · Workday customer story (skills-based assessment)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-10"},{"label":"IAEA Bulletin · Enhancing nuclear power production with artificial intelligence","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence","as_of":"2026-10-10"}]'::jsonb, 'active', 1),
('pt-twin-divergence', 'PT-TWIN-01', 'Digital twin: plant and model part ways', 'التوأم الرقمي: المحطة والنموذج يفترقان', 'The condenser twin predicts vacuum from the cooling-water temperature (SIMULATED). After the sea warmed, model and plant moved together; later they part ways. Find where the plant departs from the model, decide and justify.', 'يتنبأ توأم المكثف بالخلخلة من درجة حرارة مياه التبريد (بيانات محاكاة). بعد ارتفاع حرارة البحر تحرّك النموذج والمحطة معاً، ثم افترقا لاحقاً. حدّد موضع ابتعاد المحطة عن النموذج وقرّر وبرّر.', 'System engineer for the condenser', 'مهندس نظام المكثف', 'ai_data', array['sk-fs-ai-twin','sk-fs-ai-anomaly']::text[], 2, 20, 5, '{"t0":"2026-09-14T06:00:00Z","step_min":15,"series":[{"key":"cw_temp","label_en":"Cooling-water inlet temperature","label_ar":"حرارة مدخل مياه التبريد","unit":"°C","values":[31.08,31.08,31.08,31.08,31.07,31.07,31.07,31.07,31.07,31.07,30.97,30.97,30.97,30.97,30.98,30.98,30.97,30.98,30.97,30.97,30.97,30.97,30.97,30.97,31.17,31.37,31.57,31.77,31.97,32.17,32.37,32.57,32.77,32.97,33.16,33.36,33.36,33.37,33.37,33.37,33.44,33.44,33.44,33.44,33.44,33.44,33.45,33.45]},{"key":"cv_twin","label_en":"Condenser pressure, twin prediction","label_ar":"ضغط المكثف، تنبؤ التوأم","unit":"kPa","values":[6.25,6.25,6.25,6.25,6.24,6.24,6.24,6.24,6.24,6.24,6.19,6.19,6.19,6.19,6.19,6.19,6.19,6.19,6.19,6.19,6.18,6.18,6.18,6.18,6.24,6.31,6.37,6.45,6.51,6.57,6.63,6.69,6.76,6.82,6.89,6.96,6.96,6.96,6.96,6.96,7,7,7,7,7.01,7.01,7,7.01]},{"key":"cv_meas","label_en":"Condenser pressure, measured","label_ar":"ضغط المكثف، مقيس","unit":"kPa","values":[6.25,6.25,6.25,6.25,6.24,6.24,6.24,6.24,6.24,6.24,6.16,6.16,6.16,6.16,6.15,6.15,6.16,6.16,6.15,6.15,6.18,6.18,6.18,6.18,6.24,6.31,6.37,6.45,6.51,6.57,6.67,6.73,6.8,6.86,6.85,6.92,7.01,7.1,7.19,7.28,7.45,7.54,7.63,7.72,7.82,7.91,7.99,8.09]}]}'::jsonb, '[{"key":"retune","en":"Re-tune the twin until it matches the plant again","ar":"إعادة ضبط التوأم حتى يطابق المحطة مجدداً"},{"key":"report","en":"Treat the gap as a possible plant change: report it, ask for air in-leakage indications to be checked and keep the twin unchanged until reviewed","ar":"اعتبار الفجوة تغيّراً محتملاً في المحطة: الإبلاغ عنها وطلب فحص مؤشرات تسرّب الهواء وإبقاء التوأم دون تغيير حتى المراجعة"},{"key":"ignore","en":"Ignore it: the twin is often a little off","ar":"تجاهلها: فالتوأم كثيراً ما يخطئ قليلاً"},{"key":"switch_off","en":"Switch the twin off","ar":"إيقاف التوأم"}]'::jsonb, '[{"key":"redundant","en":"Compared redundant or related channels","ar":"قارنت القنوات الاحتياطية أو ذات الصلة"},{"key":"status","en":"Checked signal quality and instrument status","ar":"تحققت من جودة الإشارة وحالة الأداة"},{"key":"history","en":"Checked recent maintenance and calibration","ar":"تحققت من الصيانة والمعايرة الأخيرة"},{"key":"procedure","en":"Checked the procedure that applies","ar":"تحققت من الإجراء المطبق"}]'::jsonb, '[{"key":"anomaly","label_en":"Finds the anomaly","label_ar":"يحدد الشذوذ","max":3,"mode":"auto_anomaly","critical":false,"levels":[{"score":3,"en":"Marks the measured pressure where it departs from the twin while the cooling water is steady.","ar":"يعلّم الضغط المقيس حيث يبتعد عن التوأم بينما مياه التبريد مستقرة."},{"score":2,"en":"Marks the right signal within three readings of where the anomaly shows.","ar":"يعلّم الإشارة الصحيحة على بعد ثلاث قراءات أو أقل من موضع ظهور الشذوذ."},{"score":1,"en":"Marks the right signal at another point.","ar":"يعلّم الإشارة الصحيحة في موضع آخر."},{"score":0,"en":"Marks another signal.","ar":"يعلّم إشارة أخرى."}]},{"key":"quality","label_en":"Checks the data before trusting it","label_ar":"يتحقق من البيانات قبل الوثوق بها","max":3,"mode":"assessor","critical":false,"levels":[{"score":3,"en":"Names the checks made (redundant channels, quality status, recent work) and what each showed.","ar":"يذكر التحققات التي أجراها (القنوات الاحتياطية، حالة الجودة، الأعمال الأخيرة) وما أظهره كل منها."},{"score":2,"en":"Makes relevant checks but does not say what they showed.","ar":"يجري تحققات ذات صلة لكنه لا يذكر ما أظهرته."},{"score":1,"en":"Makes one check only.","ar":"يجري تحققاً واحداً فقط."},{"score":0,"en":"Trusts the data or the tool without any check.","ar":"يثق بالبيانات أو الأداة دون أي تحقق."}]},{"key":"decision","label_en":"Chooses a safe, conservative action","label_ar":"يختار إجراءً آمناً ومتحفظاً","max":3,"mode":"auto_decision","critical":true,"levels":[{"score":3,"en":"The safe, conservative action that keeps people informed and in charge.","ar":"الإجراء الآمن المتحفظ الذي يُبقي الأشخاص على اطلاع وفي موقع القرار."},{"score":1,"en":"An action that is not unsafe but is premature or disproportionate.","ar":"إجراء غير خطر لكنه متسرّع أو غير متناسب."},{"score":0,"en":"An unsafe action: this line is critical, so the task is not passed whatever the total.","ar":"إجراء غير آمن: هذا البند حاسم، فلا تُجتاز المهمة أياً كان المجموع."}]},{"key":"justify","label_en":"Justifies the decision","label_ar":"يبرر القرار","max":3,"mode":"assessor","critical":false,"levels":[{"score":3,"en":"Cites the evidence, states what is uncertain and challenges the tool or data where needed.","ar":"يستشهد بالأدلة ويذكر مواضع عدم اليقين ويعترض على الأداة أو البيانات عند الحاجة."},{"score":2,"en":"Cites evidence but does not state uncertainty.","ar":"يستشهد بالأدلة لكنه لا يذكر عدم اليقين."},{"score":1,"en":"Gives a reason without evidence.","ar":"يعطي سبباً دون دليل."},{"score":0,"en":"No real justification.","ar":"لا يوجد تبرير فعلي."}]}]'::jsonb, 1, 65, array['MC-TWINS']::text[], true, array['SKILLS-TECH','IAEA-AI']::text[], '[{"label":"IAEA Bulletin · Enhancing nuclear power production with artificial intelligence","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence","as_of":"2026-10-10"},{"label":"TechWolf · Workday customer story (skills-based assessment)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-10"}]'::jsonb, 'active', 2),
('pt-ai-alert', 'PT-AI-01', 'Challenge an AI alert', 'الاعتراض على تنبيه من الذكاء الاصطناعي', 'An AI tool flags a vibration anomaly on a cooling pump (the flag is marked on the chart; SIMULATED). Decide whether the flag is the real story, mark the anomaly that matters and justify your decision.', 'نبّهت أداة ذكاء اصطناعي إلى شذوذ في اهتزاز مضخة تبريد (التنبيه معلّم على الرسم؛ بيانات محاكاة). قرّر إن كان التنبيه هو القصة الحقيقية، وعلّم الشذوذ المهم، وبرّر قرارك.', 'Equipment reliability engineer', 'مهندس موثوقية المعدات', 'ai_data', array['sk-fs-ai-verify','sk-fs-ai-anomaly']::text[], 2, 20, 5, '{"t0":"2026-09-14T06:00:00Z","step_min":15,"ai_flag":{"series":"vib","index":20,"label_en":"AI tool: vibration anomaly (confidence 0.97)","label_ar":"أداة الذكاء الاصطناعي: شذوذ في الاهتزاز (الثقة 0.97)"},"series":[{"key":"vib","label_en":"Pump vibration","label_ar":"اهتزاز المضخة","unit":"mm/s","values":[2.17,2.17,2.18,2.18,2.17,2.17,2.17,2.17,2.18,2.18,2.21,2.21,2.21,2.21,2.21,2.21,2.21,2.21,2.2,2.2,6.63,2.04,2.03,2.03,2.04,2.04,2.04,2.04,2.04,2.04,2.04,2.04,2.04,2.04,2.04,2.04,2.04,2.04,2.05,2.05,2.03,2.03,2.03,2.03,2.03,2.03,2.04,2.04]},{"key":"brg_temp","label_en":"Pump bearing temperature","label_ar":"حرارة محمل المضخة","unit":"°C","values":[58.27,58.27,58.27,58.27,58.26,58.26,58.26,58.26,58.28,58.29,57.76,57.76,57.76,57.75,57.75,57.75,57.75,57.74,57.74,57.74,58,58,57.99,58,58.01,58.01,58,58.01,58.37,58.72,59.06,59.41,59.77,60.12,60.45,60.8,61.16,61.51,61.88,62.23,62.54,62.89,63.24,63.6,63.95,64.3,64.65,65.01]}]}'::jsonb, '[{"key":"accept","en":"Accept the AI alert as the finding and close the bearing question","ar":"قبول تنبيه الذكاء الاصطناعي نتيجةً وإغلاق مسألة المحمل"},{"key":"challenge","en":"Challenge the alert: the spike is a single reading; report the rising bearing temperature and ask for a field check","ar":"الاعتراض على التنبيه: القفزة قراءة واحدة؛ الإبلاغ عن ارتفاع حرارة المحمل وطلب فحص ميداني"},{"key":"wait","en":"Wait for the AI tool to confirm with a second alert","ar":"انتظار تأكيد أداة الذكاء الاصطناعي بتنبيه ثانٍ"},{"key":"stop","en":"Stop the pump at once","ar":"إيقاف المضخة فوراً"}]'::jsonb, '[{"key":"redundant","en":"Compared redundant or related channels","ar":"قارنت القنوات الاحتياطية أو ذات الصلة"},{"key":"status","en":"Checked signal quality and instrument status","ar":"تحققت من جودة الإشارة وحالة الأداة"},{"key":"history","en":"Checked recent maintenance and calibration","ar":"تحققت من الصيانة والمعايرة الأخيرة"},{"key":"procedure","en":"Checked the procedure that applies","ar":"تحققت من الإجراء المطبق"}]'::jsonb, '[{"key":"anomaly","label_en":"Finds the anomaly","label_ar":"يحدد الشذوذ","max":3,"mode":"auto_anomaly","critical":false,"levels":[{"score":3,"en":"Marks the bearing temperature where its steady rise begins, not the single vibration spike.","ar":"يعلّم حرارة المحمل حيث يبدأ ارتفاعها المطّرد، لا قفزة الاهتزاز المنفردة."},{"score":2,"en":"Marks the right signal within three readings of where the anomaly shows.","ar":"يعلّم الإشارة الصحيحة على بعد ثلاث قراءات أو أقل من موضع ظهور الشذوذ."},{"score":1,"en":"Marks the right signal at another point.","ar":"يعلّم الإشارة الصحيحة في موضع آخر."},{"score":0,"en":"Marks another signal.","ar":"يعلّم إشارة أخرى."}]},{"key":"quality","label_en":"Checks the data before trusting it","label_ar":"يتحقق من البيانات قبل الوثوق بها","max":3,"mode":"assessor","critical":false,"levels":[{"score":3,"en":"Names the checks made (redundant channels, quality status, recent work) and what each showed.","ar":"يذكر التحققات التي أجراها (القنوات الاحتياطية، حالة الجودة، الأعمال الأخيرة) وما أظهره كل منها."},{"score":2,"en":"Makes relevant checks but does not say what they showed.","ar":"يجري تحققات ذات صلة لكنه لا يذكر ما أظهرته."},{"score":1,"en":"Makes one check only.","ar":"يجري تحققاً واحداً فقط."},{"score":0,"en":"Trusts the data or the tool without any check.","ar":"يثق بالبيانات أو الأداة دون أي تحقق."}]},{"key":"decision","label_en":"Chooses a safe, conservative action","label_ar":"يختار إجراءً آمناً ومتحفظاً","max":3,"mode":"auto_decision","critical":true,"levels":[{"score":3,"en":"The safe, conservative action that keeps people informed and in charge.","ar":"الإجراء الآمن المتحفظ الذي يُبقي الأشخاص على اطلاع وفي موقع القرار."},{"score":1,"en":"An action that is not unsafe but is premature or disproportionate.","ar":"إجراء غير خطر لكنه متسرّع أو غير متناسب."},{"score":0,"en":"An unsafe action: this line is critical, so the task is not passed whatever the total.","ar":"إجراء غير آمن: هذا البند حاسم، فلا تُجتاز المهمة أياً كان المجموع."}]},{"key":"justify","label_en":"Justifies the decision","label_ar":"يبرر القرار","max":3,"mode":"assessor","critical":false,"levels":[{"score":3,"en":"Cites the evidence, states what is uncertain and challenges the tool or data where needed.","ar":"يستشهد بالأدلة ويذكر مواضع عدم اليقين ويعترض على الأداة أو البيانات عند الحاجة."},{"score":2,"en":"Cites evidence but does not state uncertainty.","ar":"يستشهد بالأدلة لكنه لا يذكر عدم اليقين."},{"score":1,"en":"Gives a reason without evidence.","ar":"يعطي سبباً دون دليل."},{"score":0,"en":"No real justification.","ar":"لا يوجد تبرير فعلي."}]}]'::jsonb, 1, 65, array['MC-AI-LIT']::text[], true, array['SKILLS-TECH','IAEA-AI']::text[], '[{"label":"IAEA Bulletin · Enhancing nuclear power production with artificial intelligence","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence","as_of":"2026-10-10"},{"label":"TechWolf · Workday customer story (skills-based assessment)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-10"}]'::jsonb, 'active', 3),
('pt-ghg-log', 'PT-GRN-01', 'Green: the fuel log that does not add up', 'أخضر: سجل الوقود الذي لا يستقيم', 'You prepare the emergency-generator fuel figures for the annual greenhouse-gas inventory (SIMULATED monthly data). Find the entry that does not fit, decide how to report and justify.', 'تُعدّ أرقام وقود مولدات الطوارئ لجرد غازات الدفيئة السنوي (بيانات شهرية محاكاة). جد القيد الذي لا يتسق، وقرّر كيف تبلّغ، وبرّر.', 'Sustainability analyst', 'محلل استدامة', 'green_energy', array['sk-fs-gr-ghg','sk-fs-gr-esg']::text[], 2, 20, 5, '{"t0":"2025-10-01T00:00:00Z","step_min":43200,"labels":["2025-10","2025-11","2025-12","2026-01","2026-02","2026-03","2026-04","2026-05","2026-06","2026-07","2026-08","2026-09"],"series":[{"key":"edg_fuel","label_en":"Diesel used in generator tests","label_ar":"الديزل المستخدم في اختبارات المولدات","unit":"L","values":[1833,1832,1835,1834,1829,1828,1831,18400,1841,1840,1817,1818]},{"key":"edg_tests","label_en":"Generator test runs","label_ar":"مرات تشغيل اختبار المولدات","unit":"","values":[4,4,4,4,4,4,4,4,4,4,4,5]}]}'::jsonb, '[{"key":"as_is","en":"Report the total as recorded","ar":"الإبلاغ عن المجموع كما سُجّل"},{"key":"query","en":"Query the May entry with its owner, correct it with evidence and note the change in the inventory","ar":"الاستفسار عن قيد مايو من صاحبه وتصحيحه بالدليل وتسجيل التغيير في الجرد"},{"key":"delete","en":"Delete the May entry","ar":"حذف قيد مايو"},{"key":"average","en":"Replace it with the average of the other months without a note","ar":"استبدال المتوسط به للأشهر الأخرى دون ملاحظة"}]'::jsonb, '[{"key":"redundant","en":"Compared redundant or related channels","ar":"قارنت القنوات الاحتياطية أو ذات الصلة"},{"key":"status","en":"Checked signal quality and instrument status","ar":"تحققت من جودة الإشارة وحالة الأداة"},{"key":"history","en":"Checked recent maintenance and calibration","ar":"تحققت من الصيانة والمعايرة الأخيرة"},{"key":"procedure","en":"Checked the procedure that applies","ar":"تحققت من الإجراء المطبق"}]'::jsonb, '[{"key":"anomaly","label_en":"Finds the anomaly","label_ar":"يحدد الشذوذ","max":3,"mode":"auto_anomaly","critical":false,"levels":[{"score":3,"en":"Marks the fuel entry that is about ten times the others.","ar":"يعلّم قيد الوقود الذي يبلغ نحو عشرة أضعاف الآخرين."},{"score":2,"en":"Marks the right signal within three readings of where the anomaly shows.","ar":"يعلّم الإشارة الصحيحة على بعد ثلاث قراءات أو أقل من موضع ظهور الشذوذ."},{"score":1,"en":"Marks the right signal at another point.","ar":"يعلّم الإشارة الصحيحة في موضع آخر."},{"score":0,"en":"Marks another signal.","ar":"يعلّم إشارة أخرى."}]},{"key":"quality","label_en":"Checks the data before trusting it","label_ar":"يتحقق من البيانات قبل الوثوق بها","max":3,"mode":"assessor","critical":false,"levels":[{"score":3,"en":"Names the checks made (redundant channels, quality status, recent work) and what each showed.","ar":"يذكر التحققات التي أجراها (القنوات الاحتياطية، حالة الجودة، الأعمال الأخيرة) وما أظهره كل منها."},{"score":2,"en":"Makes relevant checks but does not say what they showed.","ar":"يجري تحققات ذات صلة لكنه لا يذكر ما أظهرته."},{"score":1,"en":"Makes one check only.","ar":"يجري تحققاً واحداً فقط."},{"score":0,"en":"Trusts the data or the tool without any check.","ar":"يثق بالبيانات أو الأداة دون أي تحقق."}]},{"key":"decision","label_en":"Chooses a safe, conservative action","label_ar":"يختار إجراءً آمناً ومتحفظاً","max":3,"mode":"auto_decision","critical":true,"levels":[{"score":3,"en":"The safe, conservative action that keeps people informed and in charge.","ar":"الإجراء الآمن المتحفظ الذي يُبقي الأشخاص على اطلاع وفي موقع القرار."},{"score":1,"en":"An action that is not unsafe but is premature or disproportionate.","ar":"إجراء غير خطر لكنه متسرّع أو غير متناسب."},{"score":0,"en":"An unsafe action: this line is critical, so the task is not passed whatever the total.","ar":"إجراء غير آمن: هذا البند حاسم، فلا تُجتاز المهمة أياً كان المجموع."}]},{"key":"justify","label_en":"Justifies the decision","label_ar":"يبرر القرار","max":3,"mode":"assessor","critical":false,"levels":[{"score":3,"en":"Cites the evidence, states what is uncertain and challenges the tool or data where needed.","ar":"يستشهد بالأدلة ويذكر مواضع عدم اليقين ويعترض على الأداة أو البيانات عند الحاجة."},{"score":2,"en":"Cites evidence but does not state uncertainty.","ar":"يستشهد بالأدلة لكنه لا يذكر عدم اليقين."},{"score":1,"en":"Gives a reason without evidence.","ar":"يعطي سبباً دون دليل."},{"score":0,"en":"No real justification.","ar":"لا يوجد تبرير فعلي."}]}]'::jsonb, 1, 65, '{}'::text[], true, array['SKILLS-TECH','GREENCOMP']::text[], '[{"label":"European Commission JRC · GreenComp, the European sustainability competence framework","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"label":"TechWolf · Workday customer story (skills-based assessment)","url":"https://www.techwolf.ai/customer-stories/workday","as_of":"2026-10-10"}]'::jsonb, 'active', 4)
insert into kafaa_perf_task_keys (id, task_id, series, from_idx, to_idx, decision_points, notes_en, notes_ar) values
('ptk-feedwater-drift', 'pt-feedwater-drift', 'fw_b', 30, 47, '[0,3,1,1]'::jsonb, 'Channel B drifts upward from reading 30 while A and C agree; the conservative path relies on the agreeing channels and gets B checked.', 'تنحرف القناة B صعوداً من القراءة 30 بينما تتفق A وC؛ المسار المتحفظ يعتمد على القناتين المتفقتين ويطلب فحص B.'),
('ptk-twin-divergence', 'pt-twin-divergence', 'cv_meas', 36, 47, '[0,3,0,1]'::jsonb, 'The sea-temperature rise from reading 24 is real and the twin follows it; from reading 36 the measured pressure leaves the twin (possible air in-leakage). Re-tuning would hide a plant change.', 'ارتفاع حرارة البحر من القراءة 24 حقيقي ويتبعه التوأم؛ ومن القراءة 36 يبتعد الضغط المقيس عن التوأم (تسرّب هواء محتمل). إعادة الضبط تخفي تغيّراً في المحطة.'),
('ptk-ai-alert', 'pt-ai-alert', 'brg_temp', 28, 47, '[0,3,1,1]'::jsonb, 'The vibration flag at reading 20 is a single-point spike (data glitch); the bearing temperature rises steadily from reading 28.', 'تنبيه الاهتزاز عند القراءة 20 قفزة في نقطة واحدة (خلل بيانات)؛ وحرارة المحمل ترتفع باطّراد من القراءة 28.'),
('ptk-ghg-log', 'pt-ghg-log', 'edg_fuel', 7, 7, '[0,3,0,1]'::jsonb, 'May 2026 holds 18,400 L, about ten times the other months with a normal number of test runs: a likely entry error to query.', 'يحمل مايو 2026 18,400 لتر، أي نحو عشرة أضعاف الأشهر الأخرى مع عدد عادي من مرات التشغيل: خطأ إدخال محتمل يُستفسر عنه.')
