insert into kafaa_journey_questions (id, sort, prompt_en, prompt_ar, hint_en, hint_ar, options) values
('q01', 1, 'Which school subject do you enjoy most?', 'ما المادة الدراسية التي تستمتع بها أكثر؟', 'Pick the one you look forward to.', 'اختر المادة التي تنتظرها بشغف.', '[{"id":"a","en":"Physics and maths","ar":"الفيزياء والرياضيات","families":["engineering","operations","nuclear-fuel"]},{"id":"b","en":"Chemistry and biology","ar":"الكيمياء والأحياء","families":["chemistry","radiation-protection","environment"]},{"id":"c","en":"Computing and technology","ar":"الحاسوب والتكنولوجيا","families":["cyber","engineering"]},{"id":"d","en":"Languages, business or social studies","ar":"اللغات أو إدارة الأعمال أو الدراسات الاجتماعية","families":["corporate","licensing","supply-chain"]}]'::jsonb),
('q02', 2, 'How do you like to work best?', 'كيف تفضّل أن تعمل؟', '', '', '[{"id":"a","en":"With my hands and tools","ar":"بيديّ وبالأدوات","families":["maintenance","fire-protection"]},{"id":"b","en":"With screens, data and systems","ar":"مع الشاشات والبيانات والأنظمة","families":["operations","cyber"]},{"id":"c","en":"With people: helping, teaching, organising","ar":"مع الناس: المساعدة والتعليم والتنظيم","families":["training","health-safety","corporate"]},{"id":"d","en":"With ideas: designing and calculating","ar":"مع الأفكار: التصميم والحساب","families":["engineering","nuclear-fuel"]}]'::jsonb),
('q03', 3, 'Where would you most like to spend your working day?', 'أين تحب أن تقضي يوم عملك؟', '', '', '[{"id":"a","en":"In a control room","ar":"في غرفة التحكم","families":["operations"]},{"id":"b","en":"In a workshop or out on the plant","ar":"في الورشة أو في أرجاء المحطة","families":["maintenance","outage"]},{"id":"c","en":"In a laboratory","ar":"في المختبر","families":["chemistry","radiation-protection","environment"]},{"id":"d","en":"In an office or meeting room","ar":"في مكتب أو قاعة اجتماعات","families":["corporate","licensing","quality","supply-chain"]}]'::jsonb),
('q04', 4, 'How do you feel about shift work (days and nights on a rota with a fixed team)?', 'ما رأيك في العمل بنظام المناوبات (نهاراً وليلاً ضمن فريق ثابت)؟', 'Operations crews keep the plant running around the clock.', 'تعمل فرق التشغيل على مدار الساعة للحفاظ على تشغيل المحطة.', '[{"id":"a","en":"Sounds exciting","ar":"يبدو ممتعاً","families":["operations","fire-protection"]},{"id":"b","en":"I would rather work regular day hours","ar":"أفضّل العمل في ساعات النهار المعتادة","families":["engineering","corporate","licensing"]},{"id":"c","en":"Not sure yet","ar":"لست متأكداً بعد","families":[]}]'::jsonb),
('q05', 5, 'How much do you enjoy following a precise procedure step by step?', 'إلى أي مدى تستمتع باتباع إجراء دقيق خطوة بخطوة؟', '', '', '[{"id":"a","en":"I like it: checklists keep things right","ar":"أحب ذلك: قوائم التحقق تضمن صحة العمل","families":["operations","quality","maintenance"]},{"id":"b","en":"I like writing and improving the procedures","ar":"أحب كتابة الإجراءات وتحسينها","families":["engineering","licensing","training"]},{"id":"c","en":"I prefer open-ended problems","ar":"أفضّل المسائل المفتوحة","families":["engineering","nuclear-fuel"]}]'::jsonb),
('q06', 6, 'Which of these problems would you most like to solve?', 'أي من هذه المشكلات تحب أن تحلّها؟', '', '', '[{"id":"a","en":"Why is this pump vibrating?","ar":"لماذا تهتز هذه المضخة؟","families":["maintenance"]},{"id":"b","en":"Is the cooling water chemistry right?","ar":"هل كيمياء مياه التبريد مضبوطة؟","families":["chemistry"]},{"id":"c","en":"How do we keep people''s radiation dose low?","ar":"كيف نُبقي الجرعة الإشعاعية للعاملين منخفضة؟","families":["radiation-protection","health-safety"]},{"id":"d","en":"How do we plan a refuelling outage?","ar":"كيف نخطط لفترة إيقاف لإعادة التزود بالوقود؟","families":["outage","supply-chain"]}]'::jsonb),
('q07', 7, 'In an emergency drill, which part would you take?', 'في تمرين الطوارئ، ما الدور الذي تختاره؟', '', '', '[{"id":"a","en":"Leading and coordinating the response","ar":"قيادة الاستجابة وتنسيقها","families":["emergency-preparedness","operations"]},{"id":"b","en":"Fighting the fire or giving first aid","ar":"مكافحة الحريق أو تقديم الإسعافات الأولية","families":["fire-protection","health-safety"]},{"id":"c","en":"Checking the systems and the data","ar":"فحص الأنظمة والبيانات","families":["engineering","cyber"]},{"id":"d","en":"Explaining what is happening to people","ar":"شرح ما يحدث للناس","families":["corporate","training"]}]'::jsonb),
('q08', 8, 'Which matters most to you?', 'ما الأهم بالنسبة إليك؟', '', '', '[{"id":"a","en":"Protecting the environment and the community","ar":"حماية البيئة والمجتمع","families":["environment","radiation-protection"]},{"id":"b","en":"Making sure everything meets the rules","ar":"التأكد من أن كل شيء يلتزم بالقواعد","families":["quality","licensing","oversight"]},{"id":"c","en":"Keeping the lights on for the UAE","ar":"إبقاء الأنوار مضاءة في الإمارات","families":["operations","maintenance"]},{"id":"d","en":"Building the future of clean energy","ar":"بناء مستقبل الطاقة النظيفة","families":["engineering","nuclear-fuel"]}]'::jsonb),
('q09', 9, 'After school, how long would you like to study?', 'بعد المدرسة، كم من الوقت تحب أن تدرس؟', 'This only suggests a route; you can choose any route on the board.', 'هذا يقترح مساراً فقط، ويمكنك اختيار أي مسار على اللوحة.', '[{"id":"a","en":"About two years, then start work (a diploma)","ar":"نحو سنتين ثم أبدأ العمل (دبلوم)","families":["operations","maintenance"],"route":"dnt"},{"id":"b","en":"A four-year university degree","ar":"شهادة جامعية لمدة أربع سنوات","families":["engineering"],"route":"energy-pioneers"},{"id":"c","en":"I already have, or will soon have, a degree","ar":"لديّ شهادة جامعية أو سأحصل عليها قريباً","families":[],"route":"gdp"},{"id":"d","en":"Not sure yet","ar":"لست متأكداً بعد","families":[]}]'::jsonb),
('q10', 10, 'In a team, you are usually the one who...', 'في الفريق، عادةً ما تكون الشخص الذي...', '', '', '[{"id":"a","en":"Takes the lead and organises","ar":"يتولى القيادة والتنظيم","families":["operations","training","outage"]},{"id":"b","en":"Becomes the expert on one thing","ar":"يصبح خبيراً في مجال واحد","families":["engineering","chemistry","nuclear-fuel"]},{"id":"c","en":"Checks the details others miss","ar":"يدقق في التفاصيل التي يغفلها الآخرون","families":["quality","oversight","cyber"]},{"id":"d","en":"Helps and teaches others","ar":"يساعد الآخرين ويعلّمهم","families":["training","health-safety"]}]'::jsonb)
insert into kafaa_journey_facts (id, step, programme_id, role_id, text_en, text_ar, source_id, as_of, precision, sort) values
('jf-ex-1', 'explore', null, null, 'ENEC runs six talent pipeline programmes, and more than 2,000 UAE nationals have worked on Barakah.', 'تدير ENEC ستة برامج لاستقطاب المواهب، وقد عمل أكثر من 2,000 مواطن إماراتي في براكة.', 'enec-dnt-grad', '2026-06-17', 'day', 1),
('jf-ex-2', 'explore', null, null, 'ENEC publishes learning materials about nuclear energy for school students.', 'تنشر ENEC مواد تعليمية عن الطاقة النووية لطلاب المدارس.', 'enec-students', '2026-10-08', 'day', 2),
('jf-ex-3', 'explore', 'mawaheb', null, 'Another way in: the ENEC-DGE Mawaheb agreement (May 2026) aims to qualify at least 100 UAE nationals over five years.', 'طريق آخر: تهدف اتفاقية مواهب بين ENEC ودائرة التمكين الحكومي (مايو 2026) إلى تأهيل 100 مواطن على الأقل خلال خمس سنوات.', 'enec-dge', '2026-05-01', 'month', 3),
('jf-mq-1', 'mustaqbali', 'mustaqbali', null, 'Mustaqbali is a two-week STEM experience for high-school students.', 'برنامج مستقبلي تجربة في العلوم والتكنولوجيا والهندسة والرياضيات لمدة أسبوعين لطلاب المرحلة الثانوية.', 'sr2024', '2024-12-31', 'year', 1),
('jf-mq-2', 'mustaqbali', 'mustaqbali', null, '50 students took part in 2024.', 'شارك 50 طالباً في عام 2024.', 'sr2024', '2024-12-31', 'year', 2),
('jf-mq-3', 'mustaqbali', 'mustaqbali', null, 'It is open to UAE nationals in high school.', 'البرنامج متاح للطلاب المواطنين في المرحلة الثانوية.', 'cns10', '2026-03-01', 'month', 3),
('jf-dnt-1', 'route', 'dnt', null, 'Diploma in Nuclear Technology (DNT): 24 months, for UAE high-school graduates.', 'دبلوم التكنولوجيا النووية: 24 شهراً لخريجي الثانوية العامة من المواطنين.', 'enec-dnt-grad', '2026-06-17', 'day', 1),
('jf-dnt-2', 'route', 'dnt', null, 'The first national cohort of 20 graduated on 17 June 2026.', 'تخرجت أول دفعة وطنية من 20 طالباً في 17 يونيو 2026.', 'enec-dnt-grad', '2026-06-17', 'day', 2),
('jf-dnt-3', 'route', 'dnt', null, 'Graduates move into Local Operator or Maintenance Technician roles.', 'ينتقل الخريجون إلى وظائف المشغّل المحلي أو فني الصيانة.', 'enec-dnt-grad', '2026-06-17', 'day', 3),
('jf-dnt-4', 'route', 'dnt', null, 'A monthly stipend is paid during the programme.', 'تُصرف مكافأة شهرية خلال البرنامج.', 'enec-dnt-launch', '2023-08-01', 'month', 4),
('jf-ep-1', 'route', 'energy-pioneers', null, 'Energy Pioneers scholarships have run since 2009, and more than 500 UAE nationals have benefitted.', 'تُقدَّم منح رواد الطاقة منذ عام 2009، واستفاد منها أكثر من 500 مواطن إماراتي.', 'enec-talent', '2026-10-08', 'day', 1),
('jf-ep-2', 'route', 'energy-pioneers', null, 'Scholars study at partner universities in the UAE, the United States and Korea.', 'يدرس المبتعثون في جامعات شريكة في الإمارات والولايات المتحدة وكوريا.', 'enec-talent', '2026-10-08', 'day', 2),
('jf-ep-3', 'route', 'internships', null, 'While at university: 22 students did internships in 2024, selected through screening exams and interviews.', 'خلال الدراسة الجامعية: التحق 22 طالباً بالتدريب الداخلي في 2024 بعد اختبارات فرز ومقابلات.', 'sr2024', '2024-12-31', 'year', 3),
('jf-gdp-1', 'route', 'gdp', null, 'Graduate Development Program (GDP): 18 to 36 months of position-targeted development (careers page).', 'برنامج تطوير الخريجين: من 18 إلى 36 شهراً من التطوير الموجّه نحو وظيفة محددة (صفحة الوظائف).', 'enec-careers', '2026-10-08', 'day', 1),
('jf-gdp-2', 'route', 'gdp', null, '22 graduates joined the programme in 2024.', 'انضم 22 خريجاً إلى البرنامج في 2024.', 'sr2024', '2024-12-31', 'year', 2),
('jf-gpo-1', 'route', 'gpo', null, 'Graduate Plant Operator (GPO): engineering graduates start as Local Operators, with Senior Reactor Operator training after three years.', 'مشغّل المحطة للخريجين: يبدأ خريجو الهندسة مشغّلين محليين، ثم يتدربون ليصبحوا مشغّلي مفاعل أوائل بعد ثلاث سنوات.', 'enec-gpo', '2025-08-21', 'day', 1),
('jf-gpo-2', 'route', 'gpo', null, 'The programme was launched on 21 August 2025.', 'أُطلق البرنامج في 21 أغسطس 2025.', 'enec-gpo', '2025-08-21', 'day', 2),
('jf-fr-lo', 'first_role', null, 'local-operator', 'Local Operator is the entry role in operations; Reactor Operator and Senior Reactor Operator licences come later under FANR-REG-17.', 'المشغّل المحلي هو وظيفة الدخول في التشغيل، وتأتي رخصتا مشغّل المفاعل ومشغّل المفاعل الأول لاحقاً وفق اللائحة FANR-REG-17.', 'fanr-reg17', '2026-10-08', 'day', 1),
('jf-fr-mt', 'first_role', null, 'maintenance-technician-engineer', 'Maintenance staff keep learning: 907 maintenance trainees were in initial or continuing training in 2024.', 'يواصل فريق الصيانة التعلّم: كان 907 متدربين في الصيانة في التدريب الأولي أو المستمر خلال 2024.', 'sr2024', '2024-12-31', 'year', 2),
('jf-fr-eng', 'first_role', null, 'systems-design-plant-engineer', 'Engineers join through the scholarship and graduate programmes and train for a targeted position.', 'ينضم المهندسون عبر برامج المنح والخريجين ويتدربون على وظيفة مستهدفة.', 'enec-careers', '2026-10-08', 'day', 3)
