('fsm:as-new-licensing-basis:sk-fs-adv-regulation', 'as-new-licensing-basis', 'adv_skill', 'sk-fs-adv-regulation', 'new', 1, false, true, 'Advanced-reactor regulatory awareness (FS02).', 'الوعي التنظيمي بالمفاعلات المتقدمة (من الكتالوج).', 3, null, '2026-10-08T00:00:00Z'),
('fsm:as-other-regulators:sk-fs-adv-regulation', 'as-other-regulators', 'adv_skill', 'sk-fs-adv-regulation', 'new', 1, false, true, 'Advanced-reactor regulatory awareness (FS02).', 'الوعي التنظيمي بالمفاعلات المتقدمة (من الكتالوج).', 2, null, '2026-10-08T00:00:00Z'),
('fsm:as-transportable-units:sk-fs-adv-micro', 'as-transportable-units', 'adv_skill', 'sk-fs-adv-micro', 'new', 1, false, true, 'Microreactor and transportable unit concepts (FS02).', 'مفاهيم المفاعلات الصغرى والوحدات القابلة للنقل (من الكتالوج).', 2, null, '2026-10-08T00:00:00Z'),
('fsm:as-triso-fuel:sk-fs-adv-fuelcycle', 'as-triso-fuel', 'adv_skill', 'sk-fs-adv-fuelcycle', 'new', 1, false, true, 'Advanced fuel-cycle awareness (FS02).', 'الوعي بدورة الوقود المتقدمة (من الكتالوج).', 2, null, '2026-10-08T00:00:00Z'),
('fsm:as-digital-twins:sk-fs-ai-twin', 'as-digital-twins', 'adv_skill', 'sk-fs-ai-twin', 'new', 2, false, true, 'Digital twin validation (FS02).', 'التحقق من التوائم الرقمية (من الكتالوج).', 3, null, '2026-10-08T00:00:00Z'),
('fsm:as-ic-maintenance:sk-fs-dp-dic', 'as-ic-maintenance', 'adv_skill', 'sk-fs-dp-dic', 'adapts', 2, false, true, 'Digital I&C fundamentals (FS02).', 'أساسيات الأجهزة والتحكم الرقمية (من الكتالوج).', 2, null, '2026-10-08T00:00:00Z'),
('fsm:as-opaque-inspection:sk-fs-dp-robotics', 'as-opaque-inspection', 'adv_skill', 'sk-fs-dp-robotics', 'new', 2, false, true, 'Robotics and remote inspection (FS02).', 'الروبوتات والتفتيش عن بعد (من الكتالوج).', 2, null, '2026-10-08T00:00:00Z'),
