insert into kafaa_skill_decay_classes (id, name_en, name_ar, summary_en, summary_ar, examples_en, examples_ar, default_months, areas, facts, sources, as_of, sort) values
('fast', 'Fast-changing', 'سريعة التغيّر', 'Digital, data and AI skills. Tools and ways of working change within a few years, so evidence ages quickly and needs refreshing more often.', 'مهارات الرقمنة والبيانات والذكاء الاصطناعي. تتغير الأدوات وطرق العمل خلال سنوات قليلة، لذلك تتقادم الأدلة بسرعة وتحتاج إلى تجديد أكثر.', 'Data analysis and visualisation, scripting, digital twins, reviewing AI outputs under governance', 'تحليل البيانات وتصويرها، والبرمجة النصية، والتوائم الرقمية، ومراجعة مخرجات الذكاء الاصطناعي ضمن الحوكمة', 18, array['digital','ai_data','digital_plant','cyber_hygiene']::text[], '[{"benchmark":"WEF-FOJ","value":"39%","label_en":"of workers'' core skills are expected to change by 2030 (44% in the 2023 edition). The report''s wording is \"change\", not \"become obsolete\".","label_ar":"من المهارات الأساسية للعاملين يُتوقع أن تتغير بحلول 2030 (44% في إصدار 2023). يستخدم التقرير كلمة \"تتغير\" لا \"تصبح متقادمة\".","source":"World Economic Forum · Future of Jobs Report 2025: the jobs of the future and the skills you need to get them","url":"https://www.weforum.org/stories/2025/01/future-of-jobs-report-2025-jobs-of-the-future-and-the-skills-you-need-to-get-them","as_of":"2026-10-10"},{"benchmark":"WEF-FOJ","value":"#1","label_en":"AI and big data is the fastest-growing skill to 2030, ahead of networks and cybersecurity, and technological literacy.","label_ar":"الذكاء الاصطناعي والبيانات الضخمة هي المهارة الأسرع نمواً حتى 2030، تليها الشبكات والأمن السيبراني، ثم الإلمام التقني.","source":"World Economic Forum · The Future of Jobs Report 2025, chapter 3: Skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, '[{"label":"World Economic Forum · The Future of Jobs Report 2025, chapter 3: Skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"},{"label":"World Economic Forum · Future of Jobs Report 2025: the jobs of the future and the skills you need to get them","url":"https://www.weforum.org/stories/2025/01/future-of-jobs-report-2025-jobs-of-the-future-and-the-skills-you-need-to-get-them"}]'::jsonb, '2026-10-10', 1),
('standard', 'Standard', 'قياسية', 'Most operational, maintenance, quality, human-performance and leadership skills. Practised regularly and re-evidenced through training, work and check-ins.', 'معظم مهارات التشغيل والصيانة والجودة والأداء البشري والقيادة. تُمارس بانتظام ويُعاد إثباتها من خلال التدريب والعمل وتقييمات المهارات.', 'Field rounds, pre-job briefs, inspection planning, coaching and feedback', 'الجولات الميدانية، وإحاطات ما قبل العمل، وتخطيط الفحص، والتوجيه وتقديم الملاحظات', 36, array['operations','maintenance','radiation_chemistry','human_performance','emergency','security','quality','leadership','project']::text[], '[{"benchmark":"SKILLS-TECH","value":null,"label_en":"Self ratings, manager ratings, skill reviews and peer ratings are kept as separate signals with their own provenance, instead of one collapsed number.","label_ar":"تُحفظ التقييمات الذاتية وتقييمات المدير ومراجعات المهارات وتقييمات الزملاء كإشارات منفصلة لكل منها مصدرها، بدلاً من رقم واحد مدمج.","source":"Degreed · Peer ratings: your 360-degree view of skills","url":"https://degreed.com/experience/blog/degreed-peer-ratings-your-360-degree-view-of-skills/","as_of":"2026-10-10"}]'::jsonb, '[{"label":"Degreed · Peer ratings: your 360-degree view of skills","url":"https://degreed.com/experience/blog/degreed-peer-ratings-your-360-degree-view-of-skills/"}]'::jsonb, '2026-10-10', 2),
('slow', 'Slow-changing', 'بطيئة التغيّر', 'Foundational plant science, engineering and nuclear safety. The physics does not change, and requalification keeps it evidenced; evidence still ages, only more slowly.', 'العلوم الأساسية للمحطة والهندسة والأمان النووي. لا تتغير الفيزياء، وتحافظ إعادة التأهيل على إثباتها؛ ومع ذلك تتقادم الأدلة ولكن بوتيرة أبطأ.', 'Core physics and reactivity, reactor coolant and safety systems, design changes, technical specifications', 'فيزياء القلب والتفاعلية، وأنظمة تبريد المفاعل والسلامة، وتغييرات التصميم، والمواصفات الفنية', 60, array['plant_systems','engineering','safety']::text[], '[{"benchmark":"FORECAST","value":null,"label_en":"Skills England publishes its 2030 estimates with the caution that all estimates of future employment are highly uncertain, and flags when a change of method breaks comparison with earlier years.","label_ar":"تنشر هيئة المهارات في إنجلترا تقديراتها لعام 2030 مع التنبيه إلى أن جميع تقديرات التوظيف المستقبلي غير مؤكدة إلى حد كبير، وتنبّه عندما يمنع تغيير المنهجية المقارنة مع السنوات السابقة.","source":"Skills England · Assessment of priority skills to 2030 (12 Aug 2025, updated 5 Nov 2025)","url":"https://www.gov.uk/government/publications/assessment-of-priority-skills-to-2030/assessment-of-priority-skills-to-2030","as_of":"2026-10-10"}]'::jsonb, '[{"label":"Skills England · Assessment of priority skills to 2030 (12 Aug 2025, updated 5 Nov 2025)","url":"https://www.gov.uk/government/publications/assessment-of-priority-skills-to-2030/assessment-of-priority-skills-to-2030"}]'::jsonb, '2026-10-10', 3)
insert into kafaa_microcred_unlocks (id, def_code, target_kind, target_id, note_en, note_ar, active, set_by, set_at) values
('mcu:MC-AI-ASSURER:opportunity:fg-ai-chem-trend-flags', 'MC-AI-ASSURER', 'opportunity', 'fg-ai-chem-trend-flags', 'Flags from the chemistry trend model are checked by people who can verify AI output.', 'يتحقق من إشارات نموذج اتجاهات الكيمياء أشخاص قادرون على التحقق من مخرجات الذكاء الاصطناعي.', true, 'p-training-mgr', '2026-10-11T09:00:00Z'),
('mcu:MC-AI-ASSURER:opportunity:opp-governed-ai-pilot', 'MC-AI-ASSURER', 'opportunity', 'opp-governed-ai-pilot', 'Reviewers of AI-drafted work-order summaries must hold the AI assurer credential.', 'يجب أن يحمل مراجعو ملخصات أوامر العمل التي يصوغها الذكاء الاصطناعي اعتماد ضامن مخرجات الذكاء الاصطناعي.', true, 'p-training-mgr', '2026-09-16T09:00:00Z'),
('mcu:MC-AI-ASSURER:rotation:rt-digital-draft', 'MC-AI-ASSURER', 'rotation', 'rt-digital-draft', 'The digital and data rotation takes AI assurers first.', 'يقبل تدوير البيانات والرقمنة حاملي اعتماد ضامن مخرجات الذكاء الاصطناعي أولًا.', true, 'p-training-mgr', '2026-09-16T09:00:00Z'),
('mcu:MC-DATA-DECISIONS:opportunity:opp-outage-schedule-analytics', 'MC-DATA-DECISIONS', 'opportunity', 'opp-outage-schedule-analytics', 'The critical-path dashboard is built on data-for-decisions practice.', 'تُبنى لوحة المسار الحرج على ممارسة البيانات لقرارات المحطة.', true, 'p-training-mgr', '2026-09-16T09:00:00Z'),
('mcu:MC-DATA-DECISIONS:rotation:rt-cross-ops-eng', 'MC-DATA-DECISIONS', 'rotation', 'rt-cross-ops-eng', 'Operations staff moving to plant engineering with this credential are eligible for the cross-functional rotation.', 'موظفو العمليات المنتقلون إلى هندسة المحطة الحاملون لهذا الاعتماد مؤهلون للتدوير متعدد الوظائف.', true, 'p-training-mgr', '2026-09-16T09:00:00Z'),
('mcu:MC-DATA-DECISIONS:rotation:rt-fs-data-office', 'MC-DATA-DECISIONS', 'rotation', 'rt-fs-data-office', 'The data office rotation takes holders of the data-for-decisions credential first.', 'يقبل تدوير مكتب البيانات حاملي اعتماد البيانات لقرارات المحطة أولًا.', true, 'p-training-mgr', '2026-10-11T09:00:00Z'),
('mcu:MC-TWINS:opportunity:fg-dig-twin-validation', 'MC-TWINS', 'opportunity', 'fg-dig-twin-validation', 'Validating the twin against plant history needs a digital twin practitioner.', 'يحتاج التحقق من التوأم الرقمي مقابل سجل المحطة إلى ممارس للتوائم الرقمية.', true, 'p-training-mgr', '2026-10-11T09:00:00Z'),
('mcu:MC-TWINS:opportunity:opp-digital-twin-study', 'MC-TWINS', 'opportunity', 'opp-digital-twin-study', 'The twin feasibility study needs people who can validate a twin.', 'تحتاج دراسة جدوى التوأم الرقمي إلى أشخاص قادرين على التحقق من التوأم.', true, 'p-training-mgr', '2026-09-16T09:00:00Z'),
('mcu:MC-TWINS:rotation:rt-digital-draft', 'MC-TWINS', 'rotation', 'rt-digital-draft', 'Digital twin practitioners are eligible for the digital and data rotation.', 'ممارسو التوائم الرقمية مؤهلون لتدوير البيانات والرقمنة.', true, 'p-training-mgr', '2026-09-16T09:00:00Z'),
('mcu:MC-TWINS:rotation:rt-fs-digital-twin', 'MC-TWINS', 'rotation', 'rt-fs-digital-twin', 'The digital twin rotation takes digital twin practitioners first.', 'يقبل تدوير التوأم الرقمي ممارسي التوائم الرقمية أولًا.', true, 'p-training-mgr', '2026-10-11T09:00:00Z')
