insert into kafaa_pathways (id, skill_id, level, title_en, title_ar, summary_en, summary_ar, outcome_en, outcome_ar, envelope_months, weekly_hours, status, listed, version, benchmark_ids, sources, updated_by, updated_at, sort) values
('pw-tr-analytical-l1', 'sk-fs-tr-analytical', 1, 'Analytical thinking: foundations', 'التفكير التحليلي: الأساسيات', 'Breaks a plant problem into causes and evidence, weighs options against safety margins and explains the reasoning in writing.', 'يفكّك مشكلة في المحطة إلى أسباب وأدلة، ويوازن الخيارات مقابل هوامش السلامة، ويشرح استدلاله كتابةً.', 'You can explain the basics of analytical thinking and apply them with guidance.', 'تستطيع شرح أساسيات التفكير التحليلي وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 1),
('pw-tr-analytical-l2', 'sk-fs-tr-analytical', 2, 'Analytical thinking: practitioner', 'التفكير التحليلي: الممارسة', 'Breaks a plant problem into causes and evidence, weighs options against safety margins and explains the reasoning in writing.', 'يفكّك مشكلة في المحطة إلى أسباب وأدلة، ويوازن الخيارات مقابل هوامش السلامة، ويشرح استدلاله كتابةً.', 'You apply analytical thinking on your own in routine work and check your result.', 'تطبّق التفكير التحليلي بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 2),
('pw-tr-analytical-l3', 'sk-fs-tr-analytical', 3, 'Analytical thinking: advanced practice', 'التفكير التحليلي: الممارسة المتقدمة', 'Breaks a plant problem into causes and evidence, weighs options against safety margins and explains the reasoning in writing.', 'يفكّك مشكلة في المحطة إلى أسباب وأدلة، ويوازن الخيارات مقابل هوامش السلامة، ويشرح استدلاله كتابةً.', 'You apply analytical thinking in unfamiliar situations and help others do it.', 'تطبّق التفكير التحليلي في مواقف غير مألوفة وتساعد الآخرين على ذلك.', 6, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 3),
('pw-tr-systems-l1', 'sk-fs-tr-systems', 1, 'Systems thinking: foundations', 'التفكير المنظومي: الأساسيات', 'Traces how a change in one system, team or contract ripples through defence in depth, and flags interactions others miss.', 'يتتبّع كيف ينتقل أثر تغيير في نظام أو فريق أو عقد عبر طبقات الدفاع في العمق، وينبّه إلى تفاعلات يغفلها الآخرون.', 'You can explain the basics of systems thinking and apply them with guidance.', 'تستطيع شرح أساسيات التفكير المنظومي وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 4),
('pw-tr-systems-l2', 'sk-fs-tr-systems', 2, 'Systems thinking: practitioner', 'التفكير المنظومي: الممارسة', 'Traces how a change in one system, team or contract ripples through defence in depth, and flags interactions others miss.', 'يتتبّع كيف ينتقل أثر تغيير في نظام أو فريق أو عقد عبر طبقات الدفاع في العمق، وينبّه إلى تفاعلات يغفلها الآخرون.', 'You apply systems thinking on your own in routine work and check your result.', 'تطبّق التفكير المنظومي بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 5),
('pw-tr-systems-l3', 'sk-fs-tr-systems', 3, 'Systems thinking: advanced practice', 'التفكير المنظومي: الممارسة المتقدمة', 'Traces how a change in one system, team or contract ripples through defence in depth, and flags interactions others miss.', 'يتتبّع كيف ينتقل أثر تغيير في نظام أو فريق أو عقد عبر طبقات الدفاع في العمق، وينبّه إلى تفاعلات يغفلها الآخرون.', 'You apply systems thinking in unfamiliar situations and help others do it.', 'تطبّق التفكير المنظومي في مواقف غير مألوفة وتساعد الآخرين على ذلك.', 6, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 6),
('pw-tr-resilience-l1', 'sk-fs-tr-resilience', 1, 'Resilience, flexibility and agility: foundations', 'المرونة والقدرة على التكيّف وسرعة الاستجابة: الأساسيات', 'Stays effective through outages, shift changes and new technology, recovers from setbacks and keeps procedure discipline under pressure.', 'يحافظ على فعاليته خلال فترات الانقطاع وتغيّر الورديات والتقنيات الجديدة، ويتعافى من الانتكاسات ويلتزم بالإجراءات تحت الضغط.', 'You can explain the basics of resilience, flexibility and agility and apply them with guidance.', 'تستطيع شرح أساسيات المرونة والقدرة على التكيّف وسرعة الاستجابة وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 7),
('pw-tr-resilience-l2', 'sk-fs-tr-resilience', 2, 'Resilience, flexibility and agility: practitioner', 'المرونة والقدرة على التكيّف وسرعة الاستجابة: الممارسة', 'Stays effective through outages, shift changes and new technology, recovers from setbacks and keeps procedure discipline under pressure.', 'يحافظ على فعاليته خلال فترات الانقطاع وتغيّر الورديات والتقنيات الجديدة، ويتعافى من الانتكاسات ويلتزم بالإجراءات تحت الضغط.', 'You apply resilience, flexibility and agility on your own in routine work and check your result.', 'تطبّق المرونة والقدرة على التكيّف وسرعة الاستجابة بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 8),
('pw-tr-curiosity-l1', 'sk-fs-tr-curiosity', 1, 'Curiosity and lifelong learning: foundations', 'الفضول والتعلّم مدى الحياة: الأساسيات', 'Seeks out new knowledge and operating experience, asks why, and turns what is learned into changed practice.', 'يبحث عن المعارف الجديدة وخبرات التشغيل، ويسأل عن الأسباب، ويحوّل ما يتعلّمه إلى ممارسة متغيّرة.', 'You can explain the basics of curiosity and lifelong learning and apply them with guidance.', 'تستطيع شرح أساسيات الفضول والتعلّم مدى الحياة وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 9),
('pw-tr-curiosity-l2', 'sk-fs-tr-curiosity', 2, 'Curiosity and lifelong learning: practitioner', 'الفضول والتعلّم مدى الحياة: الممارسة', 'Seeks out new knowledge and operating experience, asks why, and turns what is learned into changed practice.', 'يبحث عن المعارف الجديدة وخبرات التشغيل، ويسأل عن الأسباب، ويحوّل ما يتعلّمه إلى ممارسة متغيّرة.', 'You apply curiosity and lifelong learning on your own in routine work and check your result.', 'تطبّق الفضول والتعلّم مدى الحياة بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 10),
('pw-tr-creative-l1', 'sk-fs-tr-creative', 1, 'Creative thinking: foundations', 'التفكير الإبداعي: الأساسيات', 'Generates and tests new ways of working within the licensing basis, separating improvement ideas from changes that need design control.', 'يولّد طرق عمل جديدة ويختبرها ضمن أساس الترخيص، ويميّز أفكار التحسين عن التغييرات التي تتطلب ضبط التصميم.', 'You can explain the basics of creative thinking and apply them with guidance.', 'تستطيع شرح أساسيات التفكير الإبداعي وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 11),
('pw-tr-creative-l2', 'sk-fs-tr-creative', 2, 'Creative thinking: practitioner', 'التفكير الإبداعي: الممارسة', 'Generates and tests new ways of working within the licensing basis, separating improvement ideas from changes that need design control.', 'يولّد طرق عمل جديدة ويختبرها ضمن أساس الترخيص، ويميّز أفكار التحسين عن التغييرات التي تتطلب ضبط التصميم.', 'You apply creative thinking on your own in routine work and check your result.', 'تطبّق التفكير الإبداعي بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 12),
('pw-tr-techlit-l1', 'sk-fs-tr-techlit', 1, 'Technological literacy: foundations', 'الإلمام التقني: الأساسيات', 'Picks up new digital tools quickly, understands what they do and where they can fail, and uses them within approved boundaries.', 'يتقن الأدوات الرقمية الجديدة بسرعة، ويفهم ما تفعله وأين قد تخفق، ويستخدمها ضمن الحدود المعتمدة.', 'You can explain the basics of technological literacy and apply them with guidance.', 'تستطيع شرح أساسيات الإلمام التقني وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 13),
('pw-tr-techlit-l2', 'sk-fs-tr-techlit', 2, 'Technological literacy: practitioner', 'الإلمام التقني: الممارسة', 'Picks up new digital tools quickly, understands what they do and where they can fail, and uses them within approved boundaries.', 'يتقن الأدوات الرقمية الجديدة بسرعة، ويفهم ما تفعله وأين قد تخفق، ويستخدمها ضمن الحدود المعتمدة.', 'You apply technological literacy on your own in routine work and check your result.', 'تطبّق الإلمام التقني بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 14),
('pw-tr-leadership-l1', 'sk-fs-tr-leadership', 1, 'Leadership and social influence: foundations', 'القيادة والتأثير الاجتماعي: الأساسيات', 'Builds commitment to safety and change across teams, including people they do not manage, and models the behaviours they ask for.', 'يبني الالتزام بالسلامة والتغيير عبر الفرق، بما في ذلك من لا يديرهم مباشرة، ويكون قدوة في السلوكيات التي يطلبها.', 'You can explain the basics of leadership and social influence and apply them with guidance.', 'تستطيع شرح أساسيات القيادة والتأثير الاجتماعي وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 15),
('pw-tr-leadership-l2', 'sk-fs-tr-leadership', 2, 'Leadership and social influence: practitioner', 'القيادة والتأثير الاجتماعي: الممارسة', 'Builds commitment to safety and change across teams, including people they do not manage, and models the behaviours they ask for.', 'يبني الالتزام بالسلامة والتغيير عبر الفرق، بما في ذلك من لا يديرهم مباشرة، ويكون قدوة في السلوكيات التي يطلبها.', 'You apply leadership and social influence on your own in routine work and check your result.', 'تطبّق القيادة والتأثير الاجتماعي بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 16),
('pw-tr-leadership-l3', 'sk-fs-tr-leadership', 3, 'Leadership and social influence: advanced practice', 'القيادة والتأثير الاجتماعي: الممارسة المتقدمة', 'Builds commitment to safety and change across teams, including people they do not manage, and models the behaviours they ask for.', 'يبني الالتزام بالسلامة والتغيير عبر الفرق، بما في ذلك من لا يديرهم مباشرة، ويكون قدوة في السلوكيات التي يطلبها.', 'You apply leadership and social influence in unfamiliar situations and help others do it.', 'تطبّق القيادة والتأثير الاجتماعي في مواقف غير مألوفة وتساعد الآخرين على ذلك.', 6, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 17),
('pw-tr-environment-l1', 'sk-fs-tr-environment', 1, 'Environmental stewardship: foundations', 'الإشراف البيئي: الأساسيات', 'Considers environmental impact in daily decisions, from effluents and waste to energy use, and raises improvement ideas.', 'يراعي الأثر البيئي في قراراته اليومية، من الانبعاثات السائلة والنفايات إلى استهلاك الطاقة، ويطرح أفكاراً للتحسين.', 'You can explain the basics of environmental stewardship and apply them with guidance.', 'تستطيع شرح أساسيات الإشراف البيئي وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 18),
('pw-tr-environment-l2', 'sk-fs-tr-environment', 2, 'Environmental stewardship: practitioner', 'الإشراف البيئي: الممارسة', 'Considers environmental impact in daily decisions, from effluents and waste to energy use, and raises improvement ideas.', 'يراعي الأثر البيئي في قراراته اليومية، من الانبعاثات السائلة والنفايات إلى استهلاك الطاقة، ويطرح أفكاراً للتحسين.', 'You apply environmental stewardship on your own in routine work and check your result.', 'تطبّق الإشراف البيئي بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 19),
('pw-tr-dependable-l1', 'sk-fs-tr-dependable', 1, 'Dependability and attention to detail: foundations', 'الموثوقية والدقة في التفاصيل: الأساسيات', 'Delivers what was agreed, to the letter of the procedure, and catches small discrepancies before they become events.', 'ينجز ما اتُّفق عليه بحرفية الإجراء، ويلتقط التباينات الصغيرة قبل أن تتحول إلى أحداث.', 'You can explain the basics of dependability and attention to detail and apply them with guidance.', 'تستطيع شرح أساسيات الموثوقية والدقة في التفاصيل وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 20),
('pw-tr-dependable-l2', 'sk-fs-tr-dependable', 2, 'Dependability and attention to detail: practitioner', 'الموثوقية والدقة في التفاصيل: الممارسة', 'Delivers what was agreed, to the letter of the procedure, and catches small discrepancies before they become events.', 'ينجز ما اتُّفق عليه بحرفية الإجراء، ويلتقط التباينات الصغيرة قبل أن تتحول إلى أحداث.', 'You apply dependability and attention to detail on your own in routine work and check your result.', 'تطبّق الموثوقية والدقة في التفاصيل بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 21),
('pw-tr-empathy-l1', 'sk-fs-tr-empathy', 1, 'Empathy and active listening: foundations', 'التعاطف والإصغاء الفعّال: الأساسيات', 'Listens to understand, checks back what was heard and adapts how they communicate to the person and the situation.', 'يُصغي ليفهم، ويتحقق مما سمعه، ويكيّف أسلوب تواصله مع الشخص والموقف.', 'You can explain the basics of empathy and active listening and apply them with guidance.', 'تستطيع شرح أساسيات التعاطف والإصغاء الفعّال وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 22),
('pw-tr-empathy-l2', 'sk-fs-tr-empathy', 2, 'Empathy and active listening: practitioner', 'التعاطف والإصغاء الفعّال: الممارسة', 'Listens to understand, checks back what was heard and adapts how they communicate to the person and the situation.', 'يُصغي ليفهم، ويتحقق مما سمعه، ويكيّف أسلوب تواصله مع الشخص والموقف.', 'You apply empathy and active listening on your own in routine work and check your result.', 'تطبّق التعاطف والإصغاء الفعّال بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 23),
('pw-tr-selfaware-l1', 'sk-fs-tr-selfaware', 1, 'Motivation and self-awareness: foundations', 'الدافعية والوعي الذاتي: الأساسيات', 'Knows their own limits and error traps, asks for help early and keeps themselves fit for duty and for learning.', 'يعرف حدوده ومواطن الخطأ لديه، ويطلب المساعدة مبكراً، ويحافظ على جاهزيته للعمل والتعلّم.', 'You can explain the basics of motivation and self-awareness and apply them with guidance.', 'تستطيع شرح أساسيات الدافعية والوعي الذاتي وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 24),
('pw-tr-selfaware-l2', 'sk-fs-tr-selfaware', 2, 'Motivation and self-awareness: practitioner', 'الدافعية والوعي الذاتي: الممارسة', 'Knows their own limits and error traps, asks for help early and keeps themselves fit for duty and for learning.', 'يعرف حدوده ومواطن الخطأ لديه، ويطلب المساعدة مبكراً، ويحافظ على جاهزيته للعمل والتعلّم.', 'You apply motivation and self-awareness on your own in routine work and check your result.', 'تطبّق الدافعية والوعي الذاتي بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 25),
('pw-tr-crosscultural-l1', 'sk-fs-tr-crosscultural', 1, 'Collaboration across cultures: foundations', 'التعاون بين الثقافات: الأساسيات', 'Works effectively in mixed Emirati, Korean and international teams, bridging language and working styles without losing precision.', 'يعمل بفعالية في فرق تجمع كوادر إماراتية وكورية ودولية، ويجسر فروق اللغة وأساليب العمل دون أن يفقد الدقة.', 'You can explain the basics of collaboration across cultures and apply them with guidance.', 'تستطيع شرح أساسيات التعاون بين الثقافات وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:NEA","label":"OECD-NEA NEST Framework and Plan 2035","url":"https://www.oecd-nea.org/upload/docs/application/pdf/2025-10/plan_2035_-_vision_paper_-_final_version.pdf"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 26),
('pw-tr-crosscultural-l2', 'sk-fs-tr-crosscultural', 2, 'Collaboration across cultures: practitioner', 'التعاون بين الثقافات: الممارسة', 'Works effectively in mixed Emirati, Korean and international teams, bridging language and working styles without losing precision.', 'يعمل بفعالية في فرق تجمع كوادر إماراتية وكورية ودولية، ويجسر فروق اللغة وأساليب العمل دون أن يفقد الدقة.', 'You apply collaboration across cultures on your own in routine work and check your result.', 'تطبّق التعاون بين الثقافات بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:NEA","label":"OECD-NEA NEST Framework and Plan 2035","url":"https://www.oecd-nea.org/upload/docs/application/pdf/2025-10/plan_2035_-_vision_paper_-_final_version.pdf"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 27),
('pw-ai-use-l1', 'sk-fs-ai-use', 1, 'Everyday use of approved AI tools: foundations', 'الاستخدام اليومي لأدوات الذكاء الاصطناعي المعتمدة: الأساسيات', 'Uses approved AI assistants for drafting, search and summarising, keeps protected information out of them and labels AI-assisted work.', 'يستخدم مساعدي الذكاء الاصطناعي المعتمدين في الصياغة والبحث والتلخيص، ويُبقي المعلومات المحمية بعيداً عنهم، ويوسم العمل المُنجز بمساعدتهم.', 'You can explain the basics of everyday use of approved ai tools and apply them with guidance.', 'تستطيع شرح أساسيات الاستخدام اليومي لأدوات الذكاء الاصطناعي المعتمدة وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:AI-LIT","label":"EU AI Act Article 4 AI-literacy repository and UNESCO AI Competency Frameworks","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 28),
('pw-ai-use-l2', 'sk-fs-ai-use', 2, 'Everyday use of approved AI tools: practitioner', 'الاستخدام اليومي لأدوات الذكاء الاصطناعي المعتمدة: الممارسة', 'Uses approved AI assistants for drafting, search and summarising, keeps protected information out of them and labels AI-assisted work.', 'يستخدم مساعدي الذكاء الاصطناعي المعتمدين في الصياغة والبحث والتلخيص، ويُبقي المعلومات المحمية بعيداً عنهم، ويوسم العمل المُنجز بمساعدتهم.', 'You apply everyday use of approved ai tools on your own in routine work and check your result.', 'تطبّق الاستخدام اليومي لأدوات الذكاء الاصطناعي المعتمدة بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:AI-LIT","label":"EU AI Act Article 4 AI-literacy repository and UNESCO AI Competency Frameworks","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 29),
('pw-ai-verify-l1', 'sk-fs-ai-verify', 1, 'AI output verification and challenge: foundations', 'التحقق من مخرجات الذكاء الاصطناعي والاعتراض عليها: الأساسيات', 'Checks AI outputs against procedures and plant data, recognises plausible but wrong answers, and stops or challenges before acting.', 'يتحقق من مخرجات الذكاء الاصطناعي مقابل الإجراءات وبيانات المحطة، ويتعرّف على الإجابات المقنعة الخاطئة، ويتوقف أو يعترض قبل التصرّف.', 'You can explain the basics of ai output verification and challenge and apply them with guidance.', 'تستطيع شرح أساسيات التحقق من مخرجات الذكاء الاصطناعي والاعتراض عليها وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:IAEA-AI","label":"IAEA AI for nuclear energy (\"Atoms for Algorithms\")","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 30),
('pw-ai-verify-l2', 'sk-fs-ai-verify', 2, 'AI output verification and challenge: practitioner', 'التحقق من مخرجات الذكاء الاصطناعي والاعتراض عليها: الممارسة', 'Checks AI outputs against procedures and plant data, recognises plausible but wrong answers, and stops or challenges before acting.', 'يتحقق من مخرجات الذكاء الاصطناعي مقابل الإجراءات وبيانات المحطة، ويتعرّف على الإجابات المقنعة الخاطئة، ويتوقف أو يعترض قبل التصرّف.', 'You apply ai output verification and challenge on your own in routine work and check your result.', 'تطبّق التحقق من مخرجات الذكاء الاصطناعي والاعتراض عليها بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:IAEA-AI","label":"IAEA AI for nuclear energy (\"Atoms for Algorithms\")","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 31),
('pw-ai-verify-l3', 'sk-fs-ai-verify', 3, 'AI output verification and challenge: advanced practice', 'التحقق من مخرجات الذكاء الاصطناعي والاعتراض عليها: الممارسة المتقدمة', 'Checks AI outputs against procedures and plant data, recognises plausible but wrong answers, and stops or challenges before acting.', 'يتحقق من مخرجات الذكاء الاصطناعي مقابل الإجراءات وبيانات المحطة، ويتعرّف على الإجابات المقنعة الخاطئة، ويتوقف أو يعترض قبل التصرّف.', 'You apply ai output verification and challenge in unfamiliar situations and help others do it.', 'تطبّق التحقق من مخرجات الذكاء الاصطناعي والاعتراض عليها في مواقف غير مألوفة وتساعد الآخرين على ذلك.', 6, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:IAEA-AI","label":"IAEA AI for nuclear energy (\"Atoms for Algorithms\")","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 32),
('pw-ai-prompt-l1', 'sk-fs-ai-prompt', 1, 'Prompt and agent literacy: foundations', 'الإلمام بصياغة الأوامر والوكلاء الذكيين: الأساسيات', 'Writes clear, bounded instructions for AI assistants and agents, sets limits on what an agent may do, and reviews each step it takes.', 'يكتب تعليمات واضحة ومحددة لمساعدي الذكاء الاصطناعي ووكلائه، ويضع حدوداً لما يجوز للوكيل فعله، ويراجع كل خطوة يتخذها.', 'You can explain the basics of prompt and agent literacy and apply them with guidance.', 'تستطيع شرح أساسيات الإلمام بصياغة الأوامر والوكلاء الذكيين وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:UAE-PEERS","label":"ADNOC AI upskilling and EGA Academy","url":"https://reports.adnoc.ae/e/sustainability-report-2025/eJFjvFKd42"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 33),
('pw-ai-prompt-l2', 'sk-fs-ai-prompt', 2, 'Prompt and agent literacy: practitioner', 'الإلمام بصياغة الأوامر والوكلاء الذكيين: الممارسة', 'Writes clear, bounded instructions for AI assistants and agents, sets limits on what an agent may do, and reviews each step it takes.', 'يكتب تعليمات واضحة ومحددة لمساعدي الذكاء الاصطناعي ووكلائه، ويضع حدوداً لما يجوز للوكيل فعله، ويراجع كل خطوة يتخذها.', 'You apply prompt and agent literacy on your own in routine work and check your result.', 'تطبّق الإلمام بصياغة الأوامر والوكلاء الذكيين بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:UAE-PEERS","label":"ADNOC AI upskilling and EGA Academy","url":"https://reports.adnoc.ae/e/sustainability-report-2025/eJFjvFKd42"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 34),
('pw-ai-dataeng-l1', 'sk-fs-ai-dataeng', 1, 'Data engineering basics: foundations', 'أساسيات هندسة البيانات: الأساسيات', 'Builds simple, documented data pipelines from approved sources, with versioned inputs and checks that others can rerun.', 'يبني خطوط بيانات بسيطة وموثّقة من مصادر معتمدة، بمدخلات مرقّمة الإصدارات وفحوص يمكن للآخرين إعادة تشغيلها.', 'You can explain the basics of data engineering basics and apply them with guidance.', 'تستطيع شرح أساسيات أساسيات هندسة البيانات وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:LINKEDIN","label":"LinkedIn Economic Graph: Skills on the Rise and Work Change","url":"https://economicgraph.linkedin.com/research"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 35),
('pw-ai-dataeng-l2', 'sk-fs-ai-dataeng', 2, 'Data engineering basics: practitioner', 'أساسيات هندسة البيانات: الممارسة', 'Builds simple, documented data pipelines from approved sources, with versioned inputs and checks that others can rerun.', 'يبني خطوط بيانات بسيطة وموثّقة من مصادر معتمدة، بمدخلات مرقّمة الإصدارات وفحوص يمكن للآخرين إعادة تشغيلها.', 'You apply data engineering basics on your own in routine work and check your result.', 'تطبّق أساسيات هندسة البيانات بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:LINKEDIN","label":"LinkedIn Economic Graph: Skills on the Rise and Work Change","url":"https://economicgraph.linkedin.com/research"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 36),
('pw-ai-plantdata-l1', 'sk-fs-ai-plantdata', 1, 'Plant-data quality: foundations', 'جودة بيانات المحطة: الأساسيات', 'Spots drift, gaps and bad tags in plant historian data, records where each data set came from and keeps data fit for safety analysis.', 'يكتشف الانحراف والفجوات والوسوم الخاطئة في البيانات التاريخية للمحطة، ويسجّل مصدر كل مجموعة بيانات، ويحافظ على صلاحيتها لتحليلات السلامة.', 'You can explain the basics of plant-data quality and apply them with guidance.', 'تستطيع شرح أساسيات جودة بيانات المحطة وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:IAEA-AI","label":"IAEA AI for nuclear energy (\"Atoms for Algorithms\")","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 37),
('pw-ai-plantdata-l2', 'sk-fs-ai-plantdata', 2, 'Plant-data quality: practitioner', 'جودة بيانات المحطة: الممارسة', 'Spots drift, gaps and bad tags in plant historian data, records where each data set came from and keeps data fit for safety analysis.', 'يكتشف الانحراف والفجوات والوسوم الخاطئة في البيانات التاريخية للمحطة، ويسجّل مصدر كل مجموعة بيانات، ويحافظ على صلاحيتها لتحليلات السلامة.', 'You apply plant-data quality on your own in routine work and check your result.', 'تطبّق جودة بيانات المحطة بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:IAEA-AI","label":"IAEA AI for nuclear energy (\"Atoms for Algorithms\")","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 38),
('pw-ai-automation-l1', 'sk-fs-ai-automation', 1, 'Automation design: foundations', 'تصميم الأتمتة: الأساسيات', 'Designs small automations for administrative workflows with a named owner, a fallback and a test record, never for plant control.', 'يصمّم أتمتة صغيرة لسير العمل الإداري مع مالك محدد وخطة بديلة وسجل اختبار، ولا يستخدمها أبداً في التحكم بالمحطة.', 'You can explain the basics of automation design and apply them with guidance.', 'تستطيع شرح أساسيات تصميم الأتمتة وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:UAE-PEERS","label":"ADNOC AI upskilling and EGA Academy","url":"https://reports.adnoc.ae/e/sustainability-report-2025/eJFjvFKd42"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 39),
('pw-ai-automation-l2', 'sk-fs-ai-automation', 2, 'Automation design: practitioner', 'تصميم الأتمتة: الممارسة', 'Designs small automations for administrative workflows with a named owner, a fallback and a test record, never for plant control.', 'يصمّم أتمتة صغيرة لسير العمل الإداري مع مالك محدد وخطة بديلة وسجل اختبار، ولا يستخدمها أبداً في التحكم بالمحطة.', 'You apply automation design on your own in routine work and check your result.', 'تطبّق تصميم الأتمتة بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:UAE-PEERS","label":"ADNOC AI upskilling and EGA Academy","url":"https://reports.adnoc.ae/e/sustainability-report-2025/eJFjvFKd42"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 40),
('pw-ai-xr-l1', 'sk-fs-ai-xr', 1, 'AR and VR for training and work: foundations', 'الواقع المعزّز والافتراضي في التدريب والعمل: الأساسيات', 'Uses augmented and virtual reality for walk-downs and practice, and knows where a simulator or the real plant is still required.', 'يستخدم الواقع المعزّز والافتراضي في الجولات التفقدية والتدريب، ويعرف متى يظل المحاكي أو المحطة الفعلية ضرورياً.', 'You can explain the basics of ar and vr for training and work and apply them with guidance.', 'تستطيع شرح أساسيات الواقع المعزّز والافتراضي في التدريب والعمل وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:SMR-WF","label":"New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 41),
('pw-ai-xr-l2', 'sk-fs-ai-xr', 2, 'AR and VR for training and work: practitioner', 'الواقع المعزّز والافتراضي في التدريب والعمل: الممارسة', 'Uses augmented and virtual reality for walk-downs and practice, and knows where a simulator or the real plant is still required.', 'يستخدم الواقع المعزّز والافتراضي في الجولات التفقدية والتدريب، ويعرف متى يظل المحاكي أو المحطة الفعلية ضرورياً.', 'You apply ar and vr for training and work on your own in routine work and check your result.', 'تطبّق الواقع المعزّز والافتراضي في التدريب والعمل بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:SMR-WF","label":"New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 42),
('pw-ai-twin-l1', 'sk-fs-ai-twin', 1, 'Digital twin validation: foundations', 'التحقق من صحة التوائم الرقمية: الأساسيات', 'Compares twin predictions with plant behaviour, records where the model is valid and flags when it drifts out of its range.', 'يقارن تنبؤات التوأم الرقمي بسلوك المحطة، ويسجّل النطاق الذي يصحّ فيه النموذج، وينبّه عند خروجه عن نطاقه.', 'You can explain the basics of digital twin validation and apply them with guidance.', 'تستطيع شرح أساسيات التحقق من صحة التوائم الرقمية وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:IAEA-AI","label":"IAEA AI for nuclear energy (\"Atoms for Algorithms\")","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 43),
('pw-ai-twin-l2', 'sk-fs-ai-twin', 2, 'Digital twin validation: practitioner', 'التحقق من صحة التوائم الرقمية: الممارسة', 'Compares twin predictions with plant behaviour, records where the model is valid and flags when it drifts out of its range.', 'يقارن تنبؤات التوأم الرقمي بسلوك المحطة، ويسجّل النطاق الذي يصحّ فيه النموذج، وينبّه عند خروجه عن نطاقه.', 'You apply digital twin validation on your own in routine work and check your result.', 'تطبّق التحقق من صحة التوائم الرقمية بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:IAEA-AI","label":"IAEA AI for nuclear energy (\"Atoms for Algorithms\")","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 44),
('pw-ai-twin-l3', 'sk-fs-ai-twin', 3, 'Digital twin validation: advanced practice', 'التحقق من صحة التوائم الرقمية: الممارسة المتقدمة', 'Compares twin predictions with plant behaviour, records where the model is valid and flags when it drifts out of its range.', 'يقارن تنبؤات التوأم الرقمي بسلوك المحطة، ويسجّل النطاق الذي يصحّ فيه النموذج، وينبّه عند خروجه عن نطاقه.', 'You apply digital twin validation in unfamiliar situations and help others do it.', 'تطبّق التحقق من صحة التوائم الرقمية في مواقف غير مألوفة وتساعد الآخرين على ذلك.', 6, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:IAEA-AI","label":"IAEA AI for nuclear energy (\"Atoms for Algorithms\")","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 45),
('pw-ai-anomaly-l1', 'sk-fs-ai-anomaly', 1, 'Anomaly triage with AI alerts: foundations', 'فرز الحالات الشاذة باستخدام تنبيهات الذكاء الاصطناعي: الأساسيات', 'Sorts AI-generated anomaly alerts into act, watch and dismiss, with reasons, and feeds the outcome back to the model owner.', 'يفرز تنبيهات الحالات الشاذة التي يولّدها الذكاء الاصطناعي إلى: تصرّف، أو مراقبة، أو تجاهل، مع الأسباب، ويعيد النتيجة إلى مالك النموذج.', 'You can explain the basics of anomaly triage with ai alerts and apply them with guidance.', 'تستطيع شرح أساسيات فرز الحالات الشاذة باستخدام تنبيهات الذكاء الاصطناعي وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:IAEA-AI","label":"IAEA AI for nuclear energy (\"Atoms for Algorithms\")","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 46),
('pw-ai-anomaly-l2', 'sk-fs-ai-anomaly', 2, 'Anomaly triage with AI alerts: practitioner', 'فرز الحالات الشاذة باستخدام تنبيهات الذكاء الاصطناعي: الممارسة', 'Sorts AI-generated anomaly alerts into act, watch and dismiss, with reasons, and feeds the outcome back to the model owner.', 'يفرز تنبيهات الحالات الشاذة التي يولّدها الذكاء الاصطناعي إلى: تصرّف، أو مراقبة، أو تجاهل، مع الأسباب، ويعيد النتيجة إلى مالك النموذج.', 'You apply anomaly triage with ai alerts on your own in routine work and check your result.', 'تطبّق فرز الحالات الشاذة باستخدام تنبيهات الذكاء الاصطناعي بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:IAEA-AI","label":"IAEA AI for nuclear energy (\"Atoms for Algorithms\")","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 47),
('pw-ai-data-care-l1', 'sk-fs-ai-data-care', 1, 'Responsible data handling: foundations', 'التعامل المسؤول مع البيانات: الأساسيات', 'Handles personal and commercial data on a need-to-know basis, minimises what is shared and knows how to report a data mistake.', 'يتعامل مع البيانات الشخصية والتجارية على أساس الحاجة إلى المعرفة، ويقلّل ما يُشارك، ويعرف كيف يبلّغ عن خطأ في البيانات.', 'You can explain the basics of responsible data handling and apply them with guidance.', 'تستطيع شرح أساسيات التعامل المسؤول مع البيانات وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:AI-LIT","label":"EU AI Act Article 4 AI-literacy repository and UNESCO AI Competency Frameworks","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 48),
('pw-ai-data-care-l2', 'sk-fs-ai-data-care', 2, 'Responsible data handling: practitioner', 'التعامل المسؤول مع البيانات: الممارسة', 'Handles personal and commercial data on a need-to-know basis, minimises what is shared and knows how to report a data mistake.', 'يتعامل مع البيانات الشخصية والتجارية على أساس الحاجة إلى المعرفة، ويقلّل ما يُشارك، ويعرف كيف يبلّغ عن خطأ في البيانات.', 'You apply responsible data handling on your own in routine work and check your result.', 'تطبّق التعامل المسؤول مع البيانات بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:AI-LIT","label":"EU AI Act Article 4 AI-literacy repository and UNESCO AI Competency Frameworks","url":"https://digital-strategy.ec.europa.eu/en/policies/repository-ai-literacy-practices"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 49),
('pw-gr-lifecycle-l1', 'sk-fs-gr-lifecycle', 1, 'Lifecycle carbon assessment: foundations', 'تقييم الكربون على امتداد دورة الحياة: الأساسيات', 'Estimates the lifecycle emissions of an energy option or project with a stated method and compares it fairly with alternatives.', 'يقدّر انبعاثات خيار طاقة أو مشروع على امتداد دورة حياته بمنهجية معلنة، ويقارنه بالبدائل مقارنة منصفة.', 'You can explain the basics of lifecycle carbon assessment and apply them with guidance.', 'تستطيع شرح أساسيات تقييم الكربون على امتداد دورة الحياة وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:GREENCOMP","label":"GreenComp, with EntreComp and LifeComp","url":"https://joint-research-centre.ec.europa.eu/greencomp"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 50),
('pw-gr-lifecycle-l2', 'sk-fs-gr-lifecycle', 2, 'Lifecycle carbon assessment: practitioner', 'تقييم الكربون على امتداد دورة الحياة: الممارسة', 'Estimates the lifecycle emissions of an energy option or project with a stated method and compares it fairly with alternatives.', 'يقدّر انبعاثات خيار طاقة أو مشروع على امتداد دورة حياته بمنهجية معلنة، ويقارنه بالبدائل مقارنة منصفة.', 'You apply lifecycle carbon assessment on your own in routine work and check your result.', 'تطبّق تقييم الكربون على امتداد دورة الحياة بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:GREENCOMP","label":"GreenComp, with EntreComp and LifeComp","url":"https://joint-research-centre.ec.europa.eu/greencomp"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 51),
('pw-gr-ghg-l1', 'sk-fs-gr-ghg', 1, 'GHG accounting basics: foundations', 'أساسيات محاسبة غازات الاحتباس الحراري: الأساسيات', 'Explains scope 1, 2 and 3 emissions, follows the GHG Protocol logic and checks the data behind a sustainability figure.', 'يشرح انبعاثات النطاقات 1 و2 و3، ويتبع منطق بروتوكول غازات الاحتباس الحراري، ويتحقق من البيانات وراء أي رقم للاستدامة.', 'You can explain the basics of ghg accounting basics and apply them with guidance.', 'تستطيع شرح أساسيات أساسيات محاسبة غازات الاحتباس الحراري وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:GREENCOMP","label":"GreenComp, with EntreComp and LifeComp","url":"https://joint-research-centre.ec.europa.eu/greencomp"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 52),
('pw-gr-ghg-l2', 'sk-fs-gr-ghg', 2, 'GHG accounting basics: practitioner', 'أساسيات محاسبة غازات الاحتباس الحراري: الممارسة', 'Explains scope 1, 2 and 3 emissions, follows the GHG Protocol logic and checks the data behind a sustainability figure.', 'يشرح انبعاثات النطاقات 1 و2 و3، ويتبع منطق بروتوكول غازات الاحتباس الحراري، ويتحقق من البيانات وراء أي رقم للاستدامة.', 'You apply ghg accounting basics on your own in routine work and check your result.', 'تطبّق أساسيات محاسبة غازات الاحتباس الحراري بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:GREENCOMP","label":"GreenComp, with EntreComp and LifeComp","url":"https://joint-research-centre.ec.europa.eu/greencomp"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 53),
('pw-gr-h2heat-l1', 'sk-fs-gr-h2heat', 1, 'Hydrogen and process-heat interfaces: foundations', 'واجهات الهيدروجين والحرارة الصناعية: الأساسيات', 'Explains how nuclear heat and power can feed hydrogen and industrial heat users, and the safety and grid questions each interface raises.', 'يشرح كيف يمكن للحرارة والكهرباء النوويتين تزويد مستخدمي الهيدروجين والحرارة الصناعية، وأسئلة السلامة والشبكة التي تثيرها كل واجهة.', 'You can explain the basics of hydrogen and process-heat interfaces and apply them with guidance.', 'تستطيع شرح أساسيات واجهات الهيدروجين والحرارة الصناعية وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:ENERGY-JOBS","label":"IEA World Energy Employment 2025 and IRENA/ILO Renewable Energy and Jobs 2025","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 54),
('pw-gr-h2heat-l2', 'sk-fs-gr-h2heat', 2, 'Hydrogen and process-heat interfaces: practitioner', 'واجهات الهيدروجين والحرارة الصناعية: الممارسة', 'Explains how nuclear heat and power can feed hydrogen and industrial heat users, and the safety and grid questions each interface raises.', 'يشرح كيف يمكن للحرارة والكهرباء النوويتين تزويد مستخدمي الهيدروجين والحرارة الصناعية، وأسئلة السلامة والشبكة التي تثيرها كل واجهة.', 'You apply hydrogen and process-heat interfaces on your own in routine work and check your result.', 'تطبّق واجهات الهيدروجين والحرارة الصناعية بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:ENERGY-JOBS","label":"IEA World Energy Employment 2025 and IRENA/ILO Renewable Energy and Jobs 2025","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 55),
('pw-gr-grid-l1', 'sk-fs-gr-grid', 1, 'Grid integration and flexible operation: foundations', 'التكامل مع الشبكة والتشغيل المرن: الأساسيات', 'Understands how a nuclear fleet works alongside solar, storage and the grid operator, including load-following limits and grid-code duties.', 'يفهم كيف يعمل أسطول نووي إلى جانب الطاقة الشمسية والتخزين ومشغّل الشبكة، بما في ذلك حدود متابعة الأحمال والتزامات كود الشبكة.', 'You can explain the basics of grid integration and flexible operation and apply them with guidance.', 'تستطيع شرح أساسيات التكامل مع الشبكة والتشغيل المرن وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:ENERGY-JOBS","label":"IEA World Energy Employment 2025 and IRENA/ILO Renewable Energy and Jobs 2025","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 56),
('pw-gr-grid-l2', 'sk-fs-gr-grid', 2, 'Grid integration and flexible operation: practitioner', 'التكامل مع الشبكة والتشغيل المرن: الممارسة', 'Understands how a nuclear fleet works alongside solar, storage and the grid operator, including load-following limits and grid-code duties.', 'يفهم كيف يعمل أسطول نووي إلى جانب الطاقة الشمسية والتخزين ومشغّل الشبكة، بما في ذلك حدود متابعة الأحمال والتزامات كود الشبكة.', 'You apply grid integration and flexible operation on your own in routine work and check your result.', 'تطبّق التكامل مع الشبكة والتشغيل المرن بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:ENERGY-JOBS","label":"IEA World Energy Employment 2025 and IRENA/ILO Renewable Energy and Jobs 2025","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 57),
('pw-gr-circular-l1', 'sk-fs-gr-circular', 1, 'Circularity and waste stewardship: foundations', 'الاقتصاد الدائري والإشراف على النفايات: الأساسيات', 'Applies reduce, reuse and recycle to conventional waste and minimises radioactive waste at source, following the site waste hierarchy.', 'يطبّق مبادئ التقليل وإعادة الاستخدام والتدوير على النفايات التقليدية، ويقلّل النفايات المشعة من مصدرها وفق هرمية إدارة النفايات المعتمدة.', 'You can explain the basics of circularity and waste stewardship and apply them with guidance.', 'تستطيع شرح أساسيات الاقتصاد الدائري والإشراف على النفايات وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:GREENCOMP","label":"GreenComp, with EntreComp and LifeComp","url":"https://joint-research-centre.ec.europa.eu/greencomp"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 58),
('pw-gr-circular-l2', 'sk-fs-gr-circular', 2, 'Circularity and waste stewardship: practitioner', 'الاقتصاد الدائري والإشراف على النفايات: الممارسة', 'Applies reduce, reuse and recycle to conventional waste and minimises radioactive waste at source, following the site waste hierarchy.', 'يطبّق مبادئ التقليل وإعادة الاستخدام والتدوير على النفايات التقليدية، ويقلّل النفايات المشعة من مصدرها وفق هرمية إدارة النفايات المعتمدة.', 'You apply circularity and waste stewardship on your own in routine work and check your result.', 'تطبّق الاقتصاد الدائري والإشراف على النفايات بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:GREENCOMP","label":"GreenComp, with EntreComp and LifeComp","url":"https://joint-research-centre.ec.europa.eu/greencomp"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 59),
('pw-gr-esg-l1', 'sk-fs-gr-esg', 1, 'ESG disclosure literacy: foundations', 'الإلمام بالإفصاح البيئي والاجتماعي والحوكمي: الأساسيات', 'Reads and checks environmental, social and governance disclosures, knows what an auditable metric needs and where a claim needs evidence.', 'يقرأ الإفصاحات البيئية والاجتماعية والحوكمية ويتحقق منها، ويعرف ما يحتاجه المقياس القابل للتدقيق ومتى يحتاج الادعاء إلى دليل.', 'You can explain the basics of esg disclosure literacy and apply them with guidance.', 'تستطيع شرح أساسيات الإلمام بالإفصاح البيئي والاجتماعي والحوكمي وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:ISO30414","label":"ISO 30414:2025 human capital reporting","url":"https://committee.iso.org/sites/tc260/home/news/content-left-area/news-and-updates/iso-30414-2025-strengthening-hum.html"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 60),
('pw-gr-esg-l2', 'sk-fs-gr-esg', 2, 'ESG disclosure literacy: practitioner', 'الإلمام بالإفصاح البيئي والاجتماعي والحوكمي: الممارسة', 'Reads and checks environmental, social and governance disclosures, knows what an auditable metric needs and where a claim needs evidence.', 'يقرأ الإفصاحات البيئية والاجتماعية والحوكمية ويتحقق منها، ويعرف ما يحتاجه المقياس القابل للتدقيق ومتى يحتاج الادعاء إلى دليل.', 'You apply esg disclosure literacy on your own in routine work and check your result.', 'تطبّق الإلمام بالإفصاح البيئي والاجتماعي والحوكمي بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:ISO30414","label":"ISO 30414:2025 human capital reporting","url":"https://committee.iso.org/sites/tc260/home/news/content-left-area/news-and-updates/iso-30414-2025-strengthening-hum.html"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 61),
('pw-gr-climaterisk-l1', 'sk-fs-gr-climaterisk', 1, 'Climate risk awareness: foundations', 'الوعي بمخاطر المناخ: الأساسيات', 'Recognises how heat, humidity, dust and sea conditions affect plant, people and supply chains, and feeds that into planning.', 'يدرك كيف تؤثر الحرارة والرطوبة والغبار وأحوال البحر في المحطة والأفراد وسلاسل الإمداد، ويُدخل ذلك في التخطيط.', 'You can explain the basics of climate risk awareness and apply them with guidance.', 'تستطيع شرح أساسيات الوعي بمخاطر المناخ وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:ENERGY-JOBS","label":"IEA World Energy Employment 2025 and IRENA/ILO Renewable Energy and Jobs 2025","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 62),
('pw-gr-climaterisk-l2', 'sk-fs-gr-climaterisk', 2, 'Climate risk awareness: practitioner', 'الوعي بمخاطر المناخ: الممارسة', 'Recognises how heat, humidity, dust and sea conditions affect plant, people and supply chains, and feeds that into planning.', 'يدرك كيف تؤثر الحرارة والرطوبة والغبار وأحوال البحر في المحطة والأفراد وسلاسل الإمداد، ويُدخل ذلك في التخطيط.', 'You apply climate risk awareness on your own in routine work and check your result.', 'تطبّق الوعي بمخاطر المناخ بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:ENERGY-JOBS","label":"IEA World Energy Employment 2025 and IRENA/ILO Renewable Energy and Jobs 2025","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 63),
('pw-adv-smr-l1', 'sk-fs-adv-smr', 1, 'SMR fundamentals: foundations', 'أساسيات المفاعلات المعيارية الصغيرة: الأساسيات', 'Compares the main SMR and microreactor design families with the APR-1400: size, coolant, fuel and what changes for operations.', 'يقارن عائلات تصاميم المفاعلات المعيارية الصغيرة والمفاعلات الدقيقة الرئيسية بمفاعل APR-1400: الحجم والمبرّد والوقود وما يتغير في التشغيل.', 'You can explain the basics of smr fundamentals and apply them with guidance.', 'تستطيع شرح أساسيات أساسيات المفاعلات المعيارية الصغيرة وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:SMR-WF","label":"New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 64),
('pw-adv-smr-l2', 'sk-fs-adv-smr', 2, 'SMR fundamentals: practitioner', 'أساسيات المفاعلات المعيارية الصغيرة: الممارسة', 'Compares the main SMR and microreactor design families with the APR-1400: size, coolant, fuel and what changes for operations.', 'يقارن عائلات تصاميم المفاعلات المعيارية الصغيرة والمفاعلات الدقيقة الرئيسية بمفاعل APR-1400: الحجم والمبرّد والوقود وما يتغير في التشغيل.', 'You apply smr fundamentals on your own in routine work and check your result.', 'تطبّق أساسيات المفاعلات المعيارية الصغيرة بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:SMR-WF","label":"New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 65),
('pw-adv-passive-l1', 'sk-fs-adv-passive', 1, 'Passive safety concepts: foundations', 'مفاهيم السلامة السلبية: الأساسيات', 'Explains how passive systems remove decay heat without pumps or operator action, and what still needs monitoring and human judgement.', 'يشرح كيف تزيل الأنظمة السلبية الحرارة المتبقية دون مضخات أو تدخل المشغّل، وما الذي يظل بحاجة إلى المراقبة والحكم البشري.', 'You can explain the basics of passive safety concepts and apply them with guidance.', 'تستطيع شرح أساسيات مفاهيم السلامة السلبية وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:SMR-WF","label":"New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 66),
('pw-adv-passive-l2', 'sk-fs-adv-passive', 2, 'Passive safety concepts: practitioner', 'مفاهيم السلامة السلبية: الممارسة', 'Explains how passive systems remove decay heat without pumps or operator action, and what still needs monitoring and human judgement.', 'يشرح كيف تزيل الأنظمة السلبية الحرارة المتبقية دون مضخات أو تدخل المشغّل، وما الذي يظل بحاجة إلى المراقبة والحكم البشري.', 'You apply passive safety concepts on your own in routine work and check your result.', 'تطبّق مفاهيم السلامة السلبية بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:SMR-WF","label":"New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 67),
('pw-adv-multimodule-l1', 'sk-fs-adv-multimodule', 1, 'Multi-module operations concepts: foundations', 'مفاهيم تشغيل الوحدات المتعددة: الأساسيات', 'Describes how one crew may supervise several modules, the human-factors questions this raises and how staffing cases are justified.', 'يصف كيف يمكن لطاقم واحد الإشراف على عدة وحدات، وأسئلة العوامل البشرية التي يثيرها ذلك، وكيف تُبرَّر حالات تحديد الطواقم.', 'You can explain the basics of multi-module operations concepts and apply them with guidance.', 'تستطيع شرح أساسيات مفاهيم تشغيل الوحدات المتعددة وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:SMR-WF","label":"New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 68),
('pw-adv-multimodule-l2', 'sk-fs-adv-multimodule', 2, 'Multi-module operations concepts: practitioner', 'مفاهيم تشغيل الوحدات المتعددة: الممارسة', 'Describes how one crew may supervise several modules, the human-factors questions this raises and how staffing cases are justified.', 'يصف كيف يمكن لطاقم واحد الإشراف على عدة وحدات، وأسئلة العوامل البشرية التي يثيرها ذلك، وكيف تُبرَّر حالات تحديد الطواقم.', 'You apply multi-module operations concepts on your own in routine work and check your result.', 'تطبّق مفاهيم تشغيل الوحدات المتعددة بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:SMR-WF","label":"New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 69),
('pw-adv-factoryqa-l1', 'sk-fs-adv-factoryqa', 1, 'Factory fabrication QA: foundations', 'ضمان الجودة في التصنيع بالمصنع: الأساسيات', 'Applies nuclear QA to modules built in a factory: source inspection, traceability and acceptance testing before shipment.', 'يطبّق ضمان الجودة النووية على الوحدات المصنّعة في المصنع: الفحص عند المصدر، وإمكانية التتبّع، واختبارات القبول قبل الشحن.', 'You can explain the basics of factory fabrication qa and apply them with guidance.', 'تستطيع شرح أساسيات ضمان الجودة في التصنيع بالمصنع وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:SMR-WF","label":"New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 70),
('pw-adv-factoryqa-l2', 'sk-fs-adv-factoryqa', 2, 'Factory fabrication QA: practitioner', 'ضمان الجودة في التصنيع بالمصنع: الممارسة', 'Applies nuclear QA to modules built in a factory: source inspection, traceability and acceptance testing before shipment.', 'يطبّق ضمان الجودة النووية على الوحدات المصنّعة في المصنع: الفحص عند المصدر، وإمكانية التتبّع، واختبارات القبول قبل الشحن.', 'You apply factory fabrication qa on your own in routine work and check your result.', 'تطبّق ضمان الجودة في التصنيع بالمصنع بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:SMR-WF","label":"New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 71),
('pw-adv-fuelcycle-l1', 'sk-fs-adv-fuelcycle', 1, 'Advanced fuel-cycle awareness: foundations', 'الوعي بدورة الوقود المتقدمة: الأساسيات', 'Explains advanced fuel forms such as TRISO and HALEU, and what they change for handling, transport and supply.', 'يشرح أشكال الوقود المتقدمة مثل TRISO وHALEU، وما تغيّره في المناولة والنقل والإمداد.', 'You can explain the basics of advanced fuel-cycle awareness and apply them with guidance.', 'تستطيع شرح أساسيات الوعي بدورة الوقود المتقدمة وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:SMR-WF","label":"New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 72),
('pw-adv-fuelcycle-l2', 'sk-fs-adv-fuelcycle', 2, 'Advanced fuel-cycle awareness: practitioner', 'الوعي بدورة الوقود المتقدمة: الممارسة', 'Explains advanced fuel forms such as TRISO and HALEU, and what they change for handling, transport and supply.', 'يشرح أشكال الوقود المتقدمة مثل TRISO وHALEU، وما تغيّره في المناولة والنقل والإمداد.', 'You apply advanced fuel-cycle awareness on your own in routine work and check your result.', 'تطبّق الوعي بدورة الوقود المتقدمة بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:SMR-WF","label":"New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 73),
('pw-adv-fusion-l1', 'sk-fs-adv-fusion', 1, 'Fusion awareness: foundations', 'الوعي بالاندماج النووي: الأساسيات', 'Explains how fusion differs from fission, where the main research programmes stand and which plant skills would transfer.', 'يشرح كيف يختلف الاندماج عن الانشطار، وأين تقف برامج البحث الرئيسية، وأي مهارات المحطة يمكن أن تنتقل إليه.', 'You can explain the basics of fusion awareness and apply them with guidance.', 'تستطيع شرح أساسيات الوعي بالاندماج النووي وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:NEA","label":"OECD-NEA NEST Framework and Plan 2035","url":"https://www.oecd-nea.org/upload/docs/application/pdf/2025-10/plan_2035_-_vision_paper_-_final_version.pdf"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 74),
('pw-adv-micro-l1', 'sk-fs-adv-micro', 1, 'Microreactor and transportable unit concepts: foundations', 'مفاهيم المفاعلات الدقيقة والوحدات القابلة للنقل: الأساسيات', 'Describes microreactor concepts, factory-sealed cores and transport considerations, and the different operating model they imply.', 'يصف مفاهيم المفاعلات الدقيقة والقلوب المختومة في المصنع واعتبارات النقل، ونموذج التشغيل المختلف الذي تقتضيه.', 'You can explain the basics of microreactor and transportable unit concepts and apply them with guidance.', 'تستطيع شرح أساسيات مفاهيم المفاعلات الدقيقة والوحدات القابلة للنقل وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:SMR-WF","label":"New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 75),
('pw-adv-micro-l2', 'sk-fs-adv-micro', 2, 'Microreactor and transportable unit concepts: practitioner', 'مفاهيم المفاعلات الدقيقة والوحدات القابلة للنقل: الممارسة', 'Describes microreactor concepts, factory-sealed cores and transport considerations, and the different operating model they imply.', 'يصف مفاهيم المفاعلات الدقيقة والقلوب المختومة في المصنع واعتبارات النقل، ونموذج التشغيل المختلف الذي تقتضيه.', 'You apply microreactor and transportable unit concepts on your own in routine work and check your result.', 'تطبّق مفاهيم المفاعلات الدقيقة والوحدات القابلة للنقل بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:SMR-WF","label":"New-build and SMR workforce models (Canada BWRX-300, NuScale E2, France MATCH)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 76),
('pw-adv-regulation-l1', 'sk-fs-adv-regulation', 1, 'Advanced-reactor regulatory awareness: foundations', 'الوعي التنظيمي بالمفاعلات المتقدمة: الأساسيات', 'Explains how regulators internationally are adapting their approaches for new designs, without anticipating any regulatory decision.', 'يشرح كيف تكيّف الجهات الرقابية حول العالم مناهجها للتصاميم الجديدة، دون استباق أي قرار رقابي.', 'You can explain the basics of advanced-reactor regulatory awareness and apply them with guidance.', 'تستطيع شرح أساسيات الوعي التنظيمي بالمفاعلات المتقدمة وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:NEA","label":"OECD-NEA NEST Framework and Plan 2035","url":"https://www.oecd-nea.org/upload/docs/application/pdf/2025-10/plan_2035_-_vision_paper_-_final_version.pdf"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 77),
('pw-adv-regulation-l2', 'sk-fs-adv-regulation', 2, 'Advanced-reactor regulatory awareness: practitioner', 'الوعي التنظيمي بالمفاعلات المتقدمة: الممارسة', 'Explains how regulators internationally are adapting their approaches for new designs, without anticipating any regulatory decision.', 'يشرح كيف تكيّف الجهات الرقابية حول العالم مناهجها للتصاميم الجديدة، دون استباق أي قرار رقابي.', 'You apply advanced-reactor regulatory awareness on your own in routine work and check your result.', 'تطبّق الوعي التنظيمي بالمفاعلات المتقدمة بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:NEA","label":"OECD-NEA NEST Framework and Plan 2035","url":"https://www.oecd-nea.org/upload/docs/application/pdf/2025-10/plan_2035_-_vision_paper_-_final_version.pdf"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 78),
('pw-cy-phishing-l1', 'sk-fs-cy-phishing', 1, 'Phishing awareness: foundations', 'الوعي بالتصيّد الاحتيالي: الأساسيات', 'Recognises suspicious emails, messages and calls, does not click or reply, and reports them through the normal channel.', 'يتعرّف على الرسائل والمكالمات المشبوهة، فلا ينقر ولا يرد، ويبلّغ عنها عبر القناة المعتادة.', 'You can explain the basics of phishing awareness and apply them with guidance.', 'تستطيع شرح أساسيات الوعي بالتصيّد الاحتيالي وتطبيقها بتوجيه.', 3, 0.5, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:OT-CYBER","label":"IAEA NSS 42-G computer security and NICE Framework v2.0 OT role","url":"https://www.iaea.org/node/97473"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 79),
('pw-cy-media-l1', 'sk-fs-cy-media', 1, 'Removable media discipline: foundations', 'الانضباط في استخدام الوسائط القابلة للإزالة: الأساسيات', 'Uses only approved, checked portable media and never connects personal devices where they are not allowed.', 'لا يستخدم إلا الوسائط المحمولة المعتمدة والمفحوصة، ولا يوصل أجهزته الشخصية حيث لا يُسمح بذلك.', 'You can explain the basics of removable media discipline and apply them with guidance.', 'تستطيع شرح أساسيات الانضباط في استخدام الوسائط القابلة للإزالة وتطبيقها بتوجيه.', 3, 0.5, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:OT-CYBER","label":"IAEA NSS 42-G computer security and NICE Framework v2.0 OT role","url":"https://www.iaea.org/node/97473"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 80),
('pw-cy-zones-l1', 'sk-fs-cy-zones', 1, 'Zone-and-conduit awareness: foundations', 'الوعي بمفهوم المناطق والقنوات: الأساسيات', 'Explains, in general terms, why plant and office networks are kept apart and why only approved connections may cross between them.', 'يشرح بعبارات عامة لماذا تُفصل شبكات المحطة عن شبكات المكاتب، ولماذا لا يُسمح إلا بالاتصالات المعتمدة بينها.', 'You can explain the basics of zone-and-conduit awareness and apply them with guidance.', 'تستطيع شرح أساسيات الوعي بمفهوم المناطق والقنوات وتطبيقها بتوجيه.', 3, 0.5, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:OT-CYBER","label":"IAEA NSS 42-G computer security and NICE Framework v2.0 OT role","url":"https://www.iaea.org/node/97473"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 81),
('pw-cy-access-l1', 'sk-fs-cy-access', 1, 'Password and access hygiene: foundations', 'النظافة في كلمات المرور وصلاحيات الوصول: الأساسيات', 'Uses strong, unique passwords and multi-factor sign-in, never shares accounts and locks the screen when away.', 'يستخدم كلمات مرور قوية وفريدة وتسجيل دخول متعدد العوامل، ولا يشارك حساباته أبداً، ويقفل الشاشة عند الابتعاد.', 'You can explain the basics of password and access hygiene and apply them with guidance.', 'تستطيع شرح أساسيات النظافة في كلمات المرور وصلاحيات الوصول وتطبيقها بتوجيه.', 3, 0.5, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:OT-CYBER","label":"IAEA NSS 42-G computer security and NICE Framework v2.0 OT role","url":"https://www.iaea.org/node/97473"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 82),
('pw-cy-report-l1', 'sk-fs-cy-report', 1, 'Reporting a suspected cyber incident: foundations', 'الإبلاغ عن حادث سيبراني مشتبه به: الأساسيات', 'Knows that any suspected cyber problem is reported at once through the normal channel, without investigating it themselves.', 'يعرف أن أي مشكلة سيبرانية مشتبه بها يُبلَّغ عنها فوراً عبر القناة المعتادة، دون أن يحقق فيها بنفسه.', 'You can explain the basics of reporting a suspected cyber incident and apply them with guidance.', 'تستطيع شرح أساسيات الإبلاغ عن حادث سيبراني مشتبه به وتطبيقها بتوجيه.', 3, 0.5, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:OT-CYBER","label":"IAEA NSS 42-G computer security and NICE Framework v2.0 OT role","url":"https://www.iaea.org/node/97473"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 83),
('pw-dp-dic-l1', 'sk-fs-dp-dic', 1, 'Digital I&C fundamentals: foundations', 'أساسيات أجهزة القياس والتحكم الرقمية: الأساسيات', 'Explains how digital instrumentation and control differs from analogue, including software qualification, diversity and common-cause failure.', 'يشرح كيف تختلف أجهزة القياس والتحكم الرقمية عن التناظرية، بما في ذلك تأهيل البرمجيات والتنوّع وأعطال السبب المشترك.', 'You can explain the basics of digital i&c fundamentals and apply them with guidance.', 'تستطيع شرح أساسيات أساسيات أجهزة القياس والتحكم الرقمية وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:OT-CYBER","label":"IAEA NSS 42-G computer security and NICE Framework v2.0 OT role","url":"https://www.iaea.org/node/97473"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 84),
('pw-dp-dic-l2', 'sk-fs-dp-dic', 2, 'Digital I&C fundamentals: practitioner', 'أساسيات أجهزة القياس والتحكم الرقمية: الممارسة', 'Explains how digital instrumentation and control differs from analogue, including software qualification, diversity and common-cause failure.', 'يشرح كيف تختلف أجهزة القياس والتحكم الرقمية عن التناظرية، بما في ذلك تأهيل البرمجيات والتنوّع وأعطال السبب المشترك.', 'You apply digital i&c fundamentals on your own in routine work and check your result.', 'تطبّق أساسيات أجهزة القياس والتحكم الرقمية بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:OT-CYBER","label":"IAEA NSS 42-G computer security and NICE Framework v2.0 OT role","url":"https://www.iaea.org/node/97473"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 85),
('pw-dp-robotics-l1', 'sk-fs-dp-robotics', 1, 'Robotics and remote inspection: foundations', 'الروبوتات والفحص عن بُعد: الأساسيات', 'Plans and supervises robot or drone inspections that cut dose and confined-space entry, and judges the quality of what they record.', 'يخطط لعمليات الفحص بالروبوتات أو الطائرات المسيّرة التي تقلّل الجرعة الإشعاعية ودخول الأماكن الضيقة ويشرف عليها، ويقيّم جودة ما تسجّله.', 'You can explain the basics of robotics and remote inspection and apply them with guidance.', 'تستطيع شرح أساسيات الروبوتات والفحص عن بُعد وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:IAEA-AI","label":"IAEA AI for nuclear energy (\"Atoms for Algorithms\")","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 86),
('pw-dp-robotics-l2', 'sk-fs-dp-robotics', 2, 'Robotics and remote inspection: practitioner', 'الروبوتات والفحص عن بُعد: الممارسة', 'Plans and supervises robot or drone inspections that cut dose and confined-space entry, and judges the quality of what they record.', 'يخطط لعمليات الفحص بالروبوتات أو الطائرات المسيّرة التي تقلّل الجرعة الإشعاعية ودخول الأماكن الضيقة ويشرف عليها، ويقيّم جودة ما تسجّله.', 'You apply robotics and remote inspection on your own in routine work and check your result.', 'تطبّق الروبوتات والفحص عن بُعد بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:IAEA-AI","label":"IAEA AI for nuclear energy (\"Atoms for Algorithms\")","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 87),
('pw-dp-procurement-l1', 'sk-fs-dp-procurement', 1, 'Digital procurement: foundations', 'المشتريات الرقمية: الأساسيات', 'Runs purchases through digital portals with traceable quality requirements, supplier evidence and in-country value data.', 'يُجري عمليات الشراء عبر البوابات الرقمية بمتطلبات جودة قابلة للتتبّع وأدلة من الموردين وبيانات القيمة المحلية المضافة.', 'You can explain the basics of digital procurement and apply them with guidance.', 'تستطيع شرح أساسيات المشتريات الرقمية وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast Open Skills and Skillabi","url":"https://lightcast.io/blog/open-skills-taxonomy"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 88),
('pw-dp-procurement-l2', 'sk-fs-dp-procurement', 2, 'Digital procurement: practitioner', 'المشتريات الرقمية: الممارسة', 'Runs purchases through digital portals with traceable quality requirements, supplier evidence and in-country value data.', 'يُجري عمليات الشراء عبر البوابات الرقمية بمتطلبات جودة قابلة للتتبّع وأدلة من الموردين وبيانات القيمة المحلية المضافة.', 'You apply digital procurement on your own in routine work and check your result.', 'تطبّق المشتريات الرقمية بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast Open Skills and Skillabi","url":"https://lightcast.io/blog/open-skills-taxonomy"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 89),
('pw-dp-ework-l1', 'sk-fs-dp-ework', 1, 'Digital work management (electronic work packages): foundations', 'الإدارة الرقمية للأعمال (حزم العمل الإلكترونية): الأساسيات', 'Executes and closes electronic work packages on a tablet, with signatures, holds and records captured as the work is done.', 'ينفّذ حزم العمل الإلكترونية ويغلقها على جهاز لوحي، مع تسجيل التواقيع ونقاط التوقف والسجلات أثناء تنفيذ العمل.', 'You can explain the basics of digital work management (electronic work packages) and apply them with guidance.', 'تستطيع شرح أساسيات الإدارة الرقمية للأعمال (حزم العمل الإلكترونية) وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:SG-JTM","label":"Jobs Transformation Maps","url":"https://wsg.gov.sg/for-employers/jobs-transformation-maps.html"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 90),
('pw-dp-ework-l2', 'sk-fs-dp-ework', 2, 'Digital work management (electronic work packages): practitioner', 'الإدارة الرقمية للأعمال (حزم العمل الإلكترونية): الممارسة', 'Executes and closes electronic work packages on a tablet, with signatures, holds and records captured as the work is done.', 'ينفّذ حزم العمل الإلكترونية ويغلقها على جهاز لوحي، مع تسجيل التواقيع ونقاط التوقف والسجلات أثناء تنفيذ العمل.', 'You apply digital work management (electronic work packages) on your own in routine work and check your result.', 'تطبّق الإدارة الرقمية للأعمال (حزم العمل الإلكترونية) بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:SG-JTM","label":"Jobs Transformation Maps","url":"https://wsg.gov.sg/for-employers/jobs-transformation-maps.html"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 91),
('pw-dp-rounds-l1', 'sk-fs-dp-rounds', 1, 'Digital operator rounds: foundations', 'الجولات التشغيلية الرقمية: الأساسيات', 'Records field readings on a handheld device, responds to out-of-range prompts and attaches photos or notes as evidence.', 'يسجّل القراءات الميدانية على جهاز محمول، ويستجيب لتنبيهات القيم خارج النطاق، ويرفق الصور أو الملاحظات دليلاً.', 'You can explain the basics of digital operator rounds and apply them with guidance.', 'تستطيع شرح أساسيات الجولات التشغيلية الرقمية وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:SG-JTM","label":"Jobs Transformation Maps","url":"https://wsg.gov.sg/for-employers/jobs-transformation-maps.html"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 92),
('pw-dp-rounds-l2', 'sk-fs-dp-rounds', 2, 'Digital operator rounds: practitioner', 'الجولات التشغيلية الرقمية: الممارسة', 'Records field readings on a handheld device, responds to out-of-range prompts and attaches photos or notes as evidence.', 'يسجّل القراءات الميدانية على جهاز محمول، ويستجيب لتنبيهات القيم خارج النطاق، ويرفق الصور أو الملاحظات دليلاً.', 'You apply digital operator rounds on your own in routine work and check your result.', 'تطبّق الجولات التشغيلية الرقمية بنفسك في العمل الاعتيادي وتتحقق من نتيجتك.', 4, 3, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:SG-JTM","label":"Jobs Transformation Maps","url":"https://wsg.gov.sg/for-employers/jobs-transformation-maps.html"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 93),
('pw-dp-paperlog-l1', 'sk-fs-dp-paperlog', 1, 'Paper log-sheet rounds: foundations', 'الجولات بسجلات ورقية: الأساسيات', 'Records readings on paper log sheets and transcribes them; still in use while digital rounds are rolled out. This skill is declining; the pathway helps you move to its digital successor.', 'يسجّل القراءات على سجلات ورقية ثم ينقلها؛ ولا يزال مستخدماً إلى أن تُعمَّم الجولات الرقمية. هذه المهارة في تراجع؛ يساعدك المسار على الانتقال إلى بديلها الرقمي.', 'You can explain the basics of paper log-sheet rounds and apply them with guidance.', 'تستطيع شرح أساسيات الجولات بسجلات ورقية وتطبيقها بتوجيه.', 3, 2, 'published', true, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"},{"id":"bm:LIGHTCAST","label":"Lightcast · Open Skills taxonomy","url":"https://lightcast.io/blog/open-skills-taxonomy","accessed":"2026-10-10"},{"id":"bm:WEF-FOJ","label":"WEF Future of Jobs Report 2025","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 94),
('pw-ai-automation-l3', 'sk-fs-ai-automation', 3, 'Automation design: advanced practice', 'تصميم الأتمتة: الممارسة المتقدمة', 'Draft: content still being commissioned.', 'مسودة: ما زال المحتوى قيد الإعداد.', 'You apply automation design in unfamiliar situations and help others do it.', 'تطبّق تصميم الأتمتة في مواقف غير مألوفة وتساعد الآخرين على ذلك.', 6, 3, 'draft', false, 1, array['ENTITLE','CORP','LIGHTCAST']::text[], '[{"id":"bm:ENTITLE","label":"MOE Singapore · SkillsFuture Level-Up programme (outcome-gated support for mid-career learning)","url":"https://www.moe.gov.sg/news/press-releases/20240304-new-skillsfuture-level-up-programme-to-boost-mid-career-upskilling-and-reskilling","accessed":"2026-10-10"},{"id":"bm:CORP","label":"Chief Learning Officer · AT&T: a fixed gaze toward the future (reskilling pathways)","url":"https://www.chieflearningofficer.com/2019/06/18/a-fixed-gaze-toward-the-future/","accessed":"2026-10-10"}]'::jsonb, 'p-training-mgr', '2026-10-10T08:00:00Z', 95),
('pw-et-system-integration', 'sk-fs-gr-h2heat', 2, 'Energy-system integration: from awareness to practitioner', 'تكامل منظومة الطاقة: من الوعي إلى الممارسة', 'Hydrogen, process heat and the grid in one route: three value chains, the interfaces with a nuclear plant and the skills they need. Concept learning; no deployment decision implied.', 'الهيدروجين والحرارة الصناعية والشبكة في مسار واحد: ثلاث سلاسل قيمة، والواجهات مع المحطة النووية، والمهارات التي تحتاجها. تعلّم مفاهيمي، ولا يُفهم منه أي قرار بالنشر.', 'You can explain how nuclear heat and electricity could serve hydrogen, industry and the grid, and where the safety boundary sits.', 'تستطيع شرح كيف يمكن للحرارة والكهرباء النوويتين خدمة الهيدروجين والصناعة والشبكة، وأين تقع حدود السلامة.', 6, 2, 'published', true, 1, array['ENERGY-JOBS','NEA']::text[], '[{"id":"fs42-nea-plan2035","label":"OECD-NEA · Plan 2035 vision paper: Scaling Technology, Growing Careers, Securing the Future (Oct 2025)","url":"https://www.oecd-nea.org/upload/docs/application/pdf/2025-10/plan_2035_-_vision_paper_-_final_version.pdf","accessed":"2026-10-10"},{"id":"fs42-iea-wee","label":"NucNet · IEA World Energy Employment 2025: jobs growth in nuclear (Dec 2025)","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025","accessed":"2026-10-10"},{"id":"fs42-irena-jobs","label":"EU BUILD UP · IRENA and ILO, Renewable Energy and Jobs: Annual Review 2025","url":"https://build-up.ec.europa.eu/en/resources-and-tools/publications/annual-review-2025-renewable-energy-and-jobs","accessed":"2026-10-10"}]'::jsonb, 'p-training-mgr', '2026-10-11T08:00:00Z', 96),
('pw-et-esg-managers', 'sk-fs-gr-esg', 1, 'ESG and GHG literacy for managers', 'الإلمام بالحوكمة البيئية والاجتماعية وغازات الدفيئة للمديرين', 'A short route for managers and reporting staff: greenhouse-gas accounting basics, sustainability and human capital reporting concepts, and a check that counts toward MC-CLEAN-ENERGY.', 'مسار قصير للمديرين وموظفي إعداد التقارير: أساسيات محاسبة غازات الدفيئة، ومفاهيم تقارير الاستدامة ورأس المال البشري، وفحص يُحتسب ضمن الاعتماد المصغّر MC-CLEAN-ENERGY.', 'You can read a sustainability or human capital disclosure, explain its main metrics and question a figure before you repeat it.', 'تستطيع قراءة إفصاح عن الاستدامة أو رأس المال البشري، وشرح مقاييسه الرئيسية، ومساءلة الرقم قبل تكراره.', 3, 1, 'published', true, 1, array['GREENCOMP','ISO30414','ENERGY-JOBS']::text[], '[{"id":"fs43-iso30414","label":"ISO TC 260 · ISO 30414:2025, strengthening human capital reporting (24 Aug 2025)","url":"https://committee.iso.org/sites/tc260/home/news/content-left-area/news-and-updates/iso-30414-2025-strengthening-hum.html","accessed":"2026-10-10"},{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","accessed":"2026-10-10"}]'::jsonb, 'p-training-mgr', '2026-10-11T08:00:00Z', 97)
