insert into kafaa_alumni_stories (id, alumni_id, engagement, title_en, title_ar, body_en, body_ar, quote_en, quote_ar, author_en, author_ar, consent_on, published_on, synthetic, listed, sort) values
('as-startup', 'alm-ops-01', 'capture_interview', 'Two hours that saved a week of startup testing', 'ساعتان وفّرتا أسبوعاً من اختبارات بدء التشغيل', 'A retired shift manager walked the Unit 4 crews through the decisions behind the first-cycle startup tests. The recorded session now sits in the knowledge base next to the procedures it explains.', 'شرح مدير وردية متقاعد لأطقم الوحدة 4 القرارات التي قامت عليها اختبارات بدء التشغيل للدورة الأولى. الجلسة المسجلة موجودة الآن في قاعدة المعرفة بجانب الإجراءات التي تشرحها.', 'The procedure tells you what to do. I could tell them why we wrote it that way.', 'الإجراء يخبرك بما تفعل. أما أنا فاستطعت أن أخبرهم لماذا كتبناه بهذه الطريقة.', 'Former shift manager, 14 years at Barakah (synthetic alumnus)', 'مدير وردية سابق، 14 عاماً في براكة (خبير سابق افتراضي)', '2026-07-01', '2026-07-15', true, true, 0),
('as-khnp', 'alm-khnp-01', 'instructor', 'From secondee to guest instructor', 'من معار إلى مدرب ضيف', 'After his KHNP secondment ended, an APR-1400 operator stayed in the reserve and co-taught emergency procedure drills on the simulator, pairing with a Barakah instructor each time.', 'بعد انتهاء إعارته من الشركة الكورية، بقي مشغل مفاعل APR-1400 في الاحتياطي وشارك في تدريب تمارين إجراءات الطوارئ على المحاكي، مع مدرب من براكة في كل مرة.', 'The crews were already good. We worked on the moments between procedures.', 'كانت الأطقم جيدة أصلاً. عملنا على اللحظات الفاصلة بين الإجراءات.', 'Former KHNP secondee, senior reactor operator (synthetic alumnus)', 'معار سابق من الشركة الكورية، كبير مشغلي مفاعل (خبير سابق افتراضي)', '2026-08-10', '2026-08-25', true, true, 1),
('as-psa', 'alm-lic-01', 'reviewer', 'A second pair of eyes on a licensing submission', 'عين ثانية على تقديم ترخيصي', 'A retired licensing engineer reviewed a PSA model update over the summer. Two of his fourteen comments changed the applicability statement before submission.', 'راجع مهندس ترخيص متقاعد تحديثاً لنموذج تقييم المخاطر الاحتمالي خلال الصيف. غيّرت ملاحظتان من ملاحظاته الأربع عشرة بيان الانطباق قبل التقديم.', 'I knew where the old assumptions were buried.', 'كنت أعرف أين دُفنت الافتراضات القديمة.', 'Former licensing engineer, 13 years (synthetic alumnus)', 'مهندس ترخيص سابق، 13 عاماً (خبير سابق افتراضي)', '2026-09-01', '2026-09-10', true, true, 2),
('as-hp', 'alm-hp-01', 'mentor', 'Coaching supervisors on the brief, not the form', 'تدريب المشرفين على الإحاطة لا على النموذج', 'Two reserve coaches spent a quarter with new first-line supervisors. Observed pre-job briefs became shorter and asked better questions.', 'أمضى مدربان من الاحتياطي ربع سنة مع المشرفين المباشرين الجدد. أصبحت إحاطات ما قبل العمل التي جرت ملاحظتها أقصر وطرحت أسئلة أفضل.', 'A good brief is a conversation. We practised the conversation.', 'الإحاطة الجيدة حوار. تدربنا على الحوار.', 'Former human-performance specialist (synthetic alumna)', 'أخصائية أداء بشري سابقة (خبيرة سابقة افتراضية)', '2026-07-05', '2026-07-20', true, true, 3),
('as-rounds', 'alm-ops-04', 'mentor', 'Field rounds, the long way', 'الجولات الميدانية بالطريق الطويل', 'A retired local operator mentored two new operators on field rounds. This story was unlisted when he withdrew his consent.', 'أرشد مشغل محلي متقاعد مشغلَين جديدين في الجولات الميدانية. أُلغي نشر هذه القصة عندما سحب موافقته.', null, null, 'Former local operator (synthetic alumnus)', 'مشغل محلي سابق (خبير سابق افتراضي)', '2026-05-01', '2026-05-10', true, false, 4)
