insert into kafaa_horizon_lanes (id, code, title_en, title_ar, summary_en, summary_ar, why_en, why_ar, skill_ids, horizon, path_only_role_ids, role_ids, sources, sort, kind, milestone_ids, as_of) values
('lane-digital', 'HZ-1', 'Digital I&C and plant data', 'أجهزة القياس والتحكم الرقمية وبيانات المحطة', 'Maintaining the APR-1400 digital platform, trending plant data and working with digital models of systems.', 'صيانة منصة APR-1400 الرقمية، وتحليل اتجاهات بيانات المحطة، والعمل مع النماذج الرقمية للأنظمة.', 'Barakah runs on digital instrumentation and control. ENEC is building data and AI platforms with partners, and the WEF expects technology skills to grow fastest to 2030 (per source).', 'تعمل براكة بأجهزة قياس وتحكم رقمية. وتبني المؤسسة منصات بيانات وذكاء اصطناعي مع شركائها، ويتوقع المنتدى الاقتصادي العالمي أن تكون المهارات التقنية الأسرع نمواً حتى 2030 (وفق المصدر).', array['sk-mp-02-dic','sk-mp-02','sk-da-01','sk-da-01-analysis','sk-da-01-scripting','sk-da-01-twins','sk-en-02-perf']::text[], 'now', '{}'::text[], array['maintenance-technician-engineer','systems-design-plant-engineer']::text[], '[{"id":"enec-presight","label":"ENEC · ENECIQ with Presight (Oct 2025)","url":"https://www.enec.ae/en/news/latest-news/enec-and-presight-co-develop-eneciq-ai-platform-to-boost-efficiency-and-knowledge-sharing/","as_of":"2026-10-08"},{"id":"wnn-kepco-2025","label":"WNN · KEPCO and ENEC enhance cooperation (Nov 2025)","url":"https://www.world-nuclear-news.org/articles/kepco-and-enec-enhance-cooperation-in-nuclear-energy","as_of":"2026-10-08"},{"id":"wef-foj-2025","label":"WEF · Future of Jobs Report 2025 (press release, Jan 2025)","url":"https://www.weforum.org/press/2025/01/future-of-jobs-report-2025-78-million-new-job-opportunities-by-2030-but-urgent-upskilling-needed-to-prepare-workforces/","as_of":"2026-10-08"}]'::jsonb, 1, 'build', array['ms-full-fleet','ms-eneciq']::text[], '2026-10-10'),
('lane-cyber', 'HZ-2', 'Cyber hygiene for everyone', 'النظافة السيبرانية للجميع', 'Everyday habits that protect plant and business systems: careful handling of media, accounts and messages, and stopping when something looks wrong.', 'عادات يومية تحمي أنظمة المحطة والأعمال: التعامل الحذر مع الوسائط والحسابات والرسائل، والتوقف عند الشك.', 'Networks and cybersecurity are among the fastest-growing skills in the WEF Future of Jobs Report 2025. Cyber and security roles are shown here as a career path only.', 'الشبكات والأمن السيبراني من أسرع المهارات نمواً في تقرير مستقبل الوظائف 2025 للمنتدى الاقتصادي العالمي. وتظهر أدوار الأمن السيبراني والأمن هنا مساراً مهنياً فقط.', array['sk-sa-01','sk-da-01','sk-hu-01-star']::text[], 'now', array['cyber-security-engineer','security-officer','safeguards-specialist']::text[], '{}'::text[], '[{"id":"wef-foj-2025","label":"WEF · Future of Jobs Report 2025 (press release, Jan 2025)","url":"https://www.weforum.org/press/2025/01/future-of-jobs-report-2025-78-million-new-job-opportunities-by-2030-but-urgent-upskilling-needed-to-prepare-workforces/","as_of":"2026-10-08"},{"id":"iaea-nss42g","label":"IAEA · Computer security techniques for nuclear facilities, NSS 42-G (2021)","url":"https://www.iaea.org/node/97473","as_of":"2026-10-10"},{"id":"nice-ot","label":"NIST / CISA · NICE Framework v2.0: OT cybersecurity engineering work role","url":"https://niccs.cisa.gov/tools/nice-framework/work-role/operational-technology-ot-cybersecurity-engineering","as_of":"2026-10-10"}]'::jsonb, 2, 'build', array['ms-full-fleet']::text[], '2026-10-10'),
('lane-ai', 'HZ-3', 'AI-assisted operations, governed', 'العمليات المدعومة بالذكاء الاصطناعي ضمن الحوكمة', 'Using AI tools for search, summaries and trend spotting while people keep every safety decision, check the outputs and record what they relied on.', 'استخدام أدوات الذكاء الاصطناعي في البحث والتلخيص ورصد الاتجاهات، مع بقاء كل قرار سلامة بيد الإنسان، والتحقق من المخرجات وتوثيق ما اعتُمد عليه.', 'ENEC and Presight are co-developing the ENECIQ AI platform for efficiency and knowledge sharing. Governed use needs staff who can question AI outputs and apply conservative decision-making.', 'تطوّر المؤسسة وبرسايت منصة ENECIQ للذكاء الاصطناعي لتعزيز الكفاءة وتبادل المعرفة. ويتطلب الاستخدام المحكوم موظفين قادرين على مساءلة مخرجات الذكاء الاصطناعي واتخاذ قرارات متحفظة.', array['sk-da-02','sk-da-02-review','sk-da-01-remote','sk-ld-02-decide','sk-hu-01-star']::text[], 'next', '{}'::text[], array['shift-technical-advisor','human-performance-specialist']::text[], '[{"id":"enec-presight","label":"ENEC · ENECIQ with Presight (Oct 2025)","url":"https://www.enec.ae/en/news/latest-news/enec-and-presight-co-develop-eneciq-ai-platform-to-boost-efficiency-and-knowledge-sharing/","as_of":"2026-10-08"},{"id":"wef-foj-2025","label":"WEF · Future of Jobs Report 2025 (press release, Jan 2025)","url":"https://www.weforum.org/press/2025/01/future-of-jobs-report-2025-78-million-new-job-opportunities-by-2030-but-urgent-upskilling-needed-to-prepare-workforces/","as_of":"2026-10-08"},{"id":"iaea-ai-bulletin","label":"IAEA Bulletin · Enhancing nuclear power production with artificial intelligence","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence","as_of":"2026-10-10"},{"id":"nei-iaea-ai","label":"NEI Magazine · IAEA hosts first AI and nuclear energy symposium (Dec 2025)","url":"https://www.neimagazine.com/news/iaea-hosts-first-ai-nuclear-symposium/","as_of":"2026-10-10"}]'::jsonb, 3, 'build', array['ms-eneciq','ms-iaea-ai','ms-uae-ai']::text[], '2026-10-10'),
('lane-advanced', 'HZ-4', 'Advanced reactor fundamentals', 'أساسيات المفاعلات المتقدمة', 'Passive safety, new coolants and fuel forms, remote operation concepts and licensing a new design.', 'السلامة الخاملة، والمبردات وأشكال الوقود الجديدة، ومفاهيم التشغيل عن بعد، وترخيص تصميم جديد.', 'Through ADVANCE, ENEC is evaluating SMRs and microreactors under several MoUs, and the NEA notes that new designs need new skills across the value chain. ENEC is evaluating these technologies; no deployment decision is implied.', 'تقيّم المؤسسة عبر برنامج ADVANCE المفاعلات الصغيرة والمتناهية الصغر بموجب عدة مذكرات تفاهم، وتشير وكالة الطاقة النووية إلى أن التصاميم الجديدة تتطلب مهارات جديدة عبر سلسلة القيمة. تقيّم المؤسسة هذه التقنيات ولا يعني ذلك أي قرار بالنشر.', array['sk-pf-01-core','sk-pf-01-advfuel','sk-pf-02-advcool','sk-ch-01-advchem','sk-ns-02-licensing','sk-mp-01-remote']::text[], 'next', '{}'::text[], array['reactor-engineer-core-physicist','regulatory-affairs-licensing-engineer']::text[], '[{"id":"wnn-advance","label":"WNN · ENEC to evaluate deployment of SMRs and microreactors (ADVANCE)","url":"https://world-nuclear-news.org/articles/enec-to-evaluate-deployment-of-smrs-and-microreact","as_of":"2026-10-08"},{"id":"wnn-smr-mous","label":"WNN · ENEC signs multiple SMR MoUs (COP28)","url":"https://world-nuclear-news.org/articles/enec-signs-multiple-smr-mous","as_of":"2026-10-08"},{"id":"nea-nest","label":"OECD NEA · Building the vital skills for the future of nuclear energy (NEST)","url":"https://www.oecd-nea.org/jcms/pl_56329/building-the-vital-skills-for-the-future-of-nuclear-energy","as_of":"2026-10-08"},{"id":"ans-canada-smr","label":"ANS · Education and training to support Canadian nuclear workforce development (Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"}]'::jsonb, 4, 'build', array['ms-cop28-smr','ms-gevh','ms-src','ms-strategy']::text[], '2026-10-10'),
('lane-netzero', 'HZ-5', 'Net zero and low-carbon industry', 'الحياد المناخي والصناعة منخفضة الكربون', 'How clean electricity supports decarbonisation: lifecycle carbon, greenhouse-gas accounting and project controls with industrial partners.', 'كيف تدعم الكهرباء النظيفة إزالة الكربون: الكربون عبر دورة الحياة، ومحاسبة غازات الدفيئة، وضبط المشاريع مع الشركاء الصناعيين.', 'Clean electricity from Barakah already supports industrial decarbonisation such as low-carbon aluminium, and ENEC reports its climate and sustainability goals publicly (per source). Hydrogen and industrial heat now have their own lane.', 'تدعم الكهرباء النظيفة من براكة بالفعل إزالة الكربون في الصناعة مثل الألمنيوم منخفض الكربون، وتنشر المؤسسة أهدافها المناخية وأهداف الاستدامة علناً (وفق المصدر). وأصبح للهيدروجين والحرارة الصناعية مسار مستقل.', array['sk-en-01-project','sk-en-02','sk-pf-02','sk-ch-01','sk-en-01-mods']::text[], 'later', '{}'::text[], array['systems-design-plant-engineer','chemistry-technician']::text[], '[{"id":"enec-climate","label":"ENEC · Climate change","url":"https://www.enec.ae/about-us/overview/climate-change/","as_of":"2026-10-08"},{"id":"enec-adnoc","label":"ENEC · ADNOC strategic collaboration (Nov 2024)","url":"https://www.enec.ae/en/news/latest-news/enec-and-adnoc-to-explore-the-use-of-advanced-nuclear-technologies-and-excess-heat-utilization-for-oil-and-gas-operations/","as_of":"2026-10-08"},{"id":"wnn-ega","label":"WNN · UAE collaboration delivers first low-carbon aluminium","url":"https://world-nuclear-news.org/articles/uae-collaboration-delivers-first-low-carbon-aluminium","as_of":"2026-10-08"},{"id":"enec-samsung","label":"ENEC · Samsung C&T MoU (Jul 2025)","url":"https://www.enec.ae/en/news/latest-news/enec-and-samsung-candt-sign-mou-to-advance-global-nuclear-energy-collaboration/","as_of":"2026-10-08"}]'::jsonb, 5, 'build', array['ms-adnoc-heat','ms-strategy']::text[], '2026-10-10'),
('lane-robotics', 'HZ-6', 'Robotics and remote inspection', 'الروبوتات والتفتيش عن بعد', 'Drones, crawlers and remote cameras for inspection in hard-to-reach areas, with people planning the work and judging what the images show.', 'الطائرات المسيّرة والروبوتات الزاحفة والكاميرات عن بعد للتفتيش في الأماكن الصعبة الوصول، مع بقاء تخطيط العمل والحكم على ما تُظهره الصور بيد الإنسان.', 'ENEC is working with TII and ASPIRE on autonomous aerial systems for critical infrastructure, and its MoU with SRC and GIEMS covers AI and robotics. The IAEA describes AI-enhanced digital replicas that support inspection and predictive maintenance (per source).', 'تعمل المؤسسة مع معهد الابتكار التكنولوجي وأسباير على الأنظمة الجوية الذاتية للبنية التحتية الحيوية، وتشمل مذكرة التفاهم مع مجلس أبحاث ساسكاتشوان وGIEMS الذكاء الاصطناعي والروبوتات. وتصف الوكالة الدولية للطاقة الذرية نماذج رقمية معززة بالذكاء الاصطناعي تدعم التفتيش والصيانة التنبؤية (وفق المصدر).', array['sk-mp-01-remote','sk-da-01-remote','sk-mp-01']::text[], 'now', '{}'::text[], array['maintenance-technician-engineer']::text[], '[{"id":"enec-tii","label":"ENEC · TII and ASPIRE autonomous aerial systems (Jan 2026)","url":"https://www.enec.ae/en/news/latest-news/enec-tii-and-aspire-collaborate-on-autonomous-aerial-systems-to-enhance-critical-infrastructure/","as_of":"2026-10-08"},{"id":"enec-src","label":"ENEC · SRC and GIEMS MoU (Jan 2026)","url":"https://enec.ae/news/latest-news/enec-saskatchewan-research-council-and-giems-sign-mou-to-advance-nuclear-research-and-capacity/","as_of":"2026-10-08"},{"id":"iaea-ai-bulletin","label":"IAEA Bulletin · Enhancing nuclear power production with artificial intelligence","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence","as_of":"2026-10-10"}]'::jsonb, 6, 'build', array['ms-tii','ms-src']::text[], '2026-10-10'),
('lane-ai-maint', 'HZ-7', 'AI-augmented maintenance', 'الصيانة المعززة بالذكاء الاصطناعي', 'Predictive maintenance from plant data: reading condition trends, triaging AI alerts and checking model outputs before any work order changes.', 'الصيانة التنبؤية من بيانات المحطة: قراءة اتجاهات حالة المعدات، وفرز تنبيهات الذكاء الاصطناعي، والتحقق من مخرجات النماذج قبل أي تغيير في أوامر العمل.', 'The IAEA describes digital twins and predictive maintenance as AI uses in plant operation, and ENEC is building the ENECIQ AI platform with Presight. The IEA reports labour shortages in technical trades across the energy sector (per source).', 'تصف الوكالة الدولية للطاقة الذرية التوائم الرقمية والصيانة التنبؤية بوصفها من استخدامات الذكاء الاصطناعي في تشغيل المحطات، وتبني المؤسسة منصة ENECIQ للذكاء الاصطناعي مع برسايت. وتشير الوكالة الدولية للطاقة إلى نقص في المهن الفنية في قطاع الطاقة (وفق المصدر).', array['sk-mp-02-dic','sk-en-02-perf','sk-da-01-analysis','sk-da-02-review']::text[], 'now', '{}'::text[], array['maintenance-technician-engineer','systems-design-plant-engineer']::text[], '[{"id":"iaea-ai-bulletin","label":"IAEA Bulletin · Enhancing nuclear power production with artificial intelligence","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence","as_of":"2026-10-10"},{"id":"enec-presight","label":"ENEC · ENECIQ with Presight (Oct 2025)","url":"https://www.enec.ae/en/news/latest-news/enec-and-presight-co-develop-eneciq-ai-platform-to-boost-efficiency-and-knowledge-sharing/","as_of":"2026-10-08"},{"id":"iea-wee-2025","label":"NucNet · IEA World Energy Employment 2025: nuclear jobs growth (Dec 2025)","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025","as_of":"2026-10-10"},{"id":"nei-iaea-ai","label":"NEI Magazine · IAEA hosts first AI and nuclear energy symposium (Dec 2025)","url":"https://www.neimagazine.com/news/iaea-hosts-first-ai-nuclear-symposium/","as_of":"2026-10-10"}]'::jsonb, 7, 'build', array['ms-eneciq','ms-iaea-ai','ms-iea-wee']::text[], '2026-10-10'),
('lane-manufacturing', 'HZ-8', 'Advanced manufacturing and factory QA', 'التصنيع المتقدم وضمان الجودة في المصنع', 'Modules built in factories and shipped to the plant: overseeing fabrication quality, dedicating commercial-grade items and digital procurement.', 'وحدات تُصنَّع في المصانع ثم تُنقل إلى المحطة: الإشراف على جودة التصنيع، واعتماد المواد التجارية، والمشتريات الرقمية.', 'Small modular designs move work from construction into factories. ENEC has signed MoUs on BWRX-300 deployment and with Samsung C&T, and IRENA and the ILO report skills shortages in manufacturing (per source). ENEC is evaluating these technologies; no deployment decision is implied.', 'تنقل التصاميم المعيارية الصغيرة جزءاً من العمل من الإنشاء إلى المصانع. ووقّعت المؤسسة مذكرات تفاهم بشأن نشر مفاعل BWRX-300 ومع سامسونج سي آند تي، وتشير الوكالة الدولية للطاقة المتجددة ومنظمة العمل الدولية إلى نقص المهارات في التصنيع (وفق المصدر). تقيّم المؤسسة هذه التقنيات ولا يعني ذلك أي قرار بالنشر.', array['sk-qa-01','sk-qa-01-inspect','sk-qa-02-cgd']::text[], 'next', '{}'::text[], array['quality-assurance-qc','procurement-engineer']::text[], '[{"id":"wnn-gevh","label":"WNN · MoU on international BWRX-300 deployment (May 2025)","url":"https://www.world-nuclear-news.org/articles/mou-paves-way-for-further-collaboration-on-bwrx-300-deployment","as_of":"2026-10-08"},{"id":"enec-samsung","label":"ENEC · Samsung C&T MoU (Jul 2025)","url":"https://www.enec.ae/en/news/latest-news/enec-and-samsung-candt-sign-mou-to-advance-global-nuclear-energy-collaboration/","as_of":"2026-10-08"},{"id":"irena-jobs-2025","label":"EU BUILD UP · IRENA and ILO, Renewable Energy and Jobs: Annual Review 2025","url":"https://build-up.ec.europa.eu/en/resources-and-tools/publications/annual-review-2025-renewable-energy-and-jobs","as_of":"2026-10-10"},{"id":"gevh-centre","label":"GE Vernova · GE Vernova Hitachi SMR engineering and service centre in Ontario (Jun 2025)","url":"https://www.gevernova.com/news/press-releases/ge-vernova-hitachi-nuclear-energy-canada-small-modular-reactor-engineering-service-centre-ontario","as_of":"2026-10-10"}]'::jsonb, 8, 'build', array['ms-gevh','ms-samsung','ms-gevh-centre']::text[], '2026-10-10'),
('lane-hydrogen', 'HZ-9', 'Hydrogen and industrial heat', 'الهيدروجين والحرارة الصناعية', 'Using clean electricity and heat beyond the grid: process-heat integration, hydrogen interfaces and the safety cases that connect a plant to industrial users.', 'استخدام الكهرباء والحرارة النظيفتين خارج الشبكة: دمج حرارة العمليات، وواجهات الهيدروجين، وحالات السلامة التي تربط المحطة بالمستخدمين الصناعيين.', 'ENEC and ADNOC are exploring advanced nuclear technologies and excess heat for oil and gas operations, and agreements with EMSTEEL and EGA already link clean nuclear electricity to industry (per source). ENEC is evaluating these technologies; no deployment decision is implied.', 'تستكشف المؤسسة وأدنوك التقنيات النووية المتقدمة والحرارة الفائضة لعمليات النفط والغاز، وتربط الاتفاقيات مع إمستيل والإمارات العالمية للألمنيوم بالفعل الكهرباء النووية النظيفة بالصناعة (وفق المصدر). تقيّم المؤسسة هذه التقنيات ولا يعني ذلك أي قرار بالنشر.', array['sk-en-01-project','sk-pf-02','sk-ch-01']::text[], 'later', '{}'::text[], array['systems-design-plant-engineer','chemistry-technician']::text[], '[{"id":"enec-adnoc","label":"ENEC · ADNOC strategic collaboration (Nov 2024)","url":"https://www.enec.ae/en/news/latest-news/enec-and-adnoc-to-explore-the-use-of-advanced-nuclear-technologies-and-excess-heat-utilization-for-oil-and-gas-operations/","as_of":"2026-10-08"},{"id":"admo-emsteel","label":"Abu Dhabi Media Office · EMSTEEL and ENEC clean nuclear energy agreement","url":"https://www.mediaoffice.abudhabi/en/economy/emsteel-group-and-emirates-nuclear-energy-company-accelerate-industrial-decarbonisation-through-clean-nuclear-energy-agreement/","as_of":"2026-10-08"},{"id":"wnn-ega","label":"WNN · UAE collaboration delivers first low-carbon aluminium","url":"https://world-nuclear-news.org/articles/uae-collaboration-delivers-first-low-carbon-aluminium","as_of":"2026-10-08"},{"id":"enec-climate","label":"ENEC · Climate change","url":"https://www.enec.ae/about-us/overview/climate-change/","as_of":"2026-10-08"}]'::jsonb, 9, 'build', array['ms-adnoc-heat']::text[], '2026-10-10'),
('lane-grid', 'HZ-10', 'Nuclear-renewables system integration', 'تكامل الطاقة النووية والمتجددة في المنظومة', 'Running clean firm power alongside a growing share of solar: grid integration, flexible operation studies and system-level planning.', 'تشغيل الطاقة النظيفة الثابتة إلى جانب حصة متزايدة من الطاقة الشمسية: التكامل مع الشبكة، ودراسات التشغيل المرن، والتخطيط على مستوى المنظومة.', 'Barakah has supplied the UAE grid since its first unit connected, and the IEA and IRENA expect energy employment to keep growing as power systems change, with shortages in technical and digital skills (per source).', 'تزوّد براكة شبكة الدولة بالكهرباء منذ ربط وحدتها الأولى، وتتوقع الوكالة الدولية للطاقة والوكالة الدولية للطاقة المتجددة استمرار نمو التوظيف في الطاقة مع تغيّر منظومات الكهرباء، مع نقص في المهارات الفنية والرقمية (وفق المصدر).', array['sk-pf-03','sk-co-03','sk-en-02']::text[], 'later', '{}'::text[], array['shift-technical-advisor','systems-design-plant-engineer']::text[], '[{"id":"wnn-grid","label":"WNN · UAE''s first reactor starts supplying power","url":"https://www.world-nuclear-news.org/articles/uaes-first-reactor-starts-supplying-power","as_of":"2026-10-08"},{"id":"iea-wee-2025","label":"NucNet · IEA World Energy Employment 2025: nuclear jobs growth (Dec 2025)","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025","as_of":"2026-10-10"},{"id":"irena-jobs-2025","label":"EU BUILD UP · IRENA and ILO, Renewable Energy and Jobs: Annual Review 2025","url":"https://build-up.ec.europa.eu/en/resources-and-tools/publications/annual-review-2025-renewable-energy-and-jobs","as_of":"2026-10-10"},{"id":"enec-climate","label":"ENEC · Climate change","url":"https://www.enec.ae/about-us/overview/climate-change/","as_of":"2026-10-08"}]'::jsonb, 10, 'build', array['ms-full-fleet','ms-iea-wee']::text[], '2026-10-10'),
('lane-fusion', 'HZ-11', 'Fusion watch (awareness only)', 'متابعة الاندماج النووي (للتوعية فقط)', 'A watching brief on fusion research: what it is, how it differs from fission and why it draws on the same specialist skills. Awareness only; no ENEC programme is implied.', 'متابعة لأبحاث الاندماج النووي: ما هو، وكيف يختلف عن الانشطار، ولماذا يعتمد على المهارات المتخصصة نفسها. للتوعية فقط، ولا يعني ذلك وجود برنامج لدى المؤسسة.', 'The IEA notes that defence nuclear and fusion compete with civil nuclear for the same specialists, and the NEA Plan 2035 aims to grow the whole nuclear workforce. Kafa''a follows fusion for awareness only (per source).', 'تشير الوكالة الدولية للطاقة إلى أن الاستخدامات النووية الدفاعية والاندماج يتنافسان مع الطاقة النووية المدنية على المتخصصين أنفسهم، وتهدف خطة وكالة الطاقة النووية 2035 إلى تنمية القوى العاملة النووية بأكملها. وتتابع كفاءة الاندماج للتوعية فقط (وفق المصدر).', array['sk-pf-01-core']::text[], 'later', '{}'::text[], '{}'::text[], '[{"id":"iea-wee-2025","label":"NucNet · IEA World Energy Employment 2025: nuclear jobs growth (Dec 2025)","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025","as_of":"2026-10-10"},{"id":"nea-plan-2035","label":"OECD-NEA · Plan 2035 vision paper (Oct 2025)","url":"https://www.oecd-nea.org/upload/docs/application/pdf/2025-10/plan_2035_-_vision_paper_-_final_version.pdf","as_of":"2026-10-10"},{"id":"nea-nest","label":"OECD NEA · Building the vital skills for the future of nuclear energy (NEST)","url":"https://www.oecd-nea.org/jcms/pl_56329/building-the-vital-skills-for-the-future-of-nuclear-energy","as_of":"2026-10-08"}]'::jsonb, 11, 'watch', array['ms-iea-wee','ms-nea-2035']::text[], '2026-10-10')
