insert into kafaa_horizon_milestones (id, year, month, kind, title_en, title_ar, summary_en, summary_ar, sources, sort) values
('ms-cop28-smr', 2023, 12, 'enec', 'SMR and advanced-technology MoUs at COP28', 'مذكرات تفاهم للمفاعلات الصغيرة والتقنيات المتقدمة في COP28', 'ENEC signs several memoranda on small modular and advanced reactors and starts evaluating them through ADVANCE.', 'توقّع المؤسسة عدة مذكرات تفاهم بشأن المفاعلات المعيارية الصغيرة والمتقدمة وتبدأ تقييمها عبر برنامج ADVANCE.', '[{"id":"wnn-smr-mous","label":"WNN · ENEC signs multiple SMR MoUs (COP28)","url":"https://world-nuclear-news.org/articles/enec-signs-multiple-smr-mous","as_of":"2026-10-08"},{"id":"wnn-advance","label":"WNN · ENEC to evaluate deployment of SMRs and microreactors (ADVANCE)","url":"https://world-nuclear-news.org/articles/enec-to-evaluate-deployment-of-smrs-and-microreact","as_of":"2026-10-08"}]'::jsonb, 1),
('ms-adnoc-heat', 2024, 11, 'enec', 'ENEC and ADNOC explore advanced nuclear heat', 'المؤسسة وأدنوك تستكشفان الحرارة النووية المتقدمة', 'A strategic collaboration to explore advanced nuclear technologies and excess heat for oil and gas operations.', 'تعاون استراتيجي لاستكشاف التقنيات النووية المتقدمة والحرارة الفائضة لعمليات النفط والغاز.', '[{"id":"enec-adnoc","label":"ENEC · ADNOC strategic collaboration (Nov 2024)","url":"https://www.enec.ae/en/news/latest-news/enec-and-adnoc-to-explore-the-use-of-advanced-nuclear-technologies-and-excess-heat-utilization-for-oil-and-gas-operations/","as_of":"2026-10-08"}]'::jsonb, 2),
('ms-gevh', 2025, 5, 'enec', 'MoU on international BWRX-300 deployment', 'مذكرة تفاهم بشأن النشر الدولي لمفاعل BWRX-300', 'ENEC joins a memorandum on deploying the BWRX-300 small boiling water reactor internationally.', 'تنضم المؤسسة إلى مذكرة تفاهم بشأن نشر مفاعل الماء المغلي الصغير BWRX-300 دولياً.', '[{"id":"wnn-gevh","label":"WNN · MoU on international BWRX-300 deployment (May 2025)","url":"https://www.world-nuclear-news.org/articles/mou-paves-way-for-further-collaboration-on-bwrx-300-deployment","as_of":"2026-10-08"}]'::jsonb, 3),
('ms-samsung', 2025, 7, 'enec', 'ENEC and Samsung C&T MoU', 'مذكرة تفاهم بين المؤسسة وسامسونج سي آند تي', 'A memorandum to advance global nuclear energy collaboration, including new-build delivery.', 'مذكرة تفاهم لتعزيز التعاون العالمي في الطاقة النووية، بما في ذلك تنفيذ المشاريع الجديدة.', '[{"id":"enec-samsung","label":"ENEC · Samsung C&T MoU (Jul 2025)","url":"https://www.enec.ae/en/news/latest-news/enec-and-samsung-candt-sign-mou-to-advance-global-nuclear-energy-collaboration/","as_of":"2026-10-08"}]'::jsonb, 4),
('ms-full-fleet', 2025, 9, 'enec', 'First year of full-fleet operations at Barakah', 'السنة الأولى من التشغيل الكامل لأسطول براكة', 'All four Barakah units complete a first full year of operation together.', 'تُكمل وحدات براكة الأربع سنتها الأولى من التشغيل معاً.', '[{"id":"admo-full-fleet","label":"Abu Dhabi Media Office · Barakah completes first year of full-fleet operations (Sep 2025)","url":"https://www.mediaoffice.abudhabi/en/energy/led-by-emirates-nuclear-energy-company-barakah-nuclear-energy-plant-completes-first-year-of-full-fleet-operations/","as_of":"2026-10-08"}]'::jsonb, 5),
('ms-eneciq', 2025, 10, 'enec', 'ENECIQ AI platform with Presight', 'منصة ENECIQ للذكاء الاصطناعي مع برسايت', 'ENEC and Presight co-develop an AI platform for efficiency and knowledge sharing.', 'تطوّر المؤسسة وبرسايت منصة للذكاء الاصطناعي لتعزيز الكفاءة وتبادل المعرفة.', '[{"id":"enec-presight","label":"ENEC · ENECIQ with Presight (Oct 2025)","url":"https://www.enec.ae/en/news/latest-news/enec-and-presight-co-develop-eneciq-ai-platform-to-boost-efficiency-and-knowledge-sharing/","as_of":"2026-10-08"}]'::jsonb, 6),
('ms-iaea-ai', 2025, 12, 'international', 'IAEA first AI and nuclear energy symposium', 'أول ندوة للوكالة الدولية للطاقة الذرية عن الذكاء الاصطناعي والطاقة النووية', 'The IAEA convenes its first symposium on AI for nuclear energy ("Atoms for Algorithms").', 'تعقد الوكالة الدولية للطاقة الذرية أول ندوة لها عن الذكاء الاصطناعي للطاقة النووية ("الذرة من أجل الخوارزميات").', '[{"id":"nei-iaea-ai","label":"NEI Magazine · IAEA hosts first AI and nuclear energy symposium (Dec 2025)","url":"https://www.neimagazine.com/news/iaea-hosts-first-ai-nuclear-symposium/","as_of":"2026-10-10"},{"id":"iaea-ai-bulletin","label":"IAEA Bulletin · Enhancing nuclear power production with artificial intelligence","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence","as_of":"2026-10-10"}]'::jsonb, 7),
('ms-iea-wee', 2025, 12, 'international', 'IEA World Energy Employment 2025', 'تقرير الوكالة الدولية للطاقة عن التوظيف في قطاع الطاقة 2025', 'The first edition with occupation-level estimates; it reports labour shortages in technical trades and nuclear specialists.', 'أول إصدار بتقديرات على مستوى المهن؛ ويشير إلى نقص في المهن الفنية والمتخصصين النوويين.', '[{"id":"iea-wee-2025","label":"NucNet · IEA World Energy Employment 2025: nuclear jobs growth (Dec 2025)","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025","as_of":"2026-10-10"}]'::jsonb, 8),
('ms-tii', 2026, 1, 'enec', 'Autonomous aerial systems with TII and ASPIRE', 'الأنظمة الجوية الذاتية مع معهد الابتكار التكنولوجي وأسباير', 'ENEC, TII and ASPIRE collaborate on autonomous aerial systems to enhance critical infrastructure.', 'تتعاون المؤسسة ومعهد الابتكار التكنولوجي وأسباير في الأنظمة الجوية الذاتية لتعزيز البنية التحتية الحيوية.', '[{"id":"enec-tii","label":"ENEC · TII and ASPIRE autonomous aerial systems (Jan 2026)","url":"https://www.enec.ae/en/news/latest-news/enec-tii-and-aspire-collaborate-on-autonomous-aerial-systems-to-enhance-critical-infrastructure/","as_of":"2026-10-08"}]'::jsonb, 9),
('ms-src', 2026, 1, 'enec', 'SRC and GIEMS MoU on research and capacity', 'مذكرة تفاهم مع مجلس أبحاث ساسكاتشوان وGIEMS للبحث وبناء القدرات', 'Cooperation on small modular reactors, AI and robotics, and capacity building.', 'تعاون في المفاعلات المعيارية الصغيرة والذكاء الاصطناعي والروبوتات وبناء القدرات.', '[{"id":"enec-src","label":"ENEC · SRC and GIEMS MoU (Jan 2026)","url":"https://enec.ae/news/latest-news/enec-saskatchewan-research-council-and-giems-sign-mou-to-advance-nuclear-research-and-capacity/","as_of":"2026-10-08"},{"id":"sask-src","label":"Government of Saskatchewan · MoU with the UAE on nuclear (Jan 2026)","url":"https://www.saskatchewan.ca/government/news-and-media/2026/january/16/saskatchewan-signs-mou-with-united-arab-emirates-on-nuclear-program","as_of":"2026-10-08"}]'::jsonb, 10),
('ms-mawaheb', 2026, 5, 'uae', 'ENEC and DGE Abu Dhabi Mawaheb agreement', 'اتفاقية مواهب بين المؤسسة ودائرة التمكين الحكومي في أبوظبي', 'A five-year agreement to train UAE nationals for civil nuclear roles.', 'اتفاقية لخمس سنوات لتدريب المواطنين على أدوار في قطاع الطاقة النووية السلمية.', '[{"id":"enec-dge","label":"ENEC · ENEC-DGE (Mawaheb) agreement (May 2026)","url":"https://www.enec.ae/news/latest-news/enec-and-department-of-government-enablement-abu-dhabi-sign-agreement/","as_of":"2026-10-08"},{"id":"wnn-dge","label":"WNN · Agreement on UAE nuclear workforce development","url":"https://www.world-nuclear-news.org/articles/agreement-on-uae-nuclear-workforce-development","as_of":"2026-10-08"}]'::jsonb, 11),
('ms-gevh-centre', 2027, 12, 'international', 'SMR engineering and service centre expected in Ontario', 'مركز هندسة وخدمات المفاعلات الصغيرة المتوقع في أونتاريو', 'GE Vernova Hitachi expects its SMR engineering and service centre, with training facilities, to be operational by the end of 2027.', 'تتوقع جي إي فيرنوفا هيتاشي تشغيل مركزها لهندسة وخدمات المفاعلات الصغيرة، بمرافق تدريبية، بحلول نهاية 2027.', '[{"id":"gevh-centre","label":"GE Vernova · GE Vernova Hitachi SMR engineering and service centre in Ontario (Jun 2025)","url":"https://www.gevernova.com/news/press-releases/ge-vernova-hitachi-nuclear-energy-canada-small-modular-reactor-engineering-service-centre-ontario","as_of":"2026-10-10"},{"id":"ans-canada-smr","label":"ANS · Education and training to support Canadian nuclear workforce development (Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"}]'::jsonb, 12),
('ms-strategy', 2029, null, 'enec', 'ENEC Enterprise Strategy 2025-2029 horizon', 'أفق الاستراتيجية المؤسسية للمؤسسة 2025-2029', 'The current enterprise strategy runs to the end of 2029.', 'تمتد الاستراتيجية المؤسسية الحالية حتى نهاية 2029.', '[{"id":"enec-strategy","label":"ENEC · Strategic roadmap (Enterprise Strategy 2025-2029)","url":"https://www.enec.ae/about-us/overview/strategic-roadmap/","as_of":"2026-10-08"}]'::jsonb, 13),
('ms-uae-ai', 2031, null, 'uae', 'UAE National AI Strategy 2031', 'الاستراتيجية الوطنية للذكاء الاصطناعي 2031', 'The national target year for AI capability across government and the economy.', 'سنة الهدف الوطني لقدرات الذكاء الاصطناعي في الحكومة والاقتصاد.', '[{"id":"dge-ainative","label":"Abu Dhabi DGE · What we do (AiNative)","url":"https://dge.gov.ae/en/what-we-do","as_of":"2026-10-10"}]'::jsonb, 14),
('ms-nea-2035', 2035, null, 'international', 'OECD-NEA Plan 2035', 'خطة وكالة الطاقة النووية 2035', 'The NEA initiative to build the nuclear workforce for growing capacity, with three pathways: inspire, mentor and network.', 'مبادرة وكالة الطاقة النووية لبناء القوى العاملة النووية لقدرات متنامية، عبر ثلاثة مسارات: الإلهام والإرشاد والتواصل.', '[{"id":"nea-plan-2035","label":"OECD-NEA · Plan 2035 vision paper (Oct 2025)","url":"https://www.oecd-nea.org/upload/docs/application/pdf/2025-10/plan_2035_-_vision_paper_-_final_version.pdf","as_of":"2026-10-10"}]'::jsonb, 15)
