insert into kafaa_communities (id, code, discipline, name_en, name_ar, charter_en, charter_ar, steward_role_en, steward_role_ar, skill_ids, open, sort) values
('cop-ops', 'COP-OPS', 'operations', 'Operations', 'العمليات', 'Share good operating practice, turnover habits and learning from simulator and plant experience across the crews. Careers and learning only: no plant procedures, setpoints or security details.', 'تبادل الممارسات التشغيلية الجيدة وعادات تسليم الوردية والتعلم من خبرات المحاكي والمحطة بين الطواقم. للمهن والتعلم فقط: لا إجراءات تشغيل ولا نقاط ضبط ولا تفاصيل أمنية.', 'Shift Supervisor (role card)', 'مشرف الوردية (بطاقة دور)', array['sk-co-01','sk-co-02','sk-co-03','sk-pf-03']::text[], true, 10),
('cop-maint', 'COP-MNT', 'maintenance', 'Maintenance', 'الصيانة', 'Work package quality, troubleshooting skills, digital I&C learning and outage lessons learned for maintenance and work control.', 'جودة حزم العمل ومهارات تحري الأعطال وتعلم أجهزة القياس والتحكم الرقمية والدروس المستفادة من فترات الإيقاف للصيانة والتحكم في الأعمال.', 'Work Control Lead (role card)', 'قائد التحكم في الأعمال (بطاقة دور)', array['sk-mp-01','sk-mp-02','sk-mp-02-dic']::text[], true, 20),
('cop-chem', 'COP-CHEM', 'chemistry', 'Chemistry', 'الكيمياء', 'Sampling practice, water chemistry learning and on-the-job tips for chemistry technicians and engineers.', 'ممارسات أخذ العينات وتعلم كيمياء المياه ونصائح التدريب أثناء العمل لفنيي ومهندسي الكيمياء.', 'Chemistry Supervisor (role card)', 'مشرف الكيمياء (بطاقة دور)', array['sk-ch-01','sk-ch-02']::text[], true, 30),
('cop-rp', 'COP-RP', 'radiation_protection', 'Radiation protection', 'الوقاية من الإشعاع', 'ALARA culture, survey technique learning and coaching new joiners on dose awareness.', 'ثقافة ALARA وتعلم تقنيات المسح وإرشاد المنضمين الجدد حول الوعي بالجرعات.', 'Radiation Protection Lead (role card)', 'قائد الوقاية من الإشعاع (بطاقة دور)', array['sk-rp-01','sk-rp-02']::text[], true, 40),
('cop-eng', 'COP-ENG', 'engineering', 'Engineering', 'الهندسة', 'Configuration management, design basis learning, system health and reactor physics refreshers.', 'إدارة التهيئة وتعلم أساس التصميم وصحة الأنظمة ومراجعات فيزياء المفاعلات.', 'Senior Systems Engineer (role card)', 'مهندس أنظمة أول (بطاقة دور)', array['sk-en-01','sk-en-02','sk-ns-01']::text[], true, 50),
('cop-digital', 'COP-DAI', 'digital_ai', 'Digital and AI', 'الرقمنة والذكاء الاصطناعي', 'Data skills, trending and the governed use of AI tools at work: what to check, what to record and what never to share.', 'مهارات البيانات وتحليل الاتجاهات والاستخدام المحكوم لأدوات الذكاء الاصطناعي في العمل: ما يجب التحقق منه وتوثيقه وما لا يجوز مشاركته أبداً.', 'AI Governance Lead (role card)', 'قائد حوكمة الذكاء الاصطناعي (بطاقة دور)', array['sk-da-01','sk-da-02']::text[], true, 60),
('cop-hp', 'COP-HP', 'human_performance', 'Human performance', 'الأداء البشري', 'Human performance tools in practice, pre-job briefs, questioning attitude and safety culture conversations across every discipline.', 'أدوات الأداء البشري في الممارسة والإحاطات قبل العمل والموقف التساؤلي وحوارات ثقافة السلامة في جميع التخصصات.', 'Training Manager (role card)', 'مدير التدريب (بطاقة دور)', array['sk-hu-01','sk-hu-02','sk-sc-01','sk-sc-02']::text[], true, 70)
