insert into kafaa_expert_requests (id, expert_id, requester_id, skill_id, message, status, reply, requester_name, requester_name_ar, expert_name, expert_name_ar, created_at, answered_at) values
('er-001', 'w-sro-01', 'p-k-ro', 'sk-co-02', 'Could we spend 20 minutes on how you structure turnover notes? I want to improve mine before my LET course.', 'accepted', 'Happy to. Find me after the Tuesday crew brief.', 'Reactor Operator, Crew B', 'مشغّل مفاعل، الطاقم ب', 'Nasser Al Marzooqi', 'ناصر المرزوقي', '2026-09-16T10:00:00Z', '2026-09-16T15:30:00Z'),
('er-002', 'p-sme-reviewer', 'p-qc-inspector', 'sk-en-01', 'I would like to understand how engineering checks a drawing revision before a design review. Could you walk me through it?', 'sent', null, 'QC Receiving Inspector (role card)', 'مفتش جودة الاستلام (بطاقة دور)', 'SME reviewer (role card)', 'مراجع خبير (بطاقة دور)', '2026-10-05T10:00:00Z', null),
('er-003', 'w-mnt-02', 'p-outage-planner', 'sk-mp-02-dic', 'Planning the next outage scope with digital I&C work. Could you share how you estimate troubleshooting time?', 'declined', 'Out on a course this month; please ask the maintenance community.', 'Outage Planner (role card)', 'مخطط فترات الإيقاف (بطاقة دور)', 'Sultan Al Mazrouei', 'سلطان المزروعي', '2026-09-28T10:00:00Z', '2026-09-28T15:30:00Z'),
('er-004', 'p-chem-sup', 'w-chem-03', 'sk-ch-02', 'Could you recommend public reading on water chemistry fundamentals for my development plan?', 'accepted', 'Yes: I will bring a list to the next knowledge-sharing session.', 'Nasser Al Marzooqi', 'ناصر المرزوقي', 'Chemistry Supervisor (role card)', 'مشرف الكيمياء (بطاقة دور)', '2026-09-10T10:00:00Z', '2026-09-10T15:30:00Z')
insert into kafaa_ks_sessions (id, community_id, topic, title_en, title_ar, summary_en, summary_ar, presenter_role_en, presenter_role_ar, held_on, status, duration_min, recording_ref, keywords, skill_ids, synthetic, sources) values
('ks-01', 'cop-ops', 'proficiency', 'Keeping proficiency between watches', 'الحفاظ على الكفاءة بين المناوبات', 'How licensed operators plan proficiency watches and use the simulator to stay sharp between cycles.', 'كيف يخطط المشغلون المرخصون لمناوبات الكفاءة ويستخدمون المحاكي للحفاظ على جاهزيتهم بين الدورات.', 'Shift Supervisor (role card)', 'مشرف الوردية (بطاقة دور)', '2025-03-12', 'held', 60, 'KS-REC-2025-001', array['proficiency','watch','الكفاءة']::text[], array['sk-co-01']::text[], true, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb),
('ks-02', 'cop-maint', 'outage_lessons', 'Outage lessons learned: work packages and parts', 'الدروس المستفادة من فترة الإيقاف: حزم العمل وقطع الغيار', 'What went well and what to improve in package preparation, parts staging and hold points.', 'ما نجح وما يجب تحسينه في إعداد حزم العمل وتجهيز قطع الغيار ونقاط التوقف.', 'Outage Manager (role card)', 'مدير فترات الإيقاف (بطاقة دور)', '2025-05-20', 'held', 75, 'KS-REC-2025-002', array['outage','lessons learned','الدروس المستفادة','فترة الإيقاف']::text[], array['sk-mp-01','sk-mp-01-outage']::text[], true, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb),
('ks-03', null, 'project_management', 'Project management basics for technical leads', 'أساسيات إدارة المشاريع للقادة الفنيين', 'Scope, schedule and risk registers in plain terms, with examples from plant improvement projects.', 'النطاق والجدول الزمني وسجلات المخاطر بلغة بسيطة مع أمثلة من مشاريع تحسين المحطة.', 'Project Engineer (role card)', 'مهندس مشاريع (بطاقة دور)', '2025-06-17', 'held', 60, 'KS-REC-2025-003', array['project','schedule','إدارة المشاريع']::text[], '{}'::text[], true, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb),
('ks-04', 'cop-digital', 'ai', 'Artificial intelligence at work: governed use', 'الذكاء الاصطناعي في العمل: استخدام محكوم', 'What AI tools are good for, what to check before relying on an output, and what must never be shared.', 'فيمَ تفيد أدوات الذكاء الاصطناعي، وما الذي يجب التحقق منه قبل الاعتماد على مخرجاتها، وما لا يجوز مشاركته أبداً.', 'AI Governance Lead (role card)', 'قائد حوكمة الذكاء الاصطناعي (بطاقة دور)', '2025-09-24', 'held', 60, 'KS-REC-2025-004', array['ai','artificial intelligence','الذكاء الاصطناعي','governance']::text[], array['sk-da-02']::text[], true, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb),
('ks-05', 'cop-ops', 'mcr_overview', 'Overview of main control room operations in a simulated environment', 'نظرة عامة على عمليات غرفة التحكم الرئيسية في بيئة محاكاة', 'A guided tour of how a crew works together in the main control room, run on the training simulator for non-operations staff.', 'جولة إرشادية حول كيفية عمل الطاقم معاً في غرفة التحكم الرئيسية، تُقدَّم على محاكي التدريب لموظفي الأقسام غير التشغيلية.', 'Senior Reactor Operator Instructor (role card)', 'مدرب مشغل مفاعل أول (بطاقة دور)', '2025-10-15', 'held', 90, 'KS-REC-2025-005', array['main control room','mcr','simulator','غرفة التحكم الرئيسية','المحاكي']::text[], array['sk-co-02']::text[], true, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb),
('ks-06', 'cop-rp', 'radiation_safety', 'Radiation safety refresher for all staff', 'تذكير بالسلامة الإشعاعية لجميع الموظفين', 'ALARA in everyday terms: time, distance and shielding, and how good planning keeps doses low.', 'مبدأ ALARA بلغة يومية: الوقت والمسافة والتدريع، وكيف يحافظ التخطيط الجيد على انخفاض الجرعات.', 'Radiation Protection Lead (role card)', 'قائد الوقاية من الإشعاع (بطاقة دور)', '2025-11-19', 'held', 60, 'KS-REC-2025-006', array['radiation','alara','dose','الوقاية من الإشعاع','الجرعة']::text[], array['sk-rp-01']::text[], true, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb),
('ks-07', 'cop-digital', 'data_analytics', 'Data analytics: trending equipment health', 'تحليل البيانات: رصد اتجاهات صحة المعدات', 'Simple trending techniques that help engineers and technicians spot early signs of equipment degradation.', 'تقنيات بسيطة لرصد الاتجاهات تساعد المهندسين والفنيين على اكتشاف العلامات المبكرة لتدهور المعدات.', 'Data Analyst (role card)', 'محلل بيانات (بطاقة دور)', '2026-01-21', 'held', 60, 'KS-REC-2026-007', array['data analytics','trending','python','تحليل البيانات']::text[], array['sk-da-01']::text[], true, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb),
('ks-08', 'cop-hp', 'human_performance', 'Human performance tools: self-checking that sticks', 'أدوات الأداء البشري: تحقق ذاتي يدوم', 'Practical ways to make STAR and peer checking habits rather than steps you remember under pressure.', 'طرق عملية لجعل أسلوب STAR والتحقق المتبادل عادة لا خطوات نتذكرها تحت الضغط.', 'Human Performance Specialist (role card)', 'أخصائي الأداء البشري (بطاقة دور)', '2026-02-18', 'held', 45, 'KS-REC-2026-008', array['star','self-checking','human performance','الأداء البشري','التحقق الذاتي']::text[], array['sk-hu-01','sk-hu-01-star']::text[], true, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb),
('ks-09', 'cop-chem', 'chemistry', 'Sampling practice for new chemistry technicians', 'ممارسات أخذ العينات لفنيي الكيمياء الجدد', 'Planning a sampling round, labelling and logging as you go, and asking for a peer check early.', 'التخطيط لجولة أخذ العينات والتوسيم والتوثيق أثناء العمل وطلب التحقق المتبادل مبكراً.', 'Chemistry Supervisor (role card)', 'مشرف الكيمياء (بطاقة دور)', '2026-03-25', 'held', 60, 'KS-REC-2026-009', array['chemistry','sampling','الكيمياء','العينات']::text[], array['sk-ch-01']::text[], true, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb),
('ks-10', 'cop-ops', 'proficiency', 'Shift turnover that works', 'تسليم وردية فعّال', 'Structured turnover, narrative logs and the questions that help the oncoming crew build the plant picture.', 'تسليم منظم للوردية وسجلات سردية وأسئلة تساعد الطاقم القادم على تكوين صورة المحطة.', 'Shift Supervisor (role card)', 'مشرف الوردية (بطاقة دور)', '2026-04-22', 'held', 60, 'KS-REC-2026-010', array['turnover','shift','تسليم الوردية']::text[], array['sk-co-02']::text[], true, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb),
('ks-11', 'cop-maint', 'maintenance', 'From analogue to digital I&C troubleshooting', 'من تحري أعطال الأجهزة التناظرية إلى الرقمية', 'How experienced technicians adapted their troubleshooting approach to digital instrumentation and control.', 'كيف كيّف الفنيون ذوو الخبرة نهجهم في تحري الأعطال مع أجهزة القياس والتحكم الرقمية.', 'Maintenance Technician Lead (role card)', 'قائد فنيي الصيانة (بطاقة دور)', '2026-05-27', 'held', 60, 'KS-REC-2026-011', array['digital i&c','troubleshooting','أجهزة القياس والتحكم']::text[], array['sk-mp-02-dic']::text[], true, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb),
('ks-12', 'cop-eng', 'proficiency', 'Configuration management for new engineers', 'إدارة التهيئة للمهندسين الجدد', 'Why revision control and design basis matter, with everyday habits that prevent errors.', 'لماذا يهم التحكم في المراجعات وأساس التصميم، مع عادات يومية تمنع الأخطاء.', 'Senior Systems Engineer (role card)', 'مهندس أنظمة أول (بطاقة دور)', '2026-06-24', 'held', 60, 'KS-REC-2026-012', array['configuration','design basis','إدارة التهيئة']::text[], array['sk-en-01']::text[], true, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb),
('ks-13', 'cop-ops', 'outage_lessons', 'Outage lessons learned for operations crews', 'الدروس المستفادة من فترة الإيقاف لطواقم العمليات', 'Upcoming: what the last outage taught operations crews about coordination with maintenance and work control.', 'قادمة: ما تعلمته طواقم العمليات من فترة الإيقاف الأخيرة حول التنسيق مع الصيانة والتحكم في الأعمال.', 'Shift Supervisor (role card)', 'مشرف الوردية (بطاقة دور)', '2026-10-21', 'upcoming', 60, null, array['outage','lessons learned','operations','فترة الإيقاف']::text[], array['sk-co-01']::text[], true, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb),
('ks-14', 'cop-digital', 'ai', 'AI search over procedures: what is allowed', 'البحث بالذكاء الاصطناعي في الوثائق: ما المسموح', 'Upcoming: governed use of AI search tools for learning content, and what stays out of scope.', 'قادمة: الاستخدام المحكوم لأدوات البحث بالذكاء الاصطناعي في محتوى التعلم، وما يبقى خارج النطاق.', 'AI Governance Lead (role card)', 'قائد حوكمة الذكاء الاصطناعي (بطاقة دور)', '2026-11-11', 'upcoming', 60, null, array['ai','search','الذكاء الاصطناعي']::text[], array['sk-da-02']::text[], true, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb),
('ks-15', 'cop-hp', 'human_performance', 'Leaders and the questioning attitude', 'القادة والموقف التساؤلي', 'Upcoming: how first-line leaders encourage people to raise questions, linked to the leadership academy.', 'قادمة: كيف يشجع قادة الخط الأول الأشخاص على طرح الأسئلة، بالارتباط مع أكاديمية القيادة.', 'Training Manager (role card)', 'مدير التدريب (بطاقة دور)', '2026-11-25', 'upcoming', 45, null, array['leadership','questioning attitude','القيادة','الموقف التساؤلي']::text[], array['sk-sc-01','sk-ld-01']::text[], true, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb),
('ks-16', 'cop-rp', 'radiation_safety', 'Survey technique clinic', 'ورشة تقنيات المسح الإشعاعي', 'Upcoming: hands-on tips for survey technique, with time for questions from new technicians.', 'قادمة: نصائح عملية لتقنيات المسح مع وقت لأسئلة الفنيين الجدد.', 'Radiation Protection Lead (role card)', 'قائد الوقاية من الإشعاع (بطاقة دور)', '2026-12-09', 'upcoming', 60, null, array['radiation','survey','المسح الإشعاعي']::text[], array['sk-rp-02-survey']::text[], true, '[{"id":"cns10","label":"UAE National Report, 10th CNS Review Meeting (IAEA)","url":"https://www.iaea.org/sites/default/files/cns-10th-review-meeing-uae-national-report_ae1.pdf","as_of":"2026-10-08"}]'::jsonb)
insert into kafaa_leadership_behaviours (id, form_from, sort, trait_id, title_en, title_ar, short_en, short_ar, statement_en, statement_ar, framework_en, framework_ar, anchors, coach, links, programme_ids, benchmark_ids, sources) values
('b-safety-values', 1, 10, 'trait-4', 'Safety values and actions', 'قيم السلامة وأفعالها', 'Safety values', 'قيم السلامة', 'Puts nuclear safety first in words and decisions, even under schedule pressure.', 'يضع السلامة النووية أولاً في الأقوال والقرارات حتى تحت ضغط الجدول.', 'INPO 12-012 safety-culture trait 4: leadership safety values and actions', 'سمة ثقافة السلامة 4 في INPO 12-012: قيم السلامة القيادية وأفعالها', '{"1":{"en":"Lets schedule or cost pressure override safety in words or decisions.","ar":"يسمح لضغط الجدول أو التكلفة بأن يتقدّم على السلامة في الأقوال أو القرارات."},"2":{"en":"Talks about safety but sends mixed signals when the work is behind.","ar":"يتحدث عن السلامة لكنه يرسل إشارات متضاربة عندما يتأخر العمل."},"3":{"en":"Puts safety first in briefs and decisions, including under schedule pressure.","ar":"يضع السلامة أولاً في الإحاطات والقرارات، حتى تحت ضغط الجدول."},"4":{"en":"Visibly stops or slows work for safety and explains why to the team.","ar":"يوقف العمل أو يبطئه علناً من أجل السلامة ويشرح السبب للفريق."},"5":{"en":"Sets the standard across teams; others quote their safety decisions as examples.","ar":"يضع المعيار عبر الفرق، ويستشهد الآخرون بقراراته المتعلقة بالسلامة كأمثلة."}}'::jsonb, '{"tips":[{"en":"Open your next brief with the one thing that must not be traded for time.","ar":"افتتح إحاطتك القادمة بالأمر الوحيد الذي لا يجوز التنازل عنه مقابل الوقت."},{"en":"When you slow a job for safety, say so out loud and say why.","ar":"عندما تبطئ عملاً من أجل السلامة، قل ذلك بصوت مسموع واذكر السبب."}],"practice":{"en":"This week: ask your team which pressure most often competes with safety, and agree one response.","ar":"هذا الأسبوع: اسأل فريقك عن أكثر ضغط يتنافس مع السلامة، واتفقوا على استجابة واحدة."},"watch":{"en":"Silence under schedule pressure reads as permission.","ar":"الصمت تحت ضغط الجدول يُفهم كإذن."}}'::jsonb, '[{"to":"/safety-culture","label_en":"Safety culture traits","label_ar":"سمات ثقافة السلامة"},{"to":"/my/safety-culture","label_en":"My safety culture","label_ar":"ثقافة السلامة لديّ"}]'::jsonb, array['prog-cld','prog-fas','prog-future-leaders','prog-inpo','prog-intilaqa','prog-let','prog-masterclass','prog-one']::text[], '{}'::text[], '[]'::jsonb),
('b-accountability', 1, 20, 'trait-1', 'Personal accountability', 'المساءلة الشخصية', 'Accountability', 'المساءلة', 'Owns outcomes, follows through and holds the standard for themselves first.', 'يتحمل مسؤولية النتائج ويتابع حتى النهاية ويلتزم بالمعيار بنفسه أولاً.', 'INPO 12-012 safety-culture trait 1: personal accountability', 'سمة ثقافة السلامة 1 في INPO 12-012: المساءلة الشخصية', '{"1":{"en":"Blames others or circumstances when things go wrong.","ar":"يلوم الآخرين أو الظروف عندما تسوء الأمور."},"2":{"en":"Owns their own tasks but not the outcome for the team.","ar":"يتحمل مسؤولية مهامه لكن لا يتحمل نتيجة الفريق."},"3":{"en":"Owns outcomes, follows through on commitments and holds themselves to the standard.","ar":"يتحمل مسؤولية النتائج ويفي بالتزاماته ويلتزم بالمعيار بنفسه."},"4":{"en":"Admits mistakes openly and fixes the system, not just the symptom.","ar":"يعترف بالأخطاء علناً ويصلح النظام لا العَرَض فقط."},"5":{"en":"Builds a team where everyone owns the standard without being told.","ar":"يبني فريقاً يتحمل فيه الجميع مسؤولية المعيار دون توجيه."}}'::jsonb, '{"tips":[{"en":"Close every commitment you make in a meeting: done, changed or dropped, and tell people which.","ar":"أغلق كل التزام تقطعه في اجتماع: أُنجز أو تغيّر أو أُلغي، وأخبر الناس بذلك."},{"en":"Name your own part first in any post-job review.","ar":"اذكر دورك أنت أولاً في أي مراجعة بعد العمل."}],"practice":{"en":"This week: list three open commitments and close one with the people who depend on it.","ar":"هذا الأسبوع: اكتب ثلاثة التزامات مفتوحة وأغلق واحداً منها مع من يعتمدون عليه."},"watch":{"en":"Accountability is not blame: fix the system as well as the slip.","ar":"المساءلة ليست لوماً: أصلح النظام إلى جانب الخطأ."}}'::jsonb, '[{"to":"/safety-culture","label_en":"Safety culture traits","label_ar":"سمات ثقافة السلامة"}]'::jsonb, array['prog-estadad','prog-exec-coaching','prog-hipo-coaching']::text[], '{}'::text[], '[]'::jsonb),
('b-questioning', 1, 30, 'trait-2', 'Questioning attitude', 'الموقف التساؤلي', 'Questioning', 'التساؤل', 'Challenges assumptions and stops when unsure; invites others to do the same.', 'يتحدى الافتراضات ويتوقف عند الشك ويدعو الآخرين إلى فعل ذلك.', 'INPO 12-012 safety-culture trait 2: questioning attitude', 'سمة ثقافة السلامة 2 في INPO 12-012: الموقف التساؤلي', '{"1":{"en":"Proceeds on assumptions and discourages questions.","ar":"يمضي بناءً على افتراضات ويثبّط الأسئلة."},"2":{"en":"Asks questions when prompted; rarely stops when unsure.","ar":"يسأل عند التنبيه، ونادراً ما يتوقف عند الشك."},"3":{"en":"Challenges assumptions and stops when unsure.","ar":"يتحدى الافتراضات ويتوقف عند الشك."},"4":{"en":"Invites challenge from the team and thanks people who stop the job.","ar":"يدعو الفريق إلى التحدي ويشكر من يوقف العمل."},"5":{"en":"Makes a questioning attitude a team habit that others learn from.","ar":"يجعل الموقف التساؤلي عادة لدى الفريق يتعلم منها الآخرون."}}'::jsonb, '{"tips":[{"en":"Ask \"what would make this go wrong?\" before every non-routine task.","ar":"اسأل \"ما الذي قد يجعل هذا يسوء؟\" قبل كل مهمة غير اعتيادية."},{"en":"Thank the first person who stops a job, even when the job was fine.","ar":"اشكر أول من يوقف العمل، حتى لو كان العمل سليماً."}],"practice":{"en":"This week: in one brief, ask the most junior person for the risk they see first.","ar":"هذا الأسبوع: في إحاطة واحدة، اسأل أحدث الحاضرين أولاً عن الخطر الذي يراه."},"watch":{"en":"Familiar tasks are where assumptions hide.","ar":"المهام المألوفة هي حيث تختبئ الافتراضات."}}'::jsonb, '[{"to":"/safety-culture","label_en":"Safety culture traits","label_ar":"سمات ثقافة السلامة"},{"to":"/my/ai-fluency/drills","label_en":"Governed AI drills","label_ar":"تمارين الذكاء الاصطناعي المنضبطة"}]'::jsonb, '{}'::text[], '{}'::text[], '[]'::jsonb),
('b-communication', 1, 40, 'trait-3', 'Effective safety communication', 'التواصل الفعّال بشأن السلامة', 'Communication', 'التواصل', 'Communicates clearly and checks understanding, in briefs and turnovers.', 'يتواصل بوضوح ويتحقق من الفهم في الإحاطات وتسليم الورديات.', 'INPO 12-012 safety-culture trait 3: effective safety communication', 'سمة ثقافة السلامة 3 في INPO 12-012: التواصل الفعّال بشأن السلامة', '{"1":{"en":"Briefs are unclear or skipped, and understanding is not checked.","ar":"الإحاطات غير واضحة أو تُتخطّى، ولا يُتحقق من الفهم."},"2":{"en":"Communicates the basics but rarely checks understanding.","ar":"يوصل الأساسيات لكنه نادراً ما يتحقق من الفهم."},"3":{"en":"Communicates clearly and checks understanding in briefs and turnovers.","ar":"يتواصل بوضوح ويتحقق من الفهم في الإحاطات وتسليم الورديات."},"4":{"en":"Uses three-way communication and adapts the message to the audience.","ar":"يستخدم التواصل الثلاثي ويكيّف الرسالة مع الجمهور."},"5":{"en":"Coaches others on safety communication; their team''s turnovers are a model.","ar":"يدرّب الآخرين على التواصل بشأن السلامة، وتسليم ورديات فريقه نموذج يُحتذى."}}'::jsonb, '{"tips":[{"en":"End each brief by asking one person to repeat the key risk in their own words.","ar":"اختم كل إحاطة بأن تطلب من شخص إعادة الخطر الرئيسي بكلماته."},{"en":"Use the same turnover structure every shift so gaps stand out.","ar":"استخدم بنية التسليم نفسها في كل وردية حتى تظهر الفجوات."}],"practice":{"en":"This week: observe one turnover and give the pair one piece of specific feedback.","ar":"هذا الأسبوع: راقب تسليماً واحداً وقدّم للطرفين ملاحظة محددة واحدة."},"watch":{"en":"A nod is not confirmation.","ar":"الإيماءة ليست تأكيداً."}}'::jsonb, '[{"to":"/safety-culture","label_en":"Safety culture traits","label_ar":"سمات ثقافة السلامة"}]'::jsonb, array['prog-estadad','prog-intilaqa','prog-let']::text[], '{}'::text[], '[]'::jsonb),
('b-decisions', 1, 50, 'trait-5', 'Conservative decision-making', 'اتخاذ القرار المتحفظ', 'Decisions', 'القرارات', 'Makes decisions that are systematic, conservative and explained to the team.', 'يتخذ قرارات منهجية ومتحفظة ويشرحها للفريق.', 'INPO 12-012 safety-culture trait 5: decision-making', 'سمة ثقافة السلامة 5 في INPO 12-012: اتخاذ القرار', '{"1":{"en":"Makes quick decisions without considering the margin to safety.","ar":"يتخذ قرارات سريعة دون مراعاة هامش السلامة."},"2":{"en":"Considers risk but rarely explains the decision.","ar":"يراعي المخاطر لكنه نادراً ما يشرح القرار."},"3":{"en":"Makes systematic, conservative decisions and explains them to the team.","ar":"يتخذ قرارات منهجية ومتحفظة ويشرحها للفريق."},"4":{"en":"Seeks other views before deciding and chooses the safer path under uncertainty.","ar":"يستطلع آراء أخرى قبل القرار ويختار المسار الأكثر أماناً عند عدم اليقين."},"5":{"en":"Others seek them out for difficult decisions, and their decisions are reviewed and learned from.","ar":"يلجأ إليه الآخرون في القرارات الصعبة، وتُراجَع قراراته ويُتعلَّم منها."}}'::jsonb, '{"tips":[{"en":"Say what you do not know before you decide.","ar":"قل ما لا تعرفه قبل أن تقرر."},{"en":"When two options look equal, pick the one that keeps more margin and say so.","ar":"عندما يبدو خياران متساويين، اختر الذي يحافظ على هامش أكبر وصرّح بذلك."}],"practice":{"en":"This week: write down one recent decision, the options you rejected and why; share it with your team.","ar":"هذا الأسبوع: دوّن قراراً حديثاً والخيارات التي رفضتها وسبب ذلك، وشاركه مع فريقك."},"watch":{"en":"Confidence is not evidence.","ar":"الثقة ليست دليلاً."}}'::jsonb, '[{"to":"/safety-culture","label_en":"Safety culture traits","label_ar":"سمات ثقافة السلامة"}]'::jsonb, array['prog-exec-coaching','prog-inpo','prog-let']::text[], '{}'::text[], '[]'::jsonb),
('b-respect', 1, 60, 'trait-6', 'Respectful work environment', 'بيئة عمل محترمة', 'Respect', 'الاحترام', 'Treats people with dignity and builds trust across teams.', 'يعامل الناس بكرامة ويبني الثقة بين الفرق.', 'INPO 12-012 safety-culture trait 6: respectful work environment', 'سمة ثقافة السلامة 6 في INPO 12-012: بيئة عمل محترمة', '{"1":{"en":"Dismisses or embarrasses people.","ar":"يتجاهل الآخرين أو يحرجهم."},"2":{"en":"Polite, but trust stays low across teams.","ar":"مهذب، لكن الثقة بين الفرق تبقى منخفضة."},"3":{"en":"Treats people with dignity and builds trust across teams.","ar":"يعامل الناس بكرامة ويبني الثقة بين الفرق."},"4":{"en":"Resolves conflict fairly and recognises others'' contributions.","ar":"يحل الخلافات بإنصاف ويقدّر مساهمات الآخرين."},"5":{"en":"Creates a climate of trust that people describe as a reason to stay.","ar":"يخلق مناخاً من الثقة يصفه الناس بأنه سبب للبقاء."}}'::jsonb, '{"tips":[{"en":"Recognise one specific contribution in public each week.","ar":"قدّر مساهمة محددة علناً كل أسبوع."},{"en":"Deal with disrespect the same day, in private.","ar":"تعامل مع عدم الاحترام في اليوم نفسه وعلى انفراد."}],"practice":{"en":"This week: thank a colleague from another team for something that helped yours.","ar":"هذا الأسبوع: اشكر زميلاً من فريق آخر على أمر ساعد فريقك."},"watch":{"en":"Jokes at someone''s expense close mouths.","ar":"النكات على حساب الآخرين تُسكت الأفواه."}}'::jsonb, '[{"to":"/safety-culture","label_en":"Safety culture traits","label_ar":"سمات ثقافة السلامة"}]'::jsonb, array['prog-intilaqa','prog-masterclass','prog-one']::text[], '{}'::text[], '[]'::jsonb),
('b-learning', 1, 70, 'trait-7', 'Continuous learning', 'التعلم المستمر', 'Learning', 'التعلم', 'Seeks feedback, learns from experience and develops others.', 'يسعى إلى الملاحظات ويتعلم من التجربة ويطوّر الآخرين.', 'INPO 12-012 safety-culture trait 7: continuous learning', 'سمة ثقافة السلامة 7 في INPO 12-012: التعلم المستمر', '{"1":{"en":"Avoids feedback and repeats the same mistakes.","ar":"يتجنب الملاحظات ويكرر الأخطاء نفسها."},"2":{"en":"Accepts feedback when given; learning stays personal.","ar":"يقبل الملاحظات عندما تُقدَّم، ويبقى التعلم شخصياً."},"3":{"en":"Seeks feedback, learns from experience and develops others.","ar":"يسعى إلى الملاحظات ويتعلم من التجربة ويطوّر الآخرين."},"4":{"en":"Uses operating experience to change how the team works.","ar":"يستخدم الخبرة التشغيلية لتغيير طريقة عمل الفريق."},"5":{"en":"Builds a learning organisation: lessons spread beyond their own team.","ar":"يبني مؤسسة متعلمة تنتشر فيها الدروس خارج فريقه."}}'::jsonb, '{"tips":[{"en":"Ask for one piece of feedback after every significant task.","ar":"اطلب ملاحظة واحدة بعد كل مهمة مهمة."},{"en":"Share one operating-experience lesson in each team meeting.","ar":"شارك درساً واحداً من الخبرة التشغيلية في كل اجتماع للفريق."}],"practice":{"en":"This week: pick one lesson from operating experience and change one thing your team does.","ar":"هذا الأسبوع: اختر درساً من الخبرة التشغيلية وغيّر أمراً واحداً يفعله فريقك."},"watch":{"en":"Learning that is not shared is lost at the next shift change.","ar":"التعلم الذي لا يُشارك يضيع عند تغيير الوردية التالي."}}'::jsonb, '[{"to":"/safety-culture","label_en":"Safety culture traits","label_ar":"سمات ثقافة السلامة"},{"to":"/knowledge","label_en":"Knowledge library","label_ar":"مكتبة المعرفة"}]'::jsonb, array['prog-cld','prog-estadad','prog-hipo-coaching','prog-mentoring','prog-one']::text[], '{}'::text[], '[]'::jsonb),
('b-concerns', 1, 80, 'trait-9', 'Environment for raising concerns', 'بيئة طرح المخاوف', 'Raising concerns', 'طرح المخاوف', 'Makes it easy and safe for anyone to raise a concern, and acts on it.', 'يجعل طرح المخاوف سهلاً وآمناً للجميع ويتصرف بناءً عليها.', 'INPO 12-012 safety-culture trait 9: environment for raising concerns', 'سمة ثقافة السلامة 9 في INPO 12-012: بيئة طرح المخاوف', '{"1":{"en":"People hesitate to raise concerns with them.","ar":"يتردد الناس في طرح مخاوفهم عليه."},"2":{"en":"Listens to concerns but rarely closes the loop.","ar":"يستمع إلى المخاوف لكنه نادراً ما يعود إلى صاحبها بما تم."},"3":{"en":"Makes it easy and safe to raise a concern, and acts on it.","ar":"يجعل طرح المخاوف سهلاً وآمناً ويتصرف بناءً عليها."},"4":{"en":"Thanks people for concerns, reports back on actions and protects them from blame.","ar":"يشكر من يطرح المخاوف ويبلغهم بالإجراءات ويحميهم من اللوم."},"5":{"en":"Concerns are raised early across the area because people trust the response.","ar":"تُطرح المخاوف مبكراً في نطاق عمله لأن الناس يثقون بالاستجابة."}}'::jsonb, '{"tips":[{"en":"Report back on every concern within a week, even if the answer is \"not yet\".","ar":"عُد بإجابة عن كل مخوف خلال أسبوع، حتى لو كانت \"ليس بعد\"."},{"en":"Remind the team of every channel, including the confidential one.","ar":"ذكّر الفريق بكل القنوات، بما فيها القناة السرية."}],"practice":{"en":"This week: ask your team what would make raising a concern easier, and act on one answer.","ar":"هذا الأسبوع: اسأل فريقك عما يسهّل طرح المخاوف، ونفّذ إجابة واحدة."},"watch":{"en":"How you react to the first concern decides whether there is a second.","ar":"ردّ فعلك على أول مخوف يحدد ما إذا كان سيأتي ثانٍ."}}'::jsonb, '[{"to":"/safety-culture","label_en":"Safety culture traits","label_ar":"سمات ثقافة السلامة"}]'::jsonb, array['prog-fas','prog-mentoring']::text[], '{}'::text[], '[]'::jsonb),
('b-digital-change', 2, 90, null, 'Leading digital change', 'قيادة التحول الرقمي', 'Digital change', 'التحول الرقمي', 'Explains why a digital change matters for safety and the work, involves the people who will use it, and keeps a proven fallback until the new way works.', 'يشرح لماذا يهم التغيير الرقمي للسلامة وللعمل، ويشرك من سيستخدمونه، ويُبقي بديلاً مجرّباً حتى تثبت الطريقة الجديدة.', 'WEF Future of Jobs 2025: technological literacy is among the fastest-growing skills (per source)', 'تقرير مستقبل الوظائف 2025 للمنتدى الاقتصادي العالمي: الإلمام التقني من أسرع المهارات نمواً (وفق المصدر)', '{"1":{"en":"Avoids or resists digital change and leaves the team to work it out.","ar":"يتجنب التغيير الرقمي أو يقاومه ويترك الفريق ليتدبر أمره."},"2":{"en":"Supports changes others lead but rarely explains them to the team.","ar":"يدعم تغييرات يقودها غيره لكنه نادراً ما يشرحها للفريق."},"3":{"en":"Explains the reason for a change, plans the training and checks that it works in practice.","ar":"يشرح سبب التغيير ويخطط للتدريب ويتحقق من نجاحه عملياً."},"4":{"en":"Involves users early, pilots the change with clear stop criteria and keeps a fallback until it is proven.","ar":"يشرك المستخدمين مبكراً ويجرّب التغيير بمعايير توقف واضحة ويُبقي بديلاً حتى يثبت."},"5":{"en":"Shapes the digital roadmap with the team, measures the benefit for safety and the work, and coaches other leaders to do the same.","ar":"يشكّل خارطة الطريق الرقمية مع الفريق ويقيس الفائدة للسلامة والعمل ويدرّب القادة الآخرين على ذلك."}}'::jsonb, '{"tips":[{"en":"Before a rollout, write one sentence on the problem it solves for the team and one on what will not change.","ar":"قبل أي إطلاق، اكتب جملة عن المشكلة التي يحلها للفريق وجملة عما لن يتغير."},{"en":"Name the fallback: the old route stays until two clean weeks on the new one.","ar":"حدّد البديل: يبقى المسار القديم حتى أسبوعين نظيفين على الجديد."},{"en":"Ask the newest and the most experienced user to test it first, and listen to both.","ar":"اطلب من أحدث مستخدم وأكثرهم خبرة أن يختبراه أولاً، واستمع إلى كليهما."}],"practice":{"en":"This week: run a 15-minute walk-through of one digital tool with your team and capture three questions.","ar":"هذا الأسبوع: قدّم عرضاً لمدة 15 دقيقة لأداة رقمية واحدة مع فريقك ودوّن ثلاثة أسئلة."},"watch":{"en":"Do not measure success by go-live dates alone.","ar":"لا تقِس النجاح بمواعيد الإطلاق وحدها."}}'::jsonb, '[{"to":"/learn/future-skills","label_en":"Future-skills course pack","label_ar":"حزمة دورات المهارات المستقبلية"},{"to":"/my/ai-fluency","label_en":"My AI fluency","label_ar":"طلاقتي في الذكاء الاصطناعي"},{"to":"/opportunities/future","label_en":"Future-skills gigs","label_ar":"مهام المهارات المستقبلية"}]'::jsonb, array['prog-future-leaders']::text[], array['WEF-FOJ']::text[], '[{"label":"WEF · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb),
('b-ai-teams', 2, 100, 'trait-2', 'Leading AI-augmented teams', 'قيادة فرق معززة بالذكاء الاصطناعي', 'AI-augmented teams', 'الفرق المعززة بالذكاء الاصطناعي', 'Sets clear rules for when the team uses approved AI tools, expects outputs to be verified against the controlled source, and backs anyone who overrides a tool when something does not look right.', 'يضع قواعد واضحة لاستخدام الفريق لأدوات الذكاء الاصطناعي المعتمدة، ويتوقع التحقق من المخرجات مقابل المصدر المعتمد، ويساند كل من يتجاوز الأداة عندما يبدو أمر ما غير صحيح.', 'WEF Future of Jobs 2025: AI and big data is the fastest-growing skill (per source); the override rule follows the questioning attitude (INPO 12-012 trait 2)', 'تقرير مستقبل الوظائف 2025: الذكاء الاصطناعي والبيانات الضخمة الأسرع نمواً (وفق المصدر)؛ وقاعدة التجاوز امتداد للموقف التساؤلي (السمة 2 في INPO 12-012)', '{"1":{"en":"Lets people use AI tools without rules, or bans them without explanation.","ar":"يترك الناس يستخدمون أدوات الذكاء الاصطناعي بلا قواعد، أو يمنعها دون تفسير."},"2":{"en":"Knows the approved tools but does not talk about how outputs are checked.","ar":"يعرف الأدوات المعتمدة لكنه لا يتحدث عن كيفية التحقق من المخرجات."},"3":{"en":"Explains which tools are approved for which tasks and expects outputs to be verified against the controlled source.","ar":"يوضح الأدوات المعتمدة لكل مهمة ويتوقع التحقق من المخرجات مقابل المصدر المعتمد."},"4":{"en":"Sets clear override rules: anyone may stop and override a tool that disagrees with indications or procedures, and is thanked for it.","ar":"يضع قواعد تجاوز واضحة: يحق لأي شخص إيقاف الأداة وتجاوزها إذا خالفت المؤشرات أو الإجراءات، ويُشكر على ذلك."},"5":{"en":"Reviews AI-related near misses with the team, feeds lessons into the AI register and coaches others on human oversight.","ar":"يراجع مع الفريق الحوادث الوشيكة المرتبطة بالذكاء الاصطناعي، ويغذي سجل الذكاء الاصطناعي بالدروس، ويدرّب الآخرين على الإشراف البشري."}}'::jsonb, '{"tips":[{"en":"Agree with your team: an AI suggestion never replaces the procedure or the controlled source.","ar":"اتفق مع فريقك: اقتراح الذكاء الاصطناعي لا يحل محل الإجراء أو المصدر المعتمد أبداً."},{"en":"Praise, in front of the team, the first person who overrides a tool for a good reason.","ar":"امدح أمام الفريق أول شخص يتجاوز أداة لسبب وجيه."},{"en":"Review one AI-assisted task a month: what was checked, by whom, and what would have been missed.","ar":"راجع مهمة واحدة بمساعدة الذكاء الاصطناعي كل شهر: ما الذي تم التحقق منه، ومن قام به، وما الذي كان سيفوت."}],"practice":{"en":"This week: do a governed AI drill and talk the planted errors through with your team.","ar":"هذا الأسبوع: أدِّ تمريناً منضبطاً للذكاء الاصطناعي وناقش الأخطاء المزروعة مع فريقك."},"watch":{"en":"Automation bias grows when a tool is usually right.","ar":"يزداد الانحياز للأتمتة عندما تكون الأداة محقة في الغالب."}}'::jsonb, '[{"to":"/my/ai-fluency/drills","label_en":"Governed AI drills","label_ar":"تمارين الذكاء الاصطناعي المنضبطة"},{"to":"/my/ai-fluency","label_en":"My AI fluency","label_ar":"طلاقتي في الذكاء الاصطناعي"},{"to":"/workforce/ai-register","label_en":"AI-literacy register","label_ar":"سجل الإلمام بالذكاء الاصطناعي"}]'::jsonb, array['prog-future-leaders']::text[], array['WEF-FOJ']::text[], '[{"label":"WEF · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"},{"label":"IAEA Bulletin · Enhancing nuclear power production with artificial intelligence","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence","as_of":"2026-10-10"}]'::jsonb),
('b-intrapreneurship', 2, 110, 'trait-8', 'Intrapreneurship', 'روح المبادرة داخل المؤسسة', 'Intrapreneurship', 'المبادرة', 'Spots chances to improve how ENEC works, gathers the resources and allies to test an idea safely, and turns it into action (EntreComp areas: ideas and opportunities, resources, into action).', 'يلتقط فرص تحسين طريقة عمل المؤسسة، ويجمع الموارد والحلفاء لاختبار الفكرة بأمان، ويحوّلها إلى عمل (مجالات EntreComp: الأفكار والفرص، والموارد، والتنفيذ).', 'EntreComp, the JRC framework in the same family as GreenComp and LifeComp (per source)', 'إطار EntreComp من مركز البحوث المشترك، من عائلة GreenComp وLifeComp نفسها (وفق المصدر)', '{"1":{"en":"Rarely suggests improvements and waits to be told.","ar":"نادراً ما يقترح تحسينات وينتظر التوجيه."},"2":{"en":"Shares ideas but does not follow them up.","ar":"يشارك الأفكار لكنه لا يتابعها."},"3":{"en":"Turns an idea into a small, safe trial with a clear owner and a check on the result.","ar":"يحوّل الفكرة إلى تجربة صغيرة وآمنة بمالك واضح وتحقق من النتيجة."},"4":{"en":"Builds a case with data, secures time and allies, and scales ideas that work through the change process.","ar":"يبني حجة بالبيانات ويؤمّن الوقت والحلفاء ويوسّع الأفكار الناجحة عبر عملية التغيير."},"5":{"en":"Creates room for others to experiment safely, sponsors their ideas and shares what failed as well as what worked.","ar":"يتيح للآخرين مساحة للتجريب الآمن ويرعى أفكارهم ويشارك ما فشل وما نجح."}}'::jsonb, '{"tips":[{"en":"Pick one friction in your area and write it as a problem statement, not a solution.","ar":"اختر عائقاً واحداً في نطاقك واكتبه كمشكلة لا كحل."},{"en":"Ask for a time envelope to test it, such as a future-skills gig or a small pilot.","ar":"اطلب نطاقاً زمنياً لاختباره، مثل مهمة مهارات مستقبلية أو تجربة صغيرة."},{"en":"Close the loop: share the result, even when the idea did not work.","ar":"أغلق الحلقة: شارك النتيجة حتى لو لم تنجح الفكرة."}],"practice":{"en":"This week: post an idea as a gig in the digital-innovation channel, or join one.","ar":"هذا الأسبوع: انشر فكرة كمهمة في قناة الابتكار الرقمي، أو انضم إلى إحداها."},"watch":{"en":"Never trial a change on plant equipment outside the formal modification process.","ar":"لا تجرّب أي تغيير على معدات المحطة خارج عملية التعديل الرسمية."}}'::jsonb, '[{"to":"/opportunities/future","label_en":"Future-skills gigs","label_ar":"مهام المهارات المستقبلية"},{"to":"/opportunities/envelope","label_en":"Ask for a time envelope","label_ar":"طلب نطاق زمني"},{"to":"/knowledge/capture","label_en":"Knowledge capture studio","label_ar":"استوديو توثيق المعرفة"}]'::jsonb, array['prog-future-leaders']::text[], array['GREENCOMP']::text[], '[{"label":"EU JRC · GreenComp (with EntreComp and LifeComp)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"}]'::jsonb),
('b-inclusion', 2, 120, 'trait-6', 'Inclusive leadership', 'القيادة الشاملة', 'Inclusion', 'الشمول', 'Makes sure every voice is heard whatever the person''s background, shift, grade or gender, shares opportunities fairly and acts on the barriers people raise.', 'يحرص على سماع كل صوت أياً كانت خلفية الشخص أو ورديته أو درجته أو جنسه، ويوزع الفرص بإنصاف، ويعالج العوائق التي يطرحها الناس.', 'OECD-NEA Plan 2035: mentor and network lanes for the nuclear workforce (per source)', 'خطة 2035 لوكالة الطاقة النووية: مسارا الإرشاد والشبكات للقوى العاملة النووية (وفق المصدر)', '{"1":{"en":"The same few people speak and get the opportunities.","ar":"يتحدث الأشخاص القلائل أنفسهم ويحصلون على الفرص."},"2":{"en":"Is fair when asked but does not notice who is left out.","ar":"منصف عندما يُطلب منه، لكنه لا يلاحظ من يُستبعد."},"3":{"en":"Invites quieter voices in meetings and rotates stretch opportunities across the team.","ar":"يدعو الأصوات الأهدأ في الاجتماعات ويدوّر الفرص التطويرية على الفريق."},"4":{"en":"Checks who gets development and visibility, removes barriers people raise and mentors across backgrounds.","ar":"يتحقق ممن يحصل على التطوير والظهور، ويزيل العوائق المطروحة، ويرشد أشخاصاً من خلفيات مختلفة."},"5":{"en":"Builds a team where people of different backgrounds lead, sponsors under-represented talent and is a role model across ENEC.","ar":"يبني فريقاً يقوده أشخاص من خلفيات مختلفة، ويرعى المواهب الأقل تمثيلاً، ويكون قدوة في المؤسسة."}}'::jsonb, '{"tips":[{"en":"In your next brief, ask the person who has not spoken yet first.","ar":"في إحاطتك القادمة، اسأل أولاً من لم يتحدث بعد."},{"en":"Look at who led the last three stretch tasks and offer the next one to someone else.","ar":"انظر إلى من قاد آخر ثلاث مهام تطويرية واعرض التالية على شخص آخر."},{"en":"Offer to mentor, or sponsor a mentor circle outside your own group.","ar":"تطوّع للإرشاد، أو ارعَ حلقة إرشاد خارج مجموعتك."}],"practice":{"en":"This week: open a mentor circle seat in the women in future nuclear skills network, or ask how to sponsor one.","ar":"هذا الأسبوع: افتح مقعداً في حلقة إرشاد ضمن شبكة المرأة في المهارات النووية المستقبلية، أو اسأل كيف ترعى حلقة."},"watch":{"en":"Inclusion is about access to opportunities, never about scores: no ranking in Kafa''a uses gender or nationality.","ar":"الشمول يتعلق بالوصول إلى الفرص لا بالدرجات: لا يستخدم أي ترتيب في كفاءة الجنس أو الجنسية."}}'::jsonb, '[{"to":"/communities/women-in-nuclear","label_en":"Women in future nuclear skills","label_ar":"المرأة في المهارات النووية المستقبلية"},{"to":"/my/mentoring","label_en":"My mentoring","label_ar":"الإرشاد الخاص بي"}]'::jsonb, array['prog-future-leaders']::text[], array['NEA']::text[], '[{"label":"OECD-NEA · Plan 2035 vision paper (NEST)","url":"https://www.oecd-nea.org/upload/docs/application/pdf/2025-10/plan_2035_-_vision_paper_-_final_version.pdf","as_of":"2026-10-10"}]'::jsonb)
insert into kafaa_fl_competencies (id, code, sort, title_en, title_ar, summary_en, summary_ar, area_en, area_ar, descriptors, skill_targets, route, external_ids, sources) values
('fl-safety-leadership', 'FL-1', 10, 'Safety culture leadership', 'قيادة ثقافة السلامة', 'Leads so that nuclear safety is the overriding priority in decisions, resources and behaviours across an organisation, not only a team.', 'يقود بحيث تكون السلامة النووية الأولوية العليا في القرارات والموارد والسلوكيات على مستوى المؤسسة لا الفريق فقط.', 'Safety and safety culture', 'السلامة وثقافة السلامة', '{"1":{"en":"Explains the safety-culture traits and how leaders influence them.","ar":"يشرح سمات ثقافة السلامة وكيف يؤثر القادة فيها."},"2":{"en":"Uses safety-culture observations and operating experience to set priorities in their own area.","ar":"يستخدم ملاحظات ثقافة السلامة والخبرة التشغيلية لتحديد الأولويات في نطاقه."},"3":{"en":"Balances production, cost and safety openly across functions and makes the trade-offs visible.","ar":"يوازن علناً بين الإنتاج والتكلفة والسلامة عبر الوظائف ويُظهر المفاضلات."},"4":{"en":"Shapes organisation-wide safety-culture improvement and answers to oversight for it.","ar":"يشكّل تحسين ثقافة السلامة على مستوى المؤسسة ويُسأل عنه أمام جهات الإشراف."}}'::jsonb, '{"sk-sc-02":3,"sk-ld-02":3,"sk-sc-01":3}'::jsonb, '[{"kind":"module","ref":"flm-safety","title_en":"Module 1: Leading safety culture","title_ar":"الوحدة 1: قيادة ثقافة السلامة"},{"kind":"programme","ref":"prog-cld","title_en":"Culture of leadership development (academy)","title_ar":"تطوير ثقافة القيادة (الأكاديمية)"},{"kind":"route","ref":"/safety-culture","title_en":"Safety culture traits","title_ar":"سمات ثقافة السلامة"},{"kind":"external","ref":"fx-iaea-nem","title_en":"IAEA School of Nuclear Energy Management","title_ar":"مدرسة إدارة الطاقة النووية التابعة للوكالة"}]'::jsonb, array['fx-iaea-nem']::text[], '[{"label":"IAEA · International Nuclear Management Academy (INMA)","url":"https://www.iaea.org/node/17745","as_of":"2026-10-10","precision":"secondary"}]'::jsonb),
('fl-regulatory', 'FL-2', 20, 'Regulatory affairs literacy', 'الإلمام بالشؤون التنظيمية', 'Understands how the regulator, the licensing basis and international safety standards shape decisions, and works with them early and openly. This is literacy, not a regulatory role.', 'يفهم كيف يشكّل المنظِّم وأساس الترخيص ومعايير السلامة الدولية القرارات، ويتعامل معها مبكراً وبشفافية. هذا إلمام وليس دوراً تنظيمياً.', 'Regulation and licensing', 'التنظيم والترخيص', '{"1":{"en":"Explains, at a high level, the role of the national regulator, licence conditions and the IAEA safety standards.","ar":"يشرح على مستوى عام دور المنظِّم الوطني وشروط الترخيص ومعايير السلامة للوكالة الدولية للطاقة الذرية."},"2":{"en":"Uses the licensing basis and technical specifications correctly when planning work in their area.","ar":"يستخدم أساس الترخيص والمواصفات الفنية بشكل صحيح عند تخطيط العمل في نطاقه."},"3":{"en":"Prepares a change or submission with the licensing team and anticipates the questions it will raise.","ar":"يُعدّ تغييراً أو تقديماً مع فريق الترخيص ويتوقع الأسئلة التي سيثيرها."},"4":{"en":"Leads engagement on new technology, such as SMRs, where the path is still being defined. No deployment decision implied.","ar":"يقود التواصل بشأن التقنيات الجديدة، مثل المفاعلات الصغيرة، حيث ما زال المسار قيد التحديد. لا يُفهم من ذلك أي قرار نشر."}}'::jsonb, '{"sk-ns-02":2,"sk-ns-02-licensing":2,"sk-fs-adv-regulation":1}'::jsonb, '[{"kind":"module","ref":"flm-regulation","title_en":"Module 2: Regulation, licensing and international standards","title_ar":"الوحدة 2: التنظيم والترخيص والمعايير الدولية"},{"kind":"route","ref":"/skills/sk-ns-02-licensing","title_en":"Skill: licensing basis and regulatory submissions","title_ar":"مهارة: أساس الترخيص والتقديمات التنظيمية"},{"kind":"external","ref":"fx-inma","title_en":"INMA-endorsed master''s programmes","title_ar":"برامج الماجستير المعتمدة من INMA"}]'::jsonb, array['fx-inma','fx-nea-nextgen']::text[], '[{"label":"IAEA · International Nuclear Management Academy (INMA)","url":"https://www.iaea.org/node/17745","as_of":"2026-10-10","precision":"secondary"}]'::jsonb),
('fl-project-cost', 'FL-3', 30, 'Project and cost control', 'ضبط المشاريع والتكاليف', 'Plans, estimates and controls projects and outages against scope, schedule, cost and risk, with safety and quality as fixed constraints.', 'يخطط المشاريع والانقطاعات ويقدّرها ويضبطها وفق النطاق والجدول والتكلفة والمخاطر، مع بقاء السلامة والجودة قيوداً ثابتة.', 'Projects, cost and economics', 'المشاريع والتكاليف والاقتصاد', '{"1":{"en":"Reads a project schedule and budget and explains a variance.","ar":"يقرأ جدول المشروع وميزانيته ويشرح أي انحراف."},"2":{"en":"Builds and tracks a work plan with milestones, costs and risks for a small project.","ar":"يبني خطة عمل لمشروع صغير بمعالمها وتكاليفها ومخاطرها ويتابعها."},"3":{"en":"Leads a multi-discipline project or outage scope with earned-value or equivalent controls.","ar":"يقود مشروعاً متعدد التخصصات أو نطاق انقطاع بضوابط القيمة المكتسبة أو ما يعادلها."},"4":{"en":"Owns a portfolio, sets investment priorities and challenges business cases.","ar":"يملك محفظة مشاريع ويحدد أولويات الاستثمار ويتحدى دراسات الجدوى."}}'::jsonb, '{"sk-en-01-project":2,"sk-mp-01-outage":2,"sk-fs-tr-analytical":2}'::jsonb, '[{"kind":"module","ref":"flm-project","title_en":"Module 3: Project, cost and outage economics","title_ar":"الوحدة 3: المشاريع والتكاليف واقتصاديات الانقطاعات"},{"kind":"programme","ref":"prog-one","title_en":"ONE leadership programme (academy)","title_ar":"برنامج ONE القيادي (الأكاديمية)"},{"kind":"route","ref":"/opportunities/future","title_en":"Practise on a future-skills gig","title_ar":"تدرّب عبر مهمة مهارات مستقبلية"}]'::jsonb, array['fx-enen2plus']::text[], '[{"label":"IAEA · International Nuclear Management Academy (INMA)","url":"https://www.iaea.org/node/17745","as_of":"2026-10-10","precision":"secondary"}]'::jsonb),
('fl-stakeholder', 'FL-4', 40, 'Stakeholder and international affairs', 'شؤون أصحاب المصلحة والشؤون الدولية', 'Represents the organisation credibly with communities, partners and international bodies, and explains nuclear energy in plain language.', 'يمثّل المؤسسة بمصداقية أمام المجتمعات والشركاء والهيئات الدولية، ويشرح الطاقة النووية بلغة واضحة.', 'Stakeholders and international affairs', 'أصحاب المصلحة والشؤون الدولية', '{"1":{"en":"Explains the organisation''s role and the basics of nuclear energy to a non-specialist.","ar":"يشرح دور المؤسسة وأساسيات الطاقة النووية لغير المتخصصين."},"2":{"en":"Works effectively with partner organisations and suppliers from other cultures.","ar":"يعمل بفعالية مع الشركاء والموردين من ثقافات أخرى."},"3":{"en":"Represents the organisation in external forums and handles difficult questions calmly.","ar":"يمثّل المؤسسة في المحافل الخارجية ويتعامل مع الأسئلة الصعبة بهدوء."},"4":{"en":"Builds long-term partnerships and contributes to international programmes.","ar":"يبني شراكات طويلة الأمد ويسهم في البرامج الدولية."}}'::jsonb, '{"sk-fs-tr-crosscultural":2,"sk-fs-tr-leadership":2,"sk-fs-tr-empathy":2}'::jsonb, '[{"kind":"module","ref":"flm-stakeholder","title_en":"Module 4: Stakeholders, public communication and international affairs","title_ar":"الوحدة 4: أصحاب المصلحة والتواصل العام والشؤون الدولية"},{"kind":"external","ref":"fx-nea-nextgen","title_en":"NEA NextGen Nuclear Leaders Summer School","title_ar":"المدرسة الصيفية لقادة الجيل القادم النوويين (NEA)"},{"kind":"route","ref":"/communities","title_en":"Communities of practice","title_ar":"مجتمعات الممارسة"}]'::jsonb, array['fx-nea-nextgen','fx-kings']::text[], '[{"label":"OECD-NEA · NextGen Nuclear Leaders Summer School 2026, final programme (PDF)","url":"https://oecd-nea.org/upload/docs/application/pdf/2026-07/nextgen_nuclear_leaders_summer_school_2026_final_programme.pdf","as_of":"2026-10-10","precision":"secondary"}]'::jsonb),
('fl-knowledge', 'FL-5', 50, 'Knowledge management', 'إدارة المعرفة', 'Treats nuclear knowledge as an asset: finds what is critical, makes sure it is captured and passed on, and plans for succession.', 'يتعامل مع المعرفة النووية كأصل: يحدد ما هو حرج ويضمن توثيقه ونقله ويخطط للتعاقب.', 'Knowledge management', 'إدارة المعرفة', '{"1":{"en":"Explains why knowledge loss is a safety and business risk.","ar":"يشرح لماذا يمثّل فقدان المعرفة خطراً على السلامة والأعمال."},"2":{"en":"Captures and shares their own critical knowledge with approved methods.","ar":"يوثّق معرفته الحرجة ويشاركها بالطرق المعتمدة."},"3":{"en":"Runs knowledge-loss assessments and capture plans for a team.","ar":"يجري تقييمات فقدان المعرفة وخطط التوثيق لفريق."},"4":{"en":"Sets knowledge strategy and succession for a function.","ar":"يضع استراتيجية المعرفة والتعاقب لوظيفة كاملة."}}'::jsonb, '{"sk-ld-01-coach":3,"sk-fs-tr-curiosity":2,"sk-ld-01-instruct":2}'::jsonb, '[{"kind":"module","ref":"flm-knowledge","title_en":"Module 5: Knowledge management and succession","title_ar":"الوحدة 5: إدارة المعرفة والتعاقب"},{"kind":"route","ref":"/knowledge/capture","title_en":"Knowledge capture studio","title_ar":"استوديو توثيق المعرفة"},{"kind":"route","ref":"/knowledge","title_en":"Knowledge library","title_ar":"مكتبة المعرفة"}]'::jsonb, array['fx-iaea-nem']::text[], '[{"label":"IAEA · International Nuclear Management Academy (INMA)","url":"https://www.iaea.org/node/17745","as_of":"2026-10-10","precision":"secondary"}]'::jsonb)
insert into kafaa_fl_external (id, kind, sort, owner_en, owner_ar, title_en, title_ar, summary_en, summary_ar, dates_en, dates_ar, year_from, year_to, competency_ids, sources) values
('fx-nea-nextgen', 'summer_school', 10, 'OECD Nuclear Energy Agency (NEA)', 'وكالة الطاقة النووية التابعة لمنظمة التعاون الاقتصادي والتنمية', 'NextGen Nuclear Leaders Summer School', 'المدرسة الصيفية لقادة الجيل القادم النوويين', 'The NEA''s flagship summer school for the next generation of nuclear leaders, convened through its Global Forum on Nuclear Education, Science, Technology and Policy.', 'المدرسة الصيفية الرئيسية للوكالة لقادة الجيل القادم، تُعقد عبر منتداها العالمي للتعليم والعلوم والتكنولوجيا والسياسات النووية.', '2026 programme published', 'نُشر برنامج 2026', 2026, 2026, array['fl-stakeholder','fl-regulatory']::text[], '[{"label":"OECD-NEA · NextGen Nuclear Leaders Summer School 2026, final programme (PDF)","url":"https://oecd-nea.org/upload/docs/application/pdf/2026-07/nextgen_nuclear_leaders_summer_school_2026_final_programme.pdf","as_of":"2026-10-10","precision":"secondary"}]'::jsonb),
('fx-iaea-nem', 'school', 20, 'International Atomic Energy Agency (IAEA)', 'الوكالة الدولية للطاقة الذرية', 'IAEA School of Nuclear Energy Management', 'مدرسة إدارة الطاقة النووية التابعة للوكالة الدولية للطاقة الذرية', 'For young professionals in Member States planning or starting nuclear power programmes; the Japan-hosted Nuclear Energy Management programme serves as a practicum component of INMA.', 'للمهنيين الشباب في الدول الأعضاء التي تخطط لبرامج القوى النووية أو تبدأها؛ ويُعد برنامج إدارة الطاقة النووية الذي تستضيفه اليابان مكوّناً تطبيقياً ضمن أكاديمية INMA.', 'Recurring school (see the source for current dates)', 'مدرسة دورية (راجع المصدر للمواعيد الحالية)', null, null, array['fl-safety-leadership','fl-knowledge']::text[], '[{"label":"IAEA · International Nuclear Management Academy (INMA)","url":"https://www.iaea.org/node/17745","as_of":"2026-10-10","precision":"secondary"}]'::jsonb),
('fx-inma', 'masters', 30, 'IAEA International Nuclear Management Academy (INMA)', 'الأكاديمية الدولية للإدارة النووية (INMA) التابعة للوكالة', 'INMA-endorsed master''s programmes in nuclear technology management', 'برامج ماجستير إدارة التكنولوجيا النووية المعتمدة من INMA', 'INMA endorses university master''s programmes in nuclear technology management against an IAEA competency model; about 10 universities are reported, and Sofia University was endorsed in early 2025.', 'تعتمد INMA برامج ماجستير جامعية في إدارة التكنولوجيا النووية وفق نموذج كفاءات للوكالة؛ ويُذكر نحو 10 جامعات، واعتُمدت جامعة صوفيا مطلع 2025.', 'Endorsements continue; Sofia University endorsed early 2025', 'الاعتمادات مستمرة؛ اعتُمدت جامعة صوفيا مطلع 2025', 2025, null, array['fl-regulatory','fl-project-cost','fl-knowledge']::text[], '[{"label":"IAEA · International Nuclear Management Academy (INMA)","url":"https://www.iaea.org/node/17745","as_of":"2026-10-10","precision":"secondary"},{"label":"Sofia University · INMA endorsement (early 2025)","url":"https://phys.uni-sofia.bg/?p=28612","as_of":"2026-10-10","precision":"secondary"},{"label":"MEPhI · nuclear technology management graduates","url":"https://eng.mephi.ru/news/120165","as_of":"2026-10-10","precision":"secondary"}]'::jsonb),
('fx-cnnems', 'school', 40, 'University of Saskatchewan (IAEA-led)', 'جامعة ساسكاتشوان (بقيادة الوكالة)', 'Canadian National Nuclear Energy Management School', 'المدرسة الوطنية الكندية لإدارة الطاقة النووية', 'An IAEA-led nuclear energy management school hosted by the University of Saskatchewan.', 'مدرسة لإدارة الطاقة النووية بقيادة الوكالة تستضيفها جامعة ساسكاتشوان.', 'Reported November 2025', 'وردت في نوفمبر 2025', 2025, null, array['fl-safety-leadership','fl-project-cost']::text[], '[{"label":"ANS Nuclear Newswire · Education and training to support the Canadian nuclear workforce (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10","precision":"secondary"}]'::jsonb),
('fx-enen2plus', 'mobility', 50, 'European Nuclear Education Network (ENEN)', 'الشبكة الأوروبية للتعليم النووي (ENEN)', 'ENEN2plus mobility grants', 'منح التنقل ENEN2plus', 'Lump-sum grants paid to the learner for internships, on-the-job training, exchanges, conferences and courses; open to students and early-career professionals with up to 10 years'' experience, with deadlines every 2 months.', 'منح مقطوعة تُدفع للمتعلم لقاء التدريب الداخلي والتدريب أثناء العمل والتبادل والمؤتمرات والدورات؛ متاحة للطلاب والمهنيين في بداية مسيرتهم بخبرة حتى 10 سنوات، ومواعيد التقديم كل شهرين.', 'June 2022 to May 2026 (CORDIS 101061677)', 'من يونيو 2022 إلى مايو 2026 (CORDIS 101061677)', 2022, 2026, array['fl-project-cost','fl-stakeholder']::text[], '[{"label":"CORDIS · ENEN2plus project 101061677","url":"https://cordis.europa.eu/project/id/101061677","as_of":"2026-10-10","precision":"secondary"}]'::jsonb),
('fx-nntp', 'trainee', 60, 'Fortum, TVO, Uniper and Vattenfall', 'فورتوم وTVO ويونيبر وفاتنفال', 'Nordic Nuclear Trainee Programme', 'برنامج المتدربين النوويين الشمالي', 'A trainee programme run jointly by four operators: six in-person modules of three days with site visits, a project assignment and mentoring. Its module, project and mentor triad is the pattern for this track.', 'برنامج متدربين يديره أربعة مشغّلين معاً: ست وحدات حضورية مدة كل منها ثلاثة أيام مع زيارات ميدانية ومشروع وإرشاد. وثلاثية الوحدة والمشروع والمرشد هي نمط هذا المسار.', 'Launched 2019; fourth round January to December 2027', 'أُطلق في 2019؛ الجولة الرابعة من يناير إلى ديسمبر 2027', 2019, 2027, array['fl-safety-leadership','fl-knowledge']::text[], '[{"label":"Fortum · Nordic Nuclear Trainee Programme","url":"https://www.fortum.com/careers/NNTP","as_of":"2026-10-10","precision":"secondary"}]'::jsonb),
('fx-kings', 'internship', 70, 'KEPCO International Nuclear Graduate School (KINGS)', 'كلية كيبكو الدولية للدراسات العليا النووية (KINGS)', 'KINGS master''s and the ENEC internship in Korea', 'ماجستير KINGS وبرنامج التدريب الداخلي في كوريا', 'KINGS was established in 2012 with a two-year master''s accredited by Korea''s Ministry of Education; ENEC''s internship with KINGS ran a second edition from 2016 with a first batch of 10 Emirati students.', 'تأسست KINGS في 2012 ببرنامج ماجستير لمدة عامين معتمد من وزارة التعليم الكورية؛ ونُظمت النسخة الثانية من برنامج التدريب الداخلي مع KINGS منذ 2016 بدفعة أولى من 10 طلاب إماراتيين.', 'Established 2012; internship edition from 2016 (historical)', 'تأسست 2012؛ نسخة التدريب منذ 2016 (تاريخي)', 2012, null, array['fl-stakeholder']::text[], '[{"label":"ENEC · Emirati students participate in ENEC internship program in South Korea","url":"https://www.enec.gov.ae/news/latest-news/emirati-students-participate-in-enec-internship-program-in-south-korea","as_of":"2026-10-10","precision":"secondary"}]'::jsonb)
insert into kafaa_fl_cohorts (id, code, year, status, seats, starts_on, ends_on, title_en, title_ar, modules, brief_en, brief_ar, mentor_en, mentor_ar, sort) values
('flc-2025', 'FL-2025', 2025, 'completed', 8, '2024-10-01', '2025-06-30', 'Future Leaders pilot cohort 2025', 'الدفعة التجريبية لقادة المستقبل 2025', '[{"id":"flm-safety","title_en":"Leading safety culture","title_ar":"قيادة ثقافة السلامة","format_en":"Three days with a site visit","format_ar":"ثلاثة أيام مع زيارة ميدانية","weeks":6,"competency_ids":["fl-safety-leadership"]},{"id":"flm-regulation","title_en":"Regulation, licensing and international standards","title_ar":"التنظيم والترخيص والمعايير الدولية","format_en":"Three days with the licensing team","format_ar":"ثلاثة أيام مع فريق الترخيص","weeks":6,"competency_ids":["fl-regulatory"]},{"id":"flm-project","title_en":"Project, cost and outage economics","title_ar":"المشاريع والتكاليف واقتصاديات الانقطاعات","format_en":"Three days with a case study","format_ar":"ثلاثة أيام مع دراسة حالة","weeks":6,"competency_ids":["fl-project-cost"]},{"id":"flm-stakeholder","title_en":"Stakeholders, public communication and international affairs","title_ar":"أصحاب المصلحة والتواصل العام والشؤون الدولية","format_en":"Three days with a media exercise","format_ar":"ثلاثة أيام مع تمرين إعلامي","weeks":6,"competency_ids":["fl-stakeholder"]},{"id":"flm-knowledge","title_en":"Knowledge management and succession","title_ar":"إدارة المعرفة والتعاقب","format_en":"Three days with a capture interview","format_ar":"ثلاثة أيام مع مقابلة توثيق","weeks":6,"competency_ids":["fl-knowledge"]},{"id":"flm-future","title_en":"Leading the future plant: digital change, AI-augmented teams and new reactors","title_ar":"قيادة محطة المستقبل: التحول الرقمي والفرق المعززة بالذكاء الاصطناعي والمفاعلات الجديدة","format_en":"Three days with a governed AI drill and the 360 (form 2)","format_ar":"ثلاثة أيام مع تمرين ذكاء اصطناعي منضبط وتقييم 360 (النموذج 2)","weeks":6,"competency_ids":["fl-safety-leadership","fl-regulatory"]}]'::jsonb, 'Each participant writes a short policy paper on a question an executive sponsors (for example, how a future fleet would change workforce planning). Concept work: no deployment decision implied.', 'يكتب كل مشارك ورقة سياسات قصيرة حول سؤال يرعاه أحد التنفيذيين (مثل كيف سيغيّر أسطول مستقبلي تخطيط القوى العاملة). عمل مفاهيمي: لا يُفهم منه أي قرار نشر.', 'Each participant has a senior leader as mentor (role card) for the year.', 'لكل مشارك مرشد من كبار القادة (بطاقة دور) طوال العام.', 10),
('flc-2026', 'FL-2026', 2026, 'running', 12, '2026-09-01', '2027-06-30', 'Future Leaders cohort 2026', 'دفعة قادة المستقبل 2026', '[{"id":"flm-safety","title_en":"Leading safety culture","title_ar":"قيادة ثقافة السلامة","format_en":"Three days with a site visit","format_ar":"ثلاثة أيام مع زيارة ميدانية","weeks":6,"competency_ids":["fl-safety-leadership"]},{"id":"flm-regulation","title_en":"Regulation, licensing and international standards","title_ar":"التنظيم والترخيص والمعايير الدولية","format_en":"Three days with the licensing team","format_ar":"ثلاثة أيام مع فريق الترخيص","weeks":6,"competency_ids":["fl-regulatory"]},{"id":"flm-project","title_en":"Project, cost and outage economics","title_ar":"المشاريع والتكاليف واقتصاديات الانقطاعات","format_en":"Three days with a case study","format_ar":"ثلاثة أيام مع دراسة حالة","weeks":6,"competency_ids":["fl-project-cost"]},{"id":"flm-stakeholder","title_en":"Stakeholders, public communication and international affairs","title_ar":"أصحاب المصلحة والتواصل العام والشؤون الدولية","format_en":"Three days with a media exercise","format_ar":"ثلاثة أيام مع تمرين إعلامي","weeks":6,"competency_ids":["fl-stakeholder"]},{"id":"flm-knowledge","title_en":"Knowledge management and succession","title_ar":"إدارة المعرفة والتعاقب","format_en":"Three days with a capture interview","format_ar":"ثلاثة أيام مع مقابلة توثيق","weeks":6,"competency_ids":["fl-knowledge"]},{"id":"flm-future","title_en":"Leading the future plant: digital change, AI-augmented teams and new reactors","title_ar":"قيادة محطة المستقبل: التحول الرقمي والفرق المعززة بالذكاء الاصطناعي والمفاعلات الجديدة","format_en":"Three days with a governed AI drill and the 360 (form 2)","format_ar":"ثلاثة أيام مع تمرين ذكاء اصطناعي منضبط وتقييم 360 (النموذج 2)","weeks":6,"competency_ids":["fl-safety-leadership","fl-regulatory"]}]'::jsonb, 'Each participant writes a short policy paper on a question an executive sponsors (for example, how a future fleet would change workforce planning). Concept work: no deployment decision implied.', 'يكتب كل مشارك ورقة سياسات قصيرة حول سؤال يرعاه أحد التنفيذيين (مثل كيف سيغيّر أسطول مستقبلي تخطيط القوى العاملة). عمل مفاهيمي: لا يُفهم منه أي قرار نشر.', 'Each participant has a senior leader as mentor (role card) for the year.', 'لكل مشارك مرشد من كبار القادة (بطاقة دور) طوال العام.', 20),
('flc-2027', 'FL-2027', 2027, 'open', 12, '2027-09-01', '2028-06-30', 'Future Leaders cohort 2027 (nominations open)', 'دفعة قادة المستقبل 2027 (الترشيحات مفتوحة)', '[{"id":"flm-safety","title_en":"Leading safety culture","title_ar":"قيادة ثقافة السلامة","format_en":"Three days with a site visit","format_ar":"ثلاثة أيام مع زيارة ميدانية","weeks":6,"competency_ids":["fl-safety-leadership"]},{"id":"flm-regulation","title_en":"Regulation, licensing and international standards","title_ar":"التنظيم والترخيص والمعايير الدولية","format_en":"Three days with the licensing team","format_ar":"ثلاثة أيام مع فريق الترخيص","weeks":6,"competency_ids":["fl-regulatory"]},{"id":"flm-project","title_en":"Project, cost and outage economics","title_ar":"المشاريع والتكاليف واقتصاديات الانقطاعات","format_en":"Three days with a case study","format_ar":"ثلاثة أيام مع دراسة حالة","weeks":6,"competency_ids":["fl-project-cost"]},{"id":"flm-stakeholder","title_en":"Stakeholders, public communication and international affairs","title_ar":"أصحاب المصلحة والتواصل العام والشؤون الدولية","format_en":"Three days with a media exercise","format_ar":"ثلاثة أيام مع تمرين إعلامي","weeks":6,"competency_ids":["fl-stakeholder"]},{"id":"flm-knowledge","title_en":"Knowledge management and succession","title_ar":"إدارة المعرفة والتعاقب","format_en":"Three days with a capture interview","format_ar":"ثلاثة أيام مع مقابلة توثيق","weeks":6,"competency_ids":["fl-knowledge"]},{"id":"flm-future","title_en":"Leading the future plant: digital change, AI-augmented teams and new reactors","title_ar":"قيادة محطة المستقبل: التحول الرقمي والفرق المعززة بالذكاء الاصطناعي والمفاعلات الجديدة","format_en":"Three days with a governed AI drill and the 360 (form 2)","format_ar":"ثلاثة أيام مع تمرين ذكاء اصطناعي منضبط وتقييم 360 (النموذج 2)","weeks":6,"competency_ids":["fl-safety-leadership","fl-regulatory"]}]'::jsonb, 'Each participant writes a short policy paper on a question an executive sponsors (for example, how a future fleet would change workforce planning). Concept work: no deployment decision implied.', 'يكتب كل مشارك ورقة سياسات قصيرة حول سؤال يرعاه أحد التنفيذيين (مثل كيف سيغيّر أسطول مستقبلي تخطيط القوى العاملة). عمل مفاهيمي: لا يُفهم منه أي قرار نشر.', 'Each participant has a senior leader as mentor (role card) for the year.', 'لكل مشارك مرشد من كبار القادة (بطاقة دور) طوال العام.', 30)
insert into kafaa_fl_participants (id, nomination_id, person_id, cohort_id, person_name, person_name_ar, modules_done, project_title, project_question, project_summary, project_sponsor_role, project_status, project_submitted_on, project_reviewed_by, project_review_note, project_decided_on, status, completed_on, history, updated_at) values
