ئ كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":1},{"skill_id":"sk-fs-dp-dic","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"pathway","ref":"pw-adv-multimodule-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 68, 'p-training-mgr', '2026-10-11T08:00:00Z'),
