insert into kafaa_cec_competences (id, code, area, name_en, name_ar, summary_en, summary_ar, plant_en, plant_ar, outcomes, greencomp_area, skill_ids, learning, jahiz_group, net_zero, benchmark_ids, sources, status, version, as_of, sort) values
('cec-1-1', 'CEC-1.1', 'values', 'Public trust and transparency', 'الثقة العامة والشفافية', 'Explains nuclear energy''s place in a low-carbon energy system honestly, with the evidence and its limits, so people can judge for themselves.', 'يشرح مكانة الطاقة النووية في منظومة طاقة منخفضة الكربون بأمانة، بالأدلة وحدودها، ليحكم الناس بأنفسهم.', 'At a nuclear plant this means answering questions about emissions, safety and waste with sourced facts, never with slogans.', 'في المحطة النووية يعني ذلك الإجابة عن أسئلة الانبعاثات والسلامة والنفايات بحقائق موثّقة المصدر، لا بالشعارات.', '[{"en":"Explain in plain language why nuclear electricity is low-carbon over its lifecycle, and where the evidence comes from.","ar":"يشرح بلغة بسيطة لماذا تُعدّ الكهرباء النووية منخفضة الكربون على امتداد دورة حياتها، ومن أين تأتي الأدلة."},{"en":"Answer a difficult public question about safety or waste with sourced facts, and say what is not known.","ar":"يجيب عن سؤال عام صعب حول السلامة أو النفايات بحقائق موثّقة المصدر، ويذكر ما لا يزال غير معروف."},{"en":"Recognise when a claim about clean energy goes beyond the evidence, and correct it respectfully.","ar":"يتعرّف على الادعاء الذي يتجاوز الأدلة بشأن الطاقة النظيفة ويصححه باحترام."}]'::jsonb, 'embodying_sustainability_values', array['sk-fs-gr-esg','sk-fs-tr-empathy','sk-sc-01']::text[], '[{"kind":"pathway","ref":"pw-gr-esg-l1","title_en":"ESG disclosure literacy: foundations","title_ar":"الإلمام بالإفصاح البيئي والاجتماعي والحوكمي: الأساسيات"},{"kind":"external","ref":"xr-et-greencomp","title_en":"GreenComp: the European sustainability competence framework","title_ar":"إطار \"غرين كومب\": الإطار الأوروبي لكفاءات الاستدامة"},{"kind":"course","ref":"c-fs-ghg","title_en":"GHG accounting basics","title_ar":"أساسيات محاسبة غازات الدفيئة"}]'::jsonb, 'new_economy', true, array['GREENCOMP','WEF-FOJ','JAHIZ']::text[], '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","as_of":"2026-10-10"},{"id":"fs41-jahiz","label":"WAM · Jahiz, the UAE platform upskilling federal government talent with future skills (Nov 2022)","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 1),
('cec-1-2', 'CEC-1.2', 'values', 'Stewardship of people and the environment', 'رعاية الناس والبيئة', 'Treats protecting people and the environment as part of the job, from radiation protection to effluent monitoring.', 'يعدّ حماية الناس والبيئة جزءاً من العمل، من الوقاية من الإشعاع إلى رصد المخلفات السائلة والغازية.', 'Radiation protection, chemistry and environmental monitoring teams already live this every day; everyone else learns why it matters.', 'تعيش فرق الوقاية من الإشعاع والكيمياء والرصد البيئي هذه الكفاءة يومياً؛ ويتعلّم الآخرون سبب أهميتها.', '[{"en":"Describe how radiation protection and effluent monitoring protect people and the environment around a plant.","ar":"يصف كيف تحمي الوقاية من الإشعاع ورصد المخلفات الناس والبيئة حول المحطة."},{"en":"Apply ALARA thinking to an everyday task and explain the trade-offs.","ar":"يطبّق مبدأ \"أدنى مستوى يمكن بلوغه عملياً\" على مهمة يومية ويشرح الموازنات."},{"en":"Report an environmental concern through the right channel without delay.","ar":"يبلّغ عن أي مخاوف بيئية عبر القناة الصحيحة دون تأخير."}]'::jsonb, 'embodying_sustainability_values', array['sk-fs-tr-environment','sk-rp-02','sk-ch-02','sk-sc-02']::text[], '[{"kind":"pathway","ref":"pw-tr-environment-l1","title_en":"Environmental stewardship: foundations","title_ar":"الإشراف البيئي: الأساسيات"},{"kind":"external","ref":"xr-uncclearn-climate","title_en":"Introductory e-Course on Climate Change","title_ar":"المقرر الإلكتروني التمهيدي حول تغير المناخ"}]'::jsonb, 'new_economy', true, array['GREENCOMP','WEF-FOJ','JAHIZ']::text[], '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","as_of":"2026-10-10"},{"id":"fs41-jahiz","label":"WAM · Jahiz, the UAE platform upskilling federal government talent with future skills (Nov 2022)","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 2),
('cec-1-3', 'CEC-1.3', 'values', 'Fairness across generations', 'العدالة بين الأجيال', 'Weighs today''s decisions against the people who will run, use and inherit the plant over its long life.', 'يوازن قرارات اليوم مع مصلحة من سيشغّلون المحطة ويستفيدون منها ويرثونها على امتداد عمرها الطويل.', 'A nuclear plant runs for decades: fuel, waste and knowledge decisions made now are inherited by the next generation of staff.', 'تعمل المحطة النووية لعقود: قرارات الوقود والنفايات والمعرفة المتخذة اليوم يرثها الجيل القادم من العاملين.', '[{"en":"Explain why decisions on fuel, waste and knowledge affect people decades from now.","ar":"يشرح لماذا تؤثّر قرارات الوقود والنفايات والمعرفة في أناس بعد عقود."},{"en":"Pass on what you know so that the next generation can operate safely.","ar":"ينقل ما يعرفه ليتمكّن الجيل القادم من التشغيل بأمان."},{"en":"Take account of future users when choosing between short-term and long-term options.","ar":"يراعي المستخدمين في المستقبل عند الاختيار بين الخيارات قصيرة الأجل وطويلة الأجل."}]'::jsonb, 'embodying_sustainability_values', array['sk-fs-gr-circular','sk-fs-tr-crosscultural','sk-ld-01-coach']::text[], '[{"kind":"pathway","ref":"pw-gr-circular-l1","title_en":"Circularity and waste stewardship: foundations","title_ar":"الاقتصاد الدائري والإشراف على النفايات: الأساسيات"},{"kind":"lane","ref":"lane-netzero","title_en":"Net zero and low-carbon industry","title_ar":"الحياد المناخي والصناعة منخفضة الكربون"}]'::jsonb, 'new_economy', true, array['GREENCOMP','WEF-FOJ','JAHIZ']::text[], '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","as_of":"2026-10-10"},{"id":"fs41-jahiz","label":"WAM · Jahiz, the UAE platform upskilling federal government talent with future skills (Nov 2022)","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 3),
('cec-2-1', 'CEC-2.1', 'complexity', 'Systems thinking under uncertainty', 'التفكير المنظومي في ظل عدم اليقين', 'Sees the energy system, the plant and its people as connected parts, and reasons about effects that are delayed, shared or uncertain.', 'يرى منظومة الطاقة والمحطة والعاملين فيها أجزاءً مترابطة، ويستدل على الآثار المتأخرة أو المشتركة أو غير المؤكدة.', 'Defence in depth is a systems idea: the same habit of mind helps when thinking about energy security and the wider grid.', 'الدفاع في العمق فكرة منظومية: والعادة الذهنية نفسها تساعد عند التفكير في أمن الطاقة والشبكة الأوسع.', '[{"en":"Map how a change in one part of the energy system affects others, including feedback and delays.","ar":"يرسم كيف يؤثّر تغيير في جزء من منظومة الطاقة في الأجزاء الأخرى، بما في ذلك التغذية الراجعة والتأخير."},{"en":"Explain defence in depth as a systems idea and relate it to energy security.","ar":"يشرح الدفاع في العمق بوصفه فكرة منظومية ويربطه بأمن الطاقة."},{"en":"State the uncertainty in a forecast or plan and what would change your view.","ar":"يحدّد عدم اليقين في توقّع أو خطة وما الذي قد يغيّر رأيه."}]'::jsonb, 'embracing_complexity_in_sustainability', array['sk-fs-tr-systems','sk-ns-01','sk-ld-02-decide']::text[], '[{"kind":"course","ref":"c-fs-systems","title_en":"Systems thinking","title_ar":"التفكير المنظومي"},{"kind":"external","ref":"xr-openlearn-systems","title_en":"Mastering systems thinking in practice","title_ar":"إتقان التفكير المنظومي في الممارسة"},{"kind":"pathway","ref":"pw-tr-systems-l1","title_en":"Systems thinking: foundations","title_ar":"التفكير المنظومي: الأساسيات"}]'::jsonb, 'new_economy', true, array['GREENCOMP','WEF-FOJ','JAHIZ']::text[], '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","as_of":"2026-10-10"},{"id":"fs41-jahiz","label":"WAM · Jahiz, the UAE platform upskilling federal government talent with future skills (Nov 2022)","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 4),
('cec-2-2', 'CEC-2.2', 'complexity', 'Lifecycle carbon thinking', 'التفكير في الكربون على امتداد دورة الحياة', 'Counts emissions across the whole life of a plant or activity, from construction and fuel to operation and decommissioning.', 'يحسب الانبعاثات على امتداد عمر المحطة أو النشاط كاملاً، من الإنشاء والوقود إلى التشغيل والإيقاف النهائي.', 'Lifecycle thinking lets a team compare options honestly, including the emissions of maintenance, travel and purchased goods.', 'يتيح التفكير في دورة الحياة للفريق مقارنة الخيارات بأمانة، بما في ذلك انبعاثات الصيانة والسفر والسلع المشتراة.', '[{"en":"Classify emissions by scope and explain an emissions-avoided figure.","ar":"يصنّف الانبعاثات حسب النطاق ويشرح رقم الانبعاثات التي تم تجنّبها."},{"en":"Outline a lifecycle carbon assessment for a plant activity.","ar":"يضع مخططاً لتقييم الكربون على امتداد دورة الحياة لنشاط في المحطة."},{"en":"Explain why lifecycle numbers differ between studies and which assumptions drive them.","ar":"يشرح لماذا تختلف أرقام دورة الحياة بين الدراسات وما الافتراضات التي تحرّكها."}]'::jsonb, 'embracing_complexity_in_sustainability', array['sk-fs-gr-lifecycle','sk-fs-gr-ghg']::text[], '[{"kind":"course","ref":"c-fs-ghg","title_en":"GHG accounting basics","title_ar":"أساسيات محاسبة غازات الدفيئة"},{"kind":"adaptive","ref":"ab-clean-energy","title_en":"CleanEnergyComp foundations","title_ar":"أسس كفاءات الطاقة النظيفة"},{"kind":"task","ref":"pt-ghg-log","title_en":"Green: the fuel log that does not add up","title_ar":"أخضر: سجل الوقود الذي لا يستقيم"},{"kind":"credential","ref":"MC-CLEAN-ENERGY","title_en":"Clean energy systems","title_ar":"أنظمة الطاقة النظيفة"}]'::jsonb, 'new_economy', true, array['GREENCOMP','WEF-FOJ','JAHIZ']::text[], '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","as_of":"2026-10-10"},{"id":"fs41-jahiz","label":"WAM · Jahiz, the UAE platform upskilling federal government talent with future skills (Nov 2022)","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 5),
('cec-2-3', 'CEC-2.3', 'complexity', 'Critical use of evidence and data', 'الاستخدام النقدي للأدلة والبيانات', 'Checks the quality of data and claims before using them in a sustainability decision or report.', 'يتحقق من جودة البيانات والادعاءات قبل استخدامها في قرار أو تقرير يخص الاستدامة.', 'The same discipline that keeps plant data trustworthy keeps sustainability figures trustworthy: source, scope, date.', 'الانضباط نفسه الذي يحفظ موثوقية بيانات المحطة يحفظ موثوقية أرقام الاستدامة: المصدر والنطاق والتاريخ.', '[{"en":"Test a sustainability figure for its source, scope and date before repeating it.","ar":"يختبر رقماً يخص الاستدامة من حيث مصدره ونطاقه وتاريخه قبل تكراره."},{"en":"Spot gaps and double counting in an emissions or resource data set.","ar":"يكتشف الثغرات والعدّ المزدوج في مجموعة بيانات للانبعاثات أو الموارد."},{"en":"Present a conclusion with its evidence and its limits.","ar":"يعرض استنتاجاً مع أدلته وحدوده."}]'::jsonb, 'embracing_complexity_in_sustainability', array['sk-fs-tr-analytical','sk-fs-ai-plantdata','sk-da-01-analysis']::text[], '[{"kind":"task","ref":"pt-ghg-log","title_en":"Green: the fuel log that does not add up","title_ar":"أخضر: سجل الوقود الذي لا يستقيم"},{"kind":"course","ref":"c-et-ghg-mgr","title_en":"GHG and ESG basics for managers","title_ar":"أساسيات غازات الدفيئة والحوكمة البيئية والاجتماعية للمديرين"},{"kind":"pathway","ref":"pw-et-esg-managers","title_en":"ESG and GHG literacy for managers","title_ar":"الإلمام بالحوكمة البيئية والاجتماعية وغازات الدفيئة للمديرين"}]'::jsonb, 'new_economy', true, array['GREENCOMP','WEF-FOJ','JAHIZ']::text[], '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","as_of":"2026-10-10"},{"id":"fs41-jahiz","label":"WAM · Jahiz, the UAE platform upskilling federal government talent with future skills (Nov 2022)","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 6),
('cec-3-1', 'CEC-3.1', 'futures', 'Net-zero pathways literacy', 'الإلمام بمسارات الحياد الصفري', 'Understands how countries and industries plan to reach net zero, and the part low-carbon electricity plays.', 'يفهم كيف تخطط الدول والصناعات لبلوغ الحياد الصفري، والدور الذي تؤديه الكهرباء منخفضة الكربون.', 'Linked to the UAE Net Zero 2050 strategic initiative and to the New Economy group of the federal Jahiz future-skills platform.', 'مرتبطة بالمبادرة الاستراتيجية للحياد المناخي 2050 في الإمارات، وبمجموعة مهارات الاقتصاد الجديد في منصة "جاهز" الاتحادية لمهارات المستقبل.', '[{"en":"Describe the main levers of a net-zero pathway: clean power, efficiency, electrification and low-carbon fuels.","ar":"يصف الروافع الرئيسية لمسار الحياد الصفري: الطاقة النظيفة والكفاءة والكهربة والوقود منخفض الكربون."},{"en":"Explain climate risk to the plant and its users in simple terms.","ar":"يشرح المخاطر المناخية على المحطة ومستخدميها بعبارات بسيطة."},{"en":"Relate the national net-zero goal to your own work and your team.","ar":"يربط الهدف الوطني للحياد الصفري بعمله وبفريقه."}]'::jsonb, 'envisioning_sustainable_futures', array['sk-fs-gr-climaterisk','sk-fs-gr-ghg']::text[], '[{"kind":"external","ref":"xr-uncclearn-climate","title_en":"Introductory e-Course on Climate Change","title_ar":"المقرر الإلكتروني التمهيدي حول تغير المناخ"},{"kind":"lane","ref":"lane-netzero","title_en":"Net zero and low-carbon industry","title_ar":"الحياد المناخي والصناعة منخفضة الكربون"},{"kind":"pathway","ref":"pw-gr-climaterisk-l1","title_en":"Climate risk awareness: foundations","title_ar":"الوعي بمخاطر المناخ: الأساسيات"}]'::jsonb, 'new_economy', true, array['GREENCOMP','WEF-FOJ','JAHIZ']::text[], '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","as_of":"2026-10-10"},{"id":"fs41-jahiz","label":"WAM · Jahiz, the UAE platform upskilling federal government talent with future skills (Nov 2022)","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 7),
('cec-3-2', 'CEC-3.2', 'futures', 'The role of nuclear in an integrated energy system', 'دور الطاقة النووية في منظومة طاقة متكاملة', 'Explains how nuclear power and heat could work with renewables, storage, hydrogen and industry. Concept learning; no deployment decision implied.', 'يشرح كيف يمكن للكهرباء والحرارة النوويتين العمل مع الطاقة المتجددة والتخزين والهيدروجين والصناعة. تعلّم مفاهيمي، ولا يُفهم منه أي قرار بالنشر.', 'Steady low-carbon output complements variable renewables; heat and power could also serve hydrogen and industrial users.', 'يكمّل الإنتاج الثابت منخفض الكربون الطاقة المتجددة المتغيرة؛ ويمكن للحرارة والكهرباء أيضاً خدمة مستخدمي الهيدروجين والصناعة.', '[{"en":"Explain how steady nuclear output complements variable renewables on the grid.","ar":"يشرح كيف يكمّل الإنتاج النووي الثابت الطاقة المتجددة المتغيرة على الشبكة."},{"en":"Describe how nuclear heat and electricity could serve hydrogen and industrial users, and where the safety boundary sits.","ar":"يصف كيف يمكن للحرارة والكهرباء النوويتين خدمة مستخدمي الهيدروجين والصناعة، وأين تقع حدود السلامة."},{"en":"Compare the hydrogen, process-heat and grid value chains and the skills each needs.","ar":"يقارن سلاسل القيمة للهيدروجين والحرارة الصناعية والشبكة والمهارات التي تحتاجها كل منها."}]'::jsonb, 'envisioning_sustainable_futures', array['sk-fs-gr-h2heat','sk-fs-gr-grid','sk-pf-02','sk-pf-03-elec']::text[], '[{"kind":"chain","ref":"vc-hydrogen","title_en":"Hydrogen","title_ar":"الهيدروجين"},{"kind":"pathway","ref":"pw-et-system-integration","title_en":"Energy-system integration: from awareness to practitioner","title_ar":"تكامل منظومة الطاقة: من الوعي إلى الممارسة"},{"kind":"course","ref":"c-fs-h2heat","title_en":"Hydrogen and process heat","title_ar":"الهيدروجين والحرارة الصناعية"},{"kind":"academy","ref":"ac-energy","title_en":"Energy Transition cohort","title_ar":"دفعة التحول في قطاع الطاقة"}]'::jsonb, 'new_economy', true, array['GREENCOMP','WEF-FOJ','JAHIZ']::text[], '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","as_of":"2026-10-10"},{"id":"fs41-jahiz","label":"WAM · Jahiz, the UAE platform upskilling federal government talent with future skills (Nov 2022)","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 8),
('cec-3-3', 'CEC-3.3', 'futures', 'Exploring new technologies with an open mind', 'استكشاف التقنيات الجديدة بعقل منفتح', 'Approaches advanced reactors and other new energy technologies with curiosity and sound judgement, separating what is known from what is promoted.', 'يتعامل مع المفاعلات المتقدمة وتقنيات الطاقة الجديدة الأخرى بفضول وحكم سليم، فيفصل بين ما هو معروف وما يُروَّج له.', 'Advanced reactor families are evaluated as concepts; curiosity and evidence keep that learning honest.', 'تُقيَّم عائلات المفاعلات المتقدمة بوصفها مفاهيم؛ ويحافظ الفضول والأدلة على أمانة هذا التعلّم.', '[{"en":"Describe the main advanced reactor families and what changes for the people who run them.","ar":"يصف العائلات الرئيسية للمفاعلات المتقدمة وما يتغيّر لمن يشغّلونها."},{"en":"Separate evidence from promotion in claims about a new energy technology.","ar":"يفصل بين الأدلة والترويج في الادعاءات المتعلقة بتقنية طاقة جديدة."},{"en":"Adapt how you work when a new technology or method arrives.","ar":"يكيّف طريقة عمله عند ظهور تقنية أو أسلوب جديد."}]'::jsonb, 'envisioning_sustainable_futures', array['sk-fs-adv-smr','sk-fs-tr-curiosity','sk-fs-tr-resilience']::text[], '[{"kind":"course","ref":"c-adv-intro","title_en":"Advanced reactor families: an orientation","title_ar":"عائلات المفاعلات المتقدمة: مدخل تعريفي"},{"kind":"adaptive","ref":"ab-smr","title_en":"SMR fundamentals","title_ar":"أساسيات المفاعلات المعيارية الصغيرة"},{"kind":"lane","ref":"lane-advanced","title_en":"Advanced reactor fundamentals","title_ar":"أساسيات المفاعلات المتقدمة"}]'::jsonb, 'new_economy', true, array['GREENCOMP','WEF-FOJ','JAHIZ']::text[], '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","as_of":"2026-10-10"},{"id":"fs41-jahiz","label":"WAM · Jahiz, the UAE platform upskilling federal government talent with future skills (Nov 2022)","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 9),
('cec-4-1', 'CEC-4.1', 'acting', 'Waste stewardship', 'رعاية النفايات', 'Minimises, tracks and safely manages waste and effluents, from daily work to the back end of the fuel cycle.', 'يقلّل النفايات والمخلفات ويتتبعها ويديرها بأمان، من العمل اليومي إلى المرحلة الختامية من دورة الوقود.', 'Every work package can create less radioactive and conventional waste when it is planned with the waste hierarchy in mind.', 'يمكن لكل حزمة عمل أن تُنتج نفايات مشعة وتقليدية أقل عندما تُخطَّط مع مراعاة هرم إدارة النفايات.', '[{"en":"Explain the waste hierarchy and how it applies to plant work.","ar":"يشرح هرم إدارة النفايات وكيف ينطبق على العمل في المحطة."},{"en":"Plan a task so that it creates less radioactive and conventional waste.","ar":"يخطط لمهمة بحيث تُنتج نفايات مشعة وتقليدية أقل."},{"en":"Describe, as a concept, how spent fuel and radioactive waste are kept safe over the long term.","ar":"يصف، بوصفه مفهوماً، كيف يُحافَظ على سلامة الوقود المستهلك والنفايات المشعة على المدى الطويل."}]'::jsonb, 'acting_for_sustainability', array['sk-fs-gr-circular','sk-ch-02','sk-rp-02-survey']::text[], '[{"kind":"opportunity","ref":"fg-kc-waste-minimisation","title_en":"Knowledge capture: waste-minimisation good practice","title_ar":"التقاط المعرفة: الممارسات الجيدة لتقليل النفايات"},{"kind":"pathway","ref":"pw-gr-circular-l1","title_en":"Circularity and waste stewardship: foundations","title_ar":"الاقتصاد الدائري والإشراف على النفايات: الأساسيات"}]'::jsonb, 'new_economy', true, array['GREENCOMP','WEF-FOJ','JAHIZ']::text[], '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","as_of":"2026-10-10"},{"id":"fs41-jahiz","label":"WAM · Jahiz, the UAE platform upskilling federal government talent with future skills (Nov 2022)","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 10),
('cec-4-2', 'CEC-4.2', 'acting', 'Circularity and resource efficiency', 'الاقتصاد الدائري وكفاءة الموارد', 'Keeps equipment, materials and data in use for longer, and buys with the whole life in mind.', 'يُبقي المعدات والمواد والبيانات قيد الاستخدام مدة أطول، ويشتري مع مراعاة دورة الحياة كاملة.', 'Maintenance, engineering and supply chain decide together when to repair, refurbish or replace.', 'تقرر الصيانة والهندسة وسلسلة الإمداد معاً متى يكون الإصلاح أو التجديد أو الاستبدال.', '[{"en":"Identify where repair, refurbishment or reuse can replace replacement in maintenance work.","ar":"يحدّد أين يمكن للإصلاح أو التجديد أو إعادة الاستخدام أن يحلّ محل الاستبدال في أعمال الصيانة."},{"en":"Include lifecycle and end-of-life questions when specifying or buying equipment.","ar":"يضمّن أسئلة دورة الحياة ونهاية العمر عند تحديد مواصفات المعدات أو شرائها."},{"en":"Use condition data to extend the useful life of a component safely.","ar":"يستخدم بيانات الحالة لإطالة العمر النافع لمكوّن بأمان."}]'::jsonb, 'acting_for_sustainability', array['sk-fs-gr-circular','sk-fs-dp-procurement','sk-en-02']::text[], '[{"kind":"pathway","ref":"pw-gr-circular-l2","title_en":"Circularity and waste stewardship: practitioner","title_ar":"الاقتصاد الدائري والإشراف على النفايات: الممارسة"},{"kind":"opportunity","ref":"fg-kc-waste-minimisation","title_en":"Knowledge capture: waste-minimisation good practice","title_ar":"التقاط المعرفة: الممارسات الجيدة لتقليل النفايات"}]'::jsonb, 'new_economy', true, array['GREENCOMP','WEF-FOJ','JAHIZ']::text[], '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","as_of":"2026-10-10"},{"id":"fs41-jahiz","label":"WAM · Jahiz, the UAE platform upskilling federal government talent with future skills (Nov 2022)","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 11),
('cec-4-3', 'CEC-4.3', 'acting', 'Advocacy with evidence', 'المناصرة بالأدلة', 'Speaks up for sustainable choices inside and outside the organisation, always with evidence and respect for other views.', 'يدافع عن الخيارات المستدامة داخل المؤسسة وخارجها، دائماً بالأدلة ومع احترام الآراء الأخرى.', 'Managers and communicators carry this most: they turn data into a fair account of progress, including what went less well.', 'يحمل المديرون والمختصون بالتواصل هذه الكفاءة أكثر من غيرهم: يحوّلون البيانات إلى عرض منصف للتقدم، بما في ذلك ما لم يسر على ما يرام.', '[{"en":"Make a short, sourced case for a sustainability improvement in your team.","ar":"يقدّم حجة قصيرة موثّقة المصدر لتحسين يخص الاستدامة في فريقه."},{"en":"Disclose sustainability information clearly, including what went less well.","ar":"يفصح عن معلومات الاستدامة بوضوح، بما في ذلك ما لم يسر على ما يرام."},{"en":"Lead or join a team effort that measurably reduces the use of a resource.","ar":"يقود جهداً جماعياً أو يشارك فيه يقلّل استخدام أحد الموارد بشكل قابل للقياس."}]'::jsonb, 'acting_for_sustainability', array['sk-fs-gr-esg','sk-fs-tr-leadership','sk-ld-01']::text[], '[{"kind":"pathway","ref":"pw-et-esg-managers","title_en":"ESG and GHG literacy for managers","title_ar":"الإلمام بالحوكمة البيئية والاجتماعية وغازات الدفيئة للمديرين"},{"kind":"course","ref":"c-et-esg-clinic","title_en":"ESG data clinic: your team''s numbers","title_ar":"عيادة بيانات الحوكمة البيئية والاجتماعية: أرقام فريقك"},{"kind":"credential","ref":"MC-CLEAN-ENERGY","title_en":"Clean energy systems","title_ar":"أنظمة الطاقة النظيفة"}]'::jsonb, 'new_economy', true, array['GREENCOMP','WEF-FOJ','JAHIZ']::text[], '[{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-greencomp-pdf","label":"European Commission · GreenComp (JRC128040, EUR 30955 EN), PDF","url":"https://wikis.ec.europa.eu/download/attachments/80183613/GreenComp.pdf","as_of":"2026-10-10"},{"id":"fs41-jahiz","label":"WAM · Jahiz, the UAE platform upskilling federal government talent with future skills (Nov 2022)","url":"https://wam.ae/en/details/1395303102696","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 12)
insert into kafaa_cec_role_targets (id, family_id, level, focus_ids, rationale_en, rationale_ar) values
('cect:operations', 'operations', 1, array['cec-1-2','cec-2-1']::text[], 'Operators steward people and the environment every shift and think in systems; awareness level across all four areas.', 'يرعى المشغّلون الناس والبيئة في كل وردية ويفكرون بطريقة منظومية؛ مستوى الوعي في المجالات الأربعة.'),
('cect:maintenance', 'maintenance', 1, array['cec-4-2','cec-4-1']::text[], 'Maintenance decides daily between repair and replacement and creates most work-package waste.', 'تقرر الصيانة يومياً بين الإصلاح والاستبدال، وتُنتج معظم نفايات حزم العمل.'),
('cect:engineering', 'engineering', 2, array['cec-3-2','cec-2-2','cec-4-2']::text[], 'Engineers assess lifecycle impacts and would carry the technical work on any energy-system interface.', 'يقيّم المهندسون آثار دورة الحياة، وسيحملون العمل الفني لأي واجهة مع منظومة الطاقة.'),
('cect:radiation-protection', 'radiation-protection', 2, array['cec-1-2','cec-4-1']::text[], 'Radiation protection leads stewardship of people and the environment and the control of radioactive waste.', 'تقود الوقاية من الإشعاع رعاية الناس والبيئة وضبط النفايات المشعة.'),
('cect:chemistry', 'chemistry', 2, array['cec-4-1','cec-1-2']::text[], 'Chemistry monitors effluents and manages chemical and radioactive waste streams.', 'تراقب الكيمياء المخلفات وتدير مسارات النفايات الكيميائية والمشعة.'),
('cect:nuclear-fuel', 'nuclear-fuel', 2, array['cec-1-3','cec-4-1']::text[], 'Fuel decisions shape the back end of the fuel cycle for decades.', 'تشكّل قرارات الوقود المرحلة الختامية من دورة الوقود لعقود.'),
('cect:outage', 'outage', 1, array['cec-4-2','cec-4-1']::text[], 'Outages concentrate maintenance waste and buying decisions in a few weeks.', 'تتركّز في فترات الانقطاع نفايات الصيانة وقرارات الشراء خلال أسابيع قليلة.'),
('cect:emergency-preparedness', 'emergency-preparedness', 1, array['cec-3-1','cec-2-1']::text[], 'Emergency planning needs a clear view of climate risk and of how systems fail together.', 'يحتاج التخطيط للطوارئ إلى رؤية واضحة للمخاطر المناخية ولكيفية تعطّل الأنظمة معاً.'),
('cect:security', 'security', 1, array['cec-1-1']::text[], 'Awareness level only; the role is shown at career-path level and sustainability content stays general.', 'مستوى الوعي فقط؛ يُعرض الدور على مستوى المسار المهني ويبقى محتوى الاستدامة عاماً.'),
('cect:cyber', 'cyber', 1, array['cec-2-3']::text[], 'Awareness level; the data discipline behind trustworthy figures is the most relevant competence.', 'مستوى الوعي؛ والانضباط في البيانات الذي يقف خلف الأرقام الموثوقة هو الكفاءة الأوثق صلة.'),
('cect:safeguards', 'safeguards', 1, array['cec-1-3']::text[], 'Awareness level; fairness across generations matches the long view of safeguards work.', 'مستوى الوعي؛ وتتوافق العدالة بين الأجيال مع النظرة البعيدة لعمل الضمانات.'),
('cect:quality', 'quality', 1, array['cec-2-3','cec-4-3']::text[], 'Quality staff check data and claims and help disclose them accurately.', 'يتحقق موظفو الجودة من البيانات والادعاءات ويساعدون في الإفصاح عنها بدقة.'),
('cect:oversight', 'oversight', 1, array['cec-2-1','cec-2-3']::text[], 'Oversight challenges assumptions and evidence across the organisation.', 'تتحدى الرقابة الافتراضات والأدلة على مستوى المؤسسة.'),
('cect:licensing', 'licensing', 1, array['cec-1-1','cec-2-1']::text[], 'Licensing explains the plant to external audiences with evidence and its limits.', 'يشرح الترخيص المحطة للجهات الخارجية بالأدلة وحدودها.'),
('cect:training', 'training', 1, array['cec-1-3','cec-4-3']::text[], 'Trainers pass knowledge to the next generation and model evidence-based advocacy.', 'ينقل المدربون المعرفة إلى الجيل القادم ويقدّمون نموذجاً للمناصرة القائمة على الأدلة.'),
('cect:health-safety', 'health-safety', 1, array['cec-1-2','cec-3-1']::text[], 'Health and safety connects stewardship of people with climate risk such as heat stress.', 'تربط الصحة والسلامة رعاية الناس بالمخاطر المناخية مثل الإجهاد الحراري.'),
('cect:environment', 'environment', 3, array['cec-2-2','cec-1-2','cec-4-1']::text[], 'The environment team leads the framework and advises others on lifecycle carbon, stewardship and waste.', 'يقود فريق البيئة الإطار وينصح الآخرين في الكربون على امتداد دورة الحياة والرعاية والنفايات.'),
('cect:supply-chain', 'supply-chain', 2, array['cec-4-2','cec-2-2']::text[], 'Supply chain buys with the whole life in mind and owns much of the purchased-goods footprint.', 'تشتري سلسلة الإمداد مع مراعاة دورة الحياة كاملة، وتملك جزءاً كبيراً من بصمة السلع المشتراة.'),
('cect:fire-protection', 'fire-protection', 1, array['cec-1-2']::text[], 'Fire protection protects people and the environment from fire and its run-off.', 'تحمي الوقاية من الحرائق الناس والبيئة من الحرائق ومخلفاتها.'),
('cect:corporate', 'corporate', 2, array['cec-1-1','cec-4-3','cec-3-1']::text[], 'Communications, sustainability and reporting teams explain and disclose progress, so they need practitioner level.', 'تشرح فرق التواصل والاستدامة وإعداد التقارير التقدّم وتفصح عنه، لذا تحتاج إلى مستوى الممارس.')
insert into kafaa_value_chains (id, code, name_en, name_ar, summary_en, summary_ar, stages, facts, skill_ids, lane_ids, pathway_ids, cec_ids, benchmark_ids, sources, status, as_of, sort) values
('vc-hydrogen', 'VC-1', 'Hydrogen', 'الهيدروجين', 'Clean electricity, and for some designs heat, can split water into hydrogen for industrial users. This explainer covers the chain and its skills only; no ENEC project or site is implied.', 'يمكن للكهرباء النظيفة، وللحرارة في بعض التصاميم، فصل الماء لإنتاج الهيدروجين للمستخدمين الصناعيين. يغطي هذا الشرح السلسلة ومهاراتها فقط، ولا يُفهم منه أي مشروع أو موقع للمؤسسة.', '[{"key":"source","en":"Low-carbon electricity and heat","ar":"كهرباء وحرارة منخفضتا الكربون","role_en":"A nuclear plant supplies steady low-carbon electricity; some reactor designs could also supply high-temperature heat.","role_ar":"توفر المحطة النووية كهرباء ثابتة منخفضة الكربون؛ ويمكن لبعض تصاميم المفاعلات أيضاً توفير حرارة عالية."},{"key":"conversion","en":"Electrolysis","ar":"التحليل الكهربائي","role_en":"Electrolysers split water into hydrogen and oxygen; high-temperature electrolysis uses heat to need less electricity.","role_ar":"تفصل أجهزة التحليل الكهربائي الماء إلى هيدروجين وأكسجين؛ ويستخدم التحليل عالي الحرارة الحرارة ليحتاج إلى كهرباء أقل."},{"key":"storage","en":"Storage and transport","ar":"التخزين والنقل","role_en":"Hydrogen is compressed, stored or converted (for example to ammonia) before it moves; safety distances and codes matter here.","role_ar":"يُضغط الهيدروجين أو يُخزَّن أو يُحوَّل (إلى الأمونيا مثلاً) قبل نقله؛ وهنا تهم مسافات السلامة والمعايير."},{"key":"use","en":"Industrial users","ar":"المستخدمون الصناعيون","role_en":"Fertiliser, steel and refining can replace fossil hydrogen; the interface stays outside the plant safety boundary.","role_ar":"يمكن لصناعات الأسمدة والصلب والتكرير استبدال الهيدروجين الأحفوري؛ وتبقى الواجهة خارج حدود السلامة للمحطة."}]'::jsonb, '[{"id":"vc-h2-f1","en":"At least 16.6 million renewable-energy jobs existed worldwide in 2024; growth slowed to 2.3% despite record capacity additions.","ar":"بلغت وظائف الطاقة المتجددة في العالم 16.6 مليون وظيفة على الأقل في 2024، وتباطأ نموها إلى 2.3% رغم إضافات قياسية في القدرة.","label":"EU BUILD UP · IRENA and ILO, Renewable Energy and Jobs: Annual Review 2025","url":"https://build-up.ec.europa.eu/en/resources-and-tools/publications/annual-review-2025-renewable-energy-and-jobs","as_of":"2026-10-10","published":"2025","secondary":true},{"id":"vc-h2-f2","en":"IRENA and the ILO call for education and training at scale against shortages, particularly in digital skills and manufacturing.","ar":"تدعو آيرينا ومنظمة العمل الدولية إلى توسيع التعليم والتدريب لمواجهة النقص، ولا سيما في المهارات الرقمية والتصنيع.","label":"EU BUILD UP · IRENA and ILO, Renewable Energy and Jobs: Annual Review 2025","url":"https://build-up.ec.europa.eu/en/resources-and-tools/publications/annual-review-2025-renewable-energy-and-jobs","as_of":"2026-10-10","published":"2025","secondary":true},{"id":"vc-h2-f3","en":"The OECD-NEA''s Plan 2035 builds the nuclear workforce in support of tripling nuclear capacity by 2050.","ar":"تبني خطة 2035 لوكالة الطاقة النووية القوى العاملة النووية دعماً لمضاعفة القدرة النووية ثلاث مرات بحلول 2050.","label":"OECD-NEA · Plan 2035 vision paper: Scaling Technology, Growing Careers, Securing the Future (Oct 2025)","url":"https://www.oecd-nea.org/upload/docs/application/pdf/2025-10/plan_2035_-_vision_paper_-_final_version.pdf","as_of":"2026-10-10","published":"2025-10","secondary":false}]'::jsonb, array['sk-fs-gr-h2heat','sk-fs-gr-lifecycle']::text[], array['lane-hydrogen','lane-netzero']::text[], array['pw-et-system-integration','pw-gr-h2heat-l1']::text[], array['cec-3-2','cec-2-2']::text[], array['ENERGY-JOBS','NEA']::text[], '[{"id":"fs42-irena-jobs","label":"EU BUILD UP · IRENA and ILO, Renewable Energy and Jobs: Annual Review 2025","url":"https://build-up.ec.europa.eu/en/resources-and-tools/publications/annual-review-2025-renewable-energy-and-jobs","as_of":"2026-10-10"},{"id":"fs42-nea-plan2035","label":"OECD-NEA · Plan 2035 vision paper: Scaling Technology, Growing Careers, Securing the Future (Oct 2025)","url":"https://www.oecd-nea.org/upload/docs/application/pdf/2025-10/plan_2035_-_vision_paper_-_final_version.pdf","as_of":"2026-10-10"}]'::jsonb, 'active', '2026-10-10', 1),
('vc-process-heat', 'VC-2', 'Process heat', 'الحرارة الصناعية', 'Reactor heat, not only electricity, could serve industrial processes such as desalination or chemicals. Concept learning only; no deployment decision implied.', 'يمكن لحرارة المفاعل، لا الكهرباء وحدها، أن تخدم عمليات صناعية مثل التحلية أو الكيماويات. تعلّم مفاهيمي فقط، ولا يُفهم منه أي قرار بالنشر.', '[{"key":"source","en":"Heat source","ar":"مصدر الحرارة","role_en":"Light-water reactors give steam at moderate temperature; high-temperature and molten-salt designs give hotter heat.","role_ar":"تعطي مفاعلات الماء الخفيف بخاراً بحرارة متوسطة؛ وتعطي التصاميم عالية الحرارة وتصاميم الأملاح المنصهرة حرارة أعلى."},{"key":"loop","en":"Heat transport loop","ar":"دائرة نقل الحرارة","role_en":"An intermediate loop (steam, gas or molten salt) carries heat away and keeps the plant separated from the user.","role_ar":"تنقل دائرة وسيطة (بخار أو غاز أو أملاح منصهرة) الحرارة وتُبقي المحطة منفصلة عن المستخدم."},{"key":"process","en":"Industrial process","ar":"العملية الصناعية","role_en":"Desalination, district heat and chemical processes use the heat; each temperature range suits different users.","role_ar":"تستخدم التحلية والتدفئة المركزية والعمليات الكيميائية الحرارة؛ ويناسب كل نطاق حراري مستخدمين مختلفين."},{"key":"safety","en":"Safety boundary","ar":"حدود السلامة","role_en":"Coupling a reactor to an industrial user needs a safety case that covers both sides of the interface.","role_ar":"يحتاج ربط مفاعل بمستخدم صناعي إلى حالة سلامة تغطي جانبي الواجهة."}]'::jsonb, '[{"id":"vc-ph-f1","en":"In the IEA Energy Employment Survey, 60% of companies reported labour shortages, worst in technical trades such as pipefitters, plant operators and nuclear specialists.","ar":"في مسح الوكالة الدولية للطاقة للتوظيف في قطاع الطاقة، أفادت 60% من الشركات بنقص في العمالة، وكان أشدّه في المهن الفنية مثل مركّبي الأنابيب ومشغلي المحطات والمتخصصين النوويين.","label":"NucNet · IEA World Energy Employment 2025: jobs growth in nuclear (Dec 2025)","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025","as_of":"2026-10-10","published":"2025-12","secondary":true},{"id":"vc-ph-f2","en":"To avoid further skill misalignment by 2030, graduates entering the energy sector must rise by about 40% globally.","ar":"لتجنّب مزيد من عدم التوافق في المهارات بحلول 2030، يجب أن يرتفع عدد الخريجين الداخلين إلى قطاع الطاقة بنحو 40% عالمياً.","label":"NucNet · IEA World Energy Employment 2025: jobs growth in nuclear (Dec 2025)","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025","as_of":"2026-10-10","published":"2025-12","secondary":true},{"id":"vc-ph-f3","en":"The IEA warns that skills shortages have contributed to increased outages and reduced output in several advanced nuclear fleets.","ar":"تحذّر الوكالة الدولية للطاقة من أن نقص المهارات أسهم في زيادة فترات الانقطاع وتراجع الإنتاج في عدة أساطيل نووية متقدمة.","label":"NucNet · IEA World Energy Employment 2025: jobs growth in nuclear (Dec 2025)","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025","as_of":"2026-10-10","published":"2025-12","secondary":true}]'::jsonb, array['sk-fs-gr-h2heat','sk-fs-tr-systems']::text[], array['lane-hydrogen','lane-advanced']::text[], array['pw-et-system-integration','pw-gr-h2heat-l2']::text[], array['cec-3-2','cec-2-1']::text[], array['ENERGY-JOBS','NEA']::text[], '[{"id":"fs42-iea-wee","label":"NucNet · IEA World Energy Employment 2025: jobs growth in nuclear (Dec 2025)","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025","as_of":"2026-10-10"}]'::jsonb, 'active', '2026-10-10', 2),
('vc-grid', 'VC-3', 'Grid integration', 'التكامل مع الشبكة', 'Firm low-carbon power works alongside solar, storage and flexible demand to keep the grid balanced. This explainer covers the system and its skills; it makes no ENEC project claim.', 'تعمل الطاقة الثابتة منخفضة الكربون جنباً إلى جنب مع الطاقة الشمسية والتخزين والطلب المرن للحفاظ على توازن الشبكة. يغطي هذا الشرح المنظومة ومهاراتها، ولا يتضمن أي ادعاء بمشروع للمؤسسة.', '[{"key":"generation","en":"Generation","ar":"التوليد","role_en":"Large reactors run at steady output and provide firm low-carbon power alongside variable solar.","role_ar":"تعمل المفاعلات الكبيرة بإنتاج ثابت وتوفر طاقة ثابتة منخفضة الكربون إلى جانب الطاقة الشمسية المتغيرة."},{"key":"flexibility","en":"Flexible operation","ar":"التشغيل المرن","role_en":"Some fleets follow load; flexibility has limits set by fuel, chemistry and equipment.","role_ar":"تتبع بعض الأساطيل الحمل؛ وللمرونة حدود يفرضها الوقود والكيمياء والمعدات."},{"key":"network","en":"Transmission and distribution","ar":"النقل والتوزيع","role_en":"The network carries power to users and depends on skilled electricians and line workers.","role_ar":"تنقل الشبكة الكهرباء إلى المستخدمين وتعتمد على كهربائيين وعمال خطوط مهرة."},{"key":"balance","en":"Demand and storage","ar":"الطلب والتخزين","role_en":"Batteries, storage and demand response balance supply and demand; hydrogen can store surplus power.","role_ar":"توازن البطاريات والتخزين والاستجابة للطلب بين العرض والطلب؛ ويمكن للهيدروجين تخزين الكهرباء الفائضة."}]'::jsonb, '[{"id":"vc-gr-f1","en":"The energy sector employed 76 million people in 2024, 5 million more than in 2019, growing about twice as fast as the global economy.","ar":"وظّف قطاع الطاقة 76 مليون شخص في 2024، بزيادة 5 ملايين عن 2019، بنمو يقارب ضعف نمو الاقتصاد العالمي.","label":"NucNet · IEA World Energy Employment 2025: jobs growth in nuclear (Dec 2025)","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025","as_of":"2026-10-10","published":"2025-12","secondary":true},{"id":"vc-gr-f2","en":"Among technical trades, the IEA reports shortages of electricians and line workers alongside plant operators.","ar":"من بين المهن الفنية، تشير الوكالة الدولية للطاقة إلى نقص في الكهربائيين وعمال الخطوط إلى جانب مشغلي المحطات.","label":"NucNet · IEA World Energy Employment 2025: jobs growth in nuclear (Dec 2025)","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025","as_of":"2026-10-10","published":"2025-12","secondary":true},{"id":"vc-gr-f3","en":"Employers in the WEF Future of Jobs Report 2025 name the green transition a top driver of change; environmental stewardship entered the ten fastest-growing skills for the first time.","ar":"يرى أصحاب العمل في تقرير مستقبل الوظائف 2025 للمنتدى الاقتصادي العالمي أن التحول الأخضر من أبرز محركات التغيير؛ ودخلت رعاية البيئة قائمة أسرع عشر مهارات نمواً لأول مرة.","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10","published":"2025-01","secondary":true}]'::jsonb, array['sk-fs-gr-grid','sk-fs-tr-systems']::text[], array['lane-grid']::text[], array['pw-et-system-integration','pw-gr-grid-l1']::text[], array['cec-3-2','cec-2-1']::text[], array['ENERGY-JOBS','NEA']::text[], '[{"id":"fs42-iea-wee","label":"NucNet · IEA World Energy Employment 2025: jobs growth in nuclear (Dec 2025)","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', '2026-10-10', 3)
insert into kafaa_transition_tracks (id, feature, pathway_id, credential_code, max_hours, audience_en, audience_ar, summary_en, summary_ar, chain_ids, benchmark_ids, sources, sort) values
('tt-system-integration', 'FS42', 'pw-et-system-integration', 'MC-H2-HEAT', null, 'Engineers, strategy staff and interested employees', 'المهندسون وموظفو الاستراتيجية والموظفون المهتمون', 'An awareness-to-practitioner route through the hydrogen, process-heat and grid value chains, with curated readings, a study gig, practice with engineering and chemistry, and the matching horizon lanes.', 'مسار من الوعي إلى الممارسة عبر سلاسل القيمة للهيدروجين والحرارة الصناعية والشبكة، مع قراءات منتقاة، ومهمة دراسية قصيرة، وممارسة مع الهندسة والكيمياء، والمسارات المستقبلية المطابقة.', array['vc-hydrogen','vc-process-heat','vc-grid']::text[], array['ENERGY-JOBS','NEA']::text[], '[{"id":"fs42-nea-plan2035","label":"OECD-NEA · Plan 2035 vision paper: Scaling Technology, Growing Careers, Securing the Future (Oct 2025)","url":"https://www.oecd-nea.org/upload/docs/application/pdf/2025-10/plan_2035_-_vision_paper_-_final_version.pdf","as_of":"2026-10-10"},{"id":"fs42-iea-wee","label":"NucNet · IEA World Energy Employment 2025: jobs growth in nuclear (Dec 2025)","url":"https://smr.nucnet.org/news/jobs-growth-in-nuclear-surged-in-2024-and-will-continue-to-expand-despite-headwinds-iea-report-12-5-2025","as_of":"2026-10-10"},{"id":"fs42-irena-jobs","label":"EU BUILD UP · IRENA and ILO, Renewable Energy and Jobs: Annual Review 2025","url":"https://build-up.ec.europa.eu/en/resources-and-tools/publications/annual-review-2025-renewable-energy-and-jobs","as_of":"2026-10-10"}]'::jsonb, 1),
('tt-esg-managers', 'FS43', 'pw-et-esg-managers', 'MC-CLEAN-ENERGY', 10, 'Managers, finance and reporting staff', 'المديرون وموظفو المالية وإعداد التقارير', 'A shared baseline for managers who report on sustainability and human capital, completable in under 10 hours at about one hour a week.', 'أساس مشترك للمديرين الذين يعدّون تقارير الاستدامة ورأس المال البشري، يمكن إكماله في أقل من 10 ساعات بمعدل ساعة أسبوعياً تقريباً.', '{}'::text[], array['GREENCOMP','ISO30414','ENERGY-JOBS']::text[], '[{"id":"fs43-iso30414","label":"ISO TC 260 · ISO 30414:2025, strengthening human capital reporting (24 Aug 2025)","url":"https://committee.iso.org/sites/tc260/home/news/content-left-area/news-and-updates/iso-30414-2025-strengthening-hum.html","as_of":"2026-10-10"},{"id":"fs41-greencomp","label":"European Commission JRC · GreenComp, the European sustainability competence framework (2022)","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"id":"fs41-wef-foj","label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 2)
insert into kafaa_core_skills (id, code, cluster, name_en, name_ar, summary_en, summary_ar, plant_en, plant_ar, descriptors, mappings, benchmark_ids, trait_ids, skill_ids, development, assessment, dev_approach_en, dev_approach_ar, assess_approach_en, assess_approach_ar, outcome_en, outcome_ar, sources, status, version, as_of, sort) values
('cs-questioning', 'TC-1', 'thinking_critically', 'Questioning attitude', 'موقف التساؤل', 'Notices when something is not as expected, asks why, and challenges assumptions before acting, including assumptions built into a plan or a tool''s output.', 'يلاحظ ما لا يسير كما هو متوقع، ويسأل عن السبب، ويتحدى الافتراضات قبل التصرف، بما فيها الافتراضات المضمّنة في خطة أو في مخرجات أداة.', 'Pauses a work package when a valve label does not match the drawing and asks work control before continuing.', 'يوقف حزمة العمل مؤقتاً عندما لا يطابق ملصق الصمام المخطط، ويستشير التحكم في العمل قبل المتابعة.', '[{"level":1,"en":"Asks when something looks different from what the procedure or briefing said.","ar":"يسأل عندما يبدو شيء مختلفاً عمّا ورد في الإجراء أو الإحاطة."},{"level":2,"en":"Challenges assumptions in plans and readings with specific questions and checks independent indications.","ar":"يتحدى الافتراضات في الخطط والقراءات بأسئلة محددة ويتحقق من مؤشرات مستقلة."},{"level":3,"en":"Builds a team habit of challenge: invites questions, values them and closes each one with an answer.","ar":"يبني لدى الفريق عادة التحدي: يدعو إلى الأسئلة ويقدّرها ويغلق كل سؤال بإجابة."}]'::jsonb, '[{"framework":"inpo","benchmark_id":null,"ref":"trait-2","label_en":"INPO safety-culture trait · Questioning attitude (M08)","label_ar":"سمة ثقافة السلامة لدى INPO · موقف التساؤل (M08)"},{"framework":"iaea_1917","benchmark_id":"IAEA-1917","ref":null,"label_en":"IAEA-TECDOC-1917 behavioural competency · questioning attitude","label_ar":"الكفاءة السلوكية في IAEA-TECDOC-1917 · موقف التساؤل"},{"framework":"lifecomp","benchmark_id":"GREENCOMP","ref":null,"label_en":"LifeComp · critical thinking","label_ar":"إطار LifeComp · التفكير النقدي"},{"framework":"wef","benchmark_id":"WEF-FOJ","ref":null,"label_en":"WEF core skill · analytical thinking","label_ar":"مهارة أساسية لدى المنتدى الاقتصادي العالمي · التفكير التحليلي"},{"framework":"ssg_ccs","benchmark_id":"SSG-SF","ref":"TC","label_en":"SkillsFuture Critical Core Skills · Thinking Critically cluster","label_ar":"المهارات الأساسية الحرجة في SkillsFuture · مجموعة التفكير النقدي"}]'::jsonb, array['GREENCOMP','IAEA-1917','SSG-SF','WEF-FOJ']::text[], array['trait-2']::text[], array['sk-sc-01','sk-fs-tr-analytical']::text[], '[{"kind":"course","ref":"c-scwe","title_en":"Safety-conscious work environment","title_ar":"بيئة العمل الواعية بالسلامة"},{"kind":"page","ref":"/oe","title_en":"Operating experience lessons where an assumption went unchallenged","title_ar":"دروس الخبرة التشغيلية حيث لم يُطعن في افتراض"},{"kind":"practice","ref":"cs-questioning","title_en":"Situational judgement practice for this skill","title_ar":"تمارين الحكم الظرفي لهذه المهارة"}]'::jsonb, '[{"kind":"checkin","ref":"/my/skills/checkins","title_en":"Skill check-in with peers and your manager","title_ar":"تقييم دوري للمهارة مع الزملاء ومديرك"},{"kind":"observation","ref":"brief-challenge","title_en":"Observed challenge in a pre-job brief","title_ar":"تحدٍّ ملاحظ في إحاطة ما قبل العمل"},{"kind":"sjt","ref":"cs-questioning","title_en":"Situational judgement practice result (development only)","title_ar":"نتيجة تمارين الحكم الظرفي (للتطوير فقط)"}]'::jsonb, 'Learning from operating experience where an unchallenged assumption mattered, and rehearsing challenge in briefs.', 'التعلّم من الخبرة التشغيلية حيث كان لافتراض لم يُطعن فيه أثر، والتمرّن على التحدي في الإحاطات.', 'Peer and manager check-ins on observed challenges, plus scenario practice.', 'تقييمات دورية من الزملاء والمدير لحالات تحدٍّ ملاحظة، إضافة إلى تمارين السيناريوهات.', '', '', '[{"label":"SkillsFuture Singapore · Factsheet on top skills trends in 2025 (Critical Core Skills)","url":"https://isomer-user-content.by.gov.sg/41/4955bc61-161d-4584-945c-7eeeb276867a/Factsheet%20on%20Top%20skills%20trends%20in%202025.pdf","as_of":"2026-10-10"},{"label":"IAEA-TECDOC-1917 · Assessing behavioural competencies of employees in nuclear facilities","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1917_web.pdf","as_of":"2026-10-10"},{"label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"},{"label":"European Commission JRC · GreenComp, with EntreComp and LifeComp","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 101),
('cs-conservative', 'TC-2', 'thinking_critically', 'Conservative decision-making', 'اتخاذ القرار المحافظ', 'When conditions are uncertain, chooses the action that keeps the plant in a known safe state, even at a cost to schedule or output.', 'عندما تكون الظروف غير مؤكدة، يختار الإجراء الذي يُبقي المحطة في حالة آمنة معروفة، حتى لو كان ذلك على حساب الجدول الزمني أو الإنتاج.', 'Recommends holding a power change when an indication is unexplained, and records the reasoning for the shift manager.', 'يوصي بتثبيت تغيير القدرة عندما يظهر مؤشر غير مفسَّر، ويوثّق الأسباب لمدير الوردية.', '[{"level":1,"en":"Stops and asks when unsure, rather than proceeding on a guess.","ar":"يتوقف ويسأل عند عدم التيقّن بدلاً من المضي بناءً على تخمين."},{"level":2,"en":"Weighs options against safety margins, chooses the conservative one and explains why.","ar":"يوازن الخيارات مقابل هوامش السلامة ويختار الخيار المحافظ ويشرح السبب."},{"level":3,"en":"Sets the expectation that production pressure never outranks margin, and backs people who slow down.","ar":"يرسّخ أن ضغط الإنتاج لا يتقدّم أبداً على هامش السلامة، ويساند من يتمهّل."}]'::jsonb, '[{"framework":"inpo","benchmark_id":null,"ref":"trait-5","label_en":"INPO safety-culture trait · Decision-making (M08)","label_ar":"سمة ثقافة السلامة لدى INPO · اتخاذ القرار (M08)"},{"framework":"iaea_1917","benchmark_id":"IAEA-1917","ref":null,"label_en":"IAEA-TECDOC-1917 behavioural competency · conservative decision-making","label_ar":"الكفاءة السلوكية في IAEA-TECDOC-1917 · اتخاذ القرار المحافظ"},{"framework":"delta","benchmark_id":"MCK-DELTA","ref":null,"label_en":"McKinsey DELTA · self-leadership · coping with uncertainty","label_ar":"عناصر DELTA لدى ماكنزي · القيادة الذاتية · التعامل مع عدم اليقين"},{"framework":"ssg_ccs","benchmark_id":"SSG-SF","ref":"TC","label_en":"SkillsFuture Critical Core Skills · Thinking Critically cluster","label_ar":"المهارات الأساسية الحرجة في SkillsFuture · مجموعة التفكير النقدي"}]'::jsonb, array['IAEA-1917','MCK-DELTA','SSG-SF']::text[], array['trait-5']::text[], array['sk-ld-02','sk-ld-02-decide']::text[], '[{"kind":"page","ref":"/my/simulator","title_en":"Simulator scenarios with uncertain indications and a decision debrief","title_ar":"سيناريوهات المحاكي بمؤشرات غير مؤكدة مع مراجعة للقرار"},{"kind":"ojt","ref":"decision-meetings","title_en":"Shadow the shift manager''s operational decision meetings","title_ar":"مرافقة مدير الوردية في اجتماعات القرارات التشغيلية"},{"kind":"practice","ref":"cs-conservative","title_en":"Situational judgement practice for this skill","title_ar":"تمارين الحكم الظرفي لهذه المهارة"}]'::jsonb, '[{"kind":"simulator","ref":"/my/simulator","title_en":"Decision scoring in the simulator debrief","title_ar":"تقييم القرار في مراجعة ما بعد المحاكي"},{"kind":"sjt","ref":"cs-conservative","title_en":"Situational judgement practice result (development only)","title_ar":"نتيجة تمارين الحكم الظرفي (للتطوير فقط)"}]'::jsonb, 'Simulator scenarios with uncertain indications and a decision debrief, and shadowing real decision meetings.', 'سيناريوهات المحاكي بمؤشرات غير مؤكدة مع مراجعة للقرار، ومرافقة اجتماعات القرارات الفعلية.', 'The decision is scored in the simulator debrief, plus scenario practice.', 'يُقيَّم القرار في مراجعة ما بعد المحاكي، إضافة إلى تمارين السيناريوهات.', '', '', '[{"label":"SkillsFuture Singapore · Factsheet on top skills trends in 2025 (Critical Core Skills)","url":"https://isomer-user-content.by.gov.sg/41/4955bc61-161d-4584-945c-7eeeb276867a/Factsheet%20on%20Top%20skills%20trends%20in%202025.pdf","as_of":"2026-10-10"},{"label":"IAEA-TECDOC-1917 · Assessing behavioural competencies of employees in nuclear facilities","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1917_web.pdf","as_of":"2026-10-10"},{"label":"McKinsey · Defining the skills citizens will need in the future world of work (DELTAs)","url":"https://www.mckinsey.com/industries/public-and-social-sector/our-insights/defining-the-skills-citizens-will-need-in-the-future-world-of-work","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 102),
('cs-procedure', 'TC-3', 'thinking_critically', 'Procedure use and knowing when to stop', 'استخدام الإجراءات ومعرفة متى تتوقف', 'Follows procedures as written, keeps place, and stops when a step cannot be done as written or the result is not what the procedure expects.', 'يتّبع الإجراءات كما هي مكتوبة، ويتتبّع موضعه فيها، ويتوقف عندما يتعذّر تنفيذ خطوة كما كُتبت أو عندما تختلف النتيجة عمّا يتوقعه الإجراء.', 'Stops at a step whose expected pump response does not occur, places the system in a safe condition and calls the supervisor.', 'يتوقف عند خطوة لا تحدث فيها استجابة المضخة المتوقعة، ويضع النظام في حالة آمنة ويتصل بالمشرف.', '[{"level":1,"en":"Uses the procedure in hand, marks each step and knows the stop criteria.","ar":"يستخدم الإجراء بين يديه ويؤشّر كل خطوة ويعرف معايير التوقف."},{"level":2,"en":"Recognises when a procedure no longer fits the situation and stops with the plant safe.","ar":"يدرك متى لم يعد الإجراء مناسباً للموقف ويتوقف مع إبقاء المحطة آمنة."},{"level":3,"en":"Coaches others in procedure use and feeds procedure problems back so they are fixed.","ar":"يدرّب الآخرين على استخدام الإجراءات ويرفع مشكلاتها كي تُعالَج."}]'::jsonb, '[{"framework":"inpo","benchmark_id":null,"ref":"trait-10","label_en":"INPO safety-culture trait · Work processes (M08)","label_ar":"سمة ثقافة السلامة لدى INPO · إجراءات العمل (M08)"},{"framework":"iaea_1917","benchmark_id":"IAEA-1917","ref":null,"label_en":"IAEA-TECDOC-1917 behavioural competency · error prevention","label_ar":"الكفاءة السلوكية في IAEA-TECDOC-1917 · منع الأخطاء"},{"framework":"wef","benchmark_id":"WEF-FOJ","ref":null,"label_en":"WEF core skill · dependability and attention to detail","label_ar":"مهارة أساسية لدى المنتدى الاقتصادي العالمي · الاعتمادية والاهتمام بالتفاصيل"},{"framework":"ssg_ccs","benchmark_id":"SSG-SF","ref":"TC","label_en":"SkillsFuture Critical Core Skills · Thinking Critically cluster","label_ar":"المهارات الأساسية الحرجة في SkillsFuture · مجموعة التفكير النقدي"}]'::jsonb, array['IAEA-1917','SSG-SF','WEF-FOJ']::text[], array['trait-10']::text[], array['sk-co-01','sk-hu-01-star']::text[], '[{"kind":"course","ref":"c-hu","title_en":"Human performance core tools","title_ar":"الأدوات الأساسية للأداء البشري"},{"kind":"ojt","ref":"place-keeping","title_en":"Supervised place-keeping on real procedures","title_ar":"تتبّع الموضع تحت الإشراف في إجراءات حقيقية"},{"kind":"practice","ref":"cs-procedure","title_en":"Situational judgement practice for this skill","title_ar":"تمارين الحكم الظرفي لهذه المهارة"}]'::jsonb, '[{"kind":"observation","ref":"procedure-use","title_en":"Field observation of procedure use against the stop criteria","title_ar":"ملاحظة ميدانية لاستخدام الإجراءات مقابل معايير التوقف"},{"kind":"sjt","ref":"cs-procedure","title_en":"Situational judgement practice result (development only)","title_ar":"نتيجة تمارين الحكم الظرفي (للتطوير فقط)"}]'::jsonb, 'HU tools training and supervised place-keeping on real procedures.', 'تدريب على أدوات الأداء البشري وتتبّع الموضع تحت الإشراف في إجراءات حقيقية.', 'Field observation of procedure use against the stop criteria.', 'ملاحظة ميدانية لاستخدام الإجراءات مقابل معايير التوقف.', '', '', '[{"label":"SkillsFuture Singapore · Factsheet on top skills trends in 2025 (Critical Core Skills)","url":"https://isomer-user-content.by.gov.sg/41/4955bc61-161d-4584-945c-7eeeb276867a/Factsheet%20on%20Top%20skills%20trends%20in%202025.pdf","as_of":"2026-10-10"},{"label":"IAEA-TECDOC-1917 · Assessing behavioural competencies of employees in nuclear facilities","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1917_web.pdf","as_of":"2026-10-10"},{"label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 103),
('cs-systems', 'TC-4', 'thinking_critically', 'Systems thinking', 'التفكير المنظومي', 'Sees how a change in one system, task or team affects others, including through the plant''s defence in depth.', 'يرى كيف يؤثر تغيير في نظام أو مهمة أو فريق على غيره، بما في ذلك عبر مستويات الدفاع في العمق في المحطة.', 'Before an isolation, checks which other systems share the power supply and who else is working on them.', 'قبل العزل، يتحقق من الأنظمة الأخرى التي تتشارك مصدر الطاقة نفسه ومن يعمل عليها.', '[{"level":1,"en":"Knows the main interfaces of their own system and asks about effects outside it.","ar":"يعرف الواجهات الرئيسية لنظامه ويسأل عن الآثار خارجه."},{"level":2,"en":"Traces knock-on effects across systems and teams before acting, and records them.","ar":"يتتبّع الآثار المتسلسلة عبر الأنظمة والفرق قبل التصرف ويوثّقها."},{"level":3,"en":"Leads cross-discipline reviews that expose hidden couplings.","ar":"يقود مراجعات متعددة التخصصات تكشف الترابطات الخفية."}]'::jsonb, '[{"framework":"wef","benchmark_id":"WEF-FOJ","ref":null,"label_en":"WEF core skill · systems thinking","label_ar":"مهارة أساسية لدى المنتدى الاقتصادي العالمي · التفكير المنظومي"},{"framework":"greencomp","benchmark_id":"GREENCOMP","ref":null,"label_en":"GreenComp · embracing complexity in sustainability","label_ar":"إطار GreenComp · استيعاب التعقيد في الاستدامة"},{"framework":"delta","benchmark_id":"MCK-DELTA","ref":null,"label_en":"McKinsey DELTA · cognitive skills","label_ar":"عناصر DELTA لدى ماكنزي · المهارات المعرفية"},{"framework":"ssg_ccs","benchmark_id":"SSG-SF","ref":"TC","label_en":"SkillsFuture Critical Core Skills · Thinking Critically cluster","label_ar":"المهارات الأساسية الحرجة في SkillsFuture · مجموعة التفكير النقدي"}]'::jsonb, array['GREENCOMP','MCK-DELTA','SSG-SF','WEF-FOJ']::text[], '{}'::text[], array['sk-fs-tr-systems','sk-ns-01']::text[], '[{"kind":"page","ref":"/communities","title_en":"A system-engineering community of practice","title_ar":"مجتمع ممارسة لهندسة الأنظمة"},{"kind":"page","ref":"/opportunities/rotations","title_en":"A rotation through another discipline","title_ar":"تناوب في تخصص آخر"},{"kind":"practice","ref":"cs-systems","title_en":"Situational judgement practice for this skill","title_ar":"تمارين الحكم الظرفي لهذه المهارة"}]'::jsonb, '[{"kind":"checkin","ref":"/my/skills/checkins","title_en":"Skill check-in with peers and your manager","title_ar":"تقييم دوري للمهارة مع الزملاء ومديرك"},{"kind":"sjt","ref":"cs-systems","title_en":"Situational judgement practice result (development only)","title_ar":"نتيجة تمارين الحكم الظرفي (للتطوير فقط)"}]'::jsonb, 'Cross-system walkdowns, a community of practice and a rotation through another discipline.', 'جولات ميدانية عبر الأنظمة، ومجتمع ممارسة، وتناوب في تخصص آخر.', 'Check-in ratings on interfaces traced in real work.', 'تقييمات دورية لتتبّع الواجهات في العمل الفعلي.', '', '', '[{"label":"SkillsFuture Singapore · Factsheet on top skills trends in 2025 (Critical Core Skills)","url":"https://isomer-user-content.by.gov.sg/41/4955bc61-161d-4584-945c-7eeeb276867a/Factsheet%20on%20Top%20skills%20trends%20in%202025.pdf","as_of":"2026-10-10"},{"label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"},{"label":"European Commission JRC · GreenComp, with EntreComp and LifeComp","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"label":"McKinsey · Defining the skills citizens will need in the future world of work (DELTAs)","url":"https://www.mckinsey.com/industries/public-and-social-sector/our-insights/defining-the-skills-citizens-will-need-in-the-future-world-of-work","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 104),
('cs-problem', 'TC-5', 'thinking_critically', 'Problem identification and resolution', 'تحديد المشكلات وحلها', 'Spots problems early, reports them in the corrective action programme, looks for causes rather than symptoms and checks the fix worked.', 'يكتشف المشكلات مبكراً ويبلغ عنها في برنامج الإجراءات التصحيحية، ويبحث عن الأسباب لا الأعراض، ويتحقق من نجاح الإصلاح.', 'Raises a condition report for a recurring alarm and joins the cause evaluation instead of resetting it each shift.', 'يرفع تقرير حالة عن إنذار متكرر وينضم إلى تقييم السبب بدلاً من إعادة ضبطه في كل وردية.', '[{"level":1,"en":"Reports problems promptly and clearly, with the facts.","ar":"يبلغ عن المشكلات فوراً وبوضوح مع الوقائع."},{"level":2,"en":"Uses structured cause analysis and checks whether actions worked.","ar":"يستخدم تحليلاً منظماً للأسباب ويتحقق من فعالية الإجراءات."},{"level":3,"en":"Leads cause evaluations and spots trends across reports.","ar":"يقود تقييمات الأسباب ويرصد الاتجاهات عبر التقارير."}]'::jsonb, '[{"framework":"inpo","benchmark_id":null,"ref":"trait-8","label_en":"INPO safety-culture trait · Problem identification and resolution (M08)","label_ar":"سمة ثقافة السلامة لدى INPO · تحديد المشكلات وحلها (M08)"},{"framework":"wef","benchmark_id":"WEF-FOJ","ref":null,"label_en":"WEF core skill · analytical thinking","label_ar":"مهارة أساسية لدى المنتدى الاقتصادي العالمي · التفكير التحليلي"},{"framework":"delta","benchmark_id":"MCK-DELTA","ref":null,"label_en":"McKinsey DELTA · cognitive skills","label_ar":"عناصر DELTA لدى ماكنزي · المهارات المعرفية"},{"framework":"ssg_ccs","benchmark_id":"SSG-SF","ref":"TC","label_en":"SkillsFuture Critical Core Skills · Thinking Critically cluster","label_ar":"المهارات الأساسية الحرجة في SkillsFuture · مجموعة التفكير النقدي"}]'::jsonb, array['MCK-DELTA','SSG-SF','WEF-FOJ']::text[], array['trait-8']::text[], array['sk-fs-tr-analytical','sk-da-01-analysis']::text[], '[{"kind":"page","ref":"/oe","title_en":"Operating experience and cause evaluations","title_ar":"الخبرة التشغيلية وتقييمات الأسباب"},{"kind":"ojt","ref":"cause-evaluation","title_en":"Join a cause evaluation with a qualified lead","title_ar":"المشاركة في تقييم للأسباب بقيادة مؤهلة"},{"kind":"practice","ref":"cs-problem","title_en":"Situational judgement practice for this skill","title_ar":"تمارين الحكم الظرفي لهذه المهارة"}]'::jsonb, '[{"kind":"checkin","ref":"/my/skills/checkins","title_en":"Skill check-in with peers and your manager","title_ar":"تقييم دوري للمهارة مع الزملاء ومديرك"},{"kind":"observation","ref":"cause-review","title_en":"Review of condition reports and cause work","title_ar":"مراجعة تقارير الحالة وأعمال تحليل الأسباب"},{"kind":"sjt","ref":"cs-problem","title_en":"Situational judgement practice result (development only)","title_ar":"نتيجة تمارين الحكم الظرفي (للتطوير فقط)"}]'::jsonb, 'Taking part in a cause evaluation with a qualified lead.', 'المشاركة في تقييم للأسباب بقيادة مؤهلة.', 'Review of the person''s condition reports and cause work in check-ins.', 'مراجعة تقارير الحالة وأعمال تحليل الأسباب التي أعدّها في التقييمات الدورية.', '', '', '[{"label":"SkillsFuture Singapore · Factsheet on top skills trends in 2025 (Critical Core Skills)","url":"https://isomer-user-content.by.gov.sg/41/4955bc61-161d-4584-945c-7eeeb276867a/Factsheet%20on%20Top%20skills%20trends%20in%202025.pdf","as_of":"2026-10-10"},{"label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"},{"label":"McKinsey · Defining the skills citizens will need in the future world of work (DELTAs)","url":"https://www.mckinsey.com/industries/public-and-social-sector/our-insights/defining-the-skills-citizens-will-need-in-the-future-world-of-work","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 105),
('cs-creative', 'TC-6', 'thinking_critically', 'Creative thinking and improvement', 'التفكير الإبداعي والتحسين', 'Proposes better ways of working and tests them through the proper change process, never by improvising on plant.', 'يقترح طرق عمل أفضل ويختبرها عبر عملية التغيير المعتمدة، ولا يرتجل أبداً في المحطة.', 'Suggests a clearer outage turnover sheet, pilots it with one crew and submits it through document control.', 'يقترح نموذجاً أوضح لتسليم العمل أثناء الانقطاع، ويجرّبه مع طاقم واحد، ويقدّمه عبر ضبط الوثائق.', '[{"level":1,"en":"Shares improvement ideas through the suggestion channel.","ar":"يشارك أفكار التحسين عبر قناة المقترحات."},{"level":2,"en":"Develops an idea with evidence and takes it through the change process.","ar":"يطوّر فكرة بالأدلة ويمضي بها عبر عملية التغيير."},{"level":3,"en":"Runs small, safe pilots and helps others turn ideas into approved changes.","ar":"يدير تجارب صغيرة آمنة ويساعد الآخرين على تحويل الأفكار إلى تغييرات معتمدة."}]'::jsonb, '[{"framework":"wef","benchmark_id":"WEF-FOJ","ref":null,"label_en":"WEF core skill · creative thinking","label_ar":"مهارة أساسية لدى المنتدى الاقتصادي العالمي · التفكير الإبداعي"},{"framework":"entrecomp","benchmark_id":"GREENCOMP","ref":null,"label_en":"EntreComp · ideas, resources, into action","label_ar":"إطار EntreComp · الأفكار والموارد والتنفيذ"},{"framework":"ssg_ccs","benchmark_id":"SSG-SF","ref":"TC","label_en":"SkillsFuture Critical Core Skills · Thinking Critically cluster","label_ar":"المهارات الأساسية الحرجة في SkillsFuture · مجموعة التفكير النقدي"}]'::jsonb, array['GREENCOMP','SSG-SF','WEF-FOJ']::text[], '{}'::text[], array['sk-fs-tr-creative']::text[], '[{"kind":"page","ref":"/opportunities","title_en":"An improvement project through the opportunity marketplace","title_ar":"مشروع تحسين عبر سوق الفرص"},{"kind":"practice","ref":"cs-creative","title_en":"Situational judgement practice for this skill","title_ar":"تمارين الحكم الظرفي لهذه المهارة"}]'::jsonb, '[{"kind":"observation","ref":"improvement-review","title_en":"Review of an improvement proposal and its outcome","title_ar":"مراجعة مقترح تحسين ونتيجته"},{"kind":"sjt","ref":"cs-creative","title_en":"Situational judgement practice result (development only)","title_ar":"نتيجة تمارين الحكم الظرفي (للتطوير فقط)"}]'::jsonb, 'An improvement project through the opportunity marketplace, with a mentor.', 'مشروع تحسين عبر سوق الفرص بإرشاد موجّه.', 'Review of the improvement proposal and its outcome.', 'مراجعة مقترح التحسين ونتيجته.', '', '', '[{"label":"SkillsFuture Singapore · Factsheet on top skills trends in 2025 (Critical Core Skills)","url":"https://isomer-user-content.by.gov.sg/41/4955bc61-161d-4584-945c-7eeeb276867a/Factsheet%20on%20Top%20skills%20trends%20in%202025.pdf","as_of":"2026-10-10"},{"label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"},{"label":"European Commission JRC · GreenComp, with EntreComp and LifeComp","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 106),
('cs-peer-check', 'IO-1', 'interacting_with_others', 'Peer checking and team error prevention', 'التحقق المتبادل ومنع أخطاء الفريق', 'Checks a colleague''s critical step before it happens, independently, and accepts the same check without taking it personally.', 'يتحقق من الخطوة الحرجة لزميله قبل تنفيذها وبشكل مستقل، ويتقبّل التحقق نفسه دون أن يأخذه على محمل شخصي.', 'Before a breaker is racked out, the second technician confirms the component ID and the expected result aloud from their own copy.', 'قبل سحب القاطع، يؤكد الفني الثاني رقم المكوّن والنتيجة المتوقعة بصوت مسموع من نسخته الخاصة.', '[{"level":1,"en":"Asks for and gives peer checks on critical steps.","ar":"يطلب التحقق من الزملاء ويقدّمه في الخطوات الحرجة."},{"level":2,"en":"Peer-checks independently: own eyes, own reference, never the colleague''s assumption.","ar":"يتحقق بشكل مستقل: بعينيه ومرجعه الخاص، لا بافتراض زميله."},{"level":3,"en":"Makes peer checking normal across crews and coaches it after events.","ar":"يجعل التحقق المتبادل ممارسة طبيعية بين الأطقم ويدرّب عليه بعد الأحداث."}]'::jsonb, '[{"framework":"iaea_1917","benchmark_id":"IAEA-1917","ref":null,"label_en":"IAEA-TECDOC-1917 behavioural competency · error prevention","label_ar":"الكفاءة السلوكية في IAEA-TECDOC-1917 · منع الأخطاء"},{"framework":"delta","benchmark_id":"MCK-DELTA","ref":null,"label_en":"McKinsey DELTA · interpersonal · teamwork effectiveness","label_ar":"عناصر DELTA لدى ماكنزي · المهارات الشخصية · فعالية العمل الجماعي"},{"framework":"ssg_ccs","benchmark_id":"SSG-SF","ref":"IO","label_en":"SkillsFuture Critical Core Skills · Interacting with Others cluster","label_ar":"المهارات الأساسية الحرجة في SkillsFuture · مجموعة التفاعل مع الآخرين"}]'::jsonb, array['IAEA-1917','MCK-DELTA','SSG-SF']::text[], '{}'::text[], array['sk-hu-01','sk-hu-02-brief']::text[], '[{"kind":"course","ref":"c-hu-ref","title_en":"HU tools refresher","title_ar":"تنشيط أدوات الأداء البشري"},{"kind":"ojt","ref":"peer-pairing","title_en":"Paired peer-check practice on shift","title_ar":"تمرين ثنائي على التحقق المتبادل أثناء الوردية"},{"kind":"practice","ref":"cs-peer-check","title_en":"Situational judgement practice for this skill","title_ar":"تمارين الحكم الظرفي لهذه المهارة"}]'::jsonb, '[{"kind":"checkin","ref":"/my/skills/checkins","title_en":"Skill check-in with peers and your manager","title_ar":"تقييم دوري للمهارة مع الزملاء ومديرك"},{"kind":"observation","ref":"peer-check","title_en":"Observed peer checks in the field","title_ar":"تحقق متبادل ملاحظ في الميدان"},{"kind":"sjt","ref":"cs-peer-check","title_en":"Situational judgement practice result (development only)","title_ar":"نتيجة تمارين الحكم الظرفي (للتطوير فقط)"}]'::jsonb, 'Paired practice of peer checks on real critical steps, with feedback.', 'تمرين ثنائي على التحقق المتبادل في خطوات حرجة حقيقية مع تغذية راجعة.', 'Observation of peer checks in the field by a qualified observer.', 'ملاحظة التحقق المتبادل في الميدان من قِبل ملاحظ مؤهل.', '', '', '[{"label":"SkillsFuture Singapore · Factsheet on top skills trends in 2025 (Critical Core Skills)","url":"https://isomer-user-content.by.gov.sg/41/4955bc61-161d-4584-945c-7eeeb276867a/Factsheet%20on%20Top%20skills%20trends%20in%202025.pdf","as_of":"2026-10-10"},{"label":"IAEA-TECDOC-1917 · Assessing behavioural competencies of employees in nuclear facilities","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1917_web.pdf","as_of":"2026-10-10"},{"label":"McKinsey · Defining the skills citizens will need in the future world of work (DELTAs)","url":"https://www.mckinsey.com/industries/public-and-social-sector/our-insights/defining-the-skills-citizens-will-need-in-the-future-world-of-work","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 207),
('cs-comm-stress', 'IO-2', 'interacting_with_others', 'Communication under stress', 'التواصل تحت الضغط', 'Keeps communication clear, closed-loop and calm when time is short and the situation is changing.', 'يحافظ على تواصل واضح ومغلق الحلقة وهادئ عندما يضيق الوقت ويتغيّر الموقف.', 'During an unplanned transient, repeats back each order, uses the phonetic alphabet and confirms completion.', 'أثناء حالة عابرة غير مخطط لها، يكرّر كل أمر ويستخدم الأبجدية الصوتية ويؤكد الإنجاز.', '[{"level":1,"en":"Uses three-way communication and the phonetic alphabet.","ar":"يستخدم التواصل ثلاثي الاتجاه والأبجدية الصوتية."},{"level":2,"en":"Keeps messages short, specific and confirmed when pressure rises.","ar":"يبقي الرسائل قصيرة ومحددة ومؤكدة عند تصاعد الضغط."},{"level":3,"en":"Sets the communication rhythm for a team in an event and corrects drift.","ar":"يضبط إيقاع التواصل للفريق أثناء الحدث ويصحّح الانحراف."}]'::jsonb, '[{"framework":"inpo","benchmark_id":null,"ref":"trait-3","label_en":"INPO safety-culture trait · Effective safety communication (M08)","label_ar":"سمة ثقافة السلامة لدى INPO · التواصل الفعّال بشأن السلامة (M08)"},{"framework":"delta","benchmark_id":"MCK-DELTA","ref":null,"label_en":"McKinsey DELTA · interpersonal · communication","label_ar":"عناصر DELTA لدى ماكنزي · المهارات الشخصية · التواصل"},{"framework":"iaea_1917","benchmark_id":"IAEA-1917","ref":null,"label_en":"IAEA-TECDOC-1917 behavioural competency · teamwork and communication","label_ar":"الكفاءة السلوكية في IAEA-TECDOC-1917 · العمل الجماعي والتواصل"},{"framework":"ssg_ccs","benchmark_id":"SSG-SF","ref":"IO","label_en":"SkillsFuture Critical Core Skills · Interacting with Others cluster","label_ar":"المهارات الأساسية الحرجة في SkillsFuture · مجموعة التفاعل مع الآخرين"}]'::jsonb, array['IAEA-1917','MCK-DELTA','SSG-SF']::text[], array['trait-3']::text[], array['sk-co-02','sk-hu-02']::text[], '[{"kind":"page","ref":"/my/simulator","title_en":"Crew simulator scenarios with communication coaching","title_ar":"سيناريوهات المحاكي للأطقم مع تدريب على التواصل"},{"kind":"ojt","ref":"drill-communicator","title_en":"Take the communicator role in emergency drills","title_ar":"تولي دور المتواصل في تمارين الطوارئ"},{"kind":"practice","ref":"cs-comm-stress","title_en":"Situational judgement practice for this skill","title_ar":"تمارين الحكم الظرفي لهذه المهارة"}]'::jsonb, '[{"kind":"simulator","ref":"/my/simulator","title_en":"Communication scoring in the simulator debrief","title_ar":"تقييم التواصل في مراجعة ما بعد المحاكي"},{"kind":"observation","ref":"drill-debrief","title_en":"Drill debrief on communication","title_ar":"مراجعة التمرين بشأن التواصل"},{"kind":"sjt","ref":"cs-comm-stress","title_en":"Situational judgement practice result (development only)","title_ar":"نتيجة تمارين الحكم الظرفي (للتطوير فقط)"}]'::jsonb, 'Crew simulator scenarios and drills with communication coaching.', 'سيناريوهات المحاكي للأطقم والتمارين مع تدريب على التواصل.', 'Communication scoring in simulator and drill debriefs.', 'تقييم التواصل في مراجعات المحاكي والتمارين.', '', '', '[{"label":"SkillsFuture Singapore · Factsheet on top skills trends in 2025 (Critical Core Skills)","url":"https://isomer-user-content.by.gov.sg/41/4955bc61-161d-4584-945c-7eeeb276867a/Factsheet%20on%20Top%20skills%20trends%20in%202025.pdf","as_of":"2026-10-10"},{"label":"IAEA-TECDOC-1917 · Assessing behavioural competencies of employees in nuclear facilities","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1917_web.pdf","as_of":"2026-10-10"},{"label":"McKinsey · Defining the skills citizens will need in the future world of work (DELTAs)","url":"https://www.mckinsey.com/industries/public-and-social-sector/our-insights/defining-the-skills-citizens-will-need-in-the-future-world-of-work","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 208),
('cs-speak-up', 'IO-3', 'interacting_with_others', 'Raising concerns and speaking up', 'طرح المخاوف والتحدث بصراحة', 'Raises safety and quality concerns promptly through the right channel, and listens well when others raise them.', 'يطرح مخاوف السلامة والجودة فوراً عبر القناة الصحيحة، ويصغي جيداً عندما يطرحها الآخرون.', 'Tells the supervisor that a contractor team skipped a pre-job brief, and uses the corrective action programme if it recurs. Kafa''a never takes concerns; the Employee Concerns Program does.', 'يبلغ المشرف بأن فريق مقاول تجاوز إحاطة ما قبل العمل، ويستخدم برنامج الإجراءات التصحيحية إن تكرر ذلك. لا تتلقى كفاءة أي مخاوف؛ فذلك دور برنامج مخاوف الموظفين.', '[{"level":1,"en":"Knows the channels, including the Employee Concerns Program, and uses them.","ar":"يعرف القنوات، ومنها برنامج مخاوف الموظفين، ويستخدمها."},{"level":2,"en":"Raises concerns clearly and early, with facts, and follows up.","ar":"يطرح المخاوف بوضوح ومبكراً مع الوقائع ويتابعها."},{"level":3,"en":"Responds to concerns in a way that makes others more willing to speak.","ar":"يستجيب للمخاوف بطريقة تشجّع الآخرين على التحدث."}]'::jsonb, '[{"framework":"inpo","benchmark_id":null,"ref":"trait-9","label_en":"INPO safety-culture trait · Environment for raising concerns (M08)","label_ar":"سمة ثقافة السلامة لدى INPO · بيئة طرح المخاوف (M08)"},{"framework":"iaea_1917","benchmark_id":"IAEA-1917","ref":null,"label_en":"IAEA-TECDOC-1917 behavioural competency · safety culture behaviours","label_ar":"الكفاءة السلوكية في IAEA-TECDOC-1917 · سلوكيات ثقافة السلامة"},{"framework":"ssg_ccs","benchmark_id":"SSG-SF","ref":"IO","label_en":"SkillsFuture Critical Core Skills · Interacting with Others cluster","label_ar":"المهارات الأساسية الحرجة في SkillsFuture · مجموعة التفاعل مع الآخرين"}]'::jsonb, array['IAEA-1917','SSG-SF']::text[], array['trait-9']::text[], array['sk-sc-01','sk-sc-02']::text[], '[{"kind":"course","ref":"c-scwe","title_en":"Safety-conscious work environment","title_ar":"بيئة العمل الواعية بالسلامة"},{"kind":"page","ref":"/my/safety-culture","title_en":"Team discussions of the safety-culture traits","title_ar":"نقاشات الفريق حول سمات ثقافة السلامة"},{"kind":"practice","ref":"cs-speak-up","title_en":"Situational judgement practice for this skill","title_ar":"تمارين الحكم الظرفي لهذه المهارة"}]'::jsonb, '[{"kind":"checkin","ref":"/my/skills/checkins","title_en":"Skill check-in with peers and your manager","title_ar":"تقييم دوري للمهارة مع الزملاء ومديرك"},{"kind":"sjt","ref":"cs-speak-up","title_en":"Situational judgement practice result (development only)","title_ar":"نتيجة تمارين الحكم الظرفي (للتطوير فقط)"}]'::jsonb, 'Safety-conscious work environment training and team discussions of the safety-culture traits.', 'تدريب على بيئة العمل الواعية بالسلامة ونقاشات الفريق حول سمات ثقافة السلامة.', 'A check-in discussion of how the person raises and responds to concerns; concern content is never recorded here.', 'نقاش في التقييم الدوري حول كيفية طرح المخاوف والاستجابة لها؛ ولا يُسجَّل مضمون أي مخاوف هنا أبداً.', '', '', '[{"label":"SkillsFuture Singapore · Factsheet on top skills trends in 2025 (Critical Core Skills)","url":"https://isomer-user-content.by.gov.sg/41/4955bc61-161d-4584-945c-7eeeb276867a/Factsheet%20on%20Top%20skills%20trends%20in%202025.pdf","as_of":"2026-10-10"},{"label":"IAEA-TECDOC-1917 · Assessing behavioural competencies of employees in nuclear facilities","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/TE-1917_web.pdf","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 209),
('cs-cross-cultural', 'IO-4', 'interacting_with_others', 'Working across cultures', 'العمل عبر الثقافات', 'Works effectively with colleagues and partners of many nationalities and organisations, checking understanding rather than assuming it.', 'يعمل بفعالية مع زملاء وشركاء من جنسيات ومؤسسات متعددة، ويتحقق من الفهم بدلاً من افتراضه.', 'In a handover with a partner-company engineer, confirms technical terms in both languages and writes down the agreed actions.', 'في تسليم مع مهندس من شركة شريكة، يؤكد المصطلحات الفنية باللغتين ويدوّن الإجراءات المتفق عليها.', '[{"level":1,"en":"Respects different working styles and checks shared understanding.","ar":"يحترم أساليب العمل المختلفة ويتحقق من الفهم المشترك."},{"level":2,"en":"Adapts how they communicate and decide to the team in front of them.","ar":"يكيّف أسلوب تواصله واتخاذ قراراته مع الفريق الذي أمامه."},{"level":3,"en":"Builds mixed teams where knowledge transfers both ways.","ar":"يبني فرقاً مختلطة تنتقل فيها المعرفة في الاتجاهين."}]'::jsonb, '[{"framework":"inpo","benchmark_id":null,"ref":"trait-6","label_en":"INPO safety-culture trait · Respectful work environment (M08)","label_ar":"سمة ثقافة السلامة لدى INPO · بيئة عمل قائمة على الاحترام (M08)"},{"framework":"lifecomp","benchmark_id":"GREENCOMP","ref":null,"label_en":"LifeComp · empathy","label_ar":"إطار LifeComp · التعاطف"},{"framework":"wef","benchmark_id":"WEF-FOJ","ref":null,"label_en":"WEF core skill · empathy and active listening","label_ar":"مهارة أساسية لدى المنتدى الاقتصادي العالمي · التعاطف والإصغاء الفعّال"},{"framework":"ssg_ccs","benchmark_id":"SSG-SF","ref":"IO","label_en":"SkillsFuture Critical Core Skills · Interacting with Others cluster","label_ar":"المهارات الأساسية الحرجة في SkillsFuture · مجموعة التفاعل مع الآخرين"}]'::jsonb, array['GREENCOMP','SSG-SF','WEF-FOJ']::text[], array['trait-6']::text[], array['sk-fs-tr-crosscultural','sk-fs-tr-empathy']::text[], '[{"kind":"page","ref":"/my/mentoring","title_en":"Cross-organisation mentoring","title_ar":"الإرشاد بين المؤسسات"},{"kind":"ojt","ref":"knowledge-transfer","title_en":"Structured knowledge-transfer handovers with partner engineers","title_ar":"عمليات تسليم منظّمة لنقل المعرفة مع مهندسي الشركاء"},{"kind":"practice","ref":"cs-cross-cultural","title_en":"Situational judgement practice for this skill","title_ar":"تمارين الحكم الظرفي لهذه المهارة"}]'::jsonb, '[{"kind":"checkin","ref":"/my/skills/checkins","title_en":"Skill check-in with peers and your manager","title_ar":"تقييم دوري للمهارة مع الزملاء ومديرك"},{"kind":"sjt","ref":"cs-cross-cultural","title_en":"Situational judgement practice result (development only)","title_ar":"نتيجة تمارين الحكم الظرفي (للتطوير فقط)"},{"kind":"observation","ref":"mixed-team-feedback","title_en":"Feedback from mixed-team colleagues","title_ar":"تغذية راجعة من زملاء الفرق المختلطة"}]'::jsonb, 'Cross-organisation mentoring and structured knowledge-transfer handovers.', 'إرشاد بين المؤسسات وعمليات تسليم منظّمة لنقل المعرفة.', 'Feedback from mixed-team colleagues in check-ins.', 'تغذية راجعة من زملاء الفرق المختلطة في التقييمات الدورية.', '', '', '[{"label":"SkillsFuture Singapore · Factsheet on top skills trends in 2025 (Critical Core Skills)","url":"https://isomer-user-content.by.gov.sg/41/4955bc61-161d-4584-945c-7eeeb276867a/Factsheet%20on%20Top%20skills%20trends%20in%202025.pdf","as_of":"2026-10-10"},{"label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"},{"label":"European Commission JRC · GreenComp, with EntreComp and LifeComp","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 210),
('cs-developing', 'IO-5', 'interacting_with_others', 'Developing others', 'تطوير الآخرين', 'Helps colleagues grow through coaching, feedback and sharing what they know, so knowledge does not sit with one person.', 'يساعد زملاءه على النمو عبر التوجيه والتغذية الراجعة ومشاركة ما يعرفه، كي لا تبقى المعرفة لدى شخص واحد.', 'Talks a new operator through a system walkdown and asks them to explain it back.', 'يرافق مشغّلاً جديداً في جولة على نظام ما ويطلب منه أن يشرحه بدوره.', '[{"level":1,"en":"Shares know-how willingly when asked.","ar":"يشارك خبرته عن طيب خاطر عندما يُطلب منه."},{"level":2,"en":"Gives specific, timely feedback and coaches on the job.","ar":"يقدّم تغذية راجعة محددة وفي وقتها ويوجّه أثناء العمل."},{"level":3,"en":"Builds a pipeline of successors and teaches others to coach.","ar":"يبني صفاً من الخلفاء ويعلّم الآخرين التوجيه."}]'::jsonb, '[{"framework":"inpo","benchmark_id":null,"ref":"trait-4","label_en":"INPO safety-culture trait · Leadership safety values and actions (M08)","label_ar":"سمة ثقافة السلامة لدى INPO · قيم القيادة وأفعالها في السلامة (M08)"},{"framework":"wef","benchmark_id":"WEF-FOJ","ref":null,"label_en":"WEF core skill · leadership and social influence","label_ar":"مهارة أساسية لدى المنتدى الاقتصادي العالمي · القيادة والتأثير الاجتماعي"},{"framework":"delta","benchmark_id":"MCK-DELTA","ref":null,"label_en":"McKinsey DELTA · interpersonal skills","label_ar":"عناصر DELTA لدى ماكنزي · المهارات الشخصية"},{"framework":"ssg_ccs","benchmark_id":"SSG-SF","ref":"IO","label_en":"SkillsFuture Critical Core Skills · Interacting with Others cluster","label_ar":"المهارات الأساسية الحرجة في SkillsFuture · مجموعة التفاعل مع الآخرين"}]'::jsonb, array['MCK-DELTA','SSG-SF','WEF-FOJ']::text[], array['trait-4']::text[], array['sk-ld-01','sk-ld-01-coach','sk-fs-tr-leadership']::text[], '[{"kind":"course","ref":"c-intilaqa","title_en":"INTILAQA: Leading Effective Teams","title_ar":"انطلاقة: قيادة الفرق الفعّالة"},{"kind":"page","ref":"/leadership","title_en":"Leadership programmes and mentoring others","title_ar":"برامج القيادة وإرشاد الآخرين"},{"kind":"practice","ref":"cs-developing","title_en":"Situational judgement practice for this skill","title_ar":"تمارين الحكم الظرفي لهذه المهارة"}]'::jsonb, '[{"kind":"360","ref":"/leadership/360","title_en":"Leadership 360 feedback","title_ar":"تقييم القيادة 360 درجة"},{"kind":"checkin","ref":"/my/skills/checkins","title_en":"Skill check-in with peers and your manager","title_ar":"تقييم دوري للمهارة مع الزملاء ومديرك"},{"kind":"sjt","ref":"cs-developing","title_en":"Situational judgement practice result (development only)","title_ar":"نتيجة تمارين الحكم الظرفي (للتطوير فقط)"}]'::jsonb, 'Leading Effective Teams and serving as a mentor.', 'برنامج قيادة الفرق الفعّالة والعمل موجّهاً.', 'Leadership 360 feedback and mentee check-ins.', 'تقييم القيادة 360 درجة وتقييمات المتعلّمين الدورية.', '', '', '[{"label":"SkillsFuture Singapore · Factsheet on top skills trends in 2025 (Critical Core Skills)","url":"https://isomer-user-content.by.gov.sg/41/4955bc61-161d-4584-945c-7eeeb276867a/Factsheet%20on%20Top%20skills%20trends%20in%202025.pdf","as_of":"2026-10-10"},{"label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"},{"label":"McKinsey · Defining the skills citizens will need in the future world of work (DELTAs)","url":"https://www.mckinsey.com/industries/public-and-social-sector/our-insights/defining-the-skills-citizens-will-need-in-the-future-world-of-work","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 211),
('cs-learning-agility', 'SR-1', 'staying_relevant', 'Learning agility', 'سرعة التعلّم', 'Learns new systems, tools and roles quickly, seeks feedback and applies lessons from operating experience.', 'يتعلّم الأنظمة والأدوات والأدوار الجديدة بسرعة، ويطلب التغذية الراجعة، ويطبّق دروس الخبرة التشغيلية.', 'Takes up a new digital rounds tool, finds its limits in the first week and shares tips with the crew.', 'يتبنّى أداة رقمية جديدة للجولات، ويكتشف حدودها في الأسبوع الأول، ويشارك النصائح مع الطاقم.', '[{"level":1,"en":"Completes required learning on time and asks for feedback.","ar":"ينجز التعلّم المطلوب في موعده ويطلب التغذية الراجعة."},{"level":2,"en":"Plans their own learning against future role needs and applies it at work.","ar":"يخطّط لتعلّمه وفق احتياجات الدور المستقبلية ويطبّقه في العمل."},{"level":3,"en":"Helps the team adopt new ways of working and learn from experience.","ar":"يساعد الفريق على تبنّي طرق عمل جديدة والتعلّم من التجربة."}]'::jsonb, '[{"framework":"ssg_ccs","benchmark_id":"SSG-SF","ref":"SR","label_en":"SkillsFuture Critical Core Skills · Learning Agility","label_ar":"المهارات الأساسية الحرجة في SkillsFuture · سرعة التعلّم"},{"framework":"wef","benchmark_id":"WEF-FOJ","ref":null,"label_en":"WEF core skill · curiosity and lifelong learning","label_ar":"مهارة أساسية لدى المنتدى الاقتصادي العالمي · الفضول والتعلّم مدى الحياة"},{"framework":"lifecomp","benchmark_id":"GREENCOMP","ref":null,"label_en":"LifeComp · growth mindset and managing learning","label_ar":"إطار LifeComp · عقلية النمو وإدارة التعلّم"},{"framework":"inpo","benchmark_id":null,"ref":"trait-7","label_en":"INPO safety-culture trait · Continuous learning (M08)","label_ar":"سمة ثقافة السلامة لدى INPO · التعلّم المستمر (M08)"}]'::jsonb, array['GREENCOMP','SSG-SF','WEF-FOJ']::text[], array['trait-7']::text[], array['sk-fs-tr-curiosity']::text[], '[{"kind":"page","ref":"/my/plan","title_en":"A development plan tied to future role needs","title_ar":"خطة تطوير مرتبطة باحتياجات الدور المستقبلية"},{"kind":"page","ref":"/my/coach","title_en":"Coach nudges for the next learning step","title_ar":"تنبيهات المدرب لخطوة التعلّم التالية"},{"kind":"practice","ref":"cs-learning-agility","title_en":"Situational judgement practice for this skill","title_ar":"تمارين الحكم الظرفي لهذه المهارة"}]'::jsonb, '[{"kind":"checkin","ref":"/my/skills/checkins","title_en":"Skill check-in with peers and your manager","title_ar":"تقييم دوري للمهارة مع الزملاء ومديرك"},{"kind":"sjt","ref":"cs-learning-agility","title_en":"Situational judgement practice result (development only)","title_ar":"نتيجة تمارين الحكم الظرفي (للتطوير فقط)"}]'::jsonb, 'A personal development plan tied to future role needs, with coach nudges.', 'خطة تطوير شخصية مرتبطة باحتياجات الدور المستقبلية مع تنبيهات من المدرب.', 'A check-in on learning applied at work.', 'تقييم دوري لما طُبّق من التعلّم في العمل.', 'Career health is treated as an outcome of this skill, not a separate competency (SkillsFuture 2025 review).', 'تُعامَل الصحة المهنية بوصفها نتيجة لهذه المهارة لا كفاءة مستقلة (مراجعة SkillsFuture لعام 2025).', '[{"label":"SkillsFuture Singapore · Factsheet on top skills trends in 2025 (Critical Core Skills)","url":"https://isomer-user-content.by.gov.sg/41/4955bc61-161d-4584-945c-7eeeb276867a/Factsheet%20on%20Top%20skills%20trends%20in%202025.pdf","as_of":"2026-10-10"},{"label":"IAFOR PCAH 2025 · mixed-methods review of the Critical Core Skills (wellbeing and career health as outcomes)","url":"https://papers.iafor.org/wp-content/uploads/papers/pcah2025/PCAH2025_93970.pdf","as_of":"2026-10-10"},{"label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"},{"label":"European Commission JRC · GreenComp, with EntreComp and LifeComp","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 312),
('cs-resilience', 'SR-2', 'staying_relevant', 'Resilience and self-management', 'المرونة وإدارة الذات', 'Manages their own energy, attention and reactions through long outages, shift work and setbacks, and keeps procedure discipline under pressure.', 'يدير طاقته وانتباهه وردود أفعاله خلال فترات الانقطاع الطويلة والعمل بنظام الورديات والانتكاسات، ويلتزم بالإجراءات تحت الضغط.', 'Recognises fatigue near the end of a night shift and uses the fatigue rules to hand over a critical task.', 'يدرك الإرهاق قرب نهاية وردية ليلية ويطبّق قواعد إدارة الإرهاق لتسليم مهمة حرجة.', '[{"level":1,"en":"Knows the signs of fatigue and stress and the fitness-for-duty rules.","ar":"يعرف علامات الإرهاق والضغط وقواعد الأهلية للعمل."},{"level":2,"en":"Plans workload and recovery and speaks up early when not fit for a task.","ar":"يخطّط لعبء العمل والتعافي ويبادر بالإفصاح عندما لا يكون مؤهلاً لمهمة."},{"level":3,"en":"Builds team routines that protect alertness through outages.","ar":"يبني لدى الفريق روتيناً يحافظ على اليقظة خلال فترات الانقطاع."}]'::jsonb, '[{"framework":"ssg_ccs","benchmark_id":"SSG-SF","ref":"SR","label_en":"SkillsFuture Critical Core Skills · Self-Management","label_ar":"المهارات الأساسية الحرجة في SkillsFuture · إدارة الذات"},{"framework":"wef","benchmark_id":"WEF-FOJ","ref":null,"label_en":"WEF core skill · resilience, flexibility and agility","label_ar":"مهارة أساسية لدى المنتدى الاقتصادي العالمي · المرونة والقدرة على التكيّف وسرعة الاستجابة"},{"framework":"lifecomp","benchmark_id":"GREENCOMP","ref":null,"label_en":"LifeComp · self-regulation","label_ar":"إطار LifeComp · التنظيم الذاتي"},{"framework":"delta","benchmark_id":"MCK-DELTA","ref":null,"label_en":"McKinsey DELTA · self-leadership","label_ar":"عناصر DELTA لدى ماكنزي · القيادة الذاتية"}]'::jsonb, array['GREENCOMP','MCK-DELTA','SSG-SF','WEF-FOJ']::text[], '{}'::text[], array['sk-fs-tr-resilience']::text[], '[{"kind":"course","ref":"c-hu-ref","title_en":"HU tools refresher (fatigue and error traps)","title_ar":"تنشيط أدوات الأداء البشري (الإرهاق وفخاخ الأخطاء)"},{"kind":"ojt","ref":"fatigue-briefing","title_en":"Fatigue-management briefing before outages","title_ar":"إحاطة إدارة الإرهاق قبل فترات الانقطاع"},{"kind":"practice","ref":"cs-resilience","title_en":"Situational judgement practice for this skill","title_ar":"تمارين الحكم الظرفي لهذه المهارة"}]'::jsonb, '[{"kind":"checkin","ref":"/my/skills/checkins","title_en":"Skill check-in with peers and your manager","title_ar":"تقييم دوري للمهارة مع الزملاء ومديرك"},{"kind":"sjt","ref":"cs-resilience","title_en":"Situational judgement practice result (development only)","title_ar":"نتيجة تمارين الحكم الظرفي (للتطوير فقط)"}]'::jsonb, 'Fatigue-management and stress-awareness sessions before outages, with team routines.', 'جلسات لإدارة الإرهاق والوعي بالضغط قبل فترات الانقطاع، مع روتين للفريق.', 'A self and manager check-in on behaviours, never on health data.', 'تقييم دوري ذاتي ومن المدير يتناول السلوكيات، ولا يتناول البيانات الصحية أبداً.', 'Wellbeing is an outcome of this skill and is never a separate competency or score (SkillsFuture 2025 review). Kafa''a records behaviours, never health information.', 'العافية نتيجة لهذه المهارة ولا تكون أبداً كفاءة أو درجة مستقلة (مراجعة SkillsFuture لعام 2025). تسجّل كفاءة السلوكيات ولا تسجّل أي معلومات صحية.', '[{"label":"SkillsFuture Singapore · Factsheet on top skills trends in 2025 (Critical Core Skills)","url":"https://isomer-user-content.by.gov.sg/41/4955bc61-161d-4584-945c-7eeeb276867a/Factsheet%20on%20Top%20skills%20trends%20in%202025.pdf","as_of":"2026-10-10"},{"label":"IAFOR PCAH 2025 · mixed-methods review of the Critical Core Skills (wellbeing and career health as outcomes)","url":"https://papers.iafor.org/wp-content/uploads/papers/pcah2025/PCAH2025_93970.pdf","as_of":"2026-10-10"},{"label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"},{"label":"European Commission JRC · GreenComp, with EntreComp and LifeComp","url":"https://joint-research-centre.ec.europa.eu/greencomp","as_of":"2026-10-10"},{"label":"McKinsey · Defining the skills citizens will need in the future world of work (DELTAs)","url":"https://www.mckinsey.com/industries/public-and-social-sector/our-insights/defining-the-skills-citizens-will-need-in-the-future-world-of-work","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 313),
('cs-adaptability', 'SR-3', 'staying_relevant', 'Adaptability when plans change', 'التكيّف عند تغيّر الخطط', 'Adjusts quickly and safely when a schedule, scope or condition changes, re-planning rather than forcing the old plan.', 'يتكيّف بسرعة وأمان عند تغيّر الجدول أو النطاق أو الظروف، ويعيد التخطيط بدلاً من فرض الخطة القديمة.', 'When a spare part arrives late during an outage, re-sequences the work package with work control and re-briefs the crew.', 'عندما تتأخر قطعة غيار أثناء الانقطاع، يعيد ترتيب حزمة العمل مع التحكم في العمل ويعيد إحاطة الطاقم.', '[{"level":1,"en":"Accepts changes to plans and asks what they mean for their task.","ar":"يتقبّل تغيّر الخطط ويسأل عن أثرها على مهمته."},{"level":2,"en":"Re-plans their work when conditions change and re-briefs the risks.","ar":"يعيد تخطيط عمله عند تغيّر الظروف ويعيد الإحاطة بالمخاطر."},{"level":3,"en":"Leads a team through a changing plan without losing control of risk.","ar":"يقود الفريق عبر خطة متغيّرة دون أن يفقد السيطرة على المخاطر."}]'::jsonb, '[{"framework":"delta","benchmark_id":"MCK-DELTA","ref":null,"label_en":"McKinsey DELTA · adaptability and mental flexibility","label_ar":"عناصر DELTA لدى ماكنزي · القدرة على التكيّف والمرونة الذهنية"},{"framework":"wef","benchmark_id":"WEF-FOJ","ref":null,"label_en":"WEF core skill · resilience, flexibility and agility","label_ar":"مهارة أساسية لدى المنتدى الاقتصادي العالمي · المرونة والقدرة على التكيّف وسرعة الاستجابة"},{"framework":"ssg_ccs","benchmark_id":"SSG-SF","ref":"SR","label_en":"SkillsFuture Critical Core Skills · Staying Relevant cluster","label_ar":"المهارات الأساسية الحرجة في SkillsFuture · مجموعة مواكبة المستجدات"}]'::jsonb, array['MCK-DELTA','SSG-SF','WEF-FOJ']::text[], '{}'::text[], array['sk-fs-tr-resilience','sk-mp-01']::text[], '[{"kind":"ojt","ref":"outage-replanning","title_en":"Outage re-planning practice alongside work control","title_ar":"التمرّن على إعادة التخطيط أثناء الانقطاع إلى جانب التحكم في العمل"},{"kind":"page","ref":"/opportunities","title_en":"A short rotation into outage planning","title_ar":"تناوب قصير في تخطيط الانقطاع"},{"kind":"practice","ref":"cs-adaptability","title_en":"Situational judgement practice for this skill","title_ar":"تمارين الحكم الظرفي لهذه المهارة"}]'::jsonb, '[{"kind":"observation","ref":"replan-brief","title_en":"Observed re-brief after a plan change","title_ar":"إعادة إحاطة ملاحظة بعد تغيّر الخطة"},{"kind":"checkin","ref":"/my/skills/checkins","title_en":"Skill check-in with peers and your manager","title_ar":"تقييم دوري للمهارة مع الزملاء ومديرك"},{"kind":"sjt","ref":"cs-adaptability","title_en":"Situational judgement practice result (development only)","title_ar":"نتيجة تمارين الحكم الظرفي (للتطوير فقط)"}]'::jsonb, 'Outage re-planning practice alongside work control, and a short rotation into outage planning.', 'التمرّن على إعادة التخطيط أثناء الانقطاع إلى جانب التحكم في العمل، وتناوب قصير في تخطيط الانقطاع.', 'Observation of a re-brief after a plan change.', 'ملاحظة إعادة الإحاطة بعد تغيّر الخطة.', '', '', '[{"label":"SkillsFuture Singapore · Factsheet on top skills trends in 2025 (Critical Core Skills)","url":"https://isomer-user-content.by.gov.sg/41/4955bc61-161d-4584-945c-7eeeb276867a/Factsheet%20on%20Top%20skills%20trends%20in%202025.pdf","as_of":"2026-10-10"},{"label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"},{"label":"McKinsey · Defining the skills citizens will need in the future world of work (DELTAs)","url":"https://www.mckinsey.com/industries/public-and-social-sector/our-insights/defining-the-skills-citizens-will-need-in-the-future-world-of-work","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 314),
('cs-digital-judgement', 'SR-4', 'staying_relevant', 'Digital and AI judgement', 'الحكم الرقمي وفي الذكاء الاصطناعي', 'Uses approved digital and AI tools well and knows when to trust, check or override what they produce.', 'يستخدم الأدوات الرقمية وأدوات الذكاء الاصطناعي المعتمدة بكفاءة، ويعرف متى يثق بمخرجاتها ومتى يتحقق منها أو يتجاوزها.', 'Checks an AI-drafted procedure summary against the controlled document before using it in a brief.', 'يتحقق من ملخص إجراء صاغه الذكاء الاصطناعي مقابل الوثيقة المضبوطة قبل استخدامه في الإحاطة.', '[{"level":1,"en":"Uses approved tools only and knows they can be wrong.","ar":"يستخدم الأدوات المعتمدة فقط ويعرف أنها قد تخطئ."},{"level":2,"en":"Verifies outputs that will be relied on against controlled sources.","ar":"يتحقق من المخرجات التي سيُعتمد عليها مقابل مصادر مضبوطة."},{"level":3,"en":"Designs team checks for AI-assisted work and challenges tool outputs openly.","ar":"يصمم ضوابط للفريق للعمل بمساعدة الذكاء الاصطناعي ويطعن في مخرجات الأدوات علناً."}]'::jsonb, '[{"framework":"wef","benchmark_id":"WEF-FOJ","ref":null,"label_en":"WEF core skill · technological literacy; AI and big data","label_ar":"مهارة أساسية لدى المنتدى الاقتصادي العالمي · الإلمام التقني؛ الذكاء الاصطناعي والبيانات الضخمة"},{"framework":"delta","benchmark_id":"MCK-DELTA","ref":null,"label_en":"McKinsey DELTA · digital skills","label_ar":"عناصر DELTA لدى ماكنزي · المهارات الرقمية"},{"framework":"ssg_ccs","benchmark_id":"SSG-SF","ref":"SR","label_en":"SkillsFuture Critical Core Skills · Staying Relevant cluster","label_ar":"المهارات الأساسية الحرجة في SkillsFuture · مجموعة مواكبة المستجدات"}]'::jsonb, array['MCK-DELTA','SSG-SF','WEF-FOJ']::text[], '{}'::text[], array['sk-fs-ai-verify','sk-fs-tr-techlit','sk-fs-ai-use']::text[], '[{"kind":"page","ref":"/learn/ai-fluency","title_en":"The AI fluency ladder","title_ar":"سلّم الطلاقة في الذكاء الاصطناعي"},{"kind":"course","ref":"c-ai-gov","title_en":"Governed use of AI at work","title_ar":"الاستخدام المحوكم للذكاء الاصطناعي في العمل"},{"kind":"practice","ref":"cs-digital-judgement","title_en":"Situational judgement practice for this skill","title_ar":"تمارين الحكم الظرفي لهذه المهارة"}]'::jsonb, '[{"kind":"fitness","ref":"/my/ai-fluency/check","title_en":"The quarterly AI and digital fitness check","title_ar":"فحص اللياقة الرقمية وفي الذكاء الاصطناعي ربع السنوي"},{"kind":"sjt","ref":"cs-digital-judgement","title_en":"Situational judgement practice result (development only)","title_ar":"نتيجة تمارين الحكم الظرفي (للتطوير فقط)"}]'::jsonb, 'The AI fluency ladder and the governed AI-use course.', 'سلّم الطلاقة في الذكاء الاصطناعي ودورة الاستخدام المحوكم للذكاء الاصطناعي.', 'The quarterly AI and digital fitness check.', 'فحص اللياقة الرقمية وفي الذكاء الاصطناعي ربع السنوي.', '', '', '[{"label":"SkillsFuture Singapore · Factsheet on top skills trends in 2025 (Critical Core Skills)","url":"https://isomer-user-content.by.gov.sg/41/4955bc61-161d-4584-945c-7eeeb276867a/Factsheet%20on%20Top%20skills%20trends%20in%202025.pdf","as_of":"2026-10-10"},{"label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"},{"label":"McKinsey · Defining the skills citizens will need in the future world of work (DELTAs)","url":"https://www.mckinsey.com/industries/public-and-social-sector/our-insights/defining-the-skills-citizens-will-need-in-the-future-world-of-work","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 315),
('cs-accountability', 'SR-5', 'staying_relevant', 'Personal accountability', 'المساءلة الشخصية', 'Owns their work and its safety consequences, keeps commitments and admits mistakes quickly so others can learn.', 'يتحمّل مسؤولية عمله وعواقبه على السلامة، ويفي بالتزاماته، ويعترف بأخطائه سريعاً كي يتعلّم الآخرون.', 'Reports their own mis-positioned valve straight away, even though nobody else noticed.', 'يبلغ فوراً عن صمام وضعه بنفسه في موضع خاطئ، رغم أن أحداً لم يلاحظ ذلك.', '[{"level":1,"en":"Meets commitments and reports their own errors.","ar":"يفي بالتزاماته ويبلغ عن أخطائه."},{"level":2,"en":"Takes ownership of outcomes beyond the task, including follow-up.","ar":"يتحمّل مسؤولية النتائج بما يتجاوز المهمة، بما في ذلك المتابعة."},{"level":3,"en":"Models accountability without blame, so the team reports freely.","ar":"يجسّد المساءلة دون لوم، فيبلغ الفريق بحرّية."}]'::jsonb, '[{"framework":"inpo","benchmark_id":null,"ref":"trait-1","label_en":"INPO safety-culture trait · Personal accountability (M08)","label_ar":"سمة ثقافة السلامة لدى INPO · المساءلة الشخصية (M08)"},{"framework":"wef","benchmark_id":"WEF-FOJ","ref":null,"label_en":"WEF core skill · motivation and self-awareness","label_ar":"مهارة أساسية لدى المنتدى الاقتصادي العالمي · الدافعية والوعي الذاتي"},{"framework":"delta","benchmark_id":"MCK-DELTA","ref":null,"label_en":"McKinsey DELTA · self-leadership","label_ar":"عناصر DELTA لدى ماكنزي · القيادة الذاتية"},{"framework":"ssg_ccs","benchmark_id":"SSG-SF","ref":"SR","label_en":"SkillsFuture Critical Core Skills · Staying Relevant cluster","label_ar":"المهارات الأساسية الحرجة في SkillsFuture · مجموعة مواكبة المستجدات"}]'::jsonb, array['MCK-DELTA','SSG-SF','WEF-FOJ']::text[], array['trait-1']::text[], array['sk-fs-tr-dependable','sk-fs-tr-selfaware']::text[], '[{"kind":"page","ref":"/my/safety-culture","title_en":"Team discussions of the personal accountability trait","title_ar":"نقاشات الفريق حول سمة المساءلة الشخصية"},{"kind":"ojt","ref":"post-job-review","title_en":"Lead post-job reviews","title_ar":"قيادة مراجعات ما بعد العمل"},{"kind":"practice","ref":"cs-accountability","title_en":"Situational judgement practice for this skill","title_ar":"تمارين الحكم الظرفي لهذه المهارة"}]'::jsonb, '[{"kind":"checkin","ref":"/my/skills/checkins","title_en":"Skill check-in with peers and your manager","title_ar":"تقييم دوري للمهارة مع الزملاء ومديرك"},{"kind":"observation","ref":"post-job-review","title_en":"Observed post-job review","title_ar":"مراجعة ما بعد العمل الملاحظة"},{"kind":"sjt","ref":"cs-accountability","title_en":"Situational judgement practice result (development only)","title_ar":"نتيجة تمارين الحكم الظرفي (للتطوير فقط)"}]'::jsonb, 'Leading post-job reviews and team discussions of the personal accountability trait.', 'قيادة مراجعات ما بعد العمل ونقاشات الفريق حول سمة المساءلة الشخصية.', 'Check-in evidence of owned follow-ups and self-reported errors.', 'أدلة في التقييم الدوري على متابعات تحمّل مسؤوليتها وأخطاء أبلغ عنها بنفسه.', '', '', '[{"label":"SkillsFuture Singapore · Factsheet on top skills trends in 2025 (Critical Core Skills)","url":"https://isomer-user-content.by.gov.sg/41/4955bc61-161d-4584-945c-7eeeb276867a/Factsheet%20on%20Top%20skills%20trends%20in%202025.pdf","as_of":"2026-10-10"},{"label":"World Economic Forum · Future of Jobs Report 2025, skills outlook","url":"https://www.weforum.org/publications/the-future-of-jobs-report-2025/in-full/3-skills-outlook/","as_of":"2026-10-10"},{"label":"McKinsey · Defining the skills citizens will need in the future world of work (DELTAs)","url":"https://www.mckinsey.com/industries/public-and-social-sector/our-insights/defining-the-skills-citizens-will-need-in-the-future-world-of-work","as_of":"2026-10-10"}]'::jsonb, 'active', 1, '2026-10-10', 316)
